  function lexiconMatchesAny(text, patterns) {
    return (patterns || []).some(function (pattern) {
      return pattern.test(text);
    });
  }

  function lexiconHasStandaloneValue(text, values) {
    return hasAnyStandalonePhrase(String(text || ""), values || []);
  }

  function extractLexiconCanonicals(text, entries) {
    var normalized = normalizeCareerIntentText(cleanMessageText(text || ""));
    return dedupeList(
      (entries || [])
        .filter(function (entry) {
          return entry && lexiconMatchesAny(normalized, entry.patterns || []);
        })
        .map(function (entry) {
          return entry.canonical;
        })
    );
  }

  function splitMeaningClauses(text) {
    return String(text || "")
      .split(
        /\b(?:and|but|or|plus|then|also|except|instead|because|if|while)\b|(?:^|\s)(?:و|لكن|بس|او|أو|بعدين|كمان|إلا|الا|بدل|إذا|اذا|لأن|لان|عشان)(?=\s|$)|[?.!;,]+|[،؛]/i
      )
      .map(function (part) {
        return cleanMessageText(part);
      })
      .filter(Boolean);
  }

  function extractMeaningFrame(text) {
    var clean = cleanMessageText(text || "");
    var normalized = normalizeCareerIntentText(clean);
    var questionWord = "";
    var actions = [];
    var topics = [];
    var roleSignals = [];
    var locationSignals = [];
    var senioritySignals = [];
    var modifiers = [];
    var clauseFrames = [];
    var clauseCount = 0;
    var clauseParts;

    if (!normalized) {
      return {
        question_word: "",
        actions: [],
        topics: [],
        roles: [],
        locations: [],
        seniority: [],
        modifiers: [],
        clauses: [],
        compact: "",
        is_question_like: false,
        clause_count: 0,
      };
    }

    questionWord =
      extractLexiconCanonicals(
        normalized,
        chatSignalLexicon.questionWords
      )[0] || "";
    actions = extractLexiconCanonicals(
      normalized,
      chatSignalLexicon.meaningActions
    );
    topics = extractLexiconCanonicals(
      normalized,
      chatSignalLexicon.meaningTopics
    );
    roleSignals = extractLexiconCanonicals(
      normalized,
      chatSignalLexicon.roleFamilies
    );
    locationSignals = extractLexiconCanonicals(
      normalized,
      chatSignalLexicon.locations
    );
    senioritySignals = extractLexiconCanonicals(
      normalized,
      chatSignalLexicon.seniorityEntries
    );
    modifiers = Object.keys(chatSignalLexicon.meaningModifiers).filter(
      function (key) {
        return lexiconMatchesAny(
          normalized,
          chatSignalLexicon.meaningModifiers[key]
        );
      }
    );
    clauseParts = splitMeaningClauses(normalized);
    clauseCount = clauseParts.length;
    clauseFrames = clauseParts.map(function (part) {
      return {
        text: part,
        question_word:
          extractLexiconCanonicals(part, chatSignalLexicon.questionWords)[0] ||
          "",
        actions: extractLexiconCanonicals(
          part,
          chatSignalLexicon.meaningActions
        ),
        topics: extractLexiconCanonicals(part, chatSignalLexicon.meaningTopics),
        roles: extractLexiconCanonicals(part, chatSignalLexicon.roleFamilies),
        locations: extractLexiconCanonicals(part, chatSignalLexicon.locations),
        seniority: extractLexiconCanonicals(
          part,
          chatSignalLexicon.seniorityEntries
        ),
        modifiers: Object.keys(chatSignalLexicon.meaningModifiers).filter(
          function (key) {
            return lexiconMatchesAny(
              part,
              chatSignalLexicon.meaningModifiers[key]
            );
          }
        ),
      };
    });

    return {
      question_word: questionWord,
      actions: actions,
      topics: topics,
      roles: roleSignals,
      locations: locationSignals,
      seniority: senioritySignals,
      modifiers: modifiers,
      clauses: clauseFrames,
      compact: [questionWord]
        .concat(actions.slice(0, 2))
        .concat(topics.slice(0, 2))
        .concat(modifiers.slice(0, 2))
        .filter(Boolean)
        .join(" "),
      is_question_like: !!(
        questionWord ||
        /\?/.test(clean) ||
        hasAnyStandalonePhrase(normalized, chatSignalLexicon.questionPhrases)
      ),
      clause_count: clauseCount,
    };
  }

  function meaningFrameHasAction(frame, values) {
    return !!(
      frame &&
      frame.actions &&
      frame.actions.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function meaningFrameHasTopic(frame, values) {
    return !!(
      frame &&
      frame.topics &&
      frame.topics.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function meaningFrameHasModifier(frame, values) {
    return !!(
      frame &&
      frame.modifiers &&
      frame.modifiers.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function meaningFrameClauseHas(frame, predicate) {
    return !!(
      frame &&
      frame.clauses &&
      frame.clauses.some(function (clause) {
        return predicate(clause);
      })
    );
  }

  function findMeaningFrameClause(frame, predicate) {
    var match = null;
    if (!frame || !frame.clauses) {
      return null;
    }
    frame.clauses.some(function (clause) {
      if (predicate(clause)) {
        match = clause;
        return true;
      }
      return false;
    });
    return match;
  }

  function clauseHasAction(clause, values) {
    return !!(
      clause &&
      clause.actions &&
      clause.actions.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function clauseHasTopic(clause, values) {
    return !!(
      clause &&
      clause.topics &&
      clause.topics.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function clauseHasModifier(clause, values) {
    return !!(
      clause &&
      clause.modifiers &&
      clause.modifiers.some(function (item) {
        return values.indexOf(item) !== -1;
      })
    );
  }

  function frameUsesQuestionWord(frame, values) {
    return !!(
      frame &&
      frame.question_word &&
      values.indexOf(frame.question_word) !== -1
    );
  }

  function inferIntentFromMeaningFrame(frame, semantics) {
    if (!frame) {
      return "";
    }
    if (
      /\bseeking a new opportunity\b/i.test(
        (semantics && semantics.clean) || ""
      ) &&
      /\bcompliance\b/i.test((semantics && semantics.clean) || "")
    ) {
      return "career_direction";
    }

    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["apply"]) &&
      (meaningFrameHasTopic(frame, [
        "application",
        "process",
        "role",
        "job_search",
      ]) ||
        frame.question_word === "when")
    ) {
      return "application_process";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["when"]) &&
      (meaningFrameHasAction(frame, ["apply", "find", "send"]) ||
        meaningFrameHasTopic(frame, [
          "application",
          "role",
          "process",
          "alerts",
        ]))
    ) {
      return "application_strategy";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasAction(frame, ["improve", "review"]) ||
        (semantics && semantics.asks_for_review)) &&
      meaningFrameHasTopic(frame, ["cv"])
    ) {
      return "cv_improvement";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["improve", "review", "help"]) &&
      (meaningFrameHasTopic(frame, ["application", "fit", "qualification"]) ||
        (frame.roles && frame.roles.length))
    ) {
      return "application_strategy";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["contact", "find"]) &&
      meaningFrameHasTopic(frame, ["recruiter"])
    ) {
      return "recruiter_networking";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["who"]) &&
      (meaningFrameHasAction(frame, ["contact", "find", "know"]) ||
        meaningFrameHasTopic(frame, ["recruiter", "networking", "company"]))
    ) {
      return meaningFrameHasTopic(frame, ["company"])
        ? "company_details"
        : "recruiter_networking";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasTopic(frame, ["salary"]) ||
        meaningFrameHasAction(frame, ["pay"]))
    ) {
      return frame.question_word === "what" || frame.question_word === "how"
        ? "salary_question"
        : "salary_advice";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["review", "improve"]) &&
      meaningFrameHasTopic(frame, ["linkedin"])
    ) {
      return "linkedin_help";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["review", "improve", "help"]) &&
      meaningFrameHasTopic(frame, ["interview"])
    ) {
      return "interview_prep";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["pay", "cancel", "login"]) &&
      meaningFrameHasTopic(frame, ["membership", "payment", "account"])
    ) {
      if (meaningFrameHasAction(frame, ["cancel"])) {
        return "membership_cancellation";
      }
      if (meaningFrameHasAction(frame, ["login"])) {
        return "account_access_issue";
      }
      return "payment_support";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["need", "want"]) &&
      meaningFrameHasTopic(frame, [
        "membership",
        "payment",
        "subscription",
        "refund",
      ])
    ) {
      return "pricing_trust";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["why"]) &&
      (meaningFrameHasTopic(frame, [
        "membership",
        "payment",
        "subscription",
        "privacy",
      ]) ||
        meaningFrameHasAction(frame, ["pay", "trust"]))
    ) {
      return meaningFrameHasTopic(frame, ["privacy"])
        ? "data_safety"
        : "pricing_trust";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["find", "help"]) &&
      meaningFrameHasTopic(frame, ["role", "job_search"])
    ) {
      return "job_search_strategy";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["what", "which"]) &&
      (meaningFrameHasAction(frame, ["find", "know", "see"]) ||
        meaningFrameHasTopic(frame, ["fit", "role", "job_search"]))
    ) {
      return "matching_jobs";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasTopic(frame, ["location"]) &&
      meaningFrameHasModifier(frame, ["contrast", "future", "uncertain"])
    ) {
      return "location_preferences";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasTopic(frame, ["alerts"]) &&
      (meaningFrameHasAction(frame, ["change", "find", "help", "know"]) ||
        frameUsesQuestionWord(frame, ["how", "what", "when"]))
    ) {
      return "job_alert_preferences";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasTopic(frame, ["membership", "payment", "account"]) &&
      meaningFrameHasModifier(frame, ["uncertain"])
    ) {
      return "pricing_trust";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasAction(frame, ["explain", "understand", "know", "see"]) ||
        frameUsesQuestionWord(frame, ["what", "how"])) &&
      meaningFrameHasTopic(frame, [
        "role",
        "company",
        "membership",
        "application",
        "process",
        "fit",
      ])
    ) {
      return "specific_vacancy_details";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["what"]) &&
      meaningFrameHasAction(frame, ["explain", "understand"]) &&
      !frame.topics.length
    ) {
      return "role_question";
    }
    if (
      frame.is_question_like &&
      meaningFrameHasAction(frame, ["compare"]) &&
      (meaningFrameHasTopic(frame, ["role", "offer"]) ||
        (frame.roles && frame.roles.length > 1))
    ) {
      return "compare_roles";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasAction(frame, ["find", "contact", "know", "see"]) ||
        frameUsesQuestionWord(frame, ["where"])) &&
      meaningFrameHasTopic(frame, ["company"])
    ) {
      return "company_details";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasAction(frame, ["login", "know", "help"]) ||
        frameUsesQuestionWord(frame, ["how", "why"])) &&
      meaningFrameHasTopic(frame, ["account", "support"])
    ) {
      return "account_access_issue";
    }
    if (
      frame.is_question_like &&
      (meaningFrameHasAction(frame, ["trust", "know", "understand"]) ||
        frameUsesQuestionWord(frame, ["how", "why"])) &&
      meaningFrameHasTopic(frame, ["privacy"])
    ) {
      return "data_safety";
    }
    if (
      frame.is_question_like &&
      frameUsesQuestionWord(frame, ["who"]) &&
      meaningFrameHasTopic(frame, ["support"])
    ) {
      return "support_contact";
    }

    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clause.locations &&
          clause.locations.length &&
          clauseHasModifier(clause, ["contrast"])
        );
      })
    ) {
      return "location_preferences";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasAction(clause, ["apply"]) &&
          clauseHasModifier(clause, ["future"])
        );
      })
    ) {
      return "application_strategy";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasTopic(clause, ["role", "job_search"]) &&
          clauseHasModifier(clause, ["uncertain"])
        );
      })
    ) {
      return "search_uncertainty";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasTopic(clause, ["membership", "payment", "account"]) &&
          clauseHasModifier(clause, ["negation", "uncertain"])
        );
      })
    ) {
      return "pricing_trust";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasTopic(clause, ["cv", "application", "fit"]) &&
          clauseHasModifier(clause, ["difficulty"])
        );
      })
    ) {
      return "cv_improvement";
    }
    var difficultyClause = findMeaningFrameClause(frame, function (clause) {
      return (
        clauseHasTopic(clause, [
          "account",
          "payment",
          "membership",
          "support",
        ]) && clauseHasModifier(clause, ["difficulty"])
      );
    });
    if (difficultyClause) {
      return clauseHasTopic(difficultyClause, ["account"])
        ? "account_access_issue"
        : "payment_support";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasTopic(clause, ["location"]) &&
          clauseHasModifier(clause, ["exclusive"])
        );
      })
    ) {
      return "location_preferences";
    }
    if (
      meaningFrameClauseHas(frame, function (clause) {
        return (
          clauseHasTopic(clause, ["role", "job_search"]) &&
          clauseHasModifier(clause, ["exclusive"])
        );
      })
    ) {
      return "role_targeting";
    }

    return "";
  }

  function matchesLexiconPhraseGroup(text, values) {
    return hasAnyStandalonePhrase(
      normalizeCareerIntentText(cleanMessageText(text || "")),
      values || []
    );
  }

  function compactAlphaToken(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/([a-z])\1{2,}/g, "$1$1")
      .replace(/[^a-z]/g, "")
      .trim();
  }

  function matchesCompactPatternList(value, patterns) {
    var compact = compactAlphaToken(value);
    if (!compact) {
      return false;
    }
    return (patterns || []).some(function (pattern) {
      return pattern.test(compact);
    });
  }

  function isLikelyClarificationShorthand(value) {
    var clean = cleanMessageText(value || "");
    var lower = clean.toLowerCase();
    if (!clean) {
      return false;
    }
    if (
      /(?:^|\b)(what do you mean|what d(?:o|you) mean|what mean|what's that|whats that|what is that|wdym|wym|come again|how so|say again|meaning\??|clarify\??|explain\??|huh\??)(?:\b|$)/i.test(
        lower
      )
    ) {
      return true;
    }
    if (
      /(?:وش\s+تقصد(?:ين)?|وش\s+يعني|ماذا\s+تقصد(?:ين)?|ما\s+المقصود|مو\s+واضح|غير\s+واضح|اشرح(?:ي)?|وض(?:ح|حي)|يعني\s+ايش|يعني\s+ماذا)/i.test(
        clean
      )
    ) {
      return true;
    }
    return matchesCompactPatternList(lower, [
      /^wh+a+s+$/,
      /^wh+at+s+$/,
      /^wh+ts$/,
      /^wdym$/,
      /^wym$/,
      /^hwa+t$/,
      /^hwa+ss$/,
      /^wot$/,
      /^wat$/,
      /^huh$/,
    ]);
  }

  function levenshteinDistance(a, b) {
    var source = String(a || "");
    var target = String(b || "");
    var sourceLength = source.length;
    var targetLength = target.length;
    var prev;
    var curr;
    var i;
    var j;
    if (!sourceLength) {
      return targetLength;
    }
    if (!targetLength) {
      return sourceLength;
    }
    prev = new Array(targetLength + 1);
    curr = new Array(targetLength + 1);
    for (j = 0; j <= targetLength; j += 1) {
      prev[j] = j;
    }
    for (i = 1; i <= sourceLength; i += 1) {
      curr[0] = i;
      for (j = 1; j <= targetLength; j += 1) {
        curr[j] = Math.min(
          curr[j - 1] + 1,
          prev[j] + 1,
          prev[j - 1] + (source.charAt(i - 1) === target.charAt(j - 1) ? 0 : 1)
        );
      }
      prev = curr.slice(0);
    }
    return prev[targetLength];
  }

  function getCareerLexiconCorrection(token) {
    var value = String(token || "");
    var lower = value.toLowerCase();
    var best = "";
    var bestDistance = 99;
    if (!/^[a-z][a-z&]{3,}$/.test(lower)) {
      return value;
    }
    if (careerIntentLexicon.indexOf(lower) !== -1) {
      return value;
    }
    careerIntentLexicon.forEach(function (candidate) {
      var candidateLower = candidate.toLowerCase();
      var maxDistance;
      var distance;
      if (!candidateLower || candidateLower === lower) {
        return;
      }
      if (candidateLower.charAt(0) !== lower.charAt(0)) {
        return;
      }
      if (Math.abs(candidateLower.length - lower.length) > 2) {
        return;
      }
      maxDistance = candidateLower.length >= 8 ? 2 : 1;
      distance = levenshteinDistance(lower, candidateLower);
      if (distance <= maxDistance && distance < bestDistance) {
        best = candidateLower;
        bestDistance = distance;
      }
    });
    return best || value;
  }

  function normalizeCareerIntentText(text) {
    var normalized = normalizeLooseText(text || "");
    if (!normalized) {
      return "";
    }
    careerIntentPhraseCorrections.forEach(function (rule) {
      normalized = normalized.replace(rule.pattern, rule.replacement);
    });
    normalized = normalized.replace(/[a-z&]{4,}/g, function (token) {
      if (protectedFinanceIntentTokens[token]) {
        return token;
      }
      return getCareerLexiconCorrection(token);
    });
    normalized = normalized
      .replace(/\bwork from hom\b/g, "work from home")
      .replace(/\bfrome\b/g, "from")
      .replace(/\s+/g, " ")
      .trim();
    return normalized;
  }

  function getResponseExpectationScores(text, context) {
    var clean = cleanMessageText(text || "");
    var lower = normalizeCareerIntentText(clean).toLowerCase();
    var sentenceParts = clean
      .replace(/([.!?؟])\s+/g, "$1\n")
      .split(/[\n\r]+/)
      .map(function (part) {
        return cleanMessageText(part);
      })
      .filter(Boolean);
    var scores = {
      question: 0,
      request: 0,
      query: 0,
      statement: 0,
      answer: 0,
    };
    var evidence = [];
    var promptKey = cleanMessageText((context && context.promptState) || "");
    var words = lower.split(/\s+/).filter(Boolean);
    var hasQuestionMark = /[?؟]/.test(clean);
    var hasInitialInterrogative =
      /^(?:what|why|how|where|when|who|which|whose|whats|what's|wot|wat)\b/i.test(
        lower
      ) &&
      !/^(?:what i|what we|what happened was|what i'm saying|what i mean|how i|why i|why we)\b/i.test(
        lower
      );
    var hasFalseInterrogativeStatement =
      /^(?:what i|what we|what happened was|what i'm saying|what i mean|how i|why i|why we)\b/i.test(
        lower
      );
    var hasInterrogativeLater =
      /\b(?:what|why|how|where|when|who|which|whether)\b/i.test(lower) &&
      !hasInitialInterrogative &&
      !hasFalseInterrogativeStatement;
    var hasAuxiliaryInversion =
      /^(?:do|does|did|can|could|will|would|should|shall|may|might|must|is|are|am|was|were|have|has|had)\s+(?:i|you|we|they|he|she|it|there)\b/i.test(
        lower
      );
    var hasEmbeddedInterrogative =
      /\b(?:wondering|not sure|unsure|confused|figure out|trying to understand|trying to decide|want to know|need to know|can you tell|could you tell|tell me|explain)\b.{0,80}\b(?:what|why|how|where|when|who|which|whether|if)\b/i.test(
        lower
      );
    var hasAdviceIntent =
      /\b(?:should i|would you recommend|worth applying|worth it|best way|best .* job|best .* role|how realistic|am i competitive|chances|what can i target|what roles? could i|what jobs? could i|what should i focus on)\b/i.test(
        lower
      );
    var hasRecommendationIntent =
      /\b(?:best|better|recommend|suggest|advice|guidance|what do you think|thoughts on)\b/i.test(
        lower
      );
    var hasComparisonIntent =
      /\b(?:vs|versus| or |better than|difference between|split between)\b/i.test(
        lower
      );
    var hasImperativeRequest =
      /^(?:please\s+)?(?:review|analyse|analyze|evaluate|compare|find|search|show|tell|explain|suggest|recommend|rewrite|improve|prepare|calculate|rank|check|look at|help me|give me)\b/i.test(
        lower
      ) ||
      /\b(?:i need|need|looking for|want)\s+(?:career\s+)?(?:guidance|advice|help)\b/i.test(
        lower
      ) ||
      /\b(?:can you|could you|would you|will you|i want you to|i need you to|i'd like you to|id like you to)\s+(?:review|analyse|analyze|evaluate|compare|find|search|show|tell|explain|suggest|recommend|rewrite|improve|prepare|calculate|rank|check|look)\b/i.test(
        lower
      );
    var hasSearchQuery =
      /\b(?:jobs?|roles?|vacanc(?:y|ies)|openings?|opportunit(?:y|ies)|companies hiring|recruiters?)\s+(?:in|at|for|near)\s+[a-z]/i.test(
        lower
      ) ||
      /\b(?:salary|compensation|requirements?|skills needed|experience required|interview questions?|cv examples?)\s+(?:for|at|in)\s+[a-z]/i.test(
        lower
      ) ||
      (words.length <= 7 &&
        /\b(?:analyst|associate|manager|director|vp|svp|avp|principal|intern|graduate|finance|investment|banking|private equity|asset management|credit|compliance|risk|treasury|fp&a|wealth|fintech|valuation|audit|real estate|infrastructure)\b/i.test(
          lower
        ) &&
        /\b(?:dubai|riyadh|abu dhabi|qatar|doha|saudi|uae|london|nyc|salary|jobs?|roles?|interview|cv)\b/i.test(
          lower
        ));
    var hasDeclarativePersonalFact =
      /^(?:for context,\s*)?(?:i am|i'm|i was|i have|i've|i had|i work|i worked|i currently|i used to|i graduated|i studied|i completed|i passed|i applied|i interviewed|i received|i got|i earn|i'm earning|i make|i live|i'm based|i am based|i prefer|i'd prefer|i want|i'd like|i'm looking|i'm interested|my background|my experience|my degree|my university|my salary|my notice period|my current role|my title|my company)\b/i.test(
        lower
      );
    var hasStatementMarker =
      /^(?:just letting you know|for your information|fyi|for context|as background|for reference|as mentioned|like i said|to clarify|to confirm|my answer is|the answer is|i chose|i selected|i decided|i've decided|i already|i previously|currently|at the moment)\b/i.test(
        lower
      );
    var isAgreement =
      /^(?:yes|yeah|yep|correct|exactly|sounds good|ok|okay|perfect|great|sure|fine|no|nope|nah|not really|thanks|thank you|got it|done)[.!]*$/i.test(
        lower
      );
    var looksLikeSuppliedData =
      words.length <= 6 &&
      /^(?:[a-z .'-]+|\d+(?:\.\d+)?\s*(?:years?|months?|days?)?|[$£€]?\s*\d[\d,.]*(?:k|m)?|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})$/i.test(
        lower
      ) &&
      !hasQuestionMark &&
      !hasInitialInterrogative &&
      !hasAuxiliaryInversion;
    var promptExpectsAnswer = !!(
      promptKey && !/^(?:question_detour|language_selection)$/.test(promptKey)
    );

    if (hasQuestionMark) {
      scores.question += 6;
      evidence.push("question_mark");
    }
    if (hasInitialInterrogative) {
      scores.question += 5;
      evidence.push("initial_interrogative");
    }
    if (hasEmbeddedInterrogative) {
      scores.question += 4;
      evidence.push("embedded_interrogative");
    }
    if (hasInterrogativeLater && hasQuestionMark) {
      scores.question += 4;
      evidence.push("interrogative_later");
    }
    if (hasAuxiliaryInversion) {
      scores.question += 5;
      evidence.push("auxiliary_inversion");
    }
    if (hasAdviceIntent) {
      scores.question += 5;
      scores.request += 2;
      evidence.push("advice_intent");
    }
    if (
      hasRecommendationIntent &&
      (hasQuestionMark || hasInitialInterrogative)
    ) {
      scores.question += 4;
      evidence.push("recommendation_intent");
    }
    if (hasComparisonIntent) {
      scores.query += 4;
      if (hasQuestionMark || words.length <= 6) {
        scores.question += 7;
      }
      evidence.push("comparison_intent");
    }
    if (hasImperativeRequest) {
      scores.request += 7;
      evidence.push("imperative_request");
    }
    if (hasSearchQuery) {
      scores.query += 6;
      evidence.push("career_query");
    }
    if (hasDeclarativePersonalFact) {
      scores.statement += 6;
      evidence.push("personal_fact");
    }
    if (hasStatementMarker) {
      scores.statement += 5;
      evidence.push("statement_marker");
    }
    if (hasFalseInterrogativeStatement || /^i do\b/i.test(lower)) {
      scores.statement += 6;
      evidence.push("declarative_false_friend");
    }
    if (
      /\b(?:i feel|i think|i believe|i guess|i'm frustrated|i am frustrated|i'm worried|i am worried)\b/i.test(
        lower
      )
    ) {
      scores.statement += 4;
      evidence.push("opinion_or_emotion");
    }
    if (isAgreement) {
      scores.answer += promptExpectsAnswer ? 8 : 3;
      scores.statement += 4;
      evidence.push("agreement_acknowledgement");
    }
    if (looksLikeSuppliedData && promptExpectsAnswer) {
      scores.answer += 8;
      evidence.push("contextual_answer");
    } else if (looksLikeSuppliedData) {
      scores.statement += 4;
      evidence.push("short_declarative_data");
    }
    if (
      /^(?:and|also|same for|what about|how about|versus|vs)\b/i.test(lower) ||
      (hasQuestionMark && words.length <= 4)
    ) {
      scores.question += 4;
      evidence.push("follow_up_shorthand");
    }

    sentenceParts.forEach(function (sentence) {
      var normalizedSentence =
        normalizeCareerIntentText(sentence).toLowerCase();
      if (
        /^(?:what|why|how|where|when|who|which|do|does|did|can|could|will|would|should|is|are|have|has)\b/i.test(
          normalizedSentence
        ) ||
        /[?؟]/.test(sentence)
      ) {
        scores.question += 2;
      } else if (
        /^(?:i|my|currently|for context|for reference|to clarify)\b/i.test(
          normalizedSentence
        )
      ) {
        scores.statement += 2;
      }
    });

    return {
      scores: scores,
      evidence: evidence,
      hasQuestionStructure: !!(
        hasQuestionMark ||
        hasInitialInterrogative ||
        (hasInterrogativeLater && hasQuestionMark) ||
        hasEmbeddedInterrogative ||
        hasAuxiliaryInversion ||
        hasComparisonIntent ||
        hasAdviceIntent
      ),
      hasRequestStructure: !!hasImperativeRequest,
      hasQueryStructure: !!hasSearchQuery,
      hasStatementStructure: !!(
        hasDeclarativePersonalFact ||
        hasStatementMarker ||
        isAgreement ||
        looksLikeSuppliedData
      ),
      containsBackgroundContext: !!(
        hasDeclarativePersonalFact || hasStatementMarker
      ),
    };
  }

  function classifyResponseExpectation(text, context) {
    var result = getResponseExpectationScores(text || "", context || {});
    var scores = result.scores;
    var semanticIntent = getResponseExpectationSemanticIntent(text || "");
    var candidates = [
      ["ANSWER", scores.answer],
      ["REQUEST", scores.request],
      ["QUESTION", result.hasQuestionStructure ? scores.question : 0],
      ["QUERY", scores.query],
      ["STATEMENT", scores.statement],
    ].sort(function (a, b) {
      return b[1] - a[1];
    });
    var winner = candidates[0];
    var runnerUp = candidates[1] || ["", 0];
    var classification = "AMBIGUOUS";
    var responseExpected = false;
    var margin = winner[1] - runnerUp[1];
    if (winner[1] > 0) {
      classification = winner[0];
    }
    if (
      scores.answer >= 8 &&
      (!result.hasQuestionStructure || scores.answer > scores.question)
    ) {
      classification = "ANSWER";
    } else if (scores.request >= 7) {
      classification = "REQUEST";
    } else if (result.hasQuestionStructure && scores.question >= 7) {
      classification = "QUESTION";
    } else if (scores.query >= 6) {
      classification = "QUERY";
    } else if (scores.statement >= 6) {
      classification = "STATEMENT";
    }
    if (
      isResponseExpectedSemanticIntent(semanticIntent) &&
      classification !== "ANSWER"
    ) {
      classification =
        scores.query >= 6 ||
        /^(?:matching_jobs|opportunity_search|search_apply|search_send_jobs|find_job)$/.test(
          semanticIntent
        )
          ? "QUERY"
          : scores.request >= 7 || isApplyControlIntent(semanticIntent)
          ? "REQUEST"
          : "QUESTION";
    }
    responseExpected = /^(?:QUESTION|REQUEST|QUERY)$/.test(classification);
    if (classification === "ANSWER") {
      responseExpected = !!(context && context.promptState);
    }
    return {
      classification: classification,
      response_expected: responseExpected,
      question_score: scores.question,
      request_score: scores.request,
      query_score: scores.query,
      statement_score: scores.statement,
      answer_score: scores.answer,
      confidence_margin: margin,
      confidence:
        margin >= 5
          ? "very_high"
          : margin >= 3
          ? "high"
          : margin >= 2
          ? "medium"
          : "ambiguous",
      contains_question: result.hasQuestionStructure && scores.question >= 7,
      contains_request: scores.request >= 7,
      contains_query: scores.query >= 6,
      contains_statement: result.hasStatementStructure || scores.statement >= 6,
      contains_background_context: result.containsBackgroundContext,
      evidence: result.evidence,
    };
  }

  function isApplyControlIntent(intent) {
    return /^(?:apply_current_cv|apply_original_cv|apply_start_auto_apply|apply_continue_background|apply_tailor_cv|apply_review_tailored_cv|apply_undo_tailoring|cv_rewrite_instruction|quick_insight_request)$/.test(
      String(intent || "")
    );
  }

  function looksLikeUnsupportedCvClaimInstruction(value) {
    var clean = normalizeCareerIntentText(
      cleanMessageText(value || "")
    ).toLowerCase();
    if (!clean || clean.length > 220) {
      return false;
    }
    return (
      /\b(?:just\s+)?(?:add|say|claim|put|include|make it say|write that)\b.*\b(?:speak|speaks|arabic|french|spanish|python|sql|cfa|aca|acca|mba|goldman|mckinsey|managed|led|team of|deal|deals|\$|bn|million|billion)\b/i.test(
        clean
      ) ||
      /\bmake me sound more senior\b/i.test(clean) ||
      /\blie\b.*\b(?:cv|resume|application|experience)\b/i.test(clean)
    );
  }

  function getResponseExpectationSemanticIntent(text) {
    var clean = normalizeCareerIntentText(
      cleanMessageText(text || "")
    ).toLowerCase();
    if (!clean) {
      return "";
    }
    if (
      /^(?:hi|hello|hey|hiya|yo|salam|salaam|مرحبا|هلا|السلام عليكم)[!.\s]*$/i.test(
        clean
      )
    ) {
      return "greeting";
    }
    if (/^(?:hi|hey|hello)\s+emily,?\s+are you good[?!.]*$/i.test(clean)) {
      return "social_check";
    }
    if (
      /^(?:can i ask(?: you)?(?: something| a question)?|could i ask(?: you)?(?: something| a question)?|quick question|question first|before that)[!?.\s]*$/i.test(
        clean
      )
    ) {
      return "different_question";
    }
    if (
      /\b(?:form won'?t load|form will not load|refused to connect|employer site refused|blank screen|iframe|embed(?:ded)? form|apply button is broken)\b/i.test(
        clean
      )
    ) {
      return "application_process";
    }
    if (
      !/^(?:do not|don't)\s+add fake experience\b/i.test(clean) &&
      /\b(?:fake|scam|not real|not convinced|waste of time|too generic|parser is weak|wrong match|misunderstood|this sounds fake|that's not right|that is not right)\b/i.test(
        clean
      )
    ) {
      return "support_complaint";
    }
    if (
      /\b(?:can't log in|cant log in|forgot my password|reset password|password reset)\b/i.test(
        clean
      )
    ) {
      return "account_access_issue";
    }
    if (
      /\b(?:payment failed|card was declined|declined|checkout failed)\b/i.test(
        clean
      )
    ) {
      return "payment_support";
    }
    if (
      /\b(?:book a call|schedule a call|talk to a person|speak to someone)\b/i.test(
        clean
      )
    ) {
      return "call_scheduling";
    }
    if (
      /\b(?:cancel my subscription|cancel subscription|refund)\b/i.test(clean)
    ) {
      return "membership_cancellation";
    }
    if (
      /\b(?:need help finding a job|help finding a job|please suggest)\b/i.test(
        clean
      )
    ) {
      return "find_job";
    }
    if (
      /\b(?:i need|need|looking for|want)\s+(?:career\s+)?(?:guidance|advice|help)\b/i.test(
        clean
      )
    ) {
      return "career_direction";
    }
    if (
      /\b(?:don't want to pay|do not want to pay|pay before seeing value|not paying before seeing value)\b/i.test(
        clean
      )
    ) {
      return "affordability_objection";
    }
    if (
      /\b(?:salary|compensation|bonus|pay)\b/i.test(clean) &&
      !/^(?:my salary is|i(?:'m| am)? currently earning|i earn|i make|why i left was)\b/i.test(
        clean
      )
    ) {
      return "salary_question";
    }
    if (/^why do you need my name[?!.]*$/i.test(clean)) {
      return "why_name";
    }
    if (
      /^(?:be honest|keep testing|continue|next|ok continue|okay continue)\b/i.test(
        clean
      )
    ) {
      return "different_question";
    }
    if (/^(?:change it to|change this to)\s+\w+/i.test(clean)) {
      return "special_request";
    }
    if (
      /^(?:give me|show me)\s+(?:one\s+)?(?:quick\s+)?insights?\b/i.test(clean)
    ) {
      return "quick_insight_request";
    }
    if (
      /\b(?:compare|check|assess|review)\s+(?:my\s+)?(?:cv|resume|profile)\s+(?:against|for|with)\s+(?:this|the)\s+(?:role|job|position)\b/i.test(
        clean
      ) ||
      /\b(?:how|where)\s+(?:does|do)\s+(?:my\s+)?(?:cv|resume|profile)\s+(?:match|fit|compare)\s+(?:this|the)\s+(?:role|job|position)\b/i.test(
        clean
      )
    ) {
      return "quick_insight_request";
    }
    if (
      /^(?:rewrite\s*:|rewrite\b|improve\b|make\b)/i.test(clean) &&
      /\b(?:cv|resume|bullet|sentence|wording|senior|robotic|shorter|clearer|stronger)\b/i.test(
        clean
      )
    ) {
      return "cv_rewrite_instruction";
    }
    if (looksLikeUnsupportedCvClaimInstruction(clean)) {
      return "cv_rewrite_instruction";
    }
    return getResponseExpectationApplyControlIntent(clean);
  }

  function getResponseExpectationApplyControlIntent(text) {
    var clean = normalizeCareerIntentText(
      cleanMessageText(text || "")
    ).toLowerCase();
    if (!clean) {
      return "";
    }
    if (
      /^(?:start\s+)?auto\s+apply\b|^start applying\b|^apply to this role\b|^submit this application\b/i.test(
        clean
      )
    ) {
      return "apply_start_auto_apply";
    }
    if (
      /^(?:continue\s+)?applying in the background\b|^keep applying\b|^continue background\b/i.test(
        clean
      )
    ) {
      return "apply_continue_background";
    }
    if (
      /^(?:tailor|rewrite|improve|fix|optimise|optimize|strengthen)\s+(?:my\s+)?(?:cv|resume)\b|^tailor the cv\b/i.test(
        clean
      )
    ) {
      return "apply_tailor_cv";
    }
    if (
      /^(?:can i see|show me|open)\s+(?:the\s+)?tailored(?:\s+version)?\b/i.test(
        clean
      )
    ) {
      return "apply_review_tailored_cv";
    }
    if (
      /^(?:undo|revert)\s+(?:the\s+)?tailor|^use original cv\b|^use the original cv\b|^don'?t tailor it\b|^do not tailor it\b/i.test(
        clean
      )
    ) {
      return "apply_undo_tailoring";
    }
    if (/^apply with (?:the )?current cv\b|^apply as[- ]is\b/i.test(clean)) {
      return "apply_current_cv";
    }
    return "";
  }

  function isResponseExpectedSemanticIntent(intent) {
    return /^(?:different_question|special_request|role_question|about_senna|how_help|membership_benefits|pricing_trust|support_contact|data_safety|company_details|company_research|job_search_help|application_process|application_strategy|application_decision|application_follow_up|career_direction|profile_fit|rejection_analysis|interview_chance|cv_review_help|cv_improvement|cover_letter_help|linkedin_help|interview_prep|role_help|reassurance|search_apply|search_send_jobs|all_in_one|consistency_question|why_email|why_name|answer_correction|opportunity_search|get_hired_help|job_search_strategy|linkedin_visibility_strategy|hidden_market_roles|hiring_friction_diagnosis|market_activity|market_compensation_reality|uae_local_candidate_bias|location_preferences|salary_question|recruiter_networking|social_check|greeting|payment_support|account_access_issue|membership_cancellation|support_complaint|call_scheduling|technical_issue|hostile_product_complaint|affordability_objection|role_availability|matching_jobs|find_job|specific_role_interest|apply_current_cv|apply_original_cv|apply_start_auto_apply|apply_continue_background|apply_tailor_cv|apply_review_tailored_cv|apply_undo_tailoring|cv_rewrite_instruction|quick_insight_request)$/.test(
      String(intent || "")
    );
  }

  function containsProfanity(text) {
    return /\b(fuck|fucking|fucked|shit|shitty|bullshit|bitch|bastard|cunt|asshole|dickhead|motherfucker|piss off|wtf)\b/i.test(
      String(text || "")
    );
  }

  function detectPositiveProfanity(text) {
    var value = String(text || "");
    if (!containsProfanity(value)) {
      return false;
    }
    return (
      /\b(fuck|fucking|bloody|damn)\b.*\b(amazing|great|brilliant|helpful|useful|good|perfect|excellent|awesome|love|lovely|spot on)\b/i.test(
        value
      ) ||
      /\b(amazing|great|brilliant|helpful|useful|good|perfect|excellent|awesome|love)\b.*\b(fuck|fucking)\b/i.test(
        value
      )
    );
  }

  function detectDirectedAbusiveProfanity(text) {
    var value = String(text || "").toLowerCase();
    if (!containsProfanity(value)) {
      return false;
    }
    if (/\bfuck off\b|\bpiss off\b|\bfuck you\b|\bgo to hell\b/.test(value)) {
      return true;
    }
    if (
      /\b(i hate you|hate this app|hate this platform|you are useless|you're useless|youre useless|stupid ai|stupid agent|piece of shit|dumb bot)\b/.test(
        value
      )
    ) {
      return true;
    }
    if (
      /\b(you|your|emily|senna|this app|this platform|this site|this agent|team)\b.*\b(fuck|fucking|shit|shitty|bullshit|bitch|bastard|cunt|asshole|garbage|trash|useless)\b/.test(
        value
      )
    ) {
      return true;
    }
    if (
      /\b(fuck|fucking|shit|bullshit|asshole|garbage|trash|useless)\b.*\b(you|emily|senna|this app|this platform|this site|this agent|team)\b/.test(
        value
      )
    ) {
      return true;
    }
    return false;
  }

