  function shouldIgnoreClauseIntent(intent) {
    return (
      !intent ||
      /^(greeting|social_check|positive_emphasis|light_flirt|about_senna|off_topic|answer_correction)$/.test(
        intent
      )
    );
  }

  function getClauseIntentPriorityBoost(
    clauseText,
    clauseIntent,
    primaryIntent
  ) {
    var clean = normalizeCareerIntentText(cleanMessageText(clauseText || ""));
    var boost = 0;
    if (!clean) {
      return 0;
    }
    if (
      sourceTextMentionsSelectionCorrection(clean) ||
      /(?:\bbut\b|\bhowever\b|\binstead\b|\bactually\b|\brather\b|\bnot that\b|\bwrong\b|\bi want\b|\bi mean\b|لكن|بس|بدل|فعلاً|غلط|مو هذا|مش هذا|أقصد|اقصد)/i.test(
        clean
      )
    ) {
      boost += 40;
    }
    if (isCompoundKnowledgeIntent(clauseIntent)) {
      boost += 18;
    }
    if (
      primaryIntent === "recruiter_networking" &&
      /(?:fit|qualified|eligible|shortlist|interview|chance|requirements?|experience|skills)/i.test(
        clean
      )
    ) {
      boost += 18;
    }
    if (
      primaryIntent === "profile_fit" &&
      /(?:recruiter|recruiters|hiring manager|talent acquisition|contact|email|linkedin|follow up|follow-up)/i.test(
        clean
      )
    ) {
      boost += 18;
    }
    if (
      primaryIntent === "compare_roles" &&
      /(?:recruiter|contact|apply|follow up|follow-up|worth applying)/i.test(
        clean
      )
    ) {
      boost += 14;
    }
    if (
      primaryIntent === "career_direction" &&
      /(?:best fit|fit|realistic|eligible|apply|worth applying)/i.test(clean)
    ) {
      boost += 14;
    }
    return boost;
  }

  function inferClauseIntentFromClauseData(clause, clauseText) {
    var clean = normalizeCareerIntentText(cleanMessageText(clauseText || ""));
    var locations = clause && clause.locations ? clause.locations : [];
    var roles = clause && clause.roles ? clause.roles : [];
    var actions = clause && clause.actions ? clause.actions : [];
    var modifiers = clause && clause.modifiers ? clause.modifiers : [];
    if (!clean) {
      return "";
    }
    if (
      locations.length &&
      (actions.indexOf("want") !== -1 ||
        modifiers.indexOf("negation") !== -1 ||
        modifiers.indexOf("contrast") !== -1 ||
        /(?:focus on|only|instead|rather|move to|relocat|based in|not\s+[a-z]+|no\s+[a-z]+)/i.test(
          clean
        ))
    ) {
      return "location_preferences";
    }
    if (
      roles.length &&
      (actions.indexOf("want") !== -1 ||
        modifiers.indexOf("contrast") !== -1 ||
        /(?:instead|rather|focus on|not that|different role|another role|target|roles? like)/i.test(
          clean
        ))
    ) {
      return "role_targeting";
    }
    return "";
  }

  function extractClauseIntentSequence(sourceText, primaryIntent) {
    var semantics;
    var frame;
    var seen = {};
    if (!sourceText) {
      return [];
    }
    semantics = parseMessageSemantics(sourceText);
    frame = semantics.meaning_frame || {};
    if (!frame.clauses || frame.clauses.length <= 1) {
      return [];
    }
    return frame.clauses
      .map(function (clause) {
        var clauseText = cleanMessageText(clause && clause.text);
        var clauseIntent = clauseText ? detectIntent(clauseText) : "";
        var summary = summarizeMeaningTargets(
          {
            roles: clause.roles || [],
            locations: clause.locations || [],
            seniority: clause.seniority || [],
          },
          parseMessageSemantics(clauseText)
        );
        if (!clauseIntent) {
          clauseIntent = inferClauseIntentFromClauseData(clause, clauseText);
        }
        return {
          text: clauseText,
          intent: clauseIntent,
          summary: summary,
          score:
            getIntentPriorityScore(clauseIntent) +
            getClauseIntentPriorityBoost(
              clauseText,
              clauseIntent,
              primaryIntent
            ),
        };
      })
      .filter(function (item) {
        if (
          !item.text ||
          shouldIgnoreClauseIntent(item.intent) ||
          item.intent === primaryIntent
        ) {
          return false;
        }
        if (seen[item.intent]) {
          return false;
        }
        seen[item.intent] = true;
        return true;
      })
      .sort(function (a, b) {
        return b.score - a.score;
      })
      .slice(0, 3);
  }

