  function sourceTextMentionsRecruiterSelectionQuestion(text) {
    var clean = normalizeCareerIntentText(cleanMessageText(text || ""));
    return /(?:how do recruiters? select|how recruiters? select|what are recruiters? looking for|how do recruiter interviews work|what questions will they ask|what mistakes should i avoid|how can i impress them|what do recruiters? care about most|how do they shortlist|what makes a candidate stand out to recruiters?)/i.test(
      clean
    );
  }

  function sourceTextMentionsRecruiterQualityQuestion(text) {
    var clean = normalizeCareerIntentText(cleanMessageText(text || ""));
    return /(?:is this recruiter good|are they worth contacting|do they reply|do candidates recommend them|are they genuine|are they trustworthy|are they experienced|are they reputable|have people had success with them|are they active on linkedin|how responsive are they|what'?s their reputation|what is their reputation|what'?s their response rate|what is their response rate|do they usually fill these roles|do they actually recruit|is this recruiter legit|what makes a good recruiter|good recruiter|bad recruiter|reliable recruiter|trustworthy recruiter|legit recruiter|scam recruiter|fake recruiter|professional recruiter|experienced recruiter|senior recruiter|responsive recruiter|helpful recruiter|honest recruiter|recommended recruiter|top recruiter|highly rated recruiter|worth my time|should i bother)/i.test(
      clean
    );
  }

