  function rememberLanguageStatus(label, isConfirmed) {
    var cleanLabel = cleanMessageText(label);
    if (!cleanLabel) {
      return;
    }
    if (isConfirmed) {
      conversationFacts.confirmedLanguages = dedupeList(
        conversationFacts.confirmedLanguages.concat([cleanLabel])
      );
      conversationFacts.unconfirmedLanguages =
        conversationFacts.unconfirmedLanguages.filter(function (item) {
          return item !== cleanLabel;
        });
      addClarificationNote(cleanLabel + " confirmed for professional use");
      return;
    }
    conversationFacts.unconfirmedLanguages = dedupeList(
      conversationFacts.unconfirmedLanguages.concat([cleanLabel])
    );
    conversationFacts.confirmedLanguages =
      conversationFacts.confirmedLanguages.filter(function (item) {
        return item !== cleanLabel;
      });
    addClarificationNote(cleanLabel + " not confirmed for professional use");
  }

  function rememberQualificationStatus(label, isConfirmed) {
    var cleanLabel = cleanMessageText(label);
    if (!cleanLabel) {
      return;
    }
    if (isConfirmed) {
      conversationFacts.confirmedQualifications = dedupeList(
        conversationFacts.confirmedQualifications.concat([cleanLabel])
      );
      conversationFacts.unconfirmedQualifications =
        conversationFacts.unconfirmedQualifications.filter(function (item) {
          return item !== cleanLabel;
        });
      addClarificationNote(cleanLabel + " confirmed");
      return;
    }
    conversationFacts.unconfirmedQualifications = dedupeList(
      conversationFacts.unconfirmedQualifications.concat([cleanLabel])
    );
    conversationFacts.confirmedQualifications =
      conversationFacts.confirmedQualifications.filter(function (item) {
        return item !== cleanLabel;
      });
    addClarificationNote(cleanLabel + " not confirmed");
  }

  function rememberWorkAuthorizationStatus(statusValue) {
    var cleanStatus = cleanMessageText(statusValue).toLowerCase();
    if (!cleanStatus) {
      return;
    }
    conversationFacts.workAuthorizationStatus = cleanStatus;
    addClarificationNote("Work authorization status: " + cleanStatus);
    queueApplyChatMemoryPersist();
  }

  function normalizeClarificationLabel(label) {
    return cleanMessageText(label).toLowerCase();
  }

  function isLanguageResolved(label) {
    var normalized = normalizeClarificationLabel(label);
    return (
      conversationFacts.confirmedLanguages.some(function (item) {
        return normalizeClarificationLabel(item) === normalized;
      }) ||
      conversationFacts.unconfirmedLanguages.some(function (item) {
        return normalizeClarificationLabel(item) === normalized;
      })
    );
  }

  function isQualificationResolved(label) {
    var normalized = normalizeClarificationLabel(label);
    return (
      conversationFacts.confirmedQualifications.some(function (item) {
        return normalizeClarificationLabel(item) === normalized;
      }) ||
      conversationFacts.unconfirmedQualifications.some(function (item) {
        return normalizeClarificationLabel(item) === normalized;
      })
    );
  }

  function isWorkAuthorizationResolved() {
    return cleanMessageText(conversationFacts.workAuthorizationStatus) !== "";
  }

  function isClarificationGapResolved(gap) {
    if (!gap) {
      return false;
    }
    if (gap.type === "language") {
      return isLanguageResolved(gap.label);
    }
    if (gap.type === "qualification") {
      return isQualificationResolved(gap.label);
    }
    if (gap.type === "work_authorization") {
      return isWorkAuthorizationResolved();
    }
    return false;
  }

  function mergeCvFacts(analysis) {
    var matchedKeywords = (analysis && analysis.matched_keywords) || [];
    var missingKeywords = (analysis && analysis.missing_keywords) || [];
    var requirementGaps = (analysis && analysis.requirement_gaps) || [];
    var sharedCvText = getSharedCapturedCvText();
    var inferredLocations = inferCvLocationFacts(sharedCvText || "");
    var headerModel = sharedCvText
      ? buildCvHeaderModel(sharedCvText, parseCvSectionsFromText(sharedCvText))
      : null;

    cvFacts.experienceTitle = cleanMessageText(
      (analysis && analysis.experience_title) ||
        cvFacts.experienceTitle ||
        (headerModel && headerModel.headline) ||
        ""
    );
    cvFacts.experienceCompany = cleanMessageText(
      (analysis && analysis.experience_company) ||
        (analysis && analysis.company_signal) ||
        cvFacts.experienceCompany
    );
    cvFacts.experienceYears = Math.max(
      Number(cvFacts.experienceYears || 0),
      Number((analysis && analysis.experience_years) || 0) || 0
    );
    cvFacts.headerLocation = cleanMessageText(
      (analysis && analysis.location_signal) ||
        cvFacts.headerLocation ||
        inferredLocations.headerLocation
    );
    cvFacts.likelyCurrentLocation = cleanMessageText(
      cvFacts.likelyCurrentLocation ||
        inferredLocations.likelyCurrentLocation ||
        cvFacts.headerLocation
    );
    cvFacts.recentLocations = dedupeList(
      (cvFacts.recentLocations || []).concat(
        inferredLocations.recentLocations || []
      )
    );
    cvFacts.detectedQualifications = dedupeList(
      (cvFacts.detectedQualifications || []).concat(
        extractSearchQualifications(sharedCvText || "")
      )
    );
    cvFacts.detectedSkills = dedupeList(
      (cvFacts.detectedSkills || []).concat(
        extractSearchSkillSignals(sharedCvText || "")
      )
    );
    cvFacts.matchedKeywords = dedupeList(
      cvFacts.matchedKeywords.concat(matchedKeywords.filter(Boolean))
    );
    cvFacts.missingKeywords = dedupeList(
      cvFacts.missingKeywords.concat(missingKeywords.filter(Boolean))
    );
    cvFacts.requirementGapLabels = dedupeList(
      cvFacts.requirementGapLabels.concat(
        requirementGaps
          .map(function (gap) {
            return gap && gap.label ? cleanMessageText(gap.label) : "";
          })
          .filter(Boolean)
      )
    );
    cvFacts.requirementGapMessages = dedupeList(
      cvFacts.requirementGapMessages.concat(
        requirementGaps
          .map(function (gap) {
            return gap && gap.message ? cleanMessageText(gap.message) : "";
          })
          .filter(Boolean)
      )
    );
    syncCvFactsFromCanonicalProfile();
    syncCvMatchesWorkspaceState();
    syncApplyChatCanonicalState("cv_facts_merged");
  }

  function getCanonicalCvProfileForFactSync(profile) {
    if (profile) {
      return profile;
    }

    if (typeof getSafeCanonicalCvProfile === "function") {
      try {
        return getSafeCanonicalCvProfile({ debug: false }) || null;
      } catch (error) {
        recordConversationAuditEvent("canonical_cv_fact_sync_failed", {
          message: cleanMessageText((error && error.message) || ""),
        });
      }
    }

    if (typeof buildCanonicalCvProfile === "function") {
      try {
        return buildCanonicalCvProfile({ debug: false }) || null;
      } catch (error) {
        recordConversationAuditEvent("canonical_cv_fact_sync_failed", {
          message: cleanMessageText((error && error.message) || ""),
        });
      }
    }

    return null;
  }

  function syncCvFactsFromCanonicalProfile(profile) {
    var canonical = getCanonicalCvProfileForFactSync(profile);
    var title;
    var company;
    var locations;
    var skills;
    var qualifications;
    var laneLabels;
    if (!canonical || canonical.source !== "structured_service") {
      return false;
    }

    title = normalizeCvRoleTitleText(canonical.currentRole || "");
    if (title && safeIsRealCvRoleTitle(title)) {
      cvFacts.experienceTitle = title;
    }

    company = cleanMessageText(canonical.currentCompany || "");
    if (company) {
      cvFacts.experienceCompany = company;
    }

    cvFacts.experienceYears = Math.max(
      Number(cvFacts.experienceYears || 0),
      Number(canonical.totalYears || 0) || 0
    );
    conversationFacts.experienceYears = Math.max(
      Number(conversationFacts.experienceYears || 0),
      Number(canonical.totalYears || 0) || 0
    );

    locations = normalizeCanonicalCvList(
      []
        .concat(canonical.locations || [])
        .concat(canonical.location || [])
        .concat(
          (canonical.experienceTimeline || []).map(function (entry) {
            return (entry && entry.location) || "";
          })
        ),
      12
    );
    if (locations.length) {
      cvFacts.headerLocation = cleanMessageText(
        cvFacts.headerLocation || canonical.location || locations[0] || ""
      );
      cvFacts.likelyCurrentLocation = cleanMessageText(
        canonical.location || locations[0] || cvFacts.likelyCurrentLocation || ""
      );
      cvFacts.recentLocations = dedupeList(
        locations.concat(cvFacts.recentLocations || [])
      ).slice(0, 8);
    }

    skills = normalizeCanonicalCvList(
      []
        .concat(canonical.skills || [])
        .concat(canonical.tools || []),
      40
    );
    if (skills.length) {
      cvFacts.detectedSkills = dedupeList(
        skills.concat(cvFacts.detectedSkills || [])
      ).slice(0, 40);
    }

    qualifications = normalizeCanonicalCvList(
      canonical.qualifications || [],
      24
    );
    if (qualifications.length) {
      cvFacts.detectedQualifications = dedupeList(
        qualifications.concat(cvFacts.detectedQualifications || [])
      ).slice(0, 24);
    }

    laneLabels = normalizeCanonicalCvList(
      []
        .concat(canonical.targetableTitles || [])
        .concat((canonical.roleFamilies || []).map(getCvRoleFamilyLabel))
        .concat(canonical.industries || [])
        .concat(skills.slice(0, 8))
        .concat(qualifications.slice(0, 6)),
      32
    );
    if (laneLabels.length) {
      cvFacts.matchedKeywords = dedupeList(
        laneLabels.concat(cvFacts.matchedKeywords || [])
      ).slice(0, 40);
      conversationFacts.roleHints = dedupeList(
        (conversationFacts.roleHints || []).concat(
          (canonical.targetableTitles || []).slice(0, 6)
        )
      ).slice(0, 12);
    }

    queueApplyChatMemoryPersist();
    return true;
  }

  function normalizeDetectedSearchLocation(value) {
    var clean = cleanMessageText(value || "");
    var exact = extractSearchLocations(clean);
    if (exact.length) {
      return exact[0];
    }
    clean = clean
      .replace(/\b(?:united arab emirates)\b/i, "UAE")
      .replace(/\b(?:saudi arabia)\b/i, "Saudi Arabia")
      .replace(/\b(?:netherlands)\b/i, "Netherlands")
      .replace(/\b(?:united kingdom)\b/i, "UK");
    exact = extractSearchLocations(clean);
    return exact.length ? exact[0] : "";
  }

  function inferCvLocationFacts(text) {
    var clean = String(text || "");
    var sections;
    var headerModel;
    var topLines;
    var lines;
    var weighted = {};
    var recentLocations = [];
    var headerLocation = "";
    var likelyCurrentLocation = "";
    var phoneRegion = "";
    var regionFallbackMap = {
      UK: "UK",
      UAE: "UAE",
      "Saudi Arabia": "Saudi Arabia",
      Qatar: "Qatar",
      Bahrain: "Bahrain",
      Oman: "Oman",
      Kuwait: "Kuwait",
      France: "France",
      Switzerland: "Switzerland",
      Netherlands: "Netherlands",
      Egypt: "Egypt",
      Greece: "Greece",
      India: "India",
      Portugal: "Portugal",
      Morocco: "Morocco",
      Nigeria: "Nigeria",
      Bulgaria: "Bulgaria",
      Germany: "Germany",
      Spain: "Spain",
      Turkey: "Turkey",
      Singapore: "Singapore",
      "South Africa": "South Africa",
    };

    function isLikelyFutureLocationLine(sourceText) {
      var lower = normalizeCareerIntentText(sourceText);
      return (
        /(?:open to relocate|open for relocation|relocate to|relocating to|moving to|planning to move|available in|available from|seeking opportunities in|looking for roles in)/i.test(
          lower
        ) || lexiconMatchesAny(lower, chatSignalLexicon.locationIntent.future)
      );
    }

    function looksLikeLocationEvidenceLine(sourceText) {
      var line = cleanMessageText(sourceText);
      if (!line) {
        return false;
      }
      if (
        /^(?:location|address|based in|residing in|currently in|present location)\b/i.test(
          line
        )
      ) {
        return true;
      }
      if (/[|,]/.test(line)) {
        return true;
      }
      if (/@|linkedin|http/i.test(line)) {
        return true;
      }
      return /\b(?:street|road|avenue|tower|house|flat|city|country|uk|united kingdom|uae|united arab emirates|saudi arabia|qatar|bahrain|oman|kuwait|france|germany|spain|portugal|italy|egypt|greece|morocco|nigeria|bulgaria|india|pakistan|ireland|switzerland|netherlands|canada|south africa|singapore|turkey)\b/i.test(
        line
      );
    }

    function addWeightedLocations(sourceText, score, requireContext) {
      if (
        !cleanMessageText(sourceText) ||
        isLikelyFutureLocationLine(sourceText)
      ) {
        return;
      }
      if (requireContext && !looksLikeLocationEvidenceLine(sourceText)) {
        return;
      }
      extractSearchLocations(sourceText).forEach(function (location) {
        var cleanLocation = cleanMessageText(location);
        if (!cleanLocation) {
          return;
        }
        weighted[cleanLocation] = (weighted[cleanLocation] || 0) + score;
      });
    }

    if (!clean) {
      return {
        headerLocation: "",
        likelyCurrentLocation: "",
        recentLocations: [],
      };
    }

    sections = parseCvSectionsFromText(clean);
    headerModel = buildCvHeaderModel(clean, sections);
    headerLocation = normalizeDetectedSearchLocation(
      headerModel && headerModel.location && headerModel.location.label
    );
    phoneRegion = inferPhoneRegion(
      (headerModel && headerModel.phone) || findCvPhone(clean) || ""
    );
    topLines = getCvTopLines(clean, 16);
    lines = clean
      .split(/\n+/)
      .map(cleanMessageText)
      .filter(Boolean)
      .slice(0, 160);

    if (headerLocation) {
      weighted[headerLocation] = (weighted[headerLocation] || 0) + 14;
    }

    topLines.forEach(function (line, index) {
      addWeightedLocations(line, index < 8 ? 8 : 4, false);
    });

    lines.forEach(function (line, index) {
      var score = 0;
      if (isLikelyFutureLocationLine(line)) {
        return;
      }
      if (/\b(?:present|current|now|to date|till date)\b/i.test(line)) {
        score += 5;
      }
      if (/\b(?:202[4-9]|203\d)\b/i.test(line)) {
        score += 2;
      }
      if (index < 30) {
        score += 2;
      } else if (index < 80) {
        score += 1;
      }
      if (score > 0) {
        addWeightedLocations(line, score, true);
      }
    });

    recentLocations = Object.keys(weighted).sort(function (left, right) {
      return (weighted[right] || 0) - (weighted[left] || 0);
    });
    var strongestScore = recentLocations.length
      ? weighted[recentLocations[0]] || 0
      : 0;
    recentLocations = recentLocations
      .filter(function (location) {
        return (weighted[location] || 0) >= Math.max(3, strongestScore - 4);
      })
      .slice(0, 4);

    likelyCurrentLocation =
      headerLocation ||
      recentLocations[0] ||
      regionFallbackMap[phoneRegion] ||
      "";
    if (
      !headerLocation &&
      !recentLocations.length &&
      phoneRegion &&
      regionFallbackMap[phoneRegion]
    ) {
      recentLocations = dedupeList(
        [regionFallbackMap[phoneRegion]].concat(recentLocations)
      );
    }

    return {
      headerLocation: headerLocation,
      likelyCurrentLocation: likelyCurrentLocation,
      recentLocations: recentLocations,
    };
  }

  function ensureCvLocationFacts() {
    var inferred;
    var sharedCvText = getSharedCapturedCvText();
    if (
      (!sharedCvText || !cleanMessageText(sharedCvText)) &&
      !cvFacts.headerLocation &&
      !cvFacts.likelyCurrentLocation
    ) {
      return;
    }
    if (cvFacts.likelyCurrentLocation && cvFacts.recentLocations.length) {
      return;
    }
    inferred = inferCvLocationFacts(sharedCvText || "");
    cvFacts.headerLocation = cleanMessageText(
      cvFacts.headerLocation || inferred.headerLocation || ""
    );
    cvFacts.likelyCurrentLocation = cleanMessageText(
      cvFacts.likelyCurrentLocation || inferred.likelyCurrentLocation || ""
    );
    cvFacts.recentLocations = dedupeList(
      (cvFacts.recentLocations || []).concat(inferred.recentLocations || [])
    );
  }

  function describeCvProfile() {
    var parts = [];
    var titleCompany = [cvFacts.experienceTitle, cvFacts.experienceCompany]
      .filter(Boolean)
      .join(" at ");

    if (titleCompany) {
      parts.push(titleCompany);
    }
    if (cvFacts.experienceYears > 0) {
      parts.push(cvFacts.experienceYears + " years of visible experience");
    }
    if (cvFacts.likelyCurrentLocation) {
      parts.push("recently based around " + cvFacts.likelyCurrentLocation);
    }
    if (
      cvFacts.detectedQualifications &&
      cvFacts.detectedQualifications.length
    ) {
      parts.push(
        "qualifications like " + formatFactList(cvFacts.detectedQualifications)
      );
    }
    if (cvFacts.detectedSkills && cvFacts.detectedSkills.length) {
      parts.push("skills around " + formatFactList(cvFacts.detectedSkills));
    }
    if (cvFacts.matchedKeywords.length) {
      parts.push(
        "background around " + formatFactList(cvFacts.matchedKeywords)
      );
    }

    return parts.join(", ");
  }

  function getCandidateAwareSearchPrompt() {
    var searchFocus = describeConversationFocus();
    var cvProfile = describeCvProfile();
    if (cvProfile && searchFocus) {
      return (
        "You're closest to " +
        searchFocus +
        " from what I can see in " +
        cvProfile +
        ". Share your CV when you are ready, or tell me the roles and locations you want me to prioritise."
      );
    }
    if (cvProfile) {
      return (
        "Your background looks strongest around " +
        cvProfile +
        ". Share your CV when you are ready, or tell me the role types you want me to narrow in on."
      );
    }
    if (searchFocus) {
      return (
        "Got it. You're mainly looking at " +
        searchFocus +
        ". Share your CV when you are ready, or give me the roles and locations you want kept in play."
      );
    }
    return "Share your CV when you are ready, or tell me the roles and locations you want me to work with, and I'll narrow it from there.";
  }

  function getCandidateAwareCvPrompt() {
    var roleHint = conversationFacts.roleHints[0] || currentRoleTitle;
    var matchedFocus = cvFacts.matchedKeywords.length
      ? " especially around " + formatFactList(cvFacts.matchedKeywords)
      : conversationFacts.targetFunctions.length
      ? " especially around " +
        formatFactList(conversationFacts.targetFunctions)
      : "";

    return (
      "Share your CV and I'll look at how clearly it lines up with " +
      escapeHtml(roleHint) +
      matchedFocus +
      "."
    );
  }

