    function getManagedServiceFaqTokens(clean) {
      var stopWords = {
        a: true,
        an: true,
        and: true,
        are: true,
        be: true,
        do: true,
        does: true,
        for: true,
        i: true,
        if: true,
        in: true,
        is: true,
        it: true,
        me: true,
        my: true,
        of: true,
        on: true,
        or: true,
        the: true,
        this: true,
        to: true,
        we: true,
        what: true,
        when: true,
        where: true,
        who: true,
        will: true,
        with: true,
        you: true,
        your: true,
      };
      return clean
        .split(/\s+/)
        .map(function (token) {
          return token.replace(/(?:ing|ed|es|s)$/i, "");
        })
        .filter(function (token) {
          return token.length > 2 && !stopWords[token];
        });
    }

    function getManagedServiceFaqQuestionShape(clean, expanded) {
      return {
        asksCan: /\b(can|could|will|would|do|does|are|is)\b/.test(clean),
        asksHow: /\bhow\b/.test(clean),
        asksWhat: /\bwhat\b/.test(clean),
        asksWho: /\bwho\b/.test(clean),
        asksWhere: /\bwhere\b/.test(clean),
        asksWhen: /\bwhen\b/.test(clean),
        hasLocationTerm:
          /\b(dubai|riyadh|abu dhabi|london|mena|remote|relocat|location|market)\b/.test(
            clean
          ),
        negative:
          /\b(no|not|never|don't|do not|won't|cannot|can't|avoid|without)\b/.test(
            expanded
          ),
        urgent: /\b(urgent|asap|quickly|today|now|soon)\b/.test(expanded),
        multiPart:
          /\b(and|also|plus|as well|but)\b/.test(clean) ||
          /\?[^?]+\?/.test(clean),
      };
    }

