    function getManagedSearchSampleItems() {
      var mainItem = normalizeCommercialApplyQueueItem(
        getCommercialApplyQueueMainItem(),
        "Ready"
      );
      var seen = {};
      var items = [];
      function add(item, status) {
        var normalized = normalizeCommercialApplyQueueItem(
          item || {},
          status || "In Queue"
        );
        var comparableKey = getCommercialApplyQueueComparableKey(normalized);
        if (!normalized.title || !comparableKey || seen[comparableKey]) {
          return;
        }
        seen[comparableKey] = true;
        items.push(normalized);
      }
      add(mainItem, "Ready");
      filterMatchingRoles()
        .concat(getJobsWorkspaceSourceItems())
        .forEach(function (item) {
          if (items.length >= 8) {
            return;
          }
          add(item, "In Queue");
        });
      return items;
    }

