    function getCurrentRoleRecruiterSummary() {
      var item = getCurrentRoleSeedItem();
      var recruiter = getRoleRecruiterPreview(item);
      return {
        name: recruiter.name,
        title: recruiter.title,
        company: recruiter.company,
        email: recruiter.email,
        linkedin: recruiter.linkedin,
        phone: recruiter.phone,
        avatar: recruiter.avatar,
        maskedName: maskRecruiterNameForDisplay(recruiter.name),
        hasRecruiter: !!recruiter.name,
      };
    }

    function getSalaryRegionLabel(text) {
      var clean = cleanMessageText(text || "").toLowerCase();
      if (!clean) {
        return "";
      }
      if (
        clean.indexOf("london") !== -1 ||
        clean.indexOf("united kingdom") !== -1 ||
        clean === "uk"
      ) {
        return "London";
      }
      if (clean.indexOf("paris") !== -1 || clean.indexOf("france") !== -1) {
        return "Paris";
      }
      if (clean.indexOf("milan") !== -1 || clean.indexOf("italy") !== -1) {
        return "Milan";
      }
      if (
        clean.indexOf("amsterdam") !== -1 ||
        clean.indexOf("netherlands") !== -1
      ) {
        return "Amsterdam";
      }
      if (
        clean.indexOf("dubai") !== -1 ||
        clean.indexOf("abu dhabi") !== -1 ||
        clean.indexOf("united arab emirates") !== -1 ||
        clean === "uae"
      ) {
        return "Dubai";
      }
      if (
        clean.indexOf("riyadh") !== -1 ||
        clean.indexOf("jeddah") !== -1 ||
        clean.indexOf("saudi") !== -1 ||
        clean.indexOf("ksa") !== -1 ||
        clean.indexOf("kingdom of saudi arabia") !== -1
      ) {
        return "Riyadh";
      }
      return "";
    }

    function getRegionalSalaryGuideCurrency(regionLabel) {
      if (regionLabel === "Dubai" || regionLabel === "UAE") {
        return "AED";
      }
      if (regionLabel === "Riyadh") {
        return "SAR";
      }
      if (regionLabel === "Doha") {
        return "QAR";
      }
      return "";
    }

    function formatSalaryBand(min, max, currency) {
      var cleanCurrency = cleanMessageText(currency || "");
      var minValue = Number(min || 0);
      var maxValue = Number(max || 0);
      if (!minValue && !maxValue) {
        return "";
      }
      if (minValue && maxValue) {
        return (
          (cleanCurrency ? cleanCurrency + " " : "") +
          Number(minValue).toLocaleString() +
          " - " +
          Number(maxValue).toLocaleString()
        );
      }
      if (minValue) {
        return (
          (cleanCurrency ? cleanCurrency + " " : "") +
          Number(minValue).toLocaleString() +
          "+"
        );
      }
      return (
        "Up to " +
        (cleanCurrency ? cleanCurrency + " " : "") +
        Number(maxValue).toLocaleString()
      );
    }

    function getCurrentMatchingSalarySummary() {
      var items = filterMatchingRoles();
      var mins = [];
      var maxes = [];
      var currencies = {};
      items.forEach(function (item) {
        var minValue = Number(item.salary_min || 0);
        var maxValue = Number(item.salary_max || 0);
        var cleanCurrency = cleanMessageText(item.salary_currency || "");
        if (minValue) {
          mins.push(minValue);
        }
        if (maxValue) {
          maxes.push(maxValue);
        }
        if (cleanCurrency) {
          currencies[cleanCurrency] = (currencies[cleanCurrency] || 0) + 1;
        }
      });
      var primaryCurrency =
        Object.keys(currencies).sort(function (a, b) {
          return currencies[b] - currencies[a];
        })[0] || "";
      return {
        count: items.length,
        min: mins.length ? Math.min.apply(Math, mins) : 0,
        max: maxes.length ? Math.max.apply(Math, maxes) : 0,
        currency: primaryCurrency,
      };
    }

    function getRegionalSalaryGuideSummary() {
      var locationLabel = getSalaryRegionLabel(
        jobSearchPreferredLocation || roleLocation || ""
      );
      var terms = getJobSearchMatchingTerms();
      var roleTerms = dedupeList(
        terms.reduce(function (carry, term) {
          return carry.concat(getMatchingRoleTitleTerms(term));
        }, [])
      );
      var ranked = matchingSalaryGuidesSeed
        .map(function (item) {
          var region = getSalaryRegionLabel(item.region || item.title || "");
          var haystack = cleanMessageText(
            [item.title, item.role, item.region, item.experience_level].join(
              " "
            )
          ).toLowerCase();
          var score = 0;

          if (locationLabel && region === locationLabel) {
            score += 12;
          } else if (locationLabel === "Dubai" && region === "Abu Dhabi") {
            score += 7;
          } else if (locationLabel === "Abu Dhabi" && region === "Dubai") {
            score += 7;
          } else if (locationLabel === "Riyadh" && region === "Saudi Arabia") {
            score += 7;
          }

          roleTerms.forEach(function (term) {
            if (haystack.indexOf(term) !== -1) {
              score += 5;
            }
          });

          return {
            item: item,
            score: score,
            region: region,
          };
        })
        .filter(function (entry) {
          return (
            entry.score > 0 &&
            (Number(entry.item.salary_min || 0) ||
              Number(entry.item.salary_max || 0))
          );
        })
        .sort(function (a, b) {
          return b.score - a.score;
        })
        .slice(0, 6);

      if (!ranked.length) {
        return {
          count: 0,
          min: 0,
          max: 0,
          currency: getRegionalSalaryGuideCurrency(locationLabel),
          region: locationLabel,
          roleLabel: "",
        };
      }

      var mins = [];
      var maxes = [];
      ranked.forEach(function (entry) {
        var minValue = Number(entry.item.salary_min || 0);
        var maxValue = Number(entry.item.salary_max || 0);
        if (minValue) {
          mins.push(minValue);
        }
        if (maxValue) {
          maxes.push(maxValue);
        }
      });

      return {
        count: ranked.length,
        min: mins.length ? Math.min.apply(Math, mins) : 0,
        max: maxes.length ? Math.max.apply(Math, maxes) : 0,
        currency: getRegionalSalaryGuideCurrency(
          ranked[0].region || locationLabel
        ),
        region: ranked[0].region || locationLabel,
        roleLabel: cleanMessageText(
          ranked[0].item.role || ranked[0].item.title || ""
        ),
      };
    }

    function getMatchingRolesFilterCacheState() {
      var cvProfile = buildCvRoleMatchProfile({ cvOnly: true }) || {};
      return JSON.stringify({
        roleTitle: cleanMessageText(roleTitle || ""),
        terms: getJobSearchMatchingTerms(),
        locationFilters: getJobSearchLocationFilters(false),
        qualifications: dedupeList(
          (conversationFacts.targetQualifications || [])
            .concat((cvProfile && cvProfile.qualifications) || [])
            .concat(cvFacts.detectedQualifications || [])
            .map(function (item) {
              return cleanMessageText(item).toLowerCase();
            })
            .filter(Boolean)
        ).slice(0, 12),
        skills: dedupeList(
          (conversationFacts.targetSkills || [])
            .concat((cvProfile && cvProfile.skills) || [])
            .concat(cvFacts.detectedSkills || [])
            .map(function (item) {
              return cleanMessageText(item).toLowerCase();
            })
            .filter(Boolean)
        ).slice(0, 18),
        desiredYears: Math.max(
          Number(conversationFacts.experienceYears || 0),
          Number((cvProfile && cvProfile.years) || 0) || 0,
          Number(cvFacts.experienceYears || 0) || 0
        ),
        seedSize: Array.isArray(matchingRolesSeed)
          ? matchingRolesSeed.length
          : 0,
      });
    }

