        recentYears: timeline[0] && timeline[0].months
          ? Number((timeline[0].months / 12).toFixed(1))
          : 0,
        seniorityLevel:
          Number((currentEntry && currentEntry.seniorityLevel) || 0) ||
          maxSeniority,
