    function getApplyForMeSenioritySearchLabel(level) {
      if (level >= 10) {
        return "director";
      }
      if (level >= 8) {
        return "vice president";
      }
      if (level >= 6) {
        return "manager";
      }
      if (level >= 4) {
        return "associate";
      }
      if (level >= 2) {
        return "analyst";
      }
      return "intern";
    }

    function detectApplyForMeCvSignals(cvText, analysis) {
      var text = normalizeApplyForMeSignalText(
        [
          cvText,
          analysis && analysis.experience_title,
          analysis && analysis.experience_company,
          ((analysis && analysis.matched_keywords) || []).join(" "),
          analysis &&
            analysis.profile_review_ontology &&
            analysis.profile_review_ontology.role_archetype,
        ]
          .filter(Boolean)
          .join(" ")
      );
      var seniorityScores = [];
      var actionScores = [];
      var sectorScores = [];
      var functionScores = [];
      var titleLevel = null;
      var actionLevel = 2;
      var demonstratedLevel;

      getApplyForMeSenioritySignals().forEach(function (group) {
        var result = scoreApplyForMeSignalGroup(
          text,
          group.terms.map(function (term) {
            return { phrases: [term], weight: group.level >= 8 ? 4 : 3 };
          })
        );
        if (result.score > 0) {
          seniorityScores.push({
            level: group.level,
            label: group.label,
            score: result.score,
            hits: result.hits,
          });
        }
      });
      seniorityScores.sort(function (a, b) {
        if (b.score !== a.score) {
          return b.score - a.score;
        }
        return b.level - a.level;
      });
      if (seniorityScores[0]) {
        titleLevel = seniorityScores[0].level;
      }

      getApplyForMeActionSignalGroups().forEach(function (group) {
        var result = scoreApplyForMeSignalGroup(
          text,
          group.terms.map(function (term) {
            return { phrases: [term], weight: group.weight };
          })
        );
        if (result.score > 0) {
          actionScores.push({
            band: group.band,
            level: group.level,
            score: result.score,
            hits: result.hits,
          });
        }
      });
      actionScores.sort(function (a, b) {
        if (b.score !== a.score) {
          return b.score - a.score;
        }
        return b.level - a.level;
      });
      if (actionScores[0]) {
        actionLevel = actionScores[0].level;
      }
      if (
        /\b(managed|led|supervised|mentored|coached)\s+(?:a\s+)?team\s+(?:of\s+)?\d+/i.test(
          text
        )
      ) {
        actionLevel = Math.max(actionLevel, 7);
      }
      if (
        /\b(board|investment committee|executive committee|c-suite|senior stakeholders)\b/i.test(
          text
        )
      ) {
        actionLevel = Math.max(actionLevel, 7);
      }
      if (
        /\b([£$€]\s?\d+|\d+(?:\.\d+)?\s?(?:m|mm|bn|million|billion))\b/i.test(
          text
        ) &&
        /\b(owned|delivered|generated|grew|secured|raised|won|reduced|increased|managed)\b/i.test(
          text
        )
      ) {
        actionLevel = Math.max(actionLevel, 8);
      }
      demonstratedLevel =
        titleLevel === null
          ? actionLevel
          : Math.round(titleLevel * 0.65 + actionLevel * 0.35);

      getApplyForMeSectorSignals().forEach(function (group) {
        var result = scoreApplyForMeSignalGroup(text, [
          { phrases: group.phrases, weight: group.weight },
        ]);
        if (result.score > 0) {
          sectorScores.push({
            key: group.key,
            label: group.label,
            query: group.query,
            score: result.score,
            hits: result.hits,
          });
        }
      });
      sectorScores.sort(function (a, b) {
        return b.score - a.score;
      });

      getApplyForMeFunctionSignals().forEach(function (group) {
        var result = scoreApplyForMeSignalGroup(text, [
          { phrases: group.phrases, weight: 3 },
        ]);
        if (result.score > 0) {
          functionScores.push({
            label: group.label,
            query: group.query,
            score: result.score,
            hits: result.hits,
          });
        }
      });
      functionScores.sort(function (a, b) {
        return b.score - a.score;
      });

      return {
        seniority: {
          title_level: titleLevel,
          title_label: seniorityScores[0] ? seniorityScores[0].label : "",
          demonstrated_level: demonstratedLevel,
          demonstrated_label:
            getApplyForMeSenioritySearchLabel(demonstratedLevel),
          action_band: actionScores[0] ? actionScores[0].band : "",
          signals: seniorityScores.slice(0, 4),
          action_signals: actionScores.slice(0, 4),
        },
        sectors: sectorScores.slice(0, 6),
        functions: functionScores.slice(0, 4),
      };
    }

    function combineApplyForMeQuery(base, seniority) {
      var cleanBase = cleanMessageText(base || "");
      var cleanSeniority = cleanMessageText(seniority || "");
      if (!cleanBase) {
        return cleanSeniority;
      }
      if (
        /\b(?:analyst|associate|assistant|manager|director|consultant|advisor|adviser|specialist|officer|banker|accountant|auditor|controller|engineer|developer|principal|avp|vp|vice president|intern|internship|trainee|graduate|executive|partner|supervisor|chief)\b/i.test(
          cleanBase
        )
      ) {
        return cleanBase;
      }
      if (
        cleanSeniority &&
        new RegExp(
          "\\b" + cleanSeniority.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b",
          "i"
        ).test(cleanBase)
      ) {
        return cleanBase;
      }
      return cleanMessageText(cleanBase + " " + cleanSeniority);
    }

    function isUsefulApplyForMeRoleDiscoveryQuery(query) {
      var clean = cleanMessageText(query || "");
      var words = clean.split(/\s+/).filter(Boolean);
      if (!clean || clean.length < 3) {
        return false;
      }
      if (
        /(?:^|\b)(?:19|20)\d{2}\b|(?:^|\b)(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\s+(?:19|20)?\d{2}\b|\b(?:present|current)\b/i.test(
          clean
        ) &&
        !hasCoreCvRoleKeyword(clean)
      ) {
        return false;
      }
      if (
        /^(?:education|academic|academics|school|schools|college|university|universities|degree|bachelor(?:'s|s)? degree|master(?:'s|s)? degree|msc|bsc|ba|ma|qualification|qualifications|certification|certifications|professional qualifications|skills|technical skills|other skills|experience|relevant experience|work experience|professional experience|employment history|projects|personal projects|profile|personal profile|summary|professional summary|personal statement|objective|career objective|contact|languages|interests|references|finance exam|investment analysis final exam)$/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        words.length === 1 &&
        /^(?:education|academic|student|member|team|coursework|project|projects|exam|merit|grade|school|university|college|degree|qualification|qualifications|certification|certifications|language|languages|skill|skills|experience|profile|statement|summary|finance|investment|analysis|management)$/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:university|college|school|msc|bsc|ba|ma|bachelor|master|diploma|coursework|module|modules|exam|education|qualification|certification|certificate|language|languages)\b/i.test(
          clean
        ) &&
        !hasCvRoleKeyword(clean)
      ) {
        return false;
      }
      if (
        /\b(?:road|street|avenue|drive|lane|london|dubai|riyadh|doha|abu dhabi|singapore|united kingdom|united arab emirates|saudi arabia|qatar|email|phone|linkedin|www\.|https?)\b/i.test(
          clean
        ) &&
        !hasCoreCvRoleKeyword(clean)
      ) {
        return false;
      }
      return true;
    }

    function normalizeApplyForMeCvRoleQuery(line) {
      var clean = safeNormalizeCvRoleTitleText(line || "")
        .replace(/\b(?:team member|member|candidate|student)\b/gi, " ")
        .replace(/\s*\/\s*/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      var match;
      var roleTitleNounPattern =
        /\b(?:analyst|associate|assistant|manager|director|consultant|advisor|adviser|specialist|officer|banker|accountant|auditor|controller|engineer|developer|principal|avp|vp|vice president|intern|internship|trainee|graduate|executive|partner|supervisor|chief)\b/i;
      if (
        !clean ||
        looksLikeCvEducationOrObjectiveFragment(clean) ||
        !roleTitleNounPattern.test(clean)
      ) {
        return "";
      }
      match = clean.match(
        /\b(?:(?:junior|senior|lead|assistant|associate|executive|investment|financial|business|research|credit|risk|portfolio|technical|quantitative|data|finance|corporate|strategy|operations|compliance|project|product|fund|management|commercial|customer|success)\s+){0,4}(?:analyst|associate|manager|director|consultant|advisor|adviser|specialist|officer|banker|accountant|auditor|controller|engineer|developer|principal|avp|vp|vice president|intern|internship|trainee)\b/i
      );
      if (match && match[0]) {
        clean = safeNormalizeCvRoleTitleText(match[0]);
      } else if (!roleTitleNounPattern.test(clean)) {
        return "";
      } else if (clean.split(/\s+/).length > 5) {
        return "";
      }
      if (/^(?:[-–—/:;|]+|\W{2,})/.test(clean)) {
        return "";
      }
      if (
        /\b(?:worked|working|responsible|supported|assisted|managed|led|developed|created|prepared|reported|collaborated|communicated|skilled|passionate|keen|experience|expertise|currently|seeking|targeting)\b/i.test(
          clean
        )
      ) {
        return "";
      }
      return safeIsRealCvRoleTitle(clean) &&
        isUsefulApplyForMeRoleDiscoveryQuery(clean)
        ? clean
        : "";
    }

    function extractApplyForMeCvRoleTitleQueries(analysis) {
      var text = String(capturedCvText || "");
      var normalizedText = normalizeApplyForMeSignalText(text);
      var queries = [];
      var lines = text
        .split(/\r?\n/)
        .map(function (line) {
          return cleanMessageText(line || "");
        })
        .filter(Boolean)
        .slice(0, 140);

      [
        analysis && analysis.experience_title,
        analysis &&
          analysis.profile_review_ontology &&
          analysis.profile_review_ontology.role_archetype,
      ].forEach(function (item) {
        var query = normalizeApplyForMeCvRoleQuery(item);
        if (query) {
          queries.push(query);
        }
      });

      if (
        /\b(?:investment fund|portfolio|equities|stocks|asset pricing|bloomberg|dcf|m&a|valuation|financial modelling|financial modeling|corporate finance|investment analysis|monte carlo|capital markets)\b/i.test(
          normalizedText
        )
      ) {
        queries.push("investment analyst", "financial analyst");
      }
      if (
        /\b(?:credit valuation|credit risk|credit analyst|credit underwriting|structured credit|fixed income)\b/i.test(
          normalizedText
        )
      ) {
        queries.push("credit analyst");
      }
      if (
        /\b(?:portfolio management|asset management|fund performance|investment mandate|aum)\b/i.test(
          normalizedText
        )
      ) {
        queries.push("portfolio analyst", "asset management analyst");
      }

      lines.forEach(function (line, index) {
        var nearbyExperience =
          lines
            .slice(Math.max(0, index - 4), Math.min(lines.length, index + 5))
            .join(" ")
            .search(
              /\b(?:experience|employment|work history|internship|investment fund|professional experience|relevant experience)\b/i
            ) !== -1;
        var query;
        if (
          looksLikeCvEducationOrObjectiveFragment(line) ||
          (!nearbyExperience &&
            !/\b(?:analyst|associate|manager|director|intern|consultant|advisor|specialist|officer|banker|accountant|auditor|project manager)\b/i.test(
              line
            ))
        ) {
          return;
        }
        query = normalizeApplyForMeCvRoleQuery(line);
        if (query) {
          queries.push(query);
        }
      });

      return uniqueCleanItems(queries).slice(0, 6);
    }

    function getApplyForMeCvFamilySearchBase(familyKey) {
      switch (cleanMessageText(familyKey || "")) {
        case "investment":
          return "investment";
        case "credit":
          return "credit";
        case "human_resources":
          return "human resources";
        case "accounting":
          return "finance";
        case "risk_compliance":
          return "risk";
        case "operations":
          return "operations";
        case "commercial":
          return "commercial";
        case "technology":
          return "data";
        case "supply_chain":
          return "supply chain";
        case "treasury":
          return "treasury";
        case "corporate_finance":
          return "corporate finance";
        default:
          return cleanMessageText(getCvRoleFamilyLabel(familyKey) || familyKey);
      }
    }

    function getApplyForMeProfileSenioritySearchLabel(profile) {
      var level = Number(
        (profile && (profile.currentSeniorityLevel || profile.maxSeniorityLevel)) ||
          0
      );
      var title = cleanMessageText((profile && profile.title) || "");
      if (/\b(?:intern|internship|trainee|graduate)\b/i.test(title)) {
        return "analyst";
      }
      if (/\b(?:associate)\b/i.test(title)) {
        return "associate";
      }
      if (/\b(?:manager|lead|head|director|vp|vice president)\b/i.test(title)) {
        return level >= 8 ? "director" : "manager";
      }
      return getApplyForMeSenioritySearchLabel(level || 3) || "analyst";
    }

    function buildApplyForMeProfileDrivenQueries(profile) {
      var cvProfile = profile || buildCvRoleMatchProfile({ cvOnly: true }) || {};
      var seniority = getApplyForMeProfileSenioritySearchLabel(cvProfile);
      var queries = [];
      var familyBases = [];
      var titleQueries = [];
      if (
        !cvProfile ||
        (!cvProfile.title &&
          !(cvProfile.roleContexts || []).length &&
          !(cvProfile.skills || []).length &&
          !(cvProfile.families || []).length)
      ) {
        return [];
      }

      queries = queries.concat(cvProfile.recommendedQueries || []);

      titleQueries = uniqueCleanItems(
        [
          cvProfile.title,
          cvProfile.directRecentRole,
        ]
          .concat(
            ((cvProfile.roleContexts || []).map(function (context) {
              return (context && (context.role || context.label)) || "";
            }) || [])
          )
          .concat(
            cvProfile.canonicalProfile &&
              cvProfile.canonicalProfile.targetableTitles
              ? cvProfile.canonicalProfile.targetableTitles
              : []
          )
          .map(normalizeApplyForMeCvRoleQuery)
          .filter(Boolean)
      ).slice(0, 5);
      queries = queries.concat(titleQueries);

      familyBases = uniqueCleanItems(
        (cvProfile.families || [])
          .map(getApplyForMeCvFamilySearchBase)
          .filter(Boolean)
      ).slice(0, 4);
      familyBases.forEach(function (base) {
        queries.push(combineApplyForMeQuery(base, seniority));
      });

      if (
        (cvProfile.skills || []).some(function (skill) {
          return /\b(?:valuation|financial modelling|financial modeling|lbo|dcf|due diligence|investment analysis|portfolio management|equity research)\b/i.test(
            skill
          );
        })
      ) {
        queries.push(combineApplyForMeQuery("investment", seniority));
        queries.push(combineApplyForMeQuery("financial", seniority));
      }
      if (
        (cvProfile.skills || []).some(function (skill) {
          return /\b(?:credit analysis|credit risk|underwriting|debt)\b/i.test(
            skill
          );
        })
      ) {
        queries.push(combineApplyForMeQuery("credit", seniority));
      }
      if (
        (cvProfile.skills || []).some(function (skill) {
          return /\b(?:accounting|audit|fp&a|treasury|financial analysis|tax)\b/i.test(
            skill
          );
        })
      ) {
        queries.push(combineApplyForMeQuery("finance", seniority));
      }
      if (
        (cvProfile.skills || []).some(function (skill) {
          return /\b(?:python|sql|power bi|tableau|data|analytics)\b/i.test(
            skill
          );
        })
      ) {
        queries.push(combineApplyForMeQuery("data", seniority));
      }
      if (
        (cvProfile.skills || []).some(function (skill) {
          return /\b(?:human resources|hr operations|talent acquisition|recruitment|payroll|employee relations|onboarding|benefits administration|compensation|performance management|workforce planning|hr systems)\b/i.test(
            skill
          );
        })
      ) {
        queries.push(combineApplyForMeQuery("human resources", seniority));
        queries.push(combineApplyForMeQuery("recruitment", seniority));
      }

      return uniqueCleanItems(queries)
        .filter(function (query) {
          return !isApplyForMeBlockedCvQuery(query, cvProfile);
        })
        .filter(isUsefulApplyForMeRoleDiscoveryQuery)
        .slice(0, 12);
    }

    function isApplyForMeBlockedCvQuery(query, profile) {
      var clean = cleanMessageText(query || "").toLowerCase();
      var blocked = (profile && profile.blockedQueries) || [];
      if (!clean) {
        return false;
      }
      return blocked.some(function (item) {
        var blockedQuery = cleanMessageText(item || "").toLowerCase();
        return blockedQuery && clean === blockedQuery;
      });
    }

    function buildApplyForMeCvSignalQueries(analysis) {
      var profileQueries = buildApplyForMeProfileDrivenQueries();
      var signals = detectApplyForMeCvSignals(
        capturedCvText || "",
        analysis || {}
      );
      var seniority = signals.seniority.demonstrated_label || "analyst";
      var sectors = signals.sectors || [];
      var functions = signals.functions || [];
      var queries = [];

      sectors.slice(0, 4).forEach(function (sector) {
        if (!sector.query || sector.score < 4) {
          return;
        }
        queries.push(combineApplyForMeQuery(sector.query, seniority));
      });
      functions.slice(0, 3).forEach(function (item) {
        if (!item.query || item.score < 3) {
          return;
        }
        queries.push(combineApplyForMeQuery(item.query, seniority));
      });
      if (
        (seniority === "analyst" || seniority === "associate") &&
        !profileQueries.length
      ) {
        queries.push("investment " + seniority);
        queries.push("financial " + seniority);
      }
      if (
        sectors.some(function (sector) {
          return sector.key === "private_equity" && sector.score >= 4;
        })
      ) {
        queries.push(combineApplyForMeQuery("private equity", seniority));
      }
      if (
        sectors.some(function (sector) {
          return sector.key === "asset_management" && sector.score >= 4;
        })
      ) {
        queries.push(combineApplyForMeQuery("asset management", seniority));
      }
      if (
        sectors.some(function (sector) {
          return sector.key === "investment_banking" && sector.score >= 4;
        })
      ) {
        queries.push(combineApplyForMeQuery("investment banking", seniority));
      }
      if (
        functions.some(function (item) {
          return item.query === "corporate finance" && item.score >= 3;
        })
      ) {
        queries.push(combineApplyForMeQuery("corporate finance", seniority));
      }
      return uniqueCleanItems(profileQueries.concat(queries))
        .filter(isUsefulApplyForMeRoleDiscoveryQuery)
        .slice(0, 12);
    }

    function getApplyForMeSearchTermsFromCvText(analysis) {
      return (
        buildApplyForMeCvSignalQueries(analysis || {})[0] ||
        extractApplyForMeCvRoleTitleQueries(analysis || {})[0] ||
        "financial analyst"
      );
    }

    function getApplyForMeRoleDiscoveryQueries(analysis) {
      var ontology = (analysis && analysis.profile_review_ontology) || {};
      var directQueries = [roleTitle, standaloneProfileReviewTargetRole];
      var contextualQueries =
        activePath === "apply_for_me_role_discovery"
          ? []
          : [
              jobSearchSeedContext && jobSearchSeedContext.roleTarget,
              jobSearchSeedContext && jobSearchSeedContext.query,
              conversationFacts.targetFunctions &&
                conversationFacts.targetFunctions[0],
            ];
      var cvQueries = buildApplyForMeCvSignalQueries(analysis || {});
      var profileQueries = buildApplyForMeProfileDrivenQueries();
      var cvProfile = buildCvRoleMatchProfile({ cvOnly: true }) || {};
      var cvRoleTitleQueries = extractApplyForMeCvRoleTitleQueries(
        analysis || {}
      );
      var analysisQueries = [
        normalizeApplyForMeCvRoleQuery(analysis && analysis.experience_title),
        normalizeApplyForMeCvRoleQuery(ontology.role_archetype),
      ];
      var combined = uniqueCleanItems(
        directQueries
          .concat(profileQueries)
          .concat(cvRoleTitleQueries)
          .concat(analysisQueries)
          .concat(cvQueries)
          .concat(contextualQueries)
      )
        .filter(function (query) {
          return !isApplyForMeBlockedCvQuery(query, cvProfile);
        })
        .filter(isUsefulApplyForMeRoleDiscoveryQuery);
      if (!combined.length) {
        combined = ["financial analyst", "investment analyst"];
      }
      return combined.slice(0, 14);
    }

    function getApplyForMeRoleDiscoveryQuery(analysis) {
      return (
        getApplyForMeRoleDiscoveryQueries(analysis || {})[0] ||
        "financial analyst"
      );
    }

    function getApplyForMeDiscoveryOpeningCopy() {
      if (!hasApplyForMeSelectedJobContext()) {
        if (hasApplyChatCvAvailable()) {
          var cvProfile = buildCvRoleMatchProfile({ cvOnly: true }) || {};
          var cvFocus = cleanCvRoleDisplayLabel(
            cvProfile.title || "",
            cvProfile.locations || []
          );
          var cvLanes = getCvDisplayLaneLabels(cvProfile, null, []).slice(0, 2);
          var cvDirection =
            cvFocus ||
            (cvLanes.length ? formatNaturalList(cvLanes) : "") ||
            "";
          return pickVariant("apply_discovery_opening_with_cv", [
            cvDirection
              ? "I already have your CV profile. I’ll search from " +
                cvDirection +
                " and keep the results tied to the evidence in the CV."
              : "I already have your CV profile. Tell me the role, sector, company, or location you want next and I’ll search from the parsed background.",
            cvDirection
              ? "Your CV is already attached to this search. I’ll use " +
                cvDirection +
                " as the starting lane unless you want me to widen it."
              : "Your CV is already attached to this search, so I can use the parsed background instead of asking you to upload it again.",
            cvDirection
              ? "I can continue from the CV I have. The clearest lane is " +
                cvDirection +
                "; tell me if you want that narrowed by market, sector, or company."
              : "I can continue from the CV I have. Send a target market or role family and I’ll narrow the live results from there.",
          ]);
        }
        if (hasPremiumMemberChatAccess()) {
          var memberCtx = getEmilyVoiceContext();
          var memberFocus = getEmilySearchFocusSummary(memberCtx);
          return pickVariant("apply_discovery_opening_paying", [
            (memberCtx.firstName
              ? "Welcome back, " + memberCtx.firstName + ". "
              : "Welcome back. ") +
              (memberFocus
                ? "I still have your search around " +
                  memberFocus +
                  ". Do you want to keep that running, tighten it, or look at a new role?"
                : "Tell me the role, sector, company, or location you want to target and I’ll continue the search from there."),
            (memberCtx.firstName ? memberCtx.firstName + ", " : "") +
              "I can pick this up from your saved search context. Send the market or role family you want next and I’ll refresh the results.",
            "You’re signed in, so I’ll keep the search history and CV context attached. What should I look for next?",
          ]);
        }
        return pickVariant("apply_discovery_opening_guest", [
          "Start with your CV and I’ll search live Middle East jobs against your actual skills and experience.",
          "Start with your CV so I can judge fit properly, then I’ll use the role or market you entered as the starting brief.",
          "Share your CV first. I’ll use your real background to decide which current roles are worth showing you.",
        ]);
      }
      var selectedRole = cleanMessageText(roleTitle || "this role");
      var selectedCompany = cleanMessageText(roleCompany || "");
      var selectedLocation = cleanMessageText(roleLocation || "");
      var roleLine =
        selectedRole +
        (selectedCompany ? " at " + selectedCompany : "") +
        (selectedLocation ? " in " + selectedLocation : "");
      var ctx = getEmilyVoiceContext({
        title: selectedRole,
        company: selectedCompany,
        location: selectedLocation,
      });
      if (ctx.isPaying) {
        return pickVariant("apply_discovery_role_opening_paying", [
          (ctx.firstName
            ? "Welcome back, " + ctx.firstName + ". "
            : "Welcome back. ") +
            "I see you’d like to apply for " +
            roleLine +
            ". Let’s get started when you’re ready.",
          "I’ve opened " +
            roleLine +
            " for you. When you’re ready, we can start the application.",
          "This role is selected: " +
            roleLine +
            ". Let’s get the application started when you’re ready.",
        ]);
      }
      return pickVariant("apply_discovery_role_opening_guest", [
        "I see you’d like to apply for " +
          roleLine +
          ". Let’s get started when you’re ready.",
        "I’ve opened " +
          roleLine +
          " for you. When you’re ready, we can start the application.",
        "This role is selected: " +
          roleLine +
          ". Let’s get the application started when you’re ready.",
      ]);
    }

    function getApplyForMeUploadCvCtaHtml() {
      var hasSelectedRole = hasApplyForMeSelectedJobContext();
      var selectedRole = hasSelectedRole
        ? cleanMessageText(roleTitle || "")
        : "";
      var selectedCompany = hasSelectedRole
        ? cleanMessageText(roleCompany || "")
        : "";
      var selectedLocation = cleanMessageText(roleLocation || "");
      var tags = uniqueCleanItems([roleSector, roleSeniority]).slice(0, 3);
      var safeLogo = getCommercialApplyQueueSafeLogoUrl(roleCompanyLogo || "");
      var fallbackInitial = escapeHtml(
        (selectedCompany.charAt(0) || "S").toUpperCase()
      );
      var fallbackLogoHtml =
        '<span class="sffc-crm-apply-chat__intro-logo-fallback" aria-hidden="true"><i>' +
        fallbackInitial +
        "</i></span>";
      var logoHtml = safeLogo
        ? '<img src="' +
          escapeHtml(safeLogo) +
          '" alt="' +
          escapeHtml(selectedCompany) +
          ' logo" onerror="this.hidden=true;this.parentNode.classList.add(&quot;has-fallback&quot;);">' +
          fallbackLogoHtml
        : fallbackLogoHtml;
      var metaLine = uniqueCleanItems([
        selectedLocation,
        roleSeniority,
        roleSector,
      ])
        .slice(0, 3)
        .join(" · ");
      var tagHtml = tags.length
        ? '<div class="sffc-crm-apply-chat__intro-job-tags">' +
          tags
            .map(function (tag) {
              return "<span>" + escapeHtml(tag) + "</span>";
            })
            .join("") +
          "</div>"
        : "";
      var selectedRoleHtml = hasSelectedRole
        ? '<div class="sffc-crm-apply-chat__intro-match-view" data-sffc-apply-chat-intro-match-view>' +
          "<h2>" +
          escapeHtml(selectedRole) +
          "</h2>" +
          '<div class="sffc-crm-apply-chat__intro-job-card">' +
          '<div class="sffc-crm-apply-chat__intro-logo-tile">' +
          logoHtml +
          "</div>" +
          '<div class="sffc-crm-apply-chat__intro-job-info">' +
          "<h3>" +
          escapeHtml(selectedCompany) +
          "</h3>" +
          (metaLine
            ? '<p class="sffc-crm-apply-chat__intro-city">' +
              escapeHtml(metaLine) +
              "</p>"
            : "") +
          tagHtml +
          "</div>" +
          "</div>" +
          '<button type="button" class="cta sffc-crm-apply-chat__intro-cta" data-sffc-apply-chat-intro-start>Get Started</button>' +
          "</div>"
        : "";
      var uploadHtml =
        '<div class="sffc-crm-apply-chat__intro-upload-view" data-sffc-apply-chat-intro-upload-view' +
        (hasSelectedRole ? " hidden" : "") +
        ">" +
        "<h2>Upload your CV</h2>" +
        '<p class="sffc-crm-apply-chat__intro-upload-sub">PDF · DOC · DOCX</p>' +
        '<button type="button" class="sffc-crm-apply-chat__intro-dropzone" data-sffc-apply-chat-intro-browse>' +
        '<span class="sffc-crm-apply-chat__intro-dropzone-icon" aria-hidden="true">↑</span>' +
        '<span class="sffc-crm-apply-chat__intro-dropzone-title">Upload your CV</span>' +
        '<span class="sffc-crm-apply-chat__intro-dropzone-sub"><span>Choose CV</span></span>' +
        "<small>PDF · DOC · DOCX</small>" +
        "</button>" +
        '<button type="button" class="sffc-crm-apply-chat__intro-secondary" data-sffc-apply-chat-intro-back>Back</button>' +
        "</div>";
      return (
        '<section class="sffc-crm-apply-chat__intro-apply-card" data-sffc-apply-chat-intro-card>' +
        (hasSelectedRole ? selectedRoleHtml + uploadHtml : uploadHtml) +
        "</section>"
      );
    }

    function hasApplyForMeSelectedJobContext() {
      var cleanTitle = cleanMessageText(roleTitle || "");
      var cleanCompany = cleanMessageText(roleCompany || "");
      var cleanApplicationUrl = cleanMessageText(applicationUrl || "").replace(
        /^#$/,
        ""
      );
      var pathname = "";
      try {
        pathname =
          window.location && window.location.pathname
            ? window.location.pathname
            : "";
      } catch (error) {
        pathname = "";
      }
      if (
        isPlaceholderRoleValue(cleanTitle) &&
        isPlaceholderRoleValue(cleanCompany) &&
        /\/shallow\/?$/i.test(pathname)
      ) {
        return false;
      }
      return !!(
        !isPlaceholderRoleValue(cleanTitle) &&
        (!isPlaceholderRoleValue(cleanCompany) ||
          cleanMessageText(postId || "") ||
          cleanMessageText(jobsPostId || "") ||
          cleanApplicationUrl)
      );
    }

    function startApplyForMeRoleDiscoveryFlow() {
      var seededSearchContext = jobSearchSeedContext || null;
      var hasLauncherBrief = !!cleanMessageText(
        seededSearchContext && !hasApplyForMeSelectedJobContext()
          ? seededSearchContext.query ||
              seededSearchContext.roleTarget ||
              seededSearchContext.sector ||
              seededSearchContext.location ||
              ""
          : ""
      );
      if (hasLoggedInChatSession() && !hasApplyForMeSelectedJobContext()) {
        showLoggedInLauncherWithMatchingJobs();
        return;
      }
      activePath = "apply_for_me_role_discovery";
      step = hasApplyForMeSelectedJobContext()
        ? "apply_role_discovery_upload"
        : "apply_role_discovery_upload";
      pendingApplyResultsSelection = null;
      careerConversationMemory.currentSelectedRole = null;
      careerConversationMemory.recentResultEntities = [];
      queueApplyChatMemoryPersist();
      setDeskIdentity("emily");
      var openingCopy = getApplyForMeDiscoveryOpeningCopy();
      var hasSelectedRoleContext = hasApplyForMeSelectedJobContext();
      var followUpCopy = hasSelectedRoleContext
        ? getApplyForMeUploadCvCtaHtml()
        : "";
      var guestWelcomeItem = getEmilyGuestWelcomeMessageItem(120);
      var sequence = [];
      if (guestWelcomeItem) {
        sequence.push(guestWelcomeItem);
      }
      sequence.push({
        html: isArabicChat()
          ? "ارفعي الـCV وسأبحث عن أدوار مناسبة فعلاً، ثم أوضح لك ما يستحق التعديل قبل التقديم."
          : openingCopy,
        delay: humanComposeDelay(cleanMessageText(openingCopy), 1300, 2600),
        pause: !hasLoggedInChatSession() ? 220 : 0,
      });
      if (followUpCopy) {
        sequence.push({
          html: followUpCopy,
          delay: humanComposeDelay(cleanMessageText(followUpCopy), 1300, 2600),
          pause: 250,
        });
      }
      botSequenceForCurrentTurn(sequence, function () {
        uploadButton.hidden = hasSelectedRoleContext;
        input.disabled = false;
        focusComposer(
          hasSelectedRoleContext
            ? "Upload your CV or paste it here"
            : hasLauncherBrief
            ? "Upload your CV to search against that brief"
            : "Upload your CV or paste it here"
        );
        if (pendingLaunchOpenFilePicker) {
          pendingLaunchOpenFilePicker = false;
        }
      });
    }

    function getSelectedApplicationRoleIntroCopy() {
      var selectedRole = cleanMessageText(roleTitle || "that role");
      var selectedCompany = cleanMessageText(roleCompany || "");
      var intro =
        "I’ll use <strong>" +
        escapeHtml(selectedRole) +
        "</strong>" +
        (selectedCompany
          ? " at <strong>" + escapeHtml(selectedCompany) + "</strong>"
          : "") +
        ".";
      if (capturedCvText || currentCvFile || hasLoggedInSavedCv()) {
        return (
          intro +
          " " +
          pickVariant("selected_application_intro_has_cv", [
            "I’ll check the CV against the role and show the application points that actually change the decision.",
            "I’ll use the CV context we already have and keep the feedback tied to this employer.",
            "I’ll start from the CV evidence and separate what is strong from what may need fixing before submission.",
          ])
        );
      }
      return (
        intro +
        " " +
        getContextualCvRequestLine(
          {
            title: selectedRole,
            company: selectedCompany,
            location: roleLocation,
            sector: roleSector,
          },
          "apply"
        )
      );
    }

    function showApplyForMeRoleSelection(analysis, sourceLabel) {
      var queries = getApplyForMeRoleDiscoveryQueries(analysis || {});
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Finding suitable roles",
        note: "I have your CV. I am searching current CRM and jobs posts before continuing the application workflow.",
        cvStatus: "CV captured",
        coverStatus: "Waiting for role selection",
      });
      var searchStartCopy = pickVariant("apply_for_me_role_search_start", [
        "I’ve read the CV signals. I’m checking live roles that fit the strongest parts of your background now.",
        "I have enough CV context to search properly. I’m looking for roles where the title, market, and evidence line up.",
        "I’m turning the CV into a sharper role search now, not just looking for broad keyword matches.",
      ]);
      botMessage(
        searchStartCopy,
        humanComposeDelay(searchStartCopy, 900, 1700),
        null,
        sourceLabel ? humanReadDelay(sourceLabel, 450) : 0
      );
      return fetchActualJobPostsWithFallbacks(queries, 8)
        .then(function (result) {
          var items = result && result.items ? result.items : [];
          var query =
            result && result.query ? result.query : queries[0] || "finance";
          botMessage(
            renderActualJobPostSearchResults(items, query, {
              selectForApplication: true,
            }),
            humanComposeDelay("Current role results ready.", 900, 1700),
            function () {
              step = "apply_role_discovery_select";
              focusComposer(
                getContextualReturnPlaceholder(
                  "Choose a role, or type another job title"
                )
              );
            }
          );
        })
        .catch(function () {
          var failureCopy = pickVariant("apply_for_me_role_search_failure", [
            "I could not load the current job posts just now. Send me a tighter title, company, sector, or market and I’ll retry from there.",
            "The live job feed did not respond cleanly. Give me the role or market again and I’ll run a narrower search.",
            "I could not refresh the live roles in this chat. Try a specific title or company and I’ll search again.",
          ]);
          botMessage(
            failureCopy,
            humanComposeDelay(failureCopy, 1000, 2000),
            function () {
              step = "apply_role_discovery_select";
              focusComposer("Type a job title");
            }
          );
        });
    }

    function searchApplyForMeRoleDiscoveryByQuery(query) {
      var clean = cleanMessageText(query || "");
      if (!clean) {
        return false;
      }
      var queryStartCopy = pickVariant("apply_for_me_query_search_start", [
        "I’m checking live roles for that now.",
        "I’ll rerun the search around that wording.",
        "I’m refreshing the current job posts with that as the new target.",
      ]);
      botMessage(queryStartCopy, humanComposeDelay(queryStartCopy, 700, 1300));
      fetchActualJobPosts(clean, 8)
        .then(function (items) {
          botMessage(
            renderActualJobPostSearchResults(items, clean, {
              selectForApplication: true,
            }),
            humanComposeDelay("Updated role results ready.", 900, 1700),
            function () {
              step = "apply_role_discovery_select";
              focusComposer(
                getContextualReturnPlaceholder(
                  "Choose a role, or type another job title"
                )
              );
            }
          );
        })
        .catch(function () {
          var queryFailureCopy = pickVariant(
            "apply_for_me_query_search_failure",
            [
              "I could not load matching job posts just now. Try a clearer title, company, sector, or location and I’ll run it again.",
              "The job search did not come back cleanly. Send a narrower target and I’ll retry.",
              "I could not refresh those results in this chat. Give me another role or market signal and I’ll try again.",
            ]
          );
          botMessage(
            queryFailureCopy,
            humanComposeDelay(queryFailureCopy, 900, 1800),
            function () {
              focusComposer("Type another job title");
            }
          );
        });
      return true;
    }

    function selectApplyForMeRoleFromButton(button) {
      var selectedTitle = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-role-title") || ""
      );
      var selectedPostId = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-post-id") || ""
      );
      var selectedJobsPostId = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-jobs-post-id") || ""
      );
      roleTitle = selectedTitle || roleTitle;
      postId = selectedPostId || postId;
      jobsPostId = selectedJobsPostId || jobsPostId;
      roleCompany = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-company") || roleCompany || ""
      );
      roleCompanyLogo = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-company-logo") ||
          button.getAttribute("data-company-logo") ||
          roleCompanyLogo ||
          ""
      );
      roleLocation = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-location") ||
          roleLocation ||
          ""
      );
      applicationUrl = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-application-url") ||
          applicationUrl ||
          "#"
      );
      applicationWorkspaceUrl = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-application-workspace-url") ||
          applicationWorkspaceUrl ||
          ""
      );
      roleUrl = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-view-url") || roleUrl || "#"
      );
      autoSubmitSupported =
        button.getAttribute("data-sffc-apply-chat-auto-submit-supported") ===
        "1";
      autoSubmitProvider = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-auto-submit-provider") ||
          button.getAttribute("data-sffc-apply-chat-source-platform") ||
          ""
      );
      autoSubmitSchemaStatus = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-auto-submit-schema-status") ||
          ""
      );
      autoSubmitFieldCount =
        parseInt(
          button.getAttribute("data-sffc-apply-chat-auto-submit-field-count") ||
            "0",
          10
        ) || 0;
      autoSubmitRequiredQuestionCount =
        parseInt(
          button.getAttribute(
            "data-sffc-apply-chat-auto-submit-required-question-count"
          ) || "0",
          10
        ) || 0;
      greenhouseBoardToken = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-greenhouse-board-token") || ""
      );
      greenhouseJobId = cleanMessageText(
        button.getAttribute("data-sffc-apply-chat-greenhouse-job-id") || ""
      );
      if (!autoSubmitSupported && hasKnownApplicationWorkerSubmitRoute()) {
        autoSubmitSupported = true;
      }
      root.setAttribute("data-role-title", roleTitle || "");
      root.setAttribute("data-post-id", postId || "");
      root.setAttribute("data-jobs-post-id", jobsPostId || "");
      root.setAttribute("data-role-company", roleCompany || "");
      root.setAttribute("data-company-logo", roleCompanyLogo || "");
      root.setAttribute("data-role-location", roleLocation || "");
      root.setAttribute("data-application-url", applicationUrl || "#");
      root.setAttribute(
        "data-application-workspace-url",
        applicationWorkspaceUrl || ""
      );
      root.setAttribute("data-role-url", roleUrl || applicationUrl || "#");
      root.setAttribute(
        "data-auto-submit-supported",
        autoSubmitSupported ? "1" : "0"
      );
      root.setAttribute("data-auto-submit-provider", autoSubmitProvider || "");
      root.setAttribute(
        "data-auto-submit-schema-status",
        autoSubmitSchemaStatus || ""
      );
      root.setAttribute(
        "data-auto-submit-field-count",
        String(autoSubmitFieldCount || 0)
      );
      root.setAttribute(
        "data-auto-submit-required-question-count",
        String(autoSubmitRequiredQuestionCount || 0)
      );
      root.setAttribute(
        "data-greenhouse-board-token",
        greenhouseBoardToken || ""
      );
      root.setAttribute("data-greenhouse-job-id", greenhouseJobId || "");
      activePath = "apply_for_me";
      step = "apply_upload";
      applyCvReviewSkipped = false;
      if (hasPremiumMemberChatAccess()) {
        pendingApplyResultsSelection = normalizeCommercialApplyQueueItem(
          getCommercialApplyQueueMainItem(),
          "Ready"
        );
        commercialApplyQueueItemsState = [pendingApplyResultsSelection];
        commercialApplyQueueInitialized = true;
        commercialApplyQueueActivated = false;
        commercialApplyQueueDetailsMode = true;
        commercialApplyQueueActiveTab = "shortlist";
        commercialApplyQueueFilter = "all";
        rememberCommercialApplyQueueCatalogItems(
          commercialApplyQueueItemsState
        );
        userMessage(roleTitle || "Apply for this role");
        botMessage(
          renderCommercialApplyQueueCard(commercialApplyQueueItemsState, {
            active: false,
            showButton: false,
            eyebrow: "Selected role",
            title: "Selected role",
          }),
          humanComposeDelay("Selected role.", 600, 1100),
          function () {
            askApplyResultsSelectedRoleNextStep(
              pendingApplyResultsSelection,
              pendingApplyResultsSelection.key || ""
            );
          }
        );
        return;
      }
      userMessage(roleTitle || "Apply for this role");
      var selectedIntroCopy = getSelectedApplicationRoleIntroCopy();
      var discoveryOpeningCopy = getApplyForMeDiscoveryOpeningCopy();
      var guestWelcomeItem = getEmilyGuestWelcomeMessageItem(120);
      var selectedSequence = [];
      if (guestWelcomeItem) {
        selectedSequence.push(guestWelcomeItem);
      }
      selectedSequence.push({
        html: discoveryOpeningCopy,
        delay: humanComposeDelay(discoveryOpeningCopy, 700, 1300),
        pause: 220,
      });
      botSequenceForCurrentTurn(selectedSequence, function () {
        if (capturedCvText) {
          botMessage(
            selectedIntroCopy +
              (getAutoSubmitDetectedCopy()
                ? "<br><br>" + escapeHtml(getAutoSubmitDetectedCopy())
                : ""),
            humanComposeDelay(cleanMessageText(selectedIntroCopy), 700, 1300)
          );
          fetchCvAnalysis(capturedCvText)
            .then(function (analysis) {
              continueApplyAfterAnalysis(analysis || {});
            })
            .catch(function () {
              beginApplyForMeFlow();
            });
          return;
        }
        if (currentCvFile) {
          botMessage(
            selectedIntroCopy +
              (getAutoSubmitDetectedCopy()
                ? "<br><br>" + escapeHtml(getAutoSubmitDetectedCopy())
                : ""),
            humanComposeDelay(cleanMessageText(selectedIntroCopy), 700, 1300)
          );
          fetchCvAnalysisFromFile(currentCvFile)
            .then(function (payload) {
              if (payload && payload.cv_text) {
                capturedCvText = normalizeStoredCvText(payload.cv_text);
              }
              continueApplyAfterAnalysis((payload && payload.analysis) || {});
            })
            .catch(function () {
              beginApplyForMeFlow();
            });
          return;
        }
        botMessage(
          getApplyForMeUploadCvCtaHtml(),
          humanComposeDelay("Upload your CV for the selected role.", 700, 1300),
          function () {
            uploadButton.hidden = true;
            input.disabled = false;
            focusComposer("Upload your CV or paste it here");
          }
        );
      });
    }

    function openJobSearchContinuityPromptState() {
      setPromptState(
        "job_search_member_follow_up",
        {
          other: function (reply) {
            handleJobSearchContinuityReply(reply);
          },
          question: function (reply) {
            handleJobSearchContinuityReply(reply || "");
          },
        },
        getJobSearchContinuityPlaceholder()
      );
      focusComposer(getJobSearchContinuityPlaceholder());
    }

    function getLiveJobSearchResultsListKey(
      value,
      intent,
      signals,
      rankingMode
    ) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      var matchingCount = getJobListViewItems("matching_cv").length;
      var recommendedCount = getJobListViewItems("recommended").length;
      var interviewCount = getJobListViewItems("interview").length;
      var salaryCount = getJobListViewItems("salary").length;
      var recentCount = getJobListViewItems("recent").length;
      if (rankingMode === "salary" && salaryCount) {
        return "salary";
      }
      if (rankingMode === "newest" && recentCount) {
        return "recent";
      }
      if (rankingMode === "safest" && interviewCount) {
        return "interview";
      }
      if (
        /(?:earlier matches|matches you showed|same matches|cv matches|roles matching my cv|these matches|those matches|previous matches|المطابقات السابقة|الماتشات السابقة|المطابقات اللي وريتني|المطابقات التي وريتني)/i.test(
          clean
        )
      ) {
        if (
          (signals.locationIntent.current || []).length ||
          (signals.roleTargets || []).length
        ) {
          return "recommended";
        }
        return "matching_cv";
      }
      if (
        intent === "matching_jobs" &&
        matchingCount &&
        !signals.roleTargets.length &&
        !(signals.locationIntent.current || []).length
      ) {
        return "matching_cv";
      }
      if (recommendedCount) {
        return "recommended";
      }
      if (interviewCount) {
        return "interview";
      }
      if (recentCount) {
        return "recent";
      }
      if (salaryCount) {
        return "salary";
      }
      return matchingCount ? "matching_cv" : "recommended";
    }

    function getJobSearchCvLaneExplanation(profile) {
      var cvProfile = profile || buildCvRoleMatchProfile({ cvOnly: true }) || {};
      var lanes = getCvDisplayLaneLabels(cvProfile, null, []).slice(0, 3);
      var current = cleanCvRoleDisplayLabel(
        cvProfile.title || "",
        cvProfile.locations || []
      );
      var parts = [];
      var strongSkills = getStrongCvSkillOverlap(cvProfile.skills || []).slice(
        0,
        4
      );
      if (current) {
        parts.push("recent role signal: " + current);
      }
      if (lanes.length) {
        parts.push("target lanes: " + formatNaturalList(lanes));
      }
      if (strongSkills.length) {
        parts.push("skills: " + formatNaturalList(strongSkills));
      }
      if ((cvProfile.qualifications || []).length) {
        parts.push(
          "qualifications: " +
            formatNaturalList((cvProfile.qualifications || []).slice(0, 3))
        );
      }
      if ((cvProfile.locations || []).length) {
        parts.push(
          "location signal: " +
            formatNaturalList((cvProfile.locations || []).slice(0, 2))
        );
      }
      return parts.filter(Boolean).slice(0, 4);
    }

    function getRoleMatchConversationalExplanation(item, options) {
      var config = options || {};
      var match = buildCvRoleMatch(item || {});
      var role = normalizeCommercialApplyQueueItem(item || {}, "Ready");
      var label = cleanMessageText(
        [role.title || "", role.company ? "at " + role.company : ""]
          .filter(Boolean)
          .join(" ")
      );
      var score = Math.max(0, Math.round(Number((match && match.score) || 0)));
      var strongComponents;
      var strengths = dedupeList(
        ((match && match.whyMatches) || [])
          .concat((match && match.cvSupport) || [])
          .map(cleanMatchNarrativeLine)
          .filter(Boolean)
      ).slice(0, config.limit || 3);
      var caveats = dedupeList(
        ((match && match.missing) || [])
          .map(cleanMatchNarrativeLine)
          .filter(Boolean)
      ).slice(0, 2);
      var components = (match && match.componentScores) || {};
      strongComponents = [
        components.title >= 55 ? "title fit" : "",
        components.skills >= 55 ? "skill overlap" : "",
        components.experience >= 55 ? "experience depth" : "",
        components.seniority >= 55 ? "seniority fit" : "",
        components.location >= 70 ? "location" : "",
      ].filter(Boolean);
      var scoreLine = score
        ? "I’m scoring it around " +
          score +
          "/100" +
          (strongComponents.length
            ? " because the strongest components are " +
              formatNaturalList(strongComponents) +
              "."
            : ".")
        : "";
      if (!strengths.length && !caveats.length) {
        return label
          ? label +
              " is in the list because it overlaps with the current search direction, but I would need to inspect the full role before calling it a clean fit."
          : "This role is in the list because it overlaps with the current search direction, but I would need to inspect the full role before calling it a clean fit.";
      }
      return [
        label ? "<strong>" + escapeHtml(label) + "</strong>:" : "",
        scoreLine ? escapeHtml(scoreLine) : "",
        strengths.length
          ? "The useful evidence is " +
            escapeHtml(formatNaturalList(strengths)) +
            "."
          : "",
        caveats.length
          ? "The caveat is " + escapeHtml(formatNaturalList(caveats)) + "."
          : "",
      ]
        .filter(Boolean)
        .join(" ");
    }

    function getJobSearchResultsReasoningHtml(items, listKey, request) {
      var cvProfile = buildCvRoleMatchProfile({ cvOnly: true }) || {};
      var laneLines = getJobSearchCvLaneExplanation(cvProfile);
      var top = (items && items[0]) || null;
      var mode = cleanMessageText((request && request.rankingMode) || "");
      var listLabel =
        listKey === "matching_cv"
          ? "CV fit"
          : listKey === "interview"
          ? "interview odds"
          : listKey === "salary"
          ? "salary"
          : listKey === "recent"
          ? "freshness"
          : "balanced fit";
      var html = "";
      if (!laneLines.length && !top) {
        return "";
      }
      html +=
        '<div class="sffc-crm-apply-chat__formatted"><p><strong>' +
        escapeHtml("How I’m reading this shortlist") +
        "</strong></p>";
      if (laneLines.length) {
        html +=
          "<p>I’m anchoring this to " +
          escapeHtml(formatNaturalList(laneLines)) +
          ".</p>";
      }
      html +=
        "<p>The current ordering is weighted toward " +
        escapeHtml(mode || listLabel) +
        ", with weak specialist matches pushed down if the CV does not prove that lane.</p>";
      if (top) {
        html +=
          "<p>" +
          getRoleMatchConversationalExplanation(top, { limit: 2 }) +
          "</p>";
      }
      html += "</div>";
      return html;
    }

    function getLiveJobSearchResultsIntro(
      value,
      signals,
      listKey,
      rankingMode
    ) {
      var clean = cleanMessageText(value || "");
      var currentLocations =
        signals && signals.locationIntent ? signals.locationIntent.current : [];
      var roleTargets =
        signals && signals.roleTargets ? signals.roleTargets : [];
      var summary = "";
      var modeText = "";
      if (rankingMode === "newest") {
        modeText = isArabicChat() ? "الأحدث" : "newest";
      } else if (rankingMode === "salary") {
        modeText = isArabicChat() ? "الأعلى راتباً" : "better-paid";
      } else if (rankingMode === "safest") {
        modeText = isArabicChat() ? "الأكثر أماناً" : "safest";
      } else if (rankingMode === "ambitious") {
        modeText = isArabicChat() ? "الأكثر طموحاً" : "more ambitious";
      } else if (rankingMode === "strongest") {
        modeText = isArabicChat() ? "الأقوى" : "strongest";
      }
      if (currentLocations && currentLocations.length) {
        summary = formatFactList(currentLocations.slice(0, 2));
        return isArabicChat()
          ? "واضح. سأعيد شد القائمة حول " +
              summary +
              (modeText ? " وأرتب لك الأدوار " + modeText : "") +
              " الآن."
          : "Understood. I'll tighten the shortlist around " +
              summary +
              (modeText
                ? " and bring back the " + modeText + " roles now."
                : " and show you what looks strongest now.");
      }
      if (roleTargets && roleTargets.length) {
        summary = formatFactList(roleTargets.slice(0, 2));
        return isArabicChat()
          ? "واضح. سأعيد شد البحث حول " +
              summary +
              (modeText ? " وأرتب لك الأدوار " + modeText : "") +
              " الآن."
          : "Understood. I'll tighten the search around " +
              summary +
              (modeText
                ? " and bring back the " + modeText + " roles now."
                : " and show you the closest roles now.");
      }
      if (
        /(?:earlier matches|matches you showed|same matches|previous matches|المطابقات السابقة|المطابقات اللي وريتني)/i.test(
          normalizeCareerIntentText(clean).toLowerCase()
        )
      ) {
        return isArabicChat()
          ? "أكيد. سأعيد عرض " +
              (modeText ? "الأدوار " + modeText : "أقوى المطابقات الحالية") +
              " هنا."
          : "Sure. I'll bring " +
              (modeText
                ? "the " + modeText + " current roles"
                : "the strongest current matches") +
              " back up here.";
      }
      return listKey === "matching_cv"
        ? isArabicChat()
          ? "سأعرض لك " +
            (modeText ? "المطابقات " + modeText : "أقرب المطابقات الحالية") +
            " الآن."
          : "I'll surface " +
            (modeText
              ? "the " + modeText + " current matches"
              : "the closest current matches") +
            " now."
        : isArabicChat()
        ? "سأعرض لك " +
          (modeText ? "الأدوار " + modeText : "أقوى الأدوار الحالية") +
          " الآن."
        : "I'll surface " +
          (modeText
            ? "the " + modeText + " live roles"
            : "the strongest live roles") +
          " now.";
    }

    function getLiveJobSearchResultsFollowUp(listKey, itemCount) {
      if (itemCount <= 0) {
        return isArabicChat()
          ? "إذا أردت، غيّر لي السوق أو الدور أو المستوى وسأعيد شد الجولة التالية مباشرة."
          : "If you want, change the market, role, or level and I'll tighten the next pass straight away.";
      }
      return getJobListChatFollowUpLine(listKey, itemCount);
    }

    function getLiveJobSearchResultsAfterword(value, intent, signals) {
      var clauseIntents;
      var actionable;
      var summary;
      var preferredIntent = "";
      var normalized = normalizeCareerIntentText(cleanMessageText(value || ""));
      var hasExplicitKnowledgeAsk = false;
      var asksForComparison =
        /\b(?:compare|rank|which one|which role|better for me|pros and cons|trade-?offs|prioriti[sz]e first|apply to first)\b/i.test(
          normalized
        );
      if (!value) {
        return null;
      }
      if (asksForComparison) {
        preferredIntent = "compare_roles";
      }
      if (
        !preferredIntent &&
        (intent === "recruiter_networking" || intent === "recruiter_comparison")
      ) {
        hasExplicitKnowledgeAsk =
          /\b(?:recruiter|recruiters|headhunter|hiring manager|talent acquisition|talent partner|hr)\b/i.test(
            normalized
          ) &&
          /\b(?:contact|email|linkedin|phone|who|which|find|show|tell me|should i contact|contact first|reach out)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "profile_fit") {
        hasExplicitKnowledgeAsk =
          /\b(?:fit|qualified|qualification|eligible|chance|chances|shortlist|shortlisted|interview|realistically|requirements?|competitive|underqualified|overqualified|too junior|too senior)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "application_decision") {
        hasExplicitKnowledgeAsk =
          /\b(?:worth applying|should i apply|apply now|apply direct|stretch role|wait|bother|wasting my time)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "career_direction") {
        hasExplicitKnowledgeAsk =
          /\b(?:what roles should i target|what level should i target|which sectors fit me|best next step|change industry|where am i strongest)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "rejection_analysis") {
        hasExplicitKnowledgeAsk =
          /\b(?:rejected|rejection|feedback|apply again)\b/i.test(normalized);
      } else if (!preferredIntent && intent === "interview_chance") {
        hasExplicitKnowledgeAsk =
          /\b(?:interview me|interview chance|interview chances|would they interview)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "application_follow_up") {
        hasExplicitKnowledgeAsk =
          /\b(?:follow up|follow-up|heard nothing|application been viewed|speed up my application)\b/i.test(
            normalized
          );
      } else if (!preferredIntent && intent === "compare_roles") {
        hasExplicitKnowledgeAsk =
          /\b(?:compare|rank|better for me|best odds|safer|more ambitious|pros and cons|trade-offs)\b/i.test(
            normalized
          );
      }
      if (
        signals &&
        signals.hasMeaningfulSignals &&
        hasExplicitKnowledgeAsk &&
        /^(?:recruiter_networking|recruiter_comparison|profile_fit|application_decision|career_direction|rejection_analysis|interview_chance|application_follow_up|compare_roles)$/.test(
          String(intent || "")
        )
      ) {
        preferredIntent = String(intent || "");
      }
      if (preferredIntent) {
        summary = summarizeCompoundKnowledgeAnswer(
          getKnowledgeAnswer(preferredIntent, value)
        );
        if (summary) {
          return {
            intent: preferredIntent,
            text: getCompoundKnowledgeBridge(preferredIntent, summary).replace(
              /^\s+/,
              ""
            ),
          };
        }
      }
      clauseIntents = extractClauseIntentSequence(value, intent);
      actionable = clauseIntents.filter(function (entry) {
        return (
          entry &&
          entry.intent &&
          /^(?:recruiter_networking|recruiter_comparison|profile_fit|application_decision|career_direction|rejection_analysis|interview_chance|application_follow_up|compare_roles|location_preferences|role_targeting)$/.test(
            String(entry.intent || "")
          )
        );
      });
      if (
        actionable.length === 1 &&
        String(actionable[0].intent || "") === "compare_roles" &&
        !asksForComparison
      ) {
        return null;
      }
      if (!actionable.length) {
        return null;
      }
      summary = summarizeCompoundKnowledgeAnswer(
        getKnowledgeAnswer(actionable[0].intent, actionable[0].text || value)
      );
      if (!summary) {
        return null;
      }
      return {
        intent: actionable[0].intent,
        text: getCompoundKnowledgeBridge(actionable[0].intent, summary).replace(
          /^\s+/,
          ""
        ),
      };
    }

    function getLiveJobSearchResultsTailCopy(request, items, listKey) {
      var afterword =
        request && request.afterword && request.afterword.text
          ? request.afterword.text
          : "";
      var rankingMode =
        request && request.rankingMode ? String(request.rankingMode) : "";
      var lead = (items && items[0]) || null;
      var second = (items && items[1]) || null;
      var leadLabel = cleanMessageText(
        (lead && (lead.title || lead.company)) || ""
      );
      var secondLabel = cleanMessageText(
        (second && (second.title || second.company)) || ""
      );
      var judgement = getLiveJobSearchResultsJudgementSummary(items);
      var bestOverallLabel = getLiveJobSearchResultsRoleLabel(
        judgement.bestOverall
      );
      var safestLabel = getLiveJobSearchResultsRoleLabel(judgement.safestFirst);
      var ambitiousLabel = getLiveJobSearchResultsRoleLabel(
        judgement.ambitiousBackup
      );
      if (
        request &&
        request.afterword &&
        String(request.afterword.intent || "") === "compare_roles" &&
        leadLabel
      ) {
        if (bestOverallLabel && safestLabel) {
          return isArabicChat()
            ? "<strong>الأفضل إجمالاً:</strong> " +
                bestOverallLabel +
                ". <strong>الأكثر أماناً كبداية:</strong> " +
                safestLabel +
                "." +
                (ambitiousLabel
                  ? " <strong>الخيار الأكثر طموحاً بعده:</strong> " +
                    ambitiousLabel +
                    "."
                  : "")
            : "<strong>Best overall:</strong> " +
                bestOverallLabel +
                ". <strong>Safest first application:</strong> " +
                safestLabel +
                "." +
                (ambitiousLabel
                  ? " <strong>More ambitious backup:</strong> " +
                    ambitiousLabel +
                    "."
                  : "");
        }
        if (rankingMode === "safest") {
          return isArabicChat()
            ? leadLabel +
                " يبدو لي التقديم الأول الأنظف إذا كانت الأولوية للواقعية. " +
                (secondLabel
                  ? "بعده مباشرة يأتي " +
                    secondLabel +
                    " إذا أردت الإبقاء على خيار ثانٍ."
                  : "إذا أردت، أفصل لك لماذا وضعته أولاً.")
            : leadLabel +
                " looks like the cleanest first application if realism is the priority. " +
                (secondLabel
                  ? secondLabel +
                    " would be the next one I would keep alive behind it."
                  : "If you want, I can break down why it sits first.");
        }
        if (rankingMode === "strongest" || rankingMode === "ambitious") {
          return isArabicChat()
            ? leadLabel +
                " هو الذي سأعطيه الأولوية أولاً من هذه الجولة. " +
                (secondLabel
                  ? secondLabel + " هو الخيار الذي سأبقيه بعده مباشرة."
                  : "إذا أردت، أرتب لك ما بعده خطوة بخطوة.")
            : leadLabel +
                " is the one I would prioritise first from this refreshed shortlist. " +
                (secondLabel
                  ? secondLabel + " is the one I would keep next behind it."
                  : "If you want, I can rank what follows behind it.");
        }
      }
      if (afterword) {
        return afterword;
      }
      if (rankingMode === "newest") {
        return isArabicChat()
          ? "هذه مرتبة بالحداثة أولاً. إذا أردت، أرتب لك الآن أيها الأنظف من ناحية الملاءمة."
          : "These are ordered by freshness first. If you want, I can now tell you which of them is actually the cleanest fit.";
      }
      if (rankingMode === "salary") {
        return isArabicChat()
          ? "هذه مرتبة بالراتب أولاً. إذا أردت، أوازنها الآن مقابل الواقعية والملاءمة."
          : "These are ordered by salary first. If you want, I can now weigh them back against realism and fit.";
      }
      if (rankingMode === "safest" && leadLabel) {
        if (bestOverallLabel && safestLabel) {
          return isArabicChat()
            ? "<strong>الأكثر أماناً كبداية:</strong> " +
                safestLabel +
                "." +
                (bestOverallLabel && bestOverallLabel !== safestLabel
                  ? " <strong>الأفضل إجمالاً:</strong> " +
                    bestOverallLabel +
                    "."
                  : "") +
                (ambitiousLabel
                  ? " <strong>الخيار الأكثر طموحاً:</strong> " +
                    ambitiousLabel +
                    "."
                  : "")
            : "<strong>Safest first application:</strong> " +
                safestLabel +
                "." +
                (bestOverallLabel && bestOverallLabel !== safestLabel
                  ? " <strong>Best overall:</strong> " + bestOverallLabel + "."
                  : "") +
                (ambitiousLabel
                  ? " <strong>More ambitious backup:</strong> " +
                    ambitiousLabel +
                    "."
                  : "");
        }
        return isArabicChat()
          ? leadLabel +
              " يبدو لي الأنظف إذا كانت الأولوية لرفع احتمالات المقابلة أولاً. هل تريدني أن أشرح السبب؟"
          : leadLabel +
              " looks like the cleanest move if the priority is improving your interview odds first. Do you want me to unpack why?";
      }
      if (rankingMode === "strongest" && leadLabel) {
        if (bestOverallLabel) {
          return isArabicChat()
            ? "<strong>الأفضل إجمالاً:</strong> " +
                bestOverallLabel +
                "." +
                (safestLabel && safestLabel !== bestOverallLabel
                  ? " <strong>الأكثر أماناً كبداية:</strong> " +
                    safestLabel +
                    "."
                  : "") +
                (ambitiousLabel
                  ? " <strong>الخيار الأكثر طموحاً بعده:</strong> " +
                    ambitiousLabel +
                    "."
                  : "")
            : "<strong>Best overall:</strong> " +
                bestOverallLabel +
                "." +
                (safestLabel && safestLabel !== bestOverallLabel
                  ? " <strong>Safest first application:</strong> " +
                    safestLabel +
                    "."
                  : "") +
                (ambitiousLabel
                  ? " <strong>More ambitious backup:</strong> " +
                    ambitiousLabel +
                    "."
                  : "");
        }
        return isArabicChat()
          ? leadLabel +
              " يبدو حالياً أقوى خيار إجمالاً. هل تريدني أن أكسر لك لماذا يتقدم الباقي أو يتأخر؟"
          : leadLabel +
              " currently looks like the strongest overall option. Do you want me to break down why the rest sit above or below it?";
      }
      if (rankingMode === "ambitious" && leadLabel) {
        return isArabicChat()
          ? "<strong>الخيار الأكثر طموحاً:</strong> " +
              leadLabel +
              "." +
              (safestLabel
                ? " <strong>الأكثر أماناً إذا أردت البداية الأنظف:</strong> " +
                  safestLabel +
                  "."
                : "")
          : "<strong>More ambitious option:</strong> " +
              leadLabel +
              "." +
              (safestLabel
                ? " <strong>Safest first application:</strong> " +
                  safestLabel +
                  "."
                : "");
      }
      return getLiveJobSearchResultsFollowUp(listKey, (items || []).length);
    }

    function getLiveJobSearchResultsNextTopic(request, currentTopic) {
      var afterwordIntent =
        request && request.afterword
          ? String(request.afterword.intent || "")
          : "";
      var signals = request && request.signals ? request.signals : null;
      if (
        /^(?:recruiter_networking|recruiter_comparison)$/.test(afterwordIntent)
      ) {
        return "outreach_style";
      }
      if (
        /^(?:application_decision|application_follow_up|interview_chance)$/.test(
          afterwordIntent
        )
      ) {
        return "application_readiness";
      }
      if (
        /^(?:profile_fit|career_direction|compare_roles|rejection_analysis)$/.test(
          afterwordIntent
        )
      ) {
        return "priority_tradeoff";
      }
      if (
        signals &&
        signals.locationIntent &&
        (signals.locationIntent.current.length ||
          signals.locationIntent.future.length ||
          signals.locationIntent.excluded.length)
      ) {
        return "seniority_scope";
      }
      if (signals && signals.roleTargets && signals.roleTargets.length) {
        return "priority_tradeoff";
      }
      return getNextJobSearchContinuityTopic(
        currentTopic || "priority_tradeoff"
      );
    }

    function resolveLiveJobSearchResultsRequest(value, intent, semantics) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      var promptSemantics = semantics || parseMessageSemantics(value);
      var signals = extractJobSearchPreferenceSignals(value);
      var explicitResultsAsk = false;
      var listKey = "";
      var afterword = null;
      var rankingMode = "";
      if (!clean) {
        return null;
      }
      explicitResultsAsk = !!(
        intent === "matching_jobs" ||
        intent === "opportunity_search" ||
        intent === "location_constraint" ||
        /(?:show me|do you have|have you got|anything in|something in|what about|more like|similar roles|matches you showed|earlier matches|previous matches|show the matches|show me roles|any roles|what have you got|worth applying for|ورني|وريني|أرني|ارني|عندك شي|عندك شيء|عندك أدوار|وش عندك|ايش عندك|ماذا عندك|ماذا لديك|فيه شي|فيه شيء|ماذا عن|وش عن|ايش عن|شي في|شيء في|أدوار في|وظائف في|المطابقات السابقة|المطابقات اللي وريتني|الأدوار اللي عندك)/i.test(
          clean
        ) ||
        (promptSemantics.has_question &&
          ((signals.locationIntent.current || []).length ||
            signals.roleTargets.length))
      );
      if (!explicitResultsAsk) {
        return null;
      }
      if (
        signals &&
        signals.locationIntent &&
        signals.locationIntent.current.length &&
        signals.locationIntent.excluded.length
      ) {
        signals.locationIntent.current = signals.locationIntent.current.filter(
          function (location) {
            return signals.locationIntent.excluded.indexOf(location) === -1;
          }
        );
      }
      if (
        signals &&
        signals.locationIntent &&
        signals.locationIntent.current.length
      ) {
        signals.locationIntent.current = signals.locationIntent.current.filter(
          function (location) {
            var label = normalizeCareerIntentText(location || "");
            if (!label) {
              return false;
            }
            if (
              new RegExp(
                "\\b(?:drop|not|exclude|remove)\\s+" +
                  label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") +
                  "\\b",
                "i"
              ).test(clean)
            ) {
              return false;
            }
            return !new RegExp(
              "\\b" +
                label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") +
                "\\s+instead\\b",
              "i"
            ).test(clean);
          }
        );
      }
      rankingMode = getLiveJobSearchResultsRankingMode(value);
      listKey = getLiveJobSearchResultsListKey(
        value,
        intent,
        signals,
        rankingMode
      );
      afterword = getLiveJobSearchResultsAfterword(value, intent, signals);
      return {
        listKey: listKey,
        signals: signals,
        rankingMode: rankingMode,
        intro: getLiveJobSearchResultsIntro(
          value,
          signals,
          listKey,
          rankingMode
        ),
        afterword: afterword,
        nextTopic: getLiveJobSearchResultsNextTopic(
          {
            signals: signals,
            afterword: afterword,
          },
          (jobSearchContinuityState && jobSearchContinuityState.topic) ||
            "priority_tradeoff"
        ),
      };
    }

    function presentLiveJobSearchResults(request, afterResults) {
      var listKey =
        request && request.listKey ? request.listKey : "recommended";
      var intro = request && request.intro ? request.intro : "";
      var items = getLiveJobSearchResultsItems(
        listKey,
        request && request.rankingMode
      ).slice(0, 3);
      var reasoningHtml = getJobSearchResultsReasoningHtml(
        items,
        listKey,
        request || {}
      );
      var nextTopic =
        request && request.nextTopic ? String(request.nextTopic) : "";
      var tailCopy = getLiveJobSearchResultsTailCopy(request, items, listKey);
      rememberLiveJobSearchResultsSnapshot(request, items);
      closeJobListView();
      resetMatchingCvConversationState();
      rememberApplyChatRecentTopic(listKey);
      if (!intro) {
        sendJobListResultsToChat(listKey);
        if (typeof afterResults === "function") {
          afterResults(items.length);
        }
        return;
      }
      botMessage(
        intro +
          renderJobListChatResultsHtml(items, listKey) +
          (reasoningHtml || "") +
          "<p>" +
          escapeHtml(tailCopy) +
          "</p>",
        humanComposeDelay("Live job search results ready.", 1200, 2300),
        function () {
          if (!isMobileWorkspaceView()) {
            setRailView("chat");
          }
          if (jobSearchContinuityState && nextTopic) {
            jobSearchContinuityState.topic = nextTopic;
          }
          openJobSearchContinuityPromptState();
          if (typeof afterResults === "function") {
            afterResults(items.length);
          }
        }
      );
    }

    function renderJobListView(listKey) {
      var config = getJobListViewConfig(listKey);
      var items = getJobListViewItems(listKey);

      if (listsResultsTitle) {
        listsResultsTitle.textContent = config.title;
      }
      if (listsResultsDescription) {
        listsResultsDescription.textContent = config.description;
      }
      if (listsResultsBody) {
        listsResultsBody.innerHTML = renderJobListResultsHtml(items, listKey);
      }
    }

    function getApplyChatLoginUrl() {
      return "https://joinsenna.com/login";
    }

    function getApplyForMeMembershipUrl() {
      return (getConfig() && getConfig().membershipsUrl) || "/memberships/";
    }

    function buildMembershipRedirectUrl(accountType) {
      var url;
      var selection =
        cleanMessageText(
          accountType || applySelectedPricingOption || ""
        ).toLowerCase() || "platform";
      try {
        url = new URL(signupUrl, window.location.origin);
      } catch (err) {
        return signupUrl;
      }
      url.searchParams.set("account_type", selection);
      url.searchParams.set("signup_path", selection);
      url.searchParams.set("source", "apply_chat");
      if (applyOnboardingFullName) {
        url.searchParams.set("full_name", applyOnboardingFullName);
      }
      if (applyOnboardingPreferredEmail) {
        url.searchParams.set("email", applyOnboardingPreferredEmail);
      }
      if (roleTitle) {
        url.searchParams.set("role", roleTitle);
      }
      if (roleCompany) {
        url.searchParams.set("company", roleCompany);
      }
      if (ensureApplyIntroState().supportMode) {
        url.searchParams.set(
          "support_mode",
          ensureApplyIntroState().supportMode
        );
      }
      if (ensureApplyIntroState().applicationsPerWeek) {
        url.searchParams.set(
          "applications_per_week",
          ensureApplyIntroState().applicationsPerWeek
        );
      }
      if (ensureApplyIntroState().introsPerWeek) {
        url.searchParams.set(
          "intros_per_week",
          ensureApplyIntroState().introsPerWeek
        );
      }
      if (ensureApplyIntroState().priority) {
        url.searchParams.set(
          "priority_preference",
          ensureApplyIntroState().priority
        );
      }
      if (ensureApplyIntroState().lanePreference) {
        url.searchParams.set(
          "lane_preference",
          ensureApplyIntroState().lanePreference
        );
      }
      if (ensureApplyIntroState().desiredRole) {
        url.searchParams.set(
          "target_roles",
          ensureApplyIntroState().desiredRole
        );
      }
      if (ensureApplyIntroState().preferredSectors) {
        url.searchParams.set(
          "target_sectors",
          ensureApplyIntroState().preferredSectors
        );
      }
      if (ensureApplyIntroState().preferredMarket) {
        url.searchParams.set(
          "preferred_market",
          ensureApplyIntroState().preferredMarket
        );
      }
      if (ensureApplyIntroState().originalBrief) {
        url.searchParams.set(
          "search_query",
          ensureApplyIntroState().originalBrief
        );
      }
      return url.toString();
    }

    function goToMembershipPage(accountType, options) {
      var selection =
        cleanMessageText(
          accountType || applySelectedPricingOption || ""
        ).toLowerCase() || "platform";
      var openInNewTab = !options || options.newTab !== false;
      var targetUrl = "";
      applySelectedPricingOption = selection;
      syncApplyChatSignupPrefill(selection)
        .then(function () {
          targetUrl = buildMembershipRedirectUrl(selection);
          sendAutoApplyContactCapture(selection, targetUrl).finally(
            function () {
              if (openInNewTab) {
                window.open(targetUrl, "_blank", "noopener");
                return;
              }
              window.location.href = targetUrl;
            }
          );
        })
        .catch(function () {
          targetUrl = buildMembershipRedirectUrl(selection);
          sendAutoApplyContactCapture(selection, targetUrl).finally(
            function () {
              if (openInNewTab) {
                window.open(targetUrl, "_blank", "noopener");
                return;
              }
              window.location.href = targetUrl;
            }
          );
        });
    }

    function getLockedResultsMembershipAccountType() {
      return (
        getMembershipAccountTypeFromJobSearchPackage(
          jobSearchSelectedPackage
        ) || "mentorship"
      );
    }

    function getLockedResultsDetailsLabel() {
      return getConfig().isLoggedIn
        ? "Upgrade for Details"
        : "Login for Details";
    }

    function getLockedResultsDetailsActionHtml() {
      return (
        '<a class="sffc-community-editorial__button is-primary" href="' +
        escapeHtml(getApplyForMeMembershipUrl()) +
        '">Apply for Me</a>'
      );
    }

    function handleLockedResultsDetailsIntent() {
      window.location.href = getApplyForMeMembershipUrl();
    }

    function shouldUseLockedResultsPreviewMode() {
      return !hasPremiumMemberChatAccess();
    }

    function shouldLockResultsListCard(listKey) {
      var cleanKey = cleanMessageText(listKey || "");
      if (!shouldUseLockedResultsPreviewMode()) {
        return false;
      }
      return !!cleanKey && cleanKey !== "matching_cv";
    }

    function getDefaultResultsPreviewListKey() {
      if (getJobListViewItems("matching_cv").length) {
        return "matching_cv";
      }
      if (
        !shouldUseLockedResultsPreviewMode() &&
        getJobListViewItems("recommended").length
      ) {
        return "recommended";
      }
      return "";
    }

    function ensureDefaultResultsPreviewSelection() {
      var defaultKey;
      if (activeEditorialResultsKey) {
        return;
      }
      defaultKey = getDefaultResultsPreviewListKey();
      if (!defaultKey) {
        return;
      }
      activeEditorialResultsKey = defaultKey;
    }

    function shouldCollapseResultsListsPanel() {
      return !!(
        shouldUseLockedResultsPreviewMode() &&
        workspaceState.previewMode !== "empty"
      );
    }

    function closeJobListView() {
      activeListView = "";
      if (listsStack) {
        setElementVisibility(listsStack, true, "grid");
      }
      if (listsResults) {
        setElementVisibility(listsResults, false, "grid");
      }
      syncActiveJobListCardState();
    }

    function syncActiveJobListCardState() {
      var selectedKey =
        activeRailView === "results" && activeEditorialResultsKey
          ? activeEditorialResultsKey
          : activeListView;
      listCards.forEach(function (card) {
        var cardKey = card.getAttribute("data-sffc-apply-chat-list-card") || "";
        card.classList.toggle("is-active", cardKey === selectedKey);
        card.classList.toggle("is-locked", shouldLockResultsListCard(cardKey));
      });
      resultsPickerButtons.forEach(function (button) {
        button.classList.toggle(
          "is-active",
          (button.getAttribute("data-sffc-apply-chat-results-picker") || "") ===
            selectedKey
        );
      });
    }

    function getEditorialResultsPickerHtml() {
      return (
        "" +
        '<div class="sffc-crm-apply-chat__results-stage-picker">' +
        '<button type="button" class="sffc-crm-apply-chat__results-stage-picker-button' +
        (activeEditorialResultsKey === "matching_cv" ? " is-active" : "") +
        '" data-sffc-apply-chat-results-picker="matching_cv">CV Matches</button>' +
        '<button type="button" class="sffc-crm-apply-chat__results-stage-picker-button' +
        (activeEditorialResultsKey === "recommended" ? " is-active" : "") +
        '" data-sffc-apply-chat-results-picker="recommended">Recommended</button>' +
        '<button type="button" class="sffc-crm-apply-chat__results-stage-picker-button' +
        (activeEditorialResultsKey === "interview" ? " is-active" : "") +
        '" data-sffc-apply-chat-results-picker="interview">Interview Likely</button>' +
        '<button type="button" class="sffc-crm-apply-chat__results-stage-picker-button' +
        (activeEditorialResultsKey === "salary" ? " is-active" : "") +
        '" data-sffc-apply-chat-results-picker="salary">High Salary</button>' +
        '<button type="button" class="sffc-crm-apply-chat__results-stage-picker-button' +
        (activeEditorialResultsKey === "recent" ? " is-active" : "") +
        '" data-sffc-apply-chat-results-picker="recent">Recently Posted</button>' +
        "</div>"
      );
    }

    function bindResultsPickerButtons() {
      resultsPickerButtons = root.querySelectorAll(
        "[data-sffc-apply-chat-results-picker]"
      );
      resultsPickerButtons.forEach(function (button) {
        if (button.dataset.sffcApplyChatBound === "true") {
          return;
        }
        button.dataset.sffcApplyChatBound = "true";
        button.addEventListener("click", function () {
          var listKey =
            button.getAttribute("data-sffc-apply-chat-results-picker") || "";
          if (!listKey) {
            return;
          }
          sendJobListResultsToChat(listKey);
        });
      });
    }

    function setEditorialResultsEmptyState(title, body) {
      if (!resultsStageEmpty) {
        return;
      }
      resultsStageEmpty.innerHTML =
        "<strong>" +
        escapeHtml(title || "Choose a results list") +
        "</strong>" +
        "<p>" +
        escapeHtml(
          body ||
            "Pick one of the shortlist views to open the editorial results workspace."
        ) +
        "</p>" +
        getEditorialResultsPickerHtml();
      bindResultsPickerButtons();
      syncActiveJobListCardState();
    }

    function openJobListView(listKey) {
      activeListView = listKey || "";
      syncActiveJobListCardState();
      renderJobListView(activeListView);
      if (listsStack) {
        setElementVisibility(listsStack, false, "grid");
      }
      if (listsResults) {
        setElementVisibility(listsResults, true, "grid");
      }
      if (!isMobileWorkspaceView()) {
        setRailView("results");
      }
    }

    function syncJobListCardCounts() {
      var counts = {
        matching_cv: getJobListViewItems("matching_cv").length,
        recommended: getJobListViewItems("recommended").length,
        interview: getJobListViewItems("interview").length,
        salary: getJobListViewItems("salary").length,
        recent: getJobListViewItems("recent").length,
      };
      setMonetizationState({
        recentRolesAvailable: !!counts.recent,
      });

      listCardCounts.forEach(function (node) {
        var key = node.getAttribute("data-sffc-apply-chat-list-card-count");
        if (!key || typeof counts[key] === "undefined") {
          return;
        }
        node.textContent = counts[key] ? String(counts[key]) : "0";
      });

      if (activeListView) {
        renderJobListView(activeListView);
      }
      if (activeEditorialResultsKey) {
        renderEditorialResultsStage();
      }
      renderRailNavigation();
    }

    function isSeniorRoleTitle(title) {
      return /\b(director|head|principal|vp|vice president|senior director|managing director|partner|lead)\b/i.test(
        cleanMessageText(title || "")
      );
    }

    function getJobSearchPrimaryRoleAnchor() {
      var recommendation = buildCvRoleRecommendationContext();
      var profile = getSharedCvRoleMatchProfile();
      return cleanCvRoleDisplayLabel(
        recommendation.primary ||
          profile.title ||
          cvFacts.experienceTitle ||
          getSharedRoleTitle() ||
          "this role",
        profile.locations || []
      );
    }

    function seedJobSearchRoleTargetsFromCv() {
      var recommendation = buildCvRoleRecommendationContext();
      var profile = getSharedCvRoleMatchProfile();
      var derivedTargets = [];
      if (
        jobSearchAdditionalTargets.length ||
        conversationFacts.targetFunctions.length
      ) {
        return;
      }
      derivedTargets = getCvDisplayLaneLabels(
        profile,
        recommendation,
        applyChatSharedRuntime.buildCvRoleMatches()
      );
      if (
        !derivedTargets.length &&
        profile.families &&
        profile.families.length
      ) {
        derivedTargets = derivedTargets.concat(
          profile.families.slice(0, 2).map(getCvRoleFamilyLabel)
        );
      }
      derivedTargets = sanitizeRoleTargetList(derivedTargets).slice(0, 3);
      if (!derivedTargets.length) {
        return;
      }
      jobSearchAdditionalTargets = sanitizeRoleTargetList(
        jobSearchAdditionalTargets.concat(derivedTargets)
      );
      conversationFacts.targetFunctions = sanitizeRoleTargetList(
        conversationFacts.targetFunctions.concat(derivedTargets)
      );
      queueApplyChatMemoryPersist();
    }

    function cleanCvRoleDisplayLabel(label, locations) {
      var cleanLabel = cleanMessageText(label || "");
      var knownLocations = dedupeList(
        (locations || [])
          .map(function (item) {
            return cleanMessageText(item || "");
          })
          .filter(Boolean)
      );
      if (!cleanLabel) {
        return "";
      }
      knownLocations.forEach(function (location) {
        var escapedLocation;
        if (!location) {
          return;
        }
        escapedLocation = escapeRegex(location);
        cleanLabel = cleanLabel.replace(
          new RegExp("\\s*[-,|]\\s*" + escapedLocation + "$", "i"),
          ""
        );
      });
      cleanLabel = cleanLabel.replace(
        /\s*(?:-|,|\|)\s*(?:uae|uk|ksa|saudi arabia|united kingdom)$/i,
        ""
      );
      return cleanMessageText(cleanLabel);
    }

    function getCvDisplayLaneLabels(profile, recommendation, matches) {
      var locations = dedupeList(
        ((profile && profile.locations) || []).slice(0, 3)
      );
      var lanes = [];
      var familyLabels = dedupeList(
        ((profile && profile.families) || []).map(getCvRoleFamilyLabel)
      );

      if (profile && safeIsRealCvRoleTitle(profile.title)) {
        lanes.push(cleanCvRoleDisplayLabel(profile.title, locations));
      }
      if (
        recommendation &&
        recommendation.topMatch &&
        recommendation.topMatch.fitType === "Direct fit" &&
        recommendation.topMatch.item &&
        recommendation.topMatch.item.title
      ) {
        lanes.push(
          cleanCvRoleDisplayLabel(recommendation.topMatch.item.title, locations)
        );
      }
      if (
        recommendation &&
        recommendation.nextMatch &&
        recommendation.nextMatch.fitType === "Direct fit" &&
        recommendation.nextMatch.item &&
        recommendation.nextMatch.item.title
      ) {
        lanes.push(
          cleanCvRoleDisplayLabel(
            recommendation.nextMatch.item.title,
            locations
          )
        );
      }
      if (matches && matches.length) {
        matches.slice(0, 4).forEach(function (match) {
          if (
            match &&
            match.fitType === "Direct fit" &&
            match.item &&
            match.item.title
          ) {
            lanes.push(cleanCvRoleDisplayLabel(match.item.title, locations));
          }
        });
      }

      lanes = sanitizeRoleTargetList(lanes).filter(function (label) {
        return !/^(?:associate|manager|director|analyst|specialist|officer)$/i.test(
          cleanMessageText(label)
        );
      });
      if (lanes.length < 3 && familyLabels.length) {
        lanes = lanes.concat(familyLabels);
      }
      return dedupeList(lanes.filter(Boolean)).slice(0, 4);
    }

    function getJobSearchStructuredProfileFacts(profile) {
      var source = (profile && profile.canonicalProfile) || {};
      var timeline = (profile && profile.experienceTimeline) || [];
      var lines = [];
      var current = timeline[0] || {};
      var entryCount = timeline.length;
      var educationCount = Array.isArray(source.education)
        ? source.education.length
        : 0;
      var parsedSource = cleanMessageText(profile && profile.profileSource);
      if (parsedSource !== "structured_service") {
        return lines;
      }
      if (current.role || current.company) {
        lines.push(
          "Most recent structured entry: " +
            cleanMessageText(
              [current.role, current.company].filter(Boolean).join(" at ")
            ) +
            (current.dates ? " (" + cleanMessageText(current.dates) + ")" : "") +
            "."
        );
      }
      if (entryCount > 1) {
        lines.push(
          "I can see " +
            entryCount +
            " separate experience entries, so I’m matching against the actual career path rather than one pasted block."
        );
      }
      if (educationCount) {
        lines.push(
          "Education is structured separately, with " +
            educationCount +
            " education " +
            (educationCount === 1 ? "entry" : "entries") +
            " available for qualification matching."
        );
      }
      return lines.slice(0, 3);
    }

    function getJobSearchCvAnalysisFacts() {
      var profile = buildCvRoleMatchProfile({ cvOnly: true });
      var lines = [];
      var laneLabels = [];
      var primaryAnchor = cleanCvRoleDisplayLabel(
        profile.title || "",
        profile.locations || []
      );
      var visibleSkills = dedupeList(
        (profile.skills || [])
          .map(function (item) {
            return cleanMessageText(item);
          })
          .filter(Boolean)
      ).slice(0, 4);
      var visibleQualifications = dedupeList(
        (profile.qualifications || [])
          .map(function (item) {
            return cleanMessageText(item);
          })
          .filter(Boolean)
      ).slice(0, 3);
      var visibleLocations = dedupeList(
        (profile.locations || [])
          .map(function (item) {
            return cleanMessageText(item);
          })
          .filter(Boolean)
      ).slice(0, 2);

      if (primaryAnchor && profile.years > 0) {
        lines.push(
          profile.years +
            " years of visible experience closest to " +
            primaryAnchor +
            "."
        );
      } else if (primaryAnchor) {
        lines.push("The CV reads closest to " + primaryAnchor + ".");
      } else if (profile.years > 0) {
        lines.push(
          profile.years + " years of visible experience are clear on the CV."
        );
      } else if (
        profile.families.length ||
        visibleSkills.length ||
        visibleQualifications.length
      ) {
        lines.push(
          "The CV points most clearly toward the strongest role lane showing through the recent background."
        );
      }

      lines = lines.concat(getJobSearchStructuredProfileFacts(profile));

      if (visibleQualifications.length) {
        lines.push(
          "Qualifications detected: " +
            formatNaturalList(visibleQualifications) +
            "."
        );
      }
      if (visibleSkills.length) {
        lines.push(
          "Core tools and skills showing through: " +
            formatNaturalList(visibleSkills) +
            "."
        );
      }
      laneLabels = getCvDisplayLaneLabels(profile, null, []);
      if (laneLabels.length) {
        lines.push(
          "Strongest role lanes right now: " +
            formatNaturalList(laneLabels) +
            "."
        );
      }
      if (visibleLocations.length) {
        lines.push(
          "Current location signal: " +
            formatNaturalList(visibleLocations) +
            "."
        );
      }

      return lines.slice(0, 5);
    }

