    function didUserConfirmInboxReceipt(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return /(received|receive(?:d)?|recieved|arrived|arrive(?:d)?|landed|showed up|shown up|came through|come through|in my inbox|in the inbox|got it|got them|got those|got the email|got the emails|all received|all arrived|all landed|all good|all there|all set|i've received|ive received|i receive|i recieved|i'?ve got it|ive got it|i got it|got it now|i can see (it|them)|can see (it|them)|see (it|them) now|they're there|theyre there|it's there|its there|it'?s arrived|its arrived|it arrived|they arrived|it'?s landed|its landed|it landed|it'?s here|its here|it is here|they came through|it came through|yes i got (it|them)|yeah i got (it|them)|yes i've got (it|them)|yes ive got (it|them)|yes i receive|yes i received|yes received|yes it received|thank you[, ]*i've got (it|them)|thank you[, ]*ive got (it|them)|thanks[, ]*i've got (it|them)|thanks[, ]*ive got (it|them)|thank you[, ]*received|thanks[, ]*received|all received thank you|all received thanks|i'?ve seen it|ive seen it|seen it|saw it|ok i'?ve seen it|okay i'?ve seen it|وصلت|وصل|استلمت|استلمتها|وصلتني|شفتها|شفت الايميل|وصل الايميل|نعم وصلت)/i.test(
        clean
      );
    }

    function didUserOnlyCheckInbox(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return /(checked|looking now|i checked|i've checked|ive checked|looked|i've looked|ive looked|done|just checked|شيكت|تحققت|بشوف|اشوف الحين|بشيك|شيكت الحين)/i.test(
        clean
      );
    }

