    function rankHomeLauncherSuggestions(query) {
      var clean = cleanMessageText(query || "");
      var lower = clean.toLowerCase();
      var roles = getHomeLauncherRoleOptions();
      var locations = getHomeLauncherLocationOptions();
      var patterns = getHomeLauncherQueryPatterns();
      var suggestions = [];
      var locationMention = extractPrimarySearchLocation(clean);
      var hasLocationPhrase = /\bin\s+[a-z]/i.test(clean);

      function pushSuggestion(text, score) {
        var normalized = cleanMessageText(text);
        if (!normalized) {
          return;
        }
        suggestions.push({
          text: normalized,
          score: score || 0,
        });
      }

      roles.forEach(function (role) {
        var roleLower = role.toLowerCase();
        if (!lower) {
          patterns.suffixes.forEach(function (suffix, suffixIndex) {
            pushSuggestion(role + suffix, 24 - suffixIndex);
          });
          return;
        }
        if (
          roleLower.indexOf(lower) !== -1 ||
          lower.indexOf(roleLower) !== -1
        ) {
          patterns.suffixes.forEach(function (suffix, suffixIndex) {
            pushSuggestion(role + suffix, 130 - suffixIndex);
          });
          if (!locationMention && !hasLocationPhrase) {
            locations.forEach(function (location, index) {
              pushSuggestion(role + " jobs in " + location, 112 - index);
              pushSuggestion(role + " roles in " + location, 102 - index);
              pushSuggestion(
                role + " opportunities in " + location,
                96 - index
              );
            });
          }
        }
      });

      patterns.prefixes.forEach(function (prefix, prefixIndex) {
        roles.slice(0, 40).forEach(function (role, roleIndex) {
          var baseRole = (prefix + role).trim();
          if (
            !lower ||
            baseRole.indexOf(lower) !== -1 ||
            lower.indexOf(baseRole) !== -1
          ) {
            patterns.suffixes.forEach(function (suffix, suffixIndex) {
              pushSuggestion(
                baseRole + suffix,
                92 - prefixIndex - roleIndex - suffixIndex
              );
            });
            if (!locationMention && !hasLocationPhrase && roleIndex < 16) {
              locations.slice(0, 8).forEach(function (location, locationIndex) {
                pushSuggestion(
                  baseRole + " jobs in " + location,
                  82 - prefixIndex - roleIndex - locationIndex
                );
              });
            }
          }
        });
      });

      if (lower) {
        locations.forEach(function (location, index) {
          var locationLower = location.toLowerCase();
          if (lower.indexOf(locationLower) !== -1) {
            roles.slice(0, 32).forEach(function (role, roleIndex) {
              pushSuggestion(role + " jobs in " + location, 100 - roleIndex);
              pushSuggestion(role + " roles in " + location, 90 - roleIndex);
              pushSuggestion(
                role + " opportunities in " + location,
                84 - roleIndex
              );
            });
          }
        });
      }

      if (lower) {
        patterns.sectorPhrases.forEach(function (sector, sectorIndex) {
          if (lower.indexOf(sector.toLowerCase()) !== -1) {
            roles.slice(0, 24).forEach(function (role, roleIndex) {
              pushSuggestion(
                role + " jobs in " + sector,
                88 - sectorIndex - roleIndex
              );
              if (!locationMention) {
                locations
                  .slice(0, 10)
                  .forEach(function (location, locationIndex) {
                    pushSuggestion(
                      role + " jobs in " + sector + " in " + location,
                      76 - sectorIndex - roleIndex - locationIndex
                    );
                  });
              }
            });
          }
        });
      }

      if (lower && !suggestions.length) {
        if (locationMention) {
          pushSuggestion(clean, 90);
        } else {
          locations.forEach(function (location, index) {
            pushSuggestion(clean + " in " + location, 70 - index);
          });
        }
      }

      if (lower) {
        roles.slice(0, 28).forEach(function (role, roleIndex) {
          patterns.modifiers.forEach(function (modifier, modifierIndex) {
            if (
              modifier &&
              (lower.indexOf(role.toLowerCase()) !== -1 ||
                role.toLowerCase().indexOf(lower) !== -1)
            ) {
              pushSuggestion(
                role + " jobs" + modifier,
                74 - roleIndex - modifierIndex
              );
            }
          });
          patterns.schedulePhrases.forEach(function (schedule, scheduleIndex) {
            if (
              lower.indexOf(role.toLowerCase()) !== -1 ||
              role.toLowerCase().indexOf(lower) !== -1
            ) {
              pushSuggestion(
                role + " " + schedule + " jobs",
                68 - roleIndex - scheduleIndex
              );
              if (!locationMention) {
                locations
                  .slice(0, 8)
                  .forEach(function (location, locationIndex) {
                    pushSuggestion(
                      role + " " + schedule + " jobs in " + location,
                      60 - roleIndex - scheduleIndex - locationIndex
                    );
                  });
              }
            }
          });
        });
      }

      return dedupeList(
        suggestions
          .sort(function (a, b) {
            return b.score - a.score;
          })
          .map(function (item) {
            return item.text;
          })
      ).slice(0, 24);
    }

    function closeHomeLauncherSuggestions() {
      homeLauncherSuggestionItems = [];
      homeLauncherSuggestionIndex = -1;
      if (homeLauncherSuggestions) {
        homeLauncherSuggestions.hidden = true;
        homeLauncherSuggestions.innerHTML = "";
      }
    }

    var homeLauncherTypingTimer = null;
    var homeLauncherTypingPhraseIndex = 0;
    var homeLauncherTypingCharIndex = 0;
    var homeLauncherTypingDeleting = false;
    var homeLauncherTypingSequence = [
      "Find private equity roles in Dubai",
      "Show me investment analyst jobs in Riyadh",
      "Search for M&A associate roles in Dubai",
      "Find corporate development jobs in Abu Dhabi",
      "Show me private credit opportunities in Riyadh",
      "Find asset management roles in Doha",
      "Search sovereign wealth fund jobs in the GCC",
      "Find recruiter-backed roles in Abu Dhabi",
      "Show me roles where Arabic is not required",
      "Find senior associate roles in consulting",
      "Search finance manager roles in Dubai",
      "Find FP&A roles in Saudi Arabia",
      "Show me internal control jobs in the UAE",
    ];

    function syncHomeLauncherTypingState() {
      if (!homeLauncherForm || !homeLauncherQuery || !homeLauncherTyping) {
        return false;
      }
      var hasValue = !!cleanMessageText(homeLauncherQuery.value || "");
      homeLauncherForm.classList.toggle("has-typing", true);
      homeLauncherForm.classList.toggle("has-value", hasValue);
      return !hasValue;
    }

    function stopHomeLauncherTyping() {
      if (homeLauncherTypingTimer) {
        window.clearTimeout(homeLauncherTypingTimer);
        homeLauncherTypingTimer = null;
      }
    }

    function scheduleHomeLauncherTyping(delay) {
      stopHomeLauncherTyping();
      homeLauncherTypingTimer = window.setTimeout(
        runHomeLauncherTypingFrame,
        delay
      );
    }

    function runHomeLauncherTypingFrame() {
      var phrase;
      var text;
      var delay;
      if (!homeLauncherTyping || !homeLauncherTypingSequence.length) {
        return;
      }
      if (!syncHomeLauncherTypingState()) {
        homeLauncherTyping.textContent = "";
        scheduleHomeLauncherTyping(260);
        return;
      }
      phrase =
        homeLauncherTypingSequence[
          homeLauncherTypingPhraseIndex % homeLauncherTypingSequence.length
        ];
      if (!homeLauncherTypingDeleting) {
        homeLauncherTypingCharIndex = Math.min(
          phrase.length,
          homeLauncherTypingCharIndex + 1
        );
        text = phrase.slice(0, homeLauncherTypingCharIndex);
        delay =
          homeLauncherTypingCharIndex >= phrase.length
            ? 1450
            : 34 + Math.round(Math.random() * 34);
        if (homeLauncherTypingCharIndex >= phrase.length) {
          homeLauncherTypingDeleting = true;
        }
      } else {
        homeLauncherTypingCharIndex = Math.max(
          0,
          homeLauncherTypingCharIndex - 2
        );
        text = phrase.slice(0, homeLauncherTypingCharIndex);
        delay =
          homeLauncherTypingCharIndex <= 0
            ? 260
            : 18 + Math.round(Math.random() * 18);
        if (homeLauncherTypingCharIndex <= 0) {
          homeLauncherTypingDeleting = false;
          homeLauncherTypingPhraseIndex =
            (homeLauncherTypingPhraseIndex + 1) %
            homeLauncherTypingSequence.length;
        }
      }
      homeLauncherTyping.textContent = text;
      scheduleHomeLauncherTyping(delay);
    }

    function startHomeLauncherTyping() {
      if (!homeLauncherTyping || !homeLauncherQuery || !homeLauncherForm) {
        return;
      }
      homeLauncherForm.classList.add("has-typing");
      if (
        window.matchMedia &&
        window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ) {
        homeLauncherTyping.textContent = homeLauncherTypingSequence[0] || "";
        syncHomeLauncherTypingState();
        return;
      }
      if (!homeLauncherTypingTimer) {
        runHomeLauncherTypingFrame();
      }
    }

    function syncHomeLauncherLocationIndicator() {
      var label;
      var location = cleanMessageText(homeLauncherSelectedLocation || "Dubai");
      if (!homeLauncherMode) {
        return;
      }
      label = homeLauncherMode.querySelector(
        "[data-sffc-apply-chat-home-location-label]"
      );
      if (label) {
        label.textContent = location;
      }
      homeLauncherMode.setAttribute(
        "aria-label",
        "Selected location: " + location
      );
      homeLauncherMode.setAttribute("data-selected-location", location);
      if (homeLauncherLocationToggle) {
        homeLauncherLocationToggle.setAttribute(
          "data-selected-location",
          location
        );
        homeLauncherLocationToggle.setAttribute(
          "aria-label",
          "Location: " + location
        );
      }
    }

    syncHomeLauncherLocationIndicator();

    function applyHomeLauncherSuggestion(value, options) {
      var cleanValue = cleanMessageText(value || "");
      var shouldLaunch = !!(options && options.launch);
      if (!homeLauncherQuery || !cleanValue) {
        return;
      }
      homeLauncherQuery.value = cleanValue;
      syncHomeLauncherTypingState();
      closeHomeLauncherSuggestions();
      if (shouldLaunch) {
        pendingLaunchContext = buildActiveLauncherContext(cleanValue);
        pendingLaunchOpenFilePicker = false;
        openChat();
        return;
      }
      homeLauncherQuery.focus();
    }

    function renderHomeLauncherSuggestions(query) {
      var suggestions;
      if (!homeLauncherSuggestions || !homeLauncherQuery) {
        return;
      }
      suggestions = rankHomeLauncherSuggestions(query);
      if (!suggestions.length || !cleanMessageText(query || "")) {
        closeHomeLauncherSuggestions();
        return;
      }
      homeLauncherSuggestionItems = suggestions.slice(0);
      homeLauncherSuggestionIndex = -1;
      homeLauncherSuggestions.innerHTML = suggestions
        .map(function (item, index) {
          return (
            "" +
            '<button type="button" class="sffc-crm-apply-chat__home-suggestion" data-sffc-apply-chat-home-suggestion="' +
            escapeHtml(item) +
            '" data-sffc-apply-chat-home-suggestion-index="' +
            index +
            '">' +
            '<span class="sffc-crm-apply-chat__home-suggestion-icon" aria-hidden="true">⌕</span>' +
            '<span class="sffc-crm-apply-chat__home-suggestion-copy">' +
            escapeHtml(item) +
            "</span>" +
            "</button>"
          );
        })
        .join("");
      homeLauncherSuggestions.hidden = false;
    }

    function updateHomeLauncherSuggestionHighlight() {
      if (!homeLauncherSuggestions) {
        return;
      }
      homeLauncherSuggestions
        .querySelectorAll("[data-sffc-apply-chat-home-suggestion-index]")
        .forEach(function (button) {
          var index = parseInt(
            button.getAttribute("data-sffc-apply-chat-home-suggestion-index") ||
              "-1",
            10
          );
          button.classList.toggle(
            "is-active",
            index === homeLauncherSuggestionIndex
          );
        });
    }

