    function startJobSearchFromLauncherContext(context) {
      if (getConfig().isLoggedIn) {
        beginLoggedInJobSearchFlow(context, {
          mode: homeLauncherMode ? homeLauncherMode.value : "search_apply",
          launchMode: jobSearchLaunchMode || "",
        });
        return;
      }
      var hasExistingCvForSearch = hasApplyChatCvAvailable();
      var introLine = getLauncherContextConfirmationLine(context);
      var uploadPromptLine = hasExistingCvForSearch
        ? getJobSearchExistingCvPromptLine()
        : getJobSearchUploadPromptLine();
      var transferCopy = getInterfaceCopy("transfer_emily");
      var sequence = [
        {
          html: introLine,
          delay: humanComposeDelay(introLine, 1800, 3400),
          pause: humanReadDelay(transferCopy, 420),
        },
      ];

      activePath = "job_search";
      step = "job_search_upload";
      jobSearchCvAcknowledged = false;
      jobSearchSeedContext = context || null;
      jobSearchSelectedPackage = context && context.mode ? context.mode : "";
      setMonetizationState({
        packageSelected: jobSearchSelectedPackage || "",
      });

      if (context && context.query) {
        userMessage(context.query, "", { skipChatLog: true });
      }
      addTransferNotice(transferCopy);
      setDeskIdentity("emily");

      sequence.push({
        html: uploadPromptLine,
        delay: humanComposeDelay(uploadPromptLine, 1800, 3400),
        pause: humanReadDelay(introLine, 420),
      });

      botSequenceForCurrentTurn(sequence, function () {
        if (hasExistingCvForSearch) {
          uploadButton.hidden = true;
          input.disabled = false;
          window.setTimeout(function () {
            continueJobSearchAfterCvUpload();
          }, randomBetween(260, 620));
          return;
        }
        uploadButton.hidden = false;
        focusComposer(getUploadCvPlaceholder());
        if (pendingLaunchOpenFilePicker) {
          pendingLaunchOpenFilePicker = false;
          window.setTimeout(function () {
            fileInput.click();
          }, 120);
        }
      });
    }

