    function routePendingLaunchContext(context) {
      if (!context) {
        return false;
      }
      rememberLauncherSearchContext(context);
      if (cleanMessageText(context.entryRoute || "") === "home_trending_job") {
        pendingApplyResultsSelection =
          setCurrentApplicationContextFromQueueItem(
            context.selectedRole || context
          );
        if (pendingApplyResultsSelection) {
          careerConversationMemory.currentSelectedRole =
            pendingApplyResultsSelection;
          rememberCommercialApplyQueueCatalogItems([
            pendingApplyResultsSelection,
          ]);
        }
        startApplyForMeRoleDiscoveryFlow();
        return true;
      }
      if (
        cleanMessageText(context.entryRoute || "") === "landing_filter_search"
      ) {
        startLandingFilterSearchFromContext(context);
        return true;
      }
      if (context.recruiterOutreachStart) {
        startRecruiterOutreachFromLauncherContext(context);
        return true;
      }
      if (context.profileReviewStart) {
        activePath = "review_profile";
        addTransferNotice(getInterfaceCopy("transfer_consultant"));
        setDeskIdentity("emily");
        if (isReviewOnlyLauncher && !hasSelectedProfileReviewRoleContext()) {
          promptForStandaloneProfileReviewTargetRole(function () {
            promptForCv();
          });
          return true;
        }
        promptForCv();
        return true;
      }
      if (
        cleanMessageText(context.entryRoute || "") ===
        "apply_for_me_role_discovery_home"
      ) {
        jobSearchSeedContext = context || null;
        startApplyForMeRoleDiscoveryFlow();
        return true;
      }
      if (isHomeApplyIntroLaunchContext(context)) {
        startApplyIntroFromLauncherContext(context);
        return true;
      }
      startJobSearchFromLauncherContext(context);
      return true;
    }

    function startLandingFilterSearchFromContext(context) {
      var query = cleanMessageText((context && context.query) || "");
      var roleFocus = cleanMessageText((context && context.roleTarget) || "");
      var locationFocus = cleanMessageText((context && context.location) || "");
      var sectorFocus = cleanMessageText((context && context.sector) || "");

      activePath = "job_search";
      step = "job_search_results";
      jobSearchSeedContext = context || null;
      jobSearchLaunchMode = "landing_filter_search";
      if (locationFocus) {
        jobSearchPreferredLocation = locationFocus;
      }
      if (roleFocus) {
        conversationFacts.targetFunctions = sanitizeRoleTargetList(
          [roleFocus].concat(conversationFacts.targetFunctions || [])
        );
      }
      if (sectorFocus) {
        conversationFacts.targetSectors = uniqueCleanItems(
          [sectorFocus].concat(conversationFacts.targetSectors || [])
        );
      }
      if (query) {
        userMessage(query, "", { skipChatLog: true });
      }
      addTransferNotice(getInterfaceCopy("transfer_emily"));
      setDeskIdentity("emily");
      searchActualJobPostsInChat(
        query || roleFocus || sectorFocus || "finance jobs"
      );
    }

