    function getApplyPricingOption(accountType) {
      var target = String(accountType || "")
        .trim()
        .toLowerCase();
      var found = null;
      applyChatPricingOptions.forEach(function (option) {
        if (found || !option) {
          return;
        }
        if (
          String(option.account_type || "")
            .trim()
            .toLowerCase() === target
        ) {
          found = option;
        }
      });
      return found;
    }

