    function normalizeDetectedCompanyName(text) {
      var clean = cleanMessageText(text || "");
      var changed = true;
      if (!clean) {
        return "";
      }
      clean = clean
        .replace(/\s*[|•·▪◦]\s*/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      while (changed) {
        changed = false;
        getCompanySuffixPatterns().forEach(function (suffix) {
          var escaped = suffix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
          var regex = new RegExp("\\s+(?:" + escaped + ")$", "i");
          if (regex.test(clean)) {
            clean = clean.replace(regex, "").trim();
            changed = true;
          }
        });
      }
      clean = clean
        .replace(/\b(?:the)\s+/i, "")
        .replace(/[.,;:]+$/g, "")
        .replace(/\s+/g, " ")
        .trim();
      return clean;
    }

    function looksLikeDetectedCompanyName(text) {
      var clean = cleanMessageText(text || "");
      var normalized = normalizeDetectedCompanyName(clean);
      if (!clean || !normalized || normalized.split(/\s+/).length > 9) {
        return false;
      }
      if (
        isCvContactLine(clean) ||
        looksLikeCvLocationLine(clean) ||
        hasCvDateRange(clean) ||
        isLikelyCvQualificationText(clean) ||
        looksLikeCvEducationSignalLine(clean) ||
        looksLikeCvAwardOrLanguageLine(clean) ||
        hasCvProfessionalActionSignal(clean) ||
        looksLikeCvResponsibilityLabel(clean)
      ) {
        return false;
      }
      if (
        /^(?:excel|vba|powerpoint|microsoft powerpoint|word|sql|python|tableau|power bi|solver|arabic|english|french|german|spanish|critical thinking|communication|leadership|time management|financial modelling|financial modeling|market research|data analysis|financial analysis|valuation|benchmarking|education|sports|healthcare|private equity|investment banking)$/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:analysis|modelling|modeling|reporting|research|reconciliation|preparation|processing|management|leadership|communication|degree|bachelor|master|university|coursework|module|modules|language|languages|native|fluent)\b/i.test(
          clean
        ) &&
        !/\b(?:ltd|limited|inc|corp|corporation|llc|llp|plc|company|co\.?|group|capital|partners|advisors?|advisory|investments?|management company|bank|consulting|holdings|ventures|services|systems|payments|pvt|ag|gmbh|sarl|sa|spa|s\.p\.a\.|s\.r\.l\.)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:analyst|associate|manager|director|consultant|intern|officer|lead|partner|controller|accountant|auditor|research|banker|specialist|advisor|vice president|vp|principal|executive)\b/i.test(
          clean
        ) &&
        !/\b(bank|group|capital|partners|advisors?|investments?|management|holdings|fund|trust|consulting)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:family office|private family office)\b/i.test(clean) ||
        getCompanySuffixPatterns().some(function (suffix) {
          var escaped = suffix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
          return new RegExp("\\b" + escaped + "\\b", "i").test(clean);
        })
      ) {
        return true;
      }
      return (
        /^[A-ZÀ-Ý][A-Za-zÀ-ÿ&'’.-]+(?:\s+[A-ZÀ-Ý][A-Za-zÀ-ÿ&'’.-]+){0,4}$/.test(
          clean
        ) && normalized.split(/\s+/).length <= 4
      );
    }

    function isBadTailoredCvCompanyValue(value, candidateName) {
      var clean = cleanMessageText(value || "");
      if (!clean) {
        return true;
      }
      if (
        candidateName &&
        clean.toLowerCase() ===
          cleanMessageText(candidateName || "").toLowerCase()
      ) {
        return true;
      }
      return /^(?:period|current|present|completed|results?|resume checker results?|matric|qualification|qualifications|berufserfahrung|thesis|kontakt|contact|education|experience|professional experience|work experience|work history|employment|skills|languages?|profile|about me|date of birth|status|nationality|madrid|london|dubai|riyadh|milan|paris|rome|toronto|india|uk|usa|uae|egypt|spain|switzerland|france|germany)$/i.test(
        clean
      );
    }

    function looksLikeStrongTailoredCvCompanyName(value) {
      var clean = cleanMessageText(value || "");
      if (!clean || clean.split(/\s+/).length < 2) {
        return false;
      }
      return (
        /\b(?:ltd|limited|inc|corp|corporation|llc|llp|plc|company|co\.?|group|capital|partners|advisors?|advisory|investments?|management|bank|consulting|finance|financial|holdings|ventures|services|systems|payments|pvt|ag|gmbh|sarl|sa|spa|s\.p\.a\.|s\.r\.l\.)\b/i.test(
          clean
        ) ||
        /\b(?:family office|private family office)\b/i.test(clean) ||
        /^[A-Z0-9&().,\s-]{8,}$/.test(clean)
      );
    }

    function sanitizeTailoredCvRenderedRole(value) {
      var role = normalizeCvRoleTitleText(
        cleanExperienceMetaFragment(value || "")
      );
      if (!role) {
        return "";
      }
      if (/^(?:with|for|at|in|on|and|to)\b/i.test(role)) {
        return "";
      }
      if (role.split(/\s+/).length > 8) {
        return "";
      }
      if (
        !looksLikeExperienceRoleLabel(role) &&
        !looksLikeCvRoleTitleLine(role, "")
      ) {
        return "";
      }
      return role;
    }

    function sanitizeTailoredCvRenderedCompany(value, candidateName) {
      var company = cleanMessageText(value || "");
      if (
        !company ||
        isBadTailoredCvCompanyValue(company, candidateName) ||
        /^(?:with|for|at|in|on|and|to|of)\b/i.test(company) ||
        /^[0-9]+(?:[.%]|\s*%|\b)/.test(company) ||
        /^(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)$/i.test(
          company
        ) ||
        looksLikeCvTailoringEducationLine(company) ||
        looksLikeExperienceRoleLabel(company) ||
        looksLikeCvRoleTitleLine(company, "")
      ) {
        return "";
      }
      if (company.split(/\s+/).length > 9) {
        return "";
      }
      return company.replace(/[.,;:]+$/g, "").trim();
    }

    function splitTailoredCvCompositeRoleCompany(role, company, candidateName) {
      var cleanRole = cleanExperienceMetaFragment(role || "");
      var cleanCompany = cleanMessageText(company || "");
      var rolePattern =
        "(?:senior\\s+|junior\\s+|associate\\s+|assistant\\s+|avp\\s+|vp\\s+)?(?:financial\\s+crime\\s+|finance\\s+|credit\\s+|investment\\s+|business\\s+development\\s+|client\\s+services\\s+|payments?\\s+and\\s+client\\s+services\\s+|kyc\\s+(?:&|and)\\s+aml\\s+|kyc\\s+(?:&|and)\\s+cdd\\s+)?(?:analyst|associate|manager|consultant|intern|officer|specialist|engineer|developer|accountant|auditor)";
      var embedded = cleanRole.match(
        new RegExp(
          "^(.{4,90}?)\\s+(" + rolePattern + ")(?:\\s*\\([^)]*\\))?$",
          "i"
        )
      );
      var moved;
      if (
        embedded &&
        looksLikeStrongTailoredCvCompanyName(embedded[1]) &&
        !isBadTailoredCvCompanyValue(embedded[1], candidateName)
      ) {
        cleanRole = cleanExperienceMetaFragment(embedded[2]);
        cleanCompany = cleanCompany || cleanMessageText(embedded[1]);
      }
      if (
        /^(?:analyst|associate|manager|consultant|specialist)$/i.test(
          cleanRole
        ) &&
        /\b(?:financial|finance|credit|investment|business development|client services|kyc|aml|cdd)\s*$/i.test(
          cleanCompany
        )
      ) {
        moved =
          (cleanCompany.match(
            /\b(financial|finance|credit|investment|business development|client services|kyc|aml|cdd)\s*$/i
          ) || [])[1] || "";
        if (moved) {
          cleanRole = cleanExperienceMetaFragment(moved + " " + cleanRole);
          cleanCompany = cleanMessageText(
            cleanCompany.replace(
              new RegExp("\\b" + moved.replace(/\s+/g, "\\s+") + "\\s*$", "i"),
              ""
            )
          );
        }
      }
      return {
        role: sanitizeTailoredCvRenderedRole(cleanRole),
        company: sanitizeTailoredCvRenderedCompany(cleanCompany, candidateName),
      };
    }

    function detectCompanyNameFromText(text) {
      var clean = cleanExperienceMetaFragment(text || "");
      var locationTrimmed;
      var parts;
      var matched = "";
      if (!clean) {
        return "";
      }
      if (isCvEvidenceLine(clean)) {
        return "";
      }
      locationTrimmed = cleanMessageText(
        clean.replace(
          /(?:,?\s*(?:dubai|abu dhabi|doha|riyadh|jeddah|dammam|khobar|london|paris|milan|rome|moscow|madrid|barcelona|new york|toronto|montreal|gurugram|amman|beirut|qatar|uae|uk|india|italy|spain|saudi arabia|syria|russia|france|canada))+$/i,
          ""
        )
      );
      parts = clean
        .split(/\s*[|•·▪◦\-–—]\s*/)
        .map(cleanExperienceMetaFragment)
        .filter(Boolean);
      if (locationTrimmed && locationTrimmed !== clean) {
        parts.unshift(locationTrimmed);
      }
      parts.some(function (part) {
        if (looksLikeDetectedCompanyName(part)) {
          matched = cleanMessageText(part);
          return true;
        }
        return false;
      });
      if (matched) {
        return matched;
      }
      return looksLikeDetectedCompanyName(clean)
        ? cleanMessageText(clean)
        : "";
    }

    function looksLikeExperienceRoleLabel(text) {
      var clean = cleanMessageText(text || "");
      if (
        !clean ||
        isCvContactLine(clean) ||
        looksLikeCvLocationLine(clean) ||
        hasCvDateRange(clean)
      ) {
        return false;
      }
      if (
        /^(?:with|and|to|for|from|of|in|on|support to|supporting|responsible for|preparation of|generation of)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      clean = clean
        .replace(/^(?:job\s+title|title|position|role)\s*[:\-]?\s*/i, "")
        .replace(
          /^(?:المسمى الوظيفي|الوظيفة|المنصب|الهدف الوظيفي)\s*[:\-]?\s*/i,
          ""
        )
        .replace(/\s*@.*$/g, "")
        .trim();
      if (
        !/\b(analyst|analista|associate|assistant|assistente|manager|director|consultant|consultor|intern|internship|officer|lead|controller|accountant|accounting|auditor|research|banker|specialist|especialista|advisor|vice president|vp|principal|executive|lawyer|graduate|scientist|programmer|engineer|developer|procurement|treasury|compliance|privacy|customer service|call cent(?:re|er)|supply chain|logistics|credit|risk|finance|strategy|trader|trading|order management|business partnerships|alliances|assistant financier|financial specialist|consultan[tc]e?|receptionist|administrative|treasurer|supervisor|chief)\b|(?:محلل|مدير|محاسب|محاسبة|مدقق|مستشار|أخصائي|اخصائي|مسؤول|منسق|مشرف|تنفيذي|مهندس|مطور|قائد فريق|رئيس قسم|متدرب|خزينة|امتثال|مخاطر|استثمار|تمويل|مالي|موارد بشرية|استقبال|مشتريات|لوجستيات|خدمة العملاء)/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(bank|group|capital|partners|advisors?|investments?|management|holdings|fund|trust|consulting|corporate and investment bank)\b/i.test(
          clean
        ) &&
        !/\b(credit|equity|research|private equity|investment banking|corporate finance|risk|finance|financial|product|strategy)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      return clean.split(/\s+/).length <= 8 && safeIsRealCvRoleTitle(clean);
    }

    function extractPrimaryExperienceRoleContext(entry) {
      var meta = buildExperienceEntryMeta(entry);
      var heading = cleanExperienceMetaFragment(meta.heading || "");
      var metaLine = cleanExperienceMetaFragment(meta.metaLine || "");
      var lines = ((entry && entry.lines) || [])
        .map(cleanMessageText)
        .filter(Boolean);
      var candidates = [];
      var headingParts;
      var companyCandidates = [];
      var role = "";
      var company = "";
      var evidenceText = "";
      var cleanHeading = cleanMessageText(meta.heading || "");
      var directCompany = "";
      var directRole = "";
      var structuredDatedEntry = null;

      function splitParts(text) {
        return cleanMessageText(text)
          .split(/\s*[|•·▪◦\-–—]\s*|\s*:\s*/)
          .map(cleanExperienceMetaFragment)
          .filter(Boolean);
      }

      if (
        lines.length >= 3 &&
        (looksLikeExperienceRoleLabel(lines[0]) ||
          looksLikeCvRoleTitleLine(lines[0], "")) &&
        !hasCvDateRange(lines[0]) &&
        !isCvEvidenceLine(lines[0])
      ) {
        var separatedCompany = cleanMessageText(
          detectCompanyNameFromText(lines[1]) || lines[1]
        );
        var separatedDate = lines.slice(1, 4).find(function (line) {
          return (
            looksLikeCvPureDateRangeLine(line) ||
            hasCvDateRange(line) ||
            getCvTailoringLooseDateText(line)
          );
        });
        if (
          separatedCompany &&
          separatedDate &&
          !looksLikeExperienceRoleLabel(separatedCompany) &&
          !isCvEvidenceLine(separatedCompany)
        ) {
          return {
            role: normalizeCvRoleTitleText(lines[0]),
            company: separatedCompany,
            label: cleanMessageText(
              [normalizeCvRoleTitleText(lines[0]), separatedCompany]
                .filter(Boolean)
                .join(" at ")
            ),
          };
        }
      }

      if (
        lines.length >= 3 &&
        looksLikeCvCompanyOrProjectHeading(lines[0]) &&
        (looksLikeExperienceRoleLabel(lines[1]) ||
          looksLikeCvRoleTitleLine(lines[1], "")) &&
        (looksLikeCvPureDateRangeLine(lines[2]) ||
          hasCvDateRange(lines[2]) ||
          getCvTailoringLooseDateText(lines[2]))
      ) {
        return {
          role: normalizeCvRoleTitleText(lines[1]),
          company: cleanMessageText(
            detectCompanyNameFromText(lines[0]) || lines[0]
          ),
          label: cleanMessageText(
            [
              normalizeCvRoleTitleText(lines[1]),
              detectCompanyNameFromText(lines[0]) || lines[0],
            ]
              .filter(Boolean)
              .join(" at ")
          ),
        };
      }

      lines.slice(0, 4).some(function (line) {
        structuredDatedEntry = parseCvStructuredDatedEntryLine(line);
        return !!structuredDatedEntry;
      });

      if (structuredDatedEntry) {
        return {
          role: cleanMessageText(structuredDatedEntry.role || ""),
          company: cleanMessageText(structuredDatedEntry.company || ""),
          label: cleanMessageText(
            structuredDatedEntry.label ||
              [structuredDatedEntry.role, structuredDatedEntry.company]
                .filter(Boolean)
                .join(" at ")
          ),
        };
      }

      lines.slice(0, 5).some(function (line) {
        var cleanedLine = cleanMessageText(line);
        var companyCandidate;
        if (
          !cleanedLine ||
          isCvContactLine(cleanedLine) ||
          hasCvDateRange(cleanedLine) ||
          isCvEvidenceLine(cleanedLine)
        ) {
          return false;
        }
        companyCandidate = detectCompanyNameFromText(cleanedLine);
        if (
          companyCandidate &&
          (looksLikeCvCompanyOrProjectHeading(cleanedLine) ||
            looksLikeDetectedCompanyName(companyCandidate))
        ) {
          directCompany = companyCandidate;
          return true;
        }
        return false;
      });

      lines.slice(0, 6).some(function (line) {
        var cleanedLine = cleanExperienceMetaFragment(line);
        if (
          !cleanedLine ||
          cleanedLine === directCompany ||
          isCvContactLine(cleanedLine) ||
          hasCvDateRange(cleanedLine) ||
          isCvEvidenceLine(cleanedLine)
        ) {
          return false;
        }
        if (
          looksLikeExperienceRoleLabel(cleanedLine) ||
          looksLikeCvRoleTitleLine(cleanedLine, "")
        ) {
          directRole = cleanedLine;
          return true;
        }
        return false;
      });

      if (directCompany || directRole) {
        return {
          role: cleanMessageText(directRole),
          company: cleanMessageText(directCompany),
          label: [cleanMessageText(directRole), cleanMessageText(directCompany)]
            .filter(Boolean)
            .join(" at "),
        };
      }

      headingParts = splitParts(heading).concat(splitParts(metaLine));
      candidates = candidates.concat(headingParts).concat(
        lines.slice(0, 4).reduce(function (list, line) {
          return list.concat(splitParts(line));
        }, [])
      );
      evidenceText = [heading, metaLine].concat(lines.slice(0, 6)).join(" | ");

      candidates.forEach(function (part) {
        var detected = detectCompanyNameFromText(part);
        if (detected && !looksLikeCvLocationLine(part) && !isCvEvidenceLine(part)) {
          companyCandidates.push(detected);
        }
      });

      candidates.forEach(function (part) {
        if (!role && !isCvEvidenceLine(part) && looksLikeExperienceRoleLabel(part)) {
          role = part;
          return;
        }
        if (
          !company &&
          role &&
          !isCvContactLine(part) &&
          !looksLikeCvLocationLine(part) &&
          !hasCvDateRange(part) &&
          !isCvEvidenceLine(part) &&
          part !== role
        ) {
          company = detectCompanyNameFromText(part);
        }
      });

      if (!role && heading && !isCvContactLine(heading)) {
        if (looksLikeExperienceRoleLabel(heading)) {
          role = heading;
        } else {
          candidates.some(function (part) {
            if (!isCvEvidenceLine(part) && looksLikeExperienceRoleLabel(part)) {
              role = part;
              return true;
            }
            return false;
          });
        }
      }
      if (!company && companyCandidates.length) {
        company = companyCandidates.sort(function (a, b) {
          return b.length - a.length;
        })[0];
      }
      if (!company) {
        company =
          detectCompanyNameFromText(heading) ||
          detectCompanyNameFromText(metaLine);
      }
      if (role && company) {
        role = cleanMessageText(role)
          .replace(
            new RegExp(
              "\\b" + company.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b",
              "i"
            ),
            ""
          )
          .replace(/\s+/g, " ")
          .trim();
      }
      if (role && /\b(at|for|with)\s*$/i.test(role)) {
        role = role.replace(/\b(at|for|with)\s*$/i, "").trim();
      }
      if (role) {
        role = cleanExperienceMetaFragment(role);
      }
      if (
        !role &&
        cleanHeading &&
        !looksLikeDetectedCompanyName(cleanHeading)
      ) {
        role = cleanExperienceMetaFragment(cleanHeading);
      }
      role = deriveCvRoleTitleFromGenericHeading(role, evidenceText) || role;

      return {
        role: cleanMessageText(role),
        company: cleanMessageText(company),
        label: [cleanMessageText(role), cleanMessageText(company)]
          .filter(Boolean)
          .join(" at "),
      };
    }

    function extractRecentCvRoleContextFromSections(sections) {
      var entries = getExperienceEntries(sections);
      var sectionItems = [];
      var resolved = null;

      function buildContextFromLines(lines) {
        var cleanLines = (lines || [])
          .map(cleanMessageText)
          .filter(Boolean)
          .slice(0, 8);
        var role = "";
        var company = "";
        var i;

        for (i = 0; i < cleanLines.length; i += 1) {
          if (looksLikeExperienceRoleLabel(cleanLines[i])) {
            role = normalizeCvRoleTitleText(cleanLines[i]);
            break;
          }
        }
        if (!role) {
          return null;
        }

        for (i = 0; i < cleanLines.length; i += 1) {
          if (cleanLines[i] === role) {
            continue;
          }
          if (
            isCvContactLine(cleanLines[i]) ||
            looksLikeCvLocationLine(cleanLines[i]) ||
            hasCvDateRange(cleanLines[i])
          ) {
            continue;
          }
          company = detectCompanyNameFromText(cleanLines[i]);
          if (company) {
            break;
          }
        }

        return {
          role: role,
          company: normalizeDetectedCompanyName(company),
          label: [role, normalizeDetectedCompanyName(company)]
            .filter(Boolean)
            .join(" at "),
        };
      }

      entries.some(function (entry) {
        var direct = extractPrimaryExperienceRoleContext(entry || {});
        if (safeIsRealCvRoleTitle((direct && direct.role) || "")) {
          resolved = {
            role: normalizeCvRoleTitleText(direct.role || ""),
            company: normalizeDetectedCompanyName(direct.company || ""),
            label: cleanMessageText(
              direct.label ||
                [direct.role, direct.company].filter(Boolean).join(" at ")
            ),
          };
          return true;
        }

        direct = buildContextFromLines(
          [entry && entry.heading]
            .concat((entry && entry.lines) || [])
            .concat((entry && entry.bullets) || [])
        );
        if (direct && safeIsRealCvRoleTitle(direct.role || "")) {
          resolved = direct;
          return true;
        }
        return false;
      });

      if (resolved) {
        return resolved;
      }

      (sections || []).some(function (section) {
        var key = String((section && section.key) || "").toLowerCase();
        if (key !== "experience" && key !== "experience_previous") {
          return false;
        }
        sectionItems = (section.items || [])
          .map(cleanMessageText)
          .filter(Boolean);
        return sectionItems.length > 0;
      });

      resolved = buildContextFromLines(sectionItems);
      return resolved || { role: "", company: "", label: "" };
    }

    function buildReviewHintAction(comment) {
      var clean = cleanMessageText(comment);
      var lower = clean.toLowerCase();

      if (!clean) {
        return "";
      }
      if (/include city|include location|target location/.test(lower)) {
        return "Add the location directly to this role line.";
      }
      if (/include months|insert dates here|include dates|date/i.test(lower)) {
        return "Make the date range explicit and consistent on this role.";
      }
      if (
        /include more achievements|outcomes|quantifiable|statistics|measurable output|identified xxx|resulting in xxx/i.test(
          lower
        )
      ) {
        return "Add a clearer outcome or quantified result to this experience.";
      }
      if (/use past tense/i.test(lower)) {
        return "Keep the wording consistently in past tense.";
      }
      if (/be more specific|provide detail|specify/i.test(lower)) {
        return "Replace generic wording with a more specific action or result.";
      }
      if (/fix formatting|formatting|new line|reduce gap/i.test(lower)) {
        return "Tidy the layout so the role block reads cleanly.";
      }
      if (/avoid repetition|repetition/i.test(lower)) {
        return "Remove repeated wording across adjacent bullets.";
      }
      if (
        /technical skills|technical software|modules\/courses|courses\/modules/i.test(
          lower
        )
      ) {
        return "";
      }
      if (/build a stock pitch|financial model to attach/i.test(lower)) {
        return "Consider adding supporting deal or market work alongside the CV.";
      }
      if (/great example|very good|good summary|good cv layout/i.test(lower)) {
        return "";
      }
      if (
        /stock pitch|case study|selected trade simulation|transaction experience/i.test(
          lower
        )
      ) {
        return "Bring the most relevant transaction or market example through more clearly.";
      }

      return takeLeadingWords(clean, 12) + ".";
    }

    function extractEntryReviewHints(text, entry) {
      var lines = String(text || "")
        .split(/\r?\n/)
        .map(normalizeCvLine)
        .filter(Boolean);
      var entryMeta = buildExperienceEntryMeta(entry);
      var anchorPhrases = dedupeList(
        [entryMeta.heading]
          .concat(((entry && entry.lines) || []).slice(0, 3))
          .concat(((entry && entry.bullets) || []).slice(0, 2))
          .map(function (line) {
            return takeLeadingWords(line, 8).toLowerCase();
          })
          .filter(Boolean)
      );
      var hints = [];

      lines.forEach(function (line, index) {
        var action;
        var windowLines;
        var context;

        if (!isCvReviewCommentLine(line)) {
          return;
        }

        action = buildReviewHintAction(line);
        if (!action) {
          return;
        }

        windowLines = [
          lines[index - 2] || "",
          lines[index - 1] || "",
          lines[index + 1] || "",
          lines[index + 2] || "",
        ].filter(function (item) {
          return item && !isCvReviewCommentLine(item);
        });
        context = windowLines.join(" ").toLowerCase();

        if (
          anchorPhrases.some(function (phrase) {
            return (
              phrase &&
              (context.indexOf(phrase) !== -1 ||
                phrase.indexOf(takeLeadingWords(context, 8)) !== -1)
            );
          })
        ) {
          hints.push(action);
        }
      });

      return dedupeList(hints).slice(0, 3);
    }

    function scoreExperienceEntry(entry, analysis, titleHint, signalTerms) {
      var score = 0;
      var heading = cleanMessageText(entry && entry.heading).toLowerCase();
      var haystack = cleanMessageText(
        []
          .concat((entry && entry.lines) || [])
          .concat((entry && entry.bullets) || [])
          .join(" ")
      ).toLowerCase();
      var beforeHint = cleanMessageText(
        analysis && analysis.before
      ).toLowerCase();

      if (
        titleHint &&
        (heading.indexOf(titleHint) !== -1 ||
          haystack.indexOf(titleHint) !== -1)
      ) {
        score += 8;
      }
      if (beforeHint) {
        beforeHint
          .split(/\s+/)
          .filter(function (word) {
            return word.length > 4;
          })
          .forEach(function (word) {
            if (haystack.indexOf(word) !== -1) {
              score += 1;
            }
          });
      }
      (signalTerms || []).forEach(function (term) {
        var normalized = cleanMessageText(term).toLowerCase();
        if (!normalized) {
          return;
        }
        if (heading.indexOf(normalized) !== -1) {
          score += 3;
        } else if (haystack.indexOf(normalized) !== -1) {
          score += 2;
        }
      });
      score += Math.min(3, entry && entry.bullets ? entry.bullets.length : 0);

      return score;
    }

    function pickRelevantExperienceEntry(analysis, sections) {
      var entries = getExperienceEntries(sections);
      var titleHint = cleanMessageText(
        (analysis && analysis.experience_title) || cvFacts.experienceTitle
      ).toLowerCase();
      var signalTerms = dedupeList(
        getApplyPrioritySkills(analysis).concat(
          getStatementSafeConfirmedSignals(analysis).map(getSignalLabel)
        )
      ).slice(0, 6);
      var ranked;

      if (!entries.length) {
        return null;
      }

      ranked = entries
        .map(function (entry) {
          return {
            entry: entry,
            score: scoreExperienceEntry(
              entry,
              analysis,
              titleHint,
              signalTerms
            ),
          };
        })
        .sort(function (a, b) {
          return b.score - a.score;
        });

      return ranked[0] ? ranked[0].entry : entries[0];
    }

    function getRankedExperienceEntries(analysis, sections) {
      var entries = getExperienceEntries(sections);
      var titleHint = cleanMessageText(
        (analysis && analysis.experience_title) || cvFacts.experienceTitle
      ).toLowerCase();
      var signalTerms = dedupeList(
        getApplyPrioritySkills(analysis).concat(
          getStatementSafeConfirmedSignals(analysis).map(getSignalLabel)
        )
      ).slice(0, 6);

      return entries
        .map(function (entry) {
          return {
            entry: entry,
            score: scoreExperienceEntry(
              entry,
              analysis,
              titleHint,
              signalTerms
            ),
          };
        })
        .sort(function (a, b) {
          return b.score - a.score;
        })
        .map(function (item) {
          return item.entry;
        });
    }

    function pickRelevantExperienceEntries(analysis, sections, limit) {
      return getRankedExperienceEntries(analysis, sections).slice(
        0,
        Math.max(1, limit || 2)
      );
    }

    function getAllRelevantExperienceEntries(analysis, sections) {
      return getRankedExperienceEntries(analysis, sections);
    }

    function isTailoredCvSalvageEvidenceLine(line) {
      var clean = stripCvBulletPrefix(cleanMessageText(line || ""));
      var words = clean.split(/\s+/).filter(Boolean);
      if (
        !clean ||
        (words.length < 7 &&
          !(words.length >= 4 && hasCvProfessionalActionSignal(clean))) ||
        clean.length > 420 ||
        /^(?:available|availability|course|courses|certificate|certification|education|training|project|location|address)\b/i.test(
          clean
        ) ||
        /^\[?\s*(?:(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\s+)?(?:19|20)\d{2}\s*(?:[-–—]|to|–)\s*(?:present|current|(?:19|20)\d{2})?\s*\]?$/i.test(
          clean
        ) ||
        /\b(?:date of birth|date of issue|date of expiry|place of issue|gender|marital status|nationality|passport|visa status|languages known)\b/i.test(
          clean
        ) ||
        isCvContactLine(clean) ||
        isCvTailoringNarrativeProfileLine(clean) ||
        hasBrokenTailoredCvBulletSyntax(clean) ||
        looksLikeCvTailoringEducationLine(clean) ||
        looksLikeCvPureDateRangeLine(clean) ||
        looksLikeCvRoleTitleLine(clean, "") ||
        looksLikeDetectedCompanyName(clean) ||
        isCvTailoringKeywordSoup(clean) ||
        getCvSectionMetaFromLine(clean)
      ) {
        return false;
      }
      if (isCvEvidenceLine(clean)) {
        return true;
      }
      return (
        /\b(?:transaction|valuation|model|modelling|modeling|financial|investment|portfolio|credit|risk|analysis|analysed|analyzed|reporting|kpi|performance|forecast|budget|market research|due diligence|client|stakeholder|pipeline|business development|operations|process|strategy|revenue|cost|growth|compliance|audit|data|excel|python|sql|tableau|power bi|bloomberg|capital iq)\b/i.test(
          clean
        ) &&
        /\b(?:support|supported|prepare|prepared|build|built|develop|developed|manage|managed|lead|led|execute|executed|analyse|analyze|analysed|analyzed|evaluate|evaluated|conduct|conducted|coordinate|coordinated|deliver|delivered|create|created|monitor|monitored|track|tracked|report|reported|identify|identified|improve|improved|assist|assisted|work|worked|participate|participated|collaborate|collaborated|responsible)\b/i.test(
          clean
        )
      );
    }

    function splitTailoredCvEvidenceLine(line) {
      var clean = stripCvBulletPrefix(cleanMessageText(line || ""));
      var parts;
      var collisionParts;
      if (!clean) {
        return [];
      }
      collisionParts = splitCvFlattenedEntryCollisionLine(clean);
      if (collisionParts.length > 1) {
        return collisionParts.reduce(function (list, part) {
          if (part === clean) {
            return list.concat(part);
          }
          return list.concat(splitTailoredCvEvidenceLine(part));
        }, []);
      }
      if (clean.length > 240) {
        parts = clean
          .split(
            /\s+(?=(?:conduct(?:ed|ing)?|management|identification|development|analysis|acquiring|grant|implemented|developed|prepared|managed|executed|supported|coordinated|generated|maintained|oversaw|contributed|worked|created|built|performed|monthly|quarterly|annual)\b)/i
          )
          .map(cleanMessageText)
          .filter(Boolean);
        if (parts.length > 1) {
          return parts.filter(function (part) {
            return (
              part.split(/\s+/).filter(Boolean).length >=
                (hasCvProfessionalActionSignal(part) ? 3 : 5) &&
              part.length <= 380
            );
          });
        }
      }
      parts = clean
        .split(
          /\s+-\s+(?=(?:led|owned|oversaw|directed|managed|executed|developed|coordinated|streamlined|sourced|qualified|delivered|implemented|reviewed|analy[sz]ed|prepared|built|created|conducted|evaluated|researched|modelled|modeled|validated|processed|reconciled|monitored|applied|improved|generated|compiled|identified|designed|maintained|advised|negotiated|liaised|collaborated|ensured|performed|provided|collected|assessed|tracked|reported|presented|calculated|supported|contributed|responsible)\b)/i
        )
        .map(cleanMessageText)
        .filter(Boolean);
      if (parts.length <= 1) {
        return [clean];
      }
      return parts.filter(function (part) {
        return part.split(/\s+/).filter(Boolean).length >= 5;
      });
    }

    function buildTailoredCvFallbackExperienceEntries(
      sections,
      analysis,
      config,
      rawText
    ) {
      var rawLines = rawText
        ? repairMergedCvSectionHeadingLines(
            mergeCvWrappedLines(
              expandFlattenedCvTextForParsing(rawText)
                .split(/\r?\n/)
                .reduce(function (list, line) {
                  return list.concat(splitCvCompositeLine(line));
                }, [])
                .filter(Boolean)
            )
          )
        : [];
      var rawColumnSegments = rawText
        ? String(rawText)
            .split(/\r?\n/)
            .reduce(function (list, line) {
              return list.concat(String(line || "").split(/\s{2,}/));
            }, [])
            .map(normalizeCvLine)
            .filter(Boolean)
        : [];
      var sourceLines = getCvTailoringCleanLineList(
        (sections || [])
          .reduce(function (list, section) {
            return list.concat((section && section.items) || []);
          }, [])
          .concat(rawLines)
          .concat(rawColumnSegments),
        config && config.full ? 120 : 48
      )
        .filter(function (line) {
          return isTailoredCvSalvageEvidenceLine(line);
        })
        .reduce(function (list, line) {
          return list.concat(splitTailoredCvEvidenceLine(line));
        }, [])
        .filter(isTailoredCvSalvageEvidenceLine);
      sourceLines = dedupeList(sourceLines).slice(
        0,
        config && config.full ? 10 : 5
      );
      if (!sourceLines.length) {
        return [];
      }
      return [
        {
          heading: cleanMessageText(
            (analysis && analysis.experience_title) ||
              cvFacts.experienceTitle ||
              roleTitle ||
              "Relevant Experience"
          ),
          lines: sourceLines,
          bullets: sourceLines,
          isFallback: true,
        },
      ];
    }

    var PASSIVE_CV_PATTERNS = [
      {
        pattern: /\bresponsible for\b/i,
        label: "Responsible for",
        replacement: "Led / Delivered / Managed",
      },
      {
        pattern: /\bin charge of\b/i,
        label: "In charge of",
        replacement: "Led / Directed / Oversaw",
      },
      {
        pattern: /\bduties included\b/i,
        label: "Duties included",
        replacement: "Delivered / Executed / Managed",
      },
      {
        pattern: /\bworked on\b/i,
        label: "Worked on",
        replacement: "Delivered / Built / Drove",
      },
      {
        pattern: /\binvolved in\b/i,
        label: "Involved in",
        replacement: "Led / Executed / Shaped",
      },
      {
        pattern: /\bhelped with\b/i,
        label: "Helped with",
        replacement: "Delivered / Supported with result",
      },
      {
        pattern: /\bassisted with\b/i,
        label: "Assisted with",
        replacement: "Supported / Coordinated / Delivered",
      },
      {
        pattern: /\bparticipated in\b/i,
        label: "Participated in",
        replacement: "Contributed to / Delivered",
      },
      {
        pattern: /\bhandled\b/i,
        label: "Handled",
        replacement: "Managed / Resolved / Executed",
      },
      {
        pattern: /\bdealt with\b/i,
        label: "Dealt with",
        replacement: "Resolved / Managed / Negotiated",
      },
      {
        pattern: /\bvarious\b/i,
        label: "Various",
        replacement: "Specific named work",
      },
      {
        pattern: /\bthings\b/i,
        label: "Things",
        replacement: "Specific deliverables",
      },
      {
        pattern: /\bstuff\b/i,
        label: "Stuff",
        replacement: "Specific deliverables",
      },
      {
        pattern: /\bsome\b/i,
        label: "Some",
        replacement: "Exact scope / quantity",
      },
      {
        pattern: /\ba lot of\b/i,
        label: "A lot of",
        replacement: "Quantify scale",
      },
      {
        pattern: /\bbasically\b/i,
        label: "Basically",
        replacement: "Direct statement",
      },
      {
        pattern: /\bkind of\b|\bsort of\b/i,
        label: "Kind of / sort of",
        replacement: "Direct statement",
      },
      {
        pattern: /\btried to\b/i,
        label: "Tried to",
        replacement: "Delivered / Improved / Achieved",
      },
      {
        pattern: /\bworked hard\b/i,
        label: "Worked hard",
        replacement: "Show result or output",
      },
      {
        pattern: /\bteam player\b/i,
        label: "Team player",
        replacement: "Show collaboration with outcome",
      },
      {
        pattern: /\bdynamic\b/i,
        label: "Dynamic",
        replacement: "Show what changed",
      },
      {
        pattern: /\bsynergy\b/i,
        label: "Synergy",
        replacement: "Specific collaboration outcome",
      },
      {
        pattern: /\bhardworking\b/i,
        label: "Hardworking",
        replacement: "Show output / result",
      },
      {
        pattern: /\bdetail-oriented\b/i,
        label: "Detail-oriented",
        replacement: "Show precision in outcome",
      },
      {
        pattern: /\bgo-getter\b/i,
        label: "Go-getter",
        replacement: "Show initiative through action",
      },
      {
        pattern: /\bpassionate about\b/i,
        label: "Passionate about",
        replacement: "Show sustained work",
      },
      {
        pattern: /\bresults-driven\b/i,
        label: "Results-driven",
        replacement: "Show actual result",
      },
      {
        pattern: /\bexcellent communication skills\b/i,
        label: "Excellent communication skills",
        replacement: "Show stakeholder outcome",
      },
      {
        pattern: /\bself-starter\b/i,
        label: "Self-starter",
        replacement: "Show ownership / initiative",
      },
      {
        pattern: /\bproactive\b/i,
        label: "Proactive",
        replacement: "Show initiative with result",
      },
      {
        pattern: /\bdid\b/i,
        label: "Did",
        replacement: "Led / Built / Delivered",
      },
      {
        pattern: /\bmade\b/i,
        label: "Made",
        replacement: "Built / Created / Produced",
      },
      {
        pattern: /\bgot\b/i,
        label: "Got",
        replacement: "Secured / Achieved / Won",
      },
      {
        pattern: /\bused\b/i,
        label: "Used",
        replacement: "Applied / Built with / Leveraged",
      },
      {
        pattern: /\bworked\b/i,
        label: "Worked",
        replacement: "Led / Delivered / Executed",
      },
      {
        pattern: /\bwas part of\b/i,
        label: "Was part of",
        replacement: "Contributed to / Delivered",
      },
      {
        pattern: /\bsupported\b/i,
        label: "Supported",
        replacement: "Supported with quantified outcome",
      },
    ];

    function detectPassiveCvPhrases(items) {
      var findings = [];

      (items || []).forEach(function (item) {
        var text = cleanMessageText(item);
        if (!text) {
          return;
        }

        PASSIVE_CV_PATTERNS.forEach(function (entry) {
          var match = text.match(entry.pattern);
          if (match) {
            findings.push({
              phrase: match[0],
              label: entry.label,
              pattern: entry.pattern,
              replacement: entry.replacement,
              source: text,
            });
          }
        });
      });

      return findings.filter(function (item, index, list) {
        return (
          list.findIndex(function (candidate) {
            return (
              candidate.label === item.label && candidate.source === item.source
            );
          }) === index
        );
      });
    }

    function buildPassiveLanguageNotes(findings, maxItems) {
      return (findings || [])
        .slice(0, Math.max(1, maxItems || 3))
        .map(function (finding) {
          return (
            'Replace "' +
            finding.label +
            '" with a stronger action verb and outcome.'
          );
        });
    }

    function getPassiveReplacementTerms(findings) {
      return dedupeList(
        (findings || [])
          .map(function (finding) {
            return finding.phrase || finding.label;
          })
          .filter(Boolean)
      );
    }

    function getFinanceActionContext(text) {
      var clean = cleanMessageText(text).toLowerCase();

      if (
        /due diligence|transaction analysis|deal analysis|deal screening|investment memo|financial model|valuation|lbo|dcf|comps|portfolio analysis/i.test(
          clean
        )
      ) {
        return {
          verb: "Executed",
          outcome: "with clearer deal-specific outcome and scope",
          example:
            "Executed due diligence workstreams and produced analysis that informed transaction decisions.",
        };
      }
      if (
        /capital call|distribution|nav|fund accounting|reconciliation|month end|year end|close process|audit support|financial statements/i.test(
          clean
        )
      ) {
        return {
          verb: "Delivered",
          outcome: "with clearer process ownership and reporting impact",
          example:
            "Delivered fund accounting and close activities with accurate reporting and tighter process control.",
        };
      }
      if (
        /investor relations|lp|fundraising|roadshow|stakeholder|client|relationship management|coverage/i.test(
          clean
        )
      ) {
        return {
          verb: "Drove",
          outcome: "with clearer commercial or stakeholder impact",
          example:
            "Drove investor communications and stakeholder coverage that strengthened fundraising and relationship outcomes.",
        };
      }
      if (
        /reporting|kpi|dashboard|power bi|excel|board pack|management information|forecast|budget/i.test(
          clean
        )
      ) {
        return {
          verb: "Produced",
          outcome: "with clearer reporting value and decision support",
          example:
            "Produced reporting and KPI analysis that improved visibility for senior decision-making.",
        };
      }
      if (
        /treasury|liquidity|cash management|working capital|fx|hedg|bank relationship/i.test(
          clean
        )
      ) {
        return {
          verb: "Managed",
          outcome: "with clearer balance-sheet or liquidity impact",
          example:
            "Managed treasury activity with clearer liquidity, cash-flow, and control outcomes.",
        };
      }
      if (
        /credit|underwriting|covenant|risk|aml|kyc|compliance|controls/i.test(
          clean
        )
      ) {
        return {
          verb: "Led",
          outcome: "with clearer control, risk, or underwriting outcome",
          example:
            "Led risk and control work with clearer compliance and decision-quality outcomes.",
        };
      }

      return {
        verb: "Delivered",
        outcome: "with a clearer action and measurable outcome",
        example:
          "Delivered work with clearer ownership, scope, and measurable outcome.",
      };
    }

    function buildPassiveReplacementNote(finding) {
      var context = getFinanceActionContext(finding && finding.source);
      if (hasStrongOutcomeLanguage(finding && finding.source)) {
        return (
          'Replace "' +
          finding.label +
          '" with a stronger action verb such as "' +
          context.verb +
          '". The result is already there, so this is mainly a wording upgrade.'
        );
      }
      return (
        'Replace "' +
        finding.label +
        '" with a stronger action verb such as "' +
        context.verb +
        '" and make the outcome explicit.'
      );
    }

    function hashCommentarySeed(text) {
      var clean = cleanMessageText(text || "");
      var hash = 0;
      for (var i = 0; i < clean.length; i += 1) {
        hash = ((hash << 5) - hash + clean.charCodeAt(i)) | 0;
      }
      return Math.abs(hash);
    }

    function chooseVariant(list, seedText) {
      var bucket = (list || []).filter(Boolean);
      if (!bucket.length) {
        return "";
      }
      return bucket[hashCommentarySeed(seedText || "") % bucket.length];
    }

    function detectCommentaryLineKind(text, section) {
      var clean = cleanMessageText(text);
      var lower = clean.toLowerCase();
      if (!clean) return "empty";
      if (/\b(date period|location|linkedin\/portfolio|\[.*?\])\b/i.test(clean))
        return "placeholder";
      if (isCvContactLine(clean)) return "contact";
      if (/^(skills|competencies|core competencies)$/i.test(clean))
        return "heading";
      if (
        /^(?:[A-Z][A-Za-z&/.,'’ -]+)$/.test(clean) &&
        clean.split(/\s+/).length <= 6 &&
        /\b(analyst|director|manager|partner|officer|banker|intern|advisor|president|lead)\b/i.test(
          clean
        )
      ) {
        return "role_title";
      }
      if (String(section || "").toLowerCase() === "skills") return "skill_item";
      if (looksLikeCvRoleMetaLine(clean) || looksLikeCvPureDateRangeLine(clean))
        return "meta";
      if (extractQuantSignals(clean).length && hasStrongOutcomeLanguage(clean))
        return "metric_achievement";
      if (hasStrongOutcomeLanguage(clean)) return "achievement";
      if (detectPassiveCvPhrases([clean]).length) return "passive";
      if (lower.indexOf("responsible for") !== -1) return "responsibility";
      if (clean.split(/\s+/).length >= 18) return "descriptor";
      return "statement";
    }

    function analyzeCommentaryContext(text, options) {
      var clean = cleanMessageText(text);
      var context = options || {};
      var roleSignals = (context.roleSignals || [])
        .map(cleanMessageText)
        .filter(Boolean);
      var lower = clean.toLowerCase();
      var passiveFindings = detectPassiveCvPhrases([clean]);
      var quantSignals = extractQuantSignals(clean);
      var matchedSignals = roleSignals.filter(function (signal) {
        return lower.indexOf(signal.toLowerCase()) !== -1;
      });
      var missingSignals = roleSignals.filter(function (signal) {
        return lower.indexOf(signal.toLowerCase()) === -1;
      });

      return {
        text: clean,
        section:
          cleanMessageText(context.section || "").toLowerCase() || "default",
        isPrimary: !!context.isPrimary,
        lineKind: detectCommentaryLineKind(clean, context.section),
        passiveFindings: passiveFindings,
        quantSignals: quantSignals,
        hasOutcome: hasStrongOutcomeLanguage(clean),
        matchedSignals: matchedSignals,
        missingSignals: missingSignals,
        financeContext: getFinanceActionContext(clean),
      };
    }

    function buildAdvancedCommentaryNotes(text, options) {
      var state = analyzeCommentaryContext(text, options);
      var notes = [];
      var finding = state.passiveFindings[0];
      var signalText = formatNaturalList(state.missingSignals.slice(0, 2));

      if (!state.text) {
        return [];
      }

      if (state.lineKind === "placeholder") {
        notes.push(
          chooseVariant(
            [
              "Replace the placeholder wording here with the actual detail before applying.",
              "This line is still carrying draft placeholder text and needs the real value.",
            ],
            state.text
          )
        );
      }

      if (finding) {
        if (state.hasOutcome) {
          notes.push(
            chooseVariant(
              [
                'Keep the result, but replace "' +
                  finding.label +
                  '" with a stronger opening verb such as "' +
                  state.financeContext.verb +
                  '".',
                'The evidence is already here. Tighten the opener by swapping "' +
                  finding.label +
                  '" for a more decisive verb such as "' +
                  state.financeContext.verb +
                  '".',
              ],
              state.text
            )
          );
        } else {
          notes.push(
            chooseVariant(
              [
                'This line still reads as responsibility rather than impact. Start it with a stronger verb such as "' +
                  state.financeContext.verb +
                  '" and add the result if evidenced.',
                'Swap "' +
                  finding.label +
                  '" for a sharper action verb such as "' +
                  state.financeContext.verb +
                  '" and make the outcome more explicit.',
              ],
              state.text
            )
          );
        }
      }

      if (
        state.isPrimary &&
        state.missingSignals.length &&
        state.lineKind !== "skill_item" &&
        state.lineKind !== "meta"
      ) {
        notes.push(
          chooseVariant(
            [
              "If the CV already evidences " +
                signalText +
                ", bring it forward more explicitly here.",
              "Where the proof is real, name " +
                signalText +
                " directly instead of leaving it implied.",
            ],
            state.text + "|signals"
          )
        );
      }

      if (
        !state.quantSignals.length &&
        lineHasMissingQuantOpportunity(state.text) &&
        state.lineKind !== "meta" &&
        state.text.length <= 220
      ) {
        notes.push(
          chooseVariant(
            [
              "Add scale here if it is supported: value, AUM, client count, team size, or % impact.",
              "This point would land harder with a number behind it if the CV supports one.",
            ],
            state.text + "|quant"
          )
        );
      }

      if (state.lineKind === "skill_item" && state.missingSignals.length) {
        notes.push(
          chooseVariant(
            [
              "Keep the strongest target-role terms higher in the skills list so they are easier to scan.",
              "Reorder this skills block so the most relevant role signals appear earlier.",
            ],
            state.text + "|skill"
          )
        );
      }

      return dedupeList(notes).slice(0, 2);
    }

    function stripTrailingPunctuation(text) {
      return cleanMessageText(text || "")
        .replace(/[.,;:!?]+$/g, "")
        .trim();
    }

    function extractQuantSignals(text) {
      var source = cleanMessageText(text || "");
      var findings = [];
      var patterns = [
        /(?:\$|£|€|AED|USD|GBP|EUR)\s?\d[\d,.]*(?:\s?(?:k|K|m|M|mn|MN|mln|MLN|mm|MM|bn|BN|bn\+|BN\+|m\+|M\+|billion|million|thousand|thousands|000'?s))?\+?/gi,
        /\b\d[\d,.]*\s?%/gi,
        /\b\d[\d,.]*\+?\s?(?:people|team members|analysts|associates|stakeholders|clients|funds|transactions|deals|entities|countries|markets|workstreams|reports|campaigns|companies|portfolios|borrowers|mandates|positions|investments|rounds)\b/gi,
        /\b\d+\s?(?:day|days|week|weeks|month|months|year|years)\b/gi,
        /\btop\s?\d+%/gi,
        /\b\d[\d,.]*\+?\s?(?:AUM|aum)\b/gi,
        /\b\d[\d,.]*\+?\s?(?:k|K|m|M|mn|MN|mln|MLN|mm|MM|bn|BN|billion|million|thousand|thousands|000'?s)\b/gi,
      ];

      patterns.forEach(function (pattern) {
        var matches = source.match(pattern) || [];
        matches.forEach(function (match) {
          findings.push(stripTrailingPunctuation(match));
        });
      });

      return dedupeList(findings).slice(0, 3);
    }

    function buildQuantOutcomeTail(source) {
      var quantities = extractQuantSignals(source);
      if (!quantities.length) {
        return "";
      }
      if (quantities.length === 1) {
        return "highlighting impact around " + quantities[0];
      }
      return "highlighting impact around " + formatNaturalList(quantities);
    }

    function hasStrongOutcomeLanguage(text) {
      return /\b(increased|reduced|cut|saved|generated|secured|achieved|won|delivered|launched|built|grew|improved|accelerated|raised|closed|completed|implemented|streamlined|automated|optimized|optimised)\b/i.test(
        cleanMessageText(text)
      );
    }

    function buildPassiveRewriteFromSource(finding) {
      var source = cleanMessageText(finding && finding.source);
      var context = getFinanceActionContext(source);
      var pattern = finding && finding.pattern ? finding.pattern : null;
      var rewritten;
      var tail;
      var quantTail;

      if (!source) {
        return context.example;
      }

      if (pattern) {
        rewritten = source.replace(pattern, context.verb);
      } else if (finding && finding.phrase) {
        rewritten = source.replace(
          new RegExp(
            finding.phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
            "i"
          ),
          context.verb
        );
      } else {
        rewritten = source;
      }

      rewritten = rewritten
        .replace(/\bwith with\b/gi, "with")
        .replace(/\bto to\b/gi, "to")
        .replace(/\s+/g, " ")
        .trim();

      if (
        /^(Responsible for|In charge of|Duties included|Worked on|Involved in|Helped with|Assisted with|Participated in|Handled|Dealt with|Did|Made|Got|Used|Worked|Was part of|Supported)\b/i.test(
          rewritten
        )
      ) {
        rewritten = source;
      }

      if (!/[.?!]$/.test(rewritten)) {
        rewritten += ".";
      }

      quantTail = buildQuantOutcomeTail(source);

      if (
        !hasStrongOutcomeLanguage(source) &&
        !/\b(increased|reduced|delivered|generated|improved|secured|achieved|built|executed|managed|led|drove|produced|implemented|streamlined|automated)\b/i.test(
          rewritten
        )
      ) {
        tail = quantTail || stripTrailingPunctuation(context.outcome);
        rewritten = stripTrailingPunctuation(rewritten) + " " + tail + ".";
      } else if (
        !hasStrongOutcomeLanguage(source) &&
        quantTail &&
        !new RegExp(quantTail.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i").test(
          rewritten
        )
      ) {
        rewritten =
          stripTrailingPunctuation(rewritten) + ", " + quantTail + ".";
      }

      return rewritten;
    }

    function buildPassiveRewriteExample(finding) {
      return buildPassiveRewriteFromSource(finding);
    }

    function buildProfileRevisionTyping(sections, analysis, finalItems) {
      var sourceItems = getProfileSourceItems(sections);
      var passiveFindings = detectPassiveCvPhrases(sourceItems);
      var beforeText = passiveFindings.length
        ? takeRevisionPhrase(passiveFindings[0].source, 5)
        : takeRevisionPhrase(
            sourceItems[0] ||
              "Experienced finance candidate with background across multiple areas.",
            4
          );
      var roleSignals = getApplyPrioritySkills(analysis).slice(0, 2);
      var signalText = roleSignals.length ? formatNaturalList(roleSignals) : "";
      var afterText = passiveFindings.length
        ? takeRevisionPhrase(buildPassiveRewriteExample(passiveFindings[0]), 5)
        : takeRevisionPhrase((finalItems || []).filter(Boolean)[0] || "", 4);
      if (!afterText) {
        afterText = takeRevisionPhrase(roleTitle + " " + signalText + ".", 4);
      }
      return buildRevisionTyping(beforeText, afterText || beforeText);
    }

    function buildExperienceRevisionTyping(analysis, sections, finalItems) {
      var focusedEntry = pickRelevantExperienceEntry(analysis, sections);
      var sourceItems = getExperienceSourceItems(analysis, sections);
      var passiveFindings = detectPassiveCvPhrases(
        (focusedEntry && focusedEntry.bullets && focusedEntry.bullets.length
          ? focusedEntry.bullets
          : []
        ).concat(sourceItems)
      );
      var beforeText = takeRevisionPhrase(
        cleanMessageText(
          (passiveFindings[0] && passiveFindings[0].source) ||
            (analysis && analysis.before) ||
            (focusedEntry && (focusedEntry.bullets || [])[0]) ||
            sourceItems[0] ||
            "Supported analysis and prepared materials for transactions."
        ),
        5
      );
      var afterText = passiveFindings.length
        ? takeRevisionPhrase(buildPassiveRewriteExample(passiveFindings[0]), 6)
        : takeRevisionPhrase(
            cleanMessageText(
              (analysis && analysis.after) ||
                (finalItems || []).filter(Boolean)[0] ||
                beforeText
            ),
            5
          );
      return buildRevisionTyping(beforeText, afterText);
    }

    function getWordCount(text) {
      var clean = cleanMessageText(text || "");
      return clean ? clean.split(/\s+/).length : 0;
    }

    function takeRevisionPhrase(text, maxWords) {
      var clean = cleanMessageText(text || "")
        .replace(/^[\-\u2022\s]+/, "")
        .replace(/\s+/g, " ")
        .trim();
      var phrase = clean
        .split(/[.;:!?]/)[0]
        .replace(
          /^(led|managed|supported|responsible for|worked on|focused on|assisted with|helped with|involved in|participated in|was part of|handled|dealt with|did|made|got|used|worked)\s+/i,
          ""
        )
        .trim();

      return takeLeadingWords(phrase || clean, Math.max(2, maxWords || 4));
    }

    function takeLeadingWords(text, maxWords) {
      var clean = cleanMessageText(text || "");
      var list = clean ? clean.split(/\s+/) : [];
      return list.slice(0, Math.max(1, maxWords || 1)).join(" ");
    }

    function highlightDraftText(text, terms) {
      var html = escapeHtml(text || "");
      var uniqueTerms = dedupeList(
        (terms || [])
          .map(function (term) {
            return cleanMessageText(term);
          })
          .filter(function (term) {
            return term && term.length > 2;
          })
      ).sort(function (a, b) {
        return b.length - a.length;
      });

      uniqueTerms.forEach(function (term, index) {
        var escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        var modifier =
          index % 4 === 0
            ? " sffc-crm-apply-chat__draft-highlight--yellow"
            : index % 4 === 1
            ? " sffc-crm-apply-chat__draft-highlight--navy"
            : index % 4 === 2
            ? " sffc-crm-apply-chat__draft-highlight--green"
            : " sffc-crm-apply-chat__draft-highlight--red";
        html = html.replace(
          new RegExp("\\b(" + escaped + ")\\b", "gi"),
          '<mark class="sffc-crm-apply-chat__draft-highlight' +
            modifier +
            '">$1</mark>'
        );
      });

      return html;
    }

    function buildDocumentPage(
      pageNumber,
      heading,
      intro,
      bodyHtml,
      noteHtml,
      modifier,
      isEditing
    ) {
      return (
        '<section class="sffc-crm-apply-chat__draft-page-sheet' +
        (modifier ? " is-" + modifier : "") +
        (isEditing ? " is-editing" : "") +
        '">' +
        '<div class="sffc-crm-apply-chat__draft-page-header">' +
        '<span class="sffc-crm-apply-chat__draft-page-number">Page ' +
        pageNumber +
        "</span>" +
        '<span class="sffc-crm-apply-chat__draft-page-editing"><i aria-hidden="true"></i>Emily editing</span>' +
        "</div>" +
        '<div class="sffc-crm-apply-chat__draft-page-heading">' +
        escapeHtml(heading) +
        "</div>" +
        (intro
          ? '<div class="sffc-crm-apply-chat__draft-page-intro">' +
            escapeHtml(intro) +
            "</div>"
          : "") +
        (noteHtml
          ? '<div class="sffc-crm-apply-chat__draft-editor-note">' +
            noteHtml +
            "</div>"
          : "") +
        '<div class="sffc-crm-apply-chat__draft-page-body" contenteditable="true" spellcheck="true">' +
        bodyHtml +
        "</div>" +
        "</section>"
      );
    }

    function hasVisiblePersonalStatement(sections) {
      return (sections || []).some(function (section) {
        var title = cleanMessageText(section && section.title).toLowerCase();
        var key = cleanMessageText(section && section.key).toLowerCase();
        return (
          /^(profile|summary|personal statement|objective)$/i.test(title) ||
          /^(profile)$/i.test(key)
        );
      });
    }

    function getCvTopLines(text, maxLines) {
      return String(text || "")
        .split(/\r?\n/)
        .map(normalizeCvLine)
        .filter(function (line) {
          return line && !isCvReviewCommentLine(line) && !isCvTrackMarker(line);
        })
        .slice(0, Math.max(1, maxLines || 12));
    }

    function normalizeEmailCandidate(email) {
      var clean = String(email || "")
        .trim()
        .toLowerCase()
        .replace(/\s+(?:at|\[at\]|\(at\))\s+/gi, "@")
        .replace(/\s+(?:dot|\[dot\]|\(dot\))\s+/gi, ".")
        .replace(/\s*@\s*/g, "@")
        .replace(/\s*\.\s*/g, ".")
        .replace(/^[<({\["'`.,;:]+|[>)}\]"'`.,;:]+$/g, "");
      var parts = clean.split("@");
      var local;
      var domain;
      if (parts.length !== 2) {
        return clean;
      }
      local = parts[0];
      domain = normalizeEmailDomain(parts[1]);
      return local + "@" + domain;
    }

    function normalizeEmailDomain(domain) {
      var clean = String(domain || "")
        .trim()
        .toLowerCase()
        .replace(/^[.]+|[.]+$/g, "");
      try {
        clean = new URL("https://" + clean).hostname.toLowerCase();
      } catch (err) {}
      return clean;
    }

    function looksLikeEmail(email) {
      var clean = normalizeEmailCandidate(email);
      var parts = clean.split("@");
      var local;
      var domain;
      if (parts.length !== 2) {
        return false;
      }
      local = parts[0];
      domain = parts[1];
      if (!local || !domain || local.length > 64 || clean.length > 254) {
        return false;
      }
      if (
        /\s/.test(clean) ||
        local.charAt(0) === "." ||
        local.slice(-1) === "."
      ) {
        return false;
      }
      if (local.indexOf("..") !== -1 || domain.indexOf("..") !== -1) {
        return false;
      }
      if (
        domain.charAt(0) === "." ||
        domain.slice(-1) === "." ||
        domain.indexOf(".") === -1
      ) {
        return false;
      }
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean);
    }

    function findCvEmail(text) {
      var normalized = String(text || "")
        .replace(/\s+(?:at|\[at\]|\(at\))\s+/gi, "@")
        .replace(/\s+(?:dot|\[dot\]|\(dot\))\s+/gi, ".")
        .replace(/\s*@\s*/g, "@")
        .replace(/\s*\.\s*/g, ".");
      var matches =
        normalized.match(
          /[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,63}/gi
        ) || [];
      var best = "";
      matches.some(function (candidate) {
        var clean = normalizeEmailCandidate(candidate);
        if (looksLikeEmail(clean)) {
          best = clean;
          return true;
        }
        return false;
      });
      return best;
    }

    function getEmailProvider(email) {
      var lower = cleanMessageText(email).toLowerCase();
      if (!lower || lower.indexOf("@") === -1) {
        return "";
      }
      return lower.split("@")[1].split(".")[0];
    }

    function findCvPhone(text) {
      var normalized = String(text || "").replace(/[–—]/g, "-");
      var matches = normalized.match(/(?:\+?\d[\d\s().-]{7,}\d)/g) || [];
      var best = "";

      function isLikelyYearRange(candidate) {
        var clean = cleanMessageText(candidate);
        return /(?:19|20)\d{2}\s*[-–—]\s*(?:19|20)\d{2}/.test(clean);
      }

      matches.forEach(function (candidate) {
        var digits = candidate.replace(/\D/g, "");
        if (
          digits.length >= 9 &&
          digits.length <= 16 &&
          !isLikelyYearRange(candidate) &&
          !/^(?:19|20)\d{6,}$/.test(digits) &&
          digits.length > best.replace(/\D/g, "").length
        ) {
          best = candidate.trim();
        }
      });

      return best;
    }

    function inferPhoneRegion(phone) {
      var clean = cleanMessageText(phone).replace(/[^\d+]/g, "");
      var codeMap = [
        { code: "+44", label: "UK" },
        { code: "+20", label: "Egypt" },
        { code: "+971", label: "UAE" },
        { code: "+966", label: "Saudi Arabia" },
        { code: "+974", label: "Qatar" },
        { code: "+973", label: "Bahrain" },
        { code: "+965", label: "Kuwait" },
        { code: "+968", label: "Oman" },
        { code: "+33", label: "France" },
        { code: "+30", label: "Greece" },
        { code: "+351", label: "Portugal" },
        { code: "+212", label: "Morocco" },
        { code: "+234", label: "Nigeria" },
        { code: "+359", label: "Bulgaria" },
        { code: "+41", label: "Switzerland" },
        { code: "+31", label: "Netherlands" },
        { code: "+39", label: "Italy" },
        { code: "+49", label: "Germany" },
        { code: "+65", label: "Singapore" },
        { code: "+91", label: "India" },
        { code: "+27", label: "South Africa" },
        { code: "+1", label: "US/Canada" },
      ];
      var matched = codeMap.find(function (item) {
        return clean.indexOf(item.code) === 0;
      });

      if (matched) {
        return matched.label;
      }
      if (/^0?7\d{9,10}$/.test(clean)) {
        return "UK";
      }
      if (/^05\d{8}$/.test(clean)) {
        return "Saudi Arabia";
      }
      if (/^06\d{8,9}$/.test(clean)) {
        return "Morocco";
      }
      if (/^3\d{9}$/.test(clean)) {
        return "Italy";
      }
      return "";
    }

    function findCvLinkedIn(text) {
      var match = String(text || "").match(
        /(?:https?:\/\/)?(?:www\.)?linkedin\.com\/in\/[A-Z0-9\-_%/]+/i
      );
      return match ? match[0] : "";
    }

    function findCvHeaderLocation(text) {
      var lines = getCvTopLines(text, 14);
      var joined = lines.join(" | ");
      var locations = [
        {
          pattern: /\blondon\b.*\buk\b|\buk\b.*\blondon\b/i,
          label: "London, UK",
          region: "UK",
        },
        {
          pattern: /\bparis\b.*\bfrance\b|\bfrance\b.*\bparis\b/i,
          label: "Paris, France",
          region: "France",
        },
        {
          pattern: /\bmilan\b.*\bitaly\b|\bitaly\b.*\bmilan\b/i,
          label: "Milan, Italy",
          region: "Italy",
        },
        {
          pattern:
            /\bamsterdam\b.*\bnetherlands\b|\bnetherlands\b.*\bamsterdam\b/i,
          label: "Amsterdam, Netherlands",
          region: "Netherlands",
        },
        {
          pattern: /\bdubai\b.*\buae\b|\buae\b.*\bdubai\b/i,
          label: "Dubai, UAE",
          region: "UAE",
        },
        {
          pattern: /\bzurich\b.*\bswitzerland\b|\bswitzerland\b.*\bzurich\b/i,
          label: "Zurich, Switzerland",
          region: "Switzerland",
        },
        {
          pattern: /\blisbon\b.*\bportugal\b|\bportugal\b.*\blisbon\b/i,
          label: "Lisbon, Portugal",
          region: "Portugal",
        },
        {
          pattern: /\bmadrid\b.*\bspain\b|\bspain\b.*\bmadrid\b/i,
          label: "Madrid, Spain",
          region: "Spain",
        },
        {
          pattern: /\bberlin\b.*\bgermany\b|\bgermany\b.*\bberlin\b/i,
          label: "Berlin, Germany",
          region: "Germany",
        },
        {
          pattern: /\bcairo\b.*\begypt\b|\begypt\b.*\bcairo\b/i,
          label: "Cairo, Egypt",
          region: "Egypt",
        },
        {
          pattern: /\bgiza\b.*\begypt\b|\begypt\b.*\bgiza\b/i,
          label: "Giza, Egypt",
          region: "Egypt",
        },
        {
          pattern: /\bjaipur\b.*\bindia\b|\bindia\b.*\bjaipur\b/i,
          label: "Jaipur, India",
          region: "India",
        },
        {
          pattern: /\bathens\b.*\bgreece\b|\bgreece\b.*\bathens\b/i,
          label: "Athens, Greece",
          region: "Greece",
        },
        {
          pattern: /\bsofia\b.*\bbulgaria\b|\bbulgaria\b.*\bsofia\b/i,
          label: "Sofia, Bulgaria",
          region: "Bulgaria",
        },
        {
          pattern: /\bcasablanca\b.*\bmorocco\b|\bmorocco\b.*\bcasablanca\b/i,
          label: "Casablanca, Morocco",
          region: "Morocco",
        },
        {
          pattern: /\brabat\b.*\bmorocco\b|\bmorocco\b.*\brabat\b/i,
          label: "Rabat, Morocco",
          region: "Morocco",
        },
        {
          pattern: /\blagos\b.*\bnigeria\b|\bnigeria\b.*\blagos\b/i,
          label: "Lagos, Nigeria",
          region: "Nigeria",
        },
        {
          pattern: /\bbandirma\b.*\bturkey\b|\bturkey\b.*\bbandirma\b/i,
          label: "Bandirma, Turkey",
          region: "Turkey",
        },
        {
          pattern:
            /\b(?:6th october|sixth october)\b.*\begypt\b|\begypt\b.*\b(?:6th october|sixth october)\b/i,
          label: "6th October, Egypt",
          region: "Egypt",
        },
      ];
      var matched = locations.find(function (item) {
        return item.pattern.test(joined);
      });

      if (matched) {
        return matched;
      }

      matched = [
        { pattern: /\blondon\b/i, label: "London", region: "UK" },
        { pattern: /\bparis\b/i, label: "Paris", region: "France" },
        { pattern: /\bmilan\b/i, label: "Milan", region: "Italy" },
        {
          pattern: /\bamsterdam\b/i,
          label: "Amsterdam",
          region: "Netherlands",
        },
        { pattern: /\bdubai\b/i, label: "Dubai", region: "UAE" },
        { pattern: /\blisbon\b/i, label: "Lisbon", region: "Portugal" },
        { pattern: /\bmadrid\b/i, label: "Madrid", region: "Spain" },
        { pattern: /\bberlin\b/i, label: "Berlin", region: "Germany" },
        { pattern: /\bcairo\b/i, label: "Cairo", region: "Egypt" },
        { pattern: /\bgiza\b/i, label: "Giza", region: "Egypt" },
        { pattern: /\bjaipur\b/i, label: "Jaipur", region: "India" },
        { pattern: /\bpatna\b/i, label: "Patna", region: "India" },
        { pattern: /\branchi\b/i, label: "Ranchi", region: "India" },
        { pattern: /\bbuxar\b/i, label: "Buxar", region: "India" },
        { pattern: /\bathens\b/i, label: "Athens", region: "Greece" },
        { pattern: /\bsofia\b/i, label: "Sofia", region: "Bulgaria" },
        { pattern: /\bcasablanca\b/i, label: "Casablanca", region: "Morocco" },
        { pattern: /\brabat\b/i, label: "Rabat", region: "Morocco" },
        { pattern: /\blagos\b/i, label: "Lagos", region: "Nigeria" },
        { pattern: /\bbandirma\b/i, label: "Bandirma", region: "Turkey" },
        { pattern: /\bgreece\b/i, label: "Greece", region: "Greece" },
        { pattern: /\begypt\b/i, label: "Egypt", region: "Egypt" },
        { pattern: /\buae\b/i, label: "UAE", region: "UAE" },
        { pattern: /\buk\b|\bunited kingdom\b/i, label: "UK", region: "UK" },
        { pattern: /\bfrance\b/i, label: "France", region: "France" },
        { pattern: /\bitaly\b/i, label: "Italy", region: "Italy" },
        {
          pattern: /\bnetherlands\b/i,
          label: "Netherlands",
          region: "Netherlands",
        },
        { pattern: /\bindia\b/i, label: "India", region: "India" },
        { pattern: /\bportugal\b/i, label: "Portugal", region: "Portugal" },
        { pattern: /\bspain\b/i, label: "Spain", region: "Spain" },
        { pattern: /\bbulgaria\b/i, label: "Bulgaria", region: "Bulgaria" },
        { pattern: /\bmorocco\b/i, label: "Morocco", region: "Morocco" },
        { pattern: /\bnigeria\b/i, label: "Nigeria", region: "Nigeria" },
      ].find(function (item) {
        return item.pattern.test(joined);
      });

      if (matched) {
        return matched;
      }

      matched = lines.reduce(function (found, line) {
        var clean = cleanMessageText(line);
        var parts;
        var tail;
        if (
          found ||
          !clean ||
          !/address\b|,\s*[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]+(?:\s+[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]+){0,2}\s*,?\s*(?:Egypt|India|Greece|South Africa|UAE|Saudi Arabia|Qatar|Bahrain|Oman|Kuwait|UK|France|Italy|Netherlands)\b/i.test(
            clean
          )
        ) {
          return found;
        }
        parts = clean
          .replace(/^address\s*/i, "")
          .split(/\s*,\s*/)
          .map(cleanMessageText)
          .filter(Boolean);
        tail = parts.slice(-2).join(", ");
        if (!tail) {
          return found;
        }
        if (/egypt/i.test(tail)) {
          return { label: tail, region: "Egypt" };
        }
        if (
          /india/i.test(tail) ||
          /\b(?:jaipur|patna|ranchi|buxar)\b/i.test(tail)
        ) {
          return { label: tail, region: "India" };
        }
        if (/greece/i.test(tail)) {
          return { label: tail, region: "Greece" };
        }
        if (/portugal/i.test(tail)) {
          return { label: tail, region: "Portugal" };
        }
        if (/bulgaria/i.test(tail)) {
          return { label: tail, region: "Bulgaria" };
        }
        if (/morocco/i.test(tail)) {
          return { label: tail, region: "Morocco" };
        }
        if (/nigeria/i.test(tail)) {
          return { label: tail, region: "Nigeria" };
        }
        return found;
      }, null);

      return matched || null;
    }

    function getRoleRegionLabel() {
      var clean = cleanMessageText(roleLocation || "");
      if (!clean) {
        return "";
      }
      if (/dubai|abu dhabi|sharjah|ras al khaimah|rak|ajman|uae/i.test(clean))
        return "UAE";
      if (/riyadh|jeddah|dammam|khobar|neom|saudi|ksa/i.test(clean))
        return "Saudi Arabia";
      if (/doha|qatar/i.test(clean)) return "Qatar";
      if (/manama|bahrain/i.test(clean)) return "Bahrain";
      if (/muscat|oman/i.test(clean)) return "Oman";
      if (/kuwait city|kuwait/i.test(clean)) return "Kuwait";
      if (/london|uk/i.test(clean)) return "UK";
      return clean;
    }

    function buildCvObservationNotes(text, sections) {
      var clean = String(text || "");
      var notes = [];
      var email = findCvEmail(clean);
      var emailProvider = getEmailProvider(email);
      var phone = findCvPhone(clean);
      var phoneRegion = inferPhoneRegion(phone);
      var linkedin = findCvLinkedIn(clean);
      var location = findCvHeaderLocation(clean);
      var roleRegion = getRoleRegionLabel();

      if (email) {
        notes.push("Good professional email (" + emailProvider + ") found.");
      } else {
        notes.push("Email address is not obvious on the CV.");
      }
      if (phone) {
        notes.push(
          "Phone number found" + (phoneRegion ? " (" + phoneRegion + ")." : ".")
        );
      } else {
        notes.push("Phone number is not obvious on the CV.");
      }
      if (location && location.label) {
        if (
          roleRegion &&
          location.region &&
          roleRegion.toLowerCase() !== location.region.toLowerCase()
        ) {
          notes.push(
            "Based in " +
              location.label +
              ", but the role is in " +
              roleLocation +
              "."
          );
        } else {
          notes.push("Based in " + location.label + ".");
        }
      } else {
        notes.push("Location is not obvious near the header details.");
      }
      if (linkedin) {
        notes.push("LinkedIn profile link is visible.");
      } else {
        notes.push("LinkedIn profile is not visible.");
      }
      if (
        phone &&
        phoneRegion &&
        location &&
        location.region &&
        phoneRegion.toLowerCase() !== location.region.toLowerCase()
      ) {
        notes.push(
          "Consider using a local " +
            location.region +
            " number if possible, because the current number reads as " +
            phoneRegion +
            "."
        );
      }
      if (!hasVisiblePersonalStatement(sections)) {
        notes.push(
          "There is no clear personal statement or summary near the top."
        );
      }

      return notes;
    }

    function isLikelyNonNameHeaderWord(word) {
      return /^(?:customer|service|financial|analysis|banker|accountant|auditor|manager|analyst|director|consultant|associate|professional|graduate|portfolio|risk|controller|details|detail|qualification|qualifications|profile|summary|objective|objectives|contact|education|experience|driving|operational|excellence|finance|investment|research|business|accounting|career|personal|humanresource|banking|assistant|specialist|support|curriculum|vitae|resume|information|qualities|nationality|gender|race|surname|address|phone|email|experienced|steady|growth|reputed|organization|organisation|success|skills|formulating|managing|targeting|preferably|region)$/i.test(
        cleanMessageText(word).replace(/[|,;:()]/g, "")
      );
    }

    function isLikelyCvQualificationText(text) {
      var clean = cleanMessageText(text || "");
      if (!clean) {
        return false;
      }
      return /\b(?:acca|cfa|cpa|aca|caia|cma|mba|bachelor(?:'s|s)?|master(?:'s|s)?|degree|university|college|affiliate|charterholder|level\s*\d+|candidate)\b/i.test(
        clean
      );
    }

    function isLikelyNameWord(word) {
      var stripped = cleanMessageText(word || "").replace(/[|,;:()]/g, "");
      if (!stripped) {
        return false;
      }
      if (isLikelyNonNameHeaderWord(stripped)) {
        return false;
      }
      if (
        /^(?:with|and|for|from|into|across|leader|private|markets|senior|junior|credit|risk|analyst|manager|director|intern|consultant|finance|investment|strategy|reporting|governance|structuring)$/i.test(
          stripped
        )
      ) {
        return false;
      }
      if (
        /^(?:al|el|de|da|del|dos|van|von|bin|bint|ibn|st\.?|saint)$/i.test(
          stripped
        )
      ) {
        return true;
      }
      if (/^[A-ZÀ-Ý][a-zà-ÿ'’.-]+$/.test(stripped)) {
        return true;
      }
      if (/^[A-ZÀ-Ý]{2,}(?:-[A-ZÀ-Ý]{2,})*$/.test(stripped)) {
        return true;
      }
      if (/^[A-ZÀ-Ý]\.$/.test(stripped)) {
        return true;
      }
      if (
        /^[a-zà-ÿ][A-Za-zÀ-ÿ'’.-]+$/.test(stripped) &&
        stripped.length >= 3 &&
        !isLikelyNonNameHeaderWord(stripped)
      ) {
        return true;
      }
      return false;
    }

    function normalizeNameTokens(text) {
      return cleanMessageText(text || "")
        .split(/[\s._\-@+]+/)
        .map(function (word) {
          return word.replace(/[^A-Za-zÀ-ÿ'’.-]/g, "").toLowerCase();
        })
        .filter(function (word) {
          return word && word.length >= 2;
        });
    }

    function getEmailNameTokens(email) {
      var local = cleanMessageText(email || "").split("@")[0] || "";
      var compactLocal = local.toLowerCase().replace(/[^a-zà-ÿ]/g, "");
      var baseTokens = normalizeNameTokens(local).filter(function (word) {
        return !/^(?:mail|gmail|outlook|hotmail|live|icloud|me|mac|yahoo|ymail|protonmail|aol|gmx|info|contact)$/.test(
          word
        );
      });
      var expanded = [];
      var credentialSuffixes = [
        "acca",
        "aca",
        "cfa",
        "cpa",
        "ca",
        "caia",
        "cma",
        "mba",
        "mca",
        "bcom",
        "mcom",
        "bba",
        "mba",
        "mdca",
      ];

      function pushToken(token) {
        var clean = String(token || "")
          .toLowerCase()
          .replace(/[^a-zà-ÿ'’.-]/g, "");
        if (clean && clean.length >= 2 && expanded.indexOf(clean) === -1) {
          expanded.push(clean);
        }
      }

      baseTokens.forEach(function (token) {
        var trimmed = token;
        pushToken(token);
        credentialSuffixes.forEach(function (suffix) {
          if (
            trimmed.length > suffix.length + 2 &&
            trimmed.slice(-suffix.length) === suffix
          ) {
            pushToken(trimmed.slice(0, -suffix.length));
          }
        });
        if (trimmed.length >= 6) {
          pushToken(trimmed.slice(0, 5));
          pushToken(trimmed.slice(0, 6));
          pushToken(trimmed.slice(0, 7));
          pushToken(trimmed.slice(0, 8));
        }
      });

      if (compactLocal.length >= 5) {
        pushToken(compactLocal);
        pushToken(compactLocal.slice(0, 5));
        pushToken(compactLocal.slice(0, 6));
        pushToken(compactLocal.slice(0, 7));
        pushToken(compactLocal.slice(0, 8));
      }

      return expanded.sort(function (a, b) {
        if (a.length !== b.length) {
          return a.length - b.length;
        }
        return a.localeCompare(b);
      });
    }

    function emailLocalContainsNameWord(email, word) {
      var compactLocal = cleanMessageText(email || "")
        .split("@")[0]
        .toLowerCase()
        .replace(/[^a-zà-ÿ]/g, "");
      var compactWord = cleanMessageText(word || "")
        .toLowerCase()
        .replace(/[^a-zà-ÿ]/g, "");
      if (!compactLocal || !compactWord || compactWord.length < 4) {
        return false;
      }
      return compactLocal.indexOf(compactWord) !== -1;
    }

    function buildTopWordNameCandidate(line, maxWords) {
      var raw = cleanMessageText(line);
      var words;
      var picked;
      var candidate;
      if (
        !raw ||
        isLikelyCvHeaderSummaryLine(raw) ||
        looksLikeCvSentenceLine(raw)
      ) {
        return "";
      }
      if (raw.split(/\s+/).filter(Boolean).length > 6) {
        return "";
      }
      if (
        /[,:;]$/.test(raw) ||
        /\b(?:with|for|in|to|from|into|targeting|preferably)\b/i.test(raw)
      ) {
        return "";
      }
      words = normalizeCvNameCandidate(raw).split(/\s+/).filter(Boolean);
      picked = words.slice(0, maxWords || 3);
      if (picked.length < 2) {
        return "";
      }
      if (!picked.every(isLikelyNameWord)) {
        return "";
      }
      candidate = cleanMessageText(picked.join(" "));
      return looksLikeCvName(candidate) ? candidate : "";
    }

    function buildAnchoredNameCandidateFromLine(line, anchorTokens) {
      var words = normalizeCvNameCandidate(line).split(/\s+/).filter(Boolean);
      var normalizedWords = words.map(function (word) {
        return word.replace(/[^A-Za-zÀ-ÿ'’.-]/g, "").toLowerCase();
      });
      var tokens = (anchorTokens || []).filter(Boolean);
      var candidates = [];

      function pushCandidate(startIndex, endIndex, bonus) {
        var candidate;
        if (
          startIndex < 0 ||
          endIndex < startIndex ||
          endIndex >= words.length
        ) {
          return;
        }
        candidate = cleanMessageText(
          words.slice(startIndex, endIndex + 1).join(" ")
        );
        if (!candidate || !looksLikeCvName(candidate)) {
          return;
        }
        candidates.push({
          value: candidate,
          score:
            scoreResolvedNameCandidate(candidate, "", tokens) + (bonus || 0),
        });
      }

      if (!tokens.length || words.length < 2) {
        return "";
      }

      tokens.forEach(function (token) {
        normalizedWords.forEach(function (word, index) {
          if (
            word === token ||
            (token.length >= 4 && token.indexOf(word) === 0)
          ) {
            pushCandidate(index, Math.min(words.length - 1, index + 1), 4);
            pushCandidate(index, Math.min(words.length - 1, index + 2), 6);
            if (index > 0) {
              pushCandidate(
                index - 1,
                Math.min(words.length - 1, index + 1),
                3
              );
              pushCandidate(
                index - 1,
                Math.min(words.length - 1, index + 2),
                5
              );
            }
          }
        });
      });

      candidates.sort(function (a, b) {
        return b.score - a.score;
      });

      return candidates.length ? candidates[0].value : "";
    }

    function scoreResolvedNameCandidate(candidate, fileNameName, emailTokens) {
      var clean = cleanMessageText(candidate || "");
      var score = 0;
      var candidateTokens;
      var fileTokens;
      if (!looksLikeCvName(clean)) {
        return -999;
      }
      candidateTokens = normalizeNameTokens(clean);
      fileTokens = normalizeNameTokens(fileNameName || "");
      score +=
        candidateTokens.length >= 2 && candidateTokens.length <= 3 ? 4 : 1;
      score += /^[A-ZÀ-Ý\s'’.-]+$/.test(clean) ? 2 : 0;
      score +=
        fileTokens.filter(function (token) {
          return candidateTokens.indexOf(token) !== -1;
        }).length * 3;
      score +=
        (emailTokens || []).filter(function (token) {
          return candidateTokens.indexOf(token) !== -1;
        }).length * 4;
      return score;
    }

    function findEmailMatchedCvName(text, email) {
      var tokens = getEmailNameTokens(email);
      var lines;
      var best = "";
      var bestScore = -999;

      if (!tokens.length) {
        return "";
      }

      lines = String(text || "")
        .split(/\r?\n/)
        .map(normalizeCvLine)
        .filter(Boolean)
        .slice(0, 40);

      lines.forEach(function (line, index) {
        var clean = normalizeCvNameCandidate(line);
        var words = clean.split(/\s+/).filter(Boolean);
        var anchoredCandidate = buildAnchoredNameCandidateFromLine(
          clean,
          tokens
        );
        var anchoredScore;
        if (anchoredCandidate) {
          anchoredScore =
            scoreResolvedNameCandidate(anchoredCandidate, "", tokens) +
            Math.max(0, 10 - index) +
            4;
          if (anchoredScore > bestScore) {
            bestScore = anchoredScore;
            best = anchoredCandidate;
          }
        }
        [2, 3].forEach(function (size) {
          var start;
          var candidate;
          var candidateTokens;
          var overlap;
          var emailWordMatches;
          var score;
          for (start = 0; start <= words.length - size; start += 1) {
            candidate = cleanMessageText(
              words.slice(start, start + size).join(" ")
            );
            if (!looksLikeCvName(candidate)) {
              continue;
            }
            candidateTokens = normalizeNameTokens(candidate);
            overlap = tokens.filter(function (token) {
              return candidateTokens.indexOf(token) !== -1;
            }).length;
            emailWordMatches = candidateTokens.filter(function (token) {
              return emailLocalContainsNameWord(email, token);
            }).length;
            if (!overlap && !emailWordMatches) {
              continue;
            }
            score =
              overlap * 5 + emailWordMatches * 6 + Math.max(0, 10 - index);
            if (score > bestScore) {
              bestScore = score;
              best = candidate;
            }
          }
        });
      });

      return best;
    }

    function looksLikeCvName(line) {
      var clean = normalizeCvNameCandidate(line);
      var words;
      var lowerWordCount;
      var nonNameWordCount;
      if (
        !clean ||
        /\d|@|linkedin|http|\b(summary|experience|education|skills|certifications|awards|interests|languages|projects|profile|contact|objective)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /^(?:personal information|career objectives?|profile summary|professional summary|summary|qualities|contact details|education|professional qualifications?)$/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:experienced in|targeting|preferably|to be the part of|steady career growth|give value contribution)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (isLikelyCvQualificationText(clean)) {
        return false;
      }
      if (
        /^(?:contact details|contact|objective|career objective|profile summary|professional summary|summary|curriculum vitae|resume|cv|personal details|work experience|employment history)$/i.test(
          clean
        )
      ) {
        return false;
      }
      if (looksLikeCvLocationLine(clean) || !/[A-ZÀ-Ý]/.test(clean)) {
        return false;
      }
      if (/[&:]/.test(clean)) {
        return false;
      }
      words = clean.split(/\s+/).filter(Boolean);
      if (words.length < 2 || words.length > 6) {
        return false;
      }
      lowerWordCount = words.filter(function (word) {
        var stripped = word.replace(/[|,;:()]/g, "");
        return (
          /^[a-zà-ÿ]/.test(stripped) &&
          !/^(?:al|el|de|da|del|dos|der|di|du|la|le|van|von|bin|bint|ibn|st\.?|saint)$/i.test(
            stripped
          )
        );
      }).length;
      if ((words.length >= 4 && lowerWordCount >= 1) || lowerWordCount >= 2) {
        return false;
      }
      if (
        words.length >= 3 &&
        /^(?:[A-ZÀ-Ý][a-zà-ÿ'’.-]+\s+){2,}(?:with|for|in|to|from|into)\b/.test(
          clean
        )
      ) {
        return false;
      }
      nonNameWordCount = words.filter(isLikelyNonNameHeaderWord).length;
      if (nonNameWordCount >= 2 || nonNameWordCount === words.length) {
        return false;
      }
      return words.every(isLikelyNameWord);
    }

    function normalizeCvNameCandidate(line) {
      var clean = cleanMessageText(line);
      if (!clean) {
        return "";
      }
      clean = clean
        .replace(
          /\b([A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]{1,})\.([A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]{1,})\b/g,
          "$1 $2"
        )
        .replace(/\((?:preferred name|preferred)\s+[^)]+\)/gi, " ")
        .replace(/\bca\s*\(\s*sa\s*\)\b/gi, " ")
        .replace(/\bcasa\b/gi, " ")
        .replace(
          /^(?:[a-z]\s+)?(?:name|candidate name|full name)\s*[:\-–—]\s*/i,
          ""
        )
        .replace(
          /\b(?:an?\s+)?(?:acca|cfa|cpa|aca|caia|cma|mba|m\.?eng|b\.?eng|b\.?com|m\.?com|icwa|cima|ph\.?d|msc|msc\.?|bsc|bsc\.?|llm|jd|esq)\s+(?:affiliate|candidate|charterholder)\b/gi,
          " "
        )
        .replace(
          /\b(?:cfa|cpa|caia|aca|acca|cma|mba|m\.?eng|b\.?eng|b\.?com|m\.?com|icwa|cima|ph\.?d|msc|msc\.?|bsc|bsc\.?|llm|jd|esq)\b(?:\s*\(?level\s*\d+\)?|\s*l\d+|\s*cleared|\s*candidate|\s*charterholder)?/gi,
          " "
        )
        .replace(
          /\b(?:bachelor(?:'s|s)?|master(?:'s|s)?|degree|university|college|affiliate)\b/gi,
          " "
        )
        .replace(/\band a\b/gi, " ")
        .replace(/\b(?:level\s*\d+|cleared|candidate|charterholder)\b/gi, " ")
        .replace(/\s+/g, " ")
        .trim();
      return clean;
    }

    function extractLeadingCvNameCandidate(line) {
      var clean = normalizeCvNameCandidate(line);
      var words;
      var taken = [];
      if (!clean || isLikelyCvSectionHeading(clean)) {
        return "";
      }
      if (isCvContactLine(clean)) {
        clean = cleanMessageText(
          clean
            .replace(
              /\b(?:email|e-mail|mobile|phone|tel|telephone|contact|linkedin)\b.*$/i,
              ""
            )
            .replace(
              /\s*(?:\+?\d[\d\s().-]{7,}\d|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|(?:https?:\/\/)?(?:www\.)?linkedin\.com\/\S+).*$/i,
              ""
            )
        );
      }
      if (!clean) {
        return "";
      }
      if (/\(\s*preferred name/i.test(cleanMessageText(line))) {
        clean = clean.replace(/\s+/g, " ").trim();
      }
      words = clean.split(/\s+/).filter(Boolean);
      words.some(function (word) {
        var stripped = word.replace(/[|,;:()]/g, "");
        if (isLikelyNameWord(stripped)) {
          taken.push(stripped);
          return taken.length >= 5;
        }
        return true;
      });
      if (taken.length < 2 || taken.length > 5) {
        return "";
      }
      clean = cleanMessageText(taken.join(" "));
      return looksLikeCvName(clean) ? clean : "";
    }

    function extractCvNameCandidateAnywhere(line) {
      var raw = cleanMessageText(line);
      var clean = normalizeCvNameCandidate(line);
      var words;
      var size;
      var start;
      var candidate;
      if (!raw || !/^(?:name|candidate name|full name)\s*[:\-–—]/i.test(raw)) {
        return "";
      }
      if (!clean || isCvContactLine(clean) || isLikelyCvSectionHeading(clean)) {
        return "";
      }
      if (looksLikeCvName(clean)) {
        return clean;
      }
      words = clean.split(/\s+/).filter(Boolean);
      for (size = Math.min(5, words.length); size >= 2; size -= 1) {
        for (start = 0; start <= words.length - size; start += 1) {
          candidate = cleanMessageText(
            words.slice(start, start + size).join(" ")
          );
          if (looksLikeCvName(candidate)) {
            return candidate;
          }
        }
      }
      return "";
    }

    function isLikelyCvSectionHeading(line) {
      return !!getCvSectionMetaFromLine(line);
    }

    function looksLikeCvHeadline(line) {
      var clean = cleanMessageText(line);
      var words;
      if (!clean || looksLikeCvName(clean) || isLikelyCvSectionHeading(clean)) {
        return false;
      }
      if (/^(?:with|and|to|for|from|of|in|on)\b/i.test(clean)) {
        return false;
      }
      if (/\d|@|linkedin|http/i.test(clean)) {
        return false;
      }
      if (/^[•▪◦●■□‣\-]/.test(clean) || /[.?!]$/.test(clean)) {
        return false;
      }
      words = clean.split(/\s+/).filter(Boolean);
      if (words.length > 10) {
        return false;
      }
      if (words.length > 5 && !/[|/,&-]/.test(clean)) {
        return false;
      }
      return (
        /\b(analyst|analista|associate|assistant|assistente|manager|director|consultant|consultor|intern|internship|officer|lead|controller|accountant|accounting|auditor|research|banker|specialist|especialista|advisor|vice president|vp|principal|executive|engineer|developer|lawyer|graduate|scientist|programmer|procurement|treasury|compliance|privacy|customer service|call cent(?:re|er)|supply chain|logistics|credit|risk|finance|investment|strategy|private equity|venture capital|order management|business partnerships|alliances|assistant financier|financial specialist|consultan[tc]e?|receptionist|administrative|partner|trader|cashier|teller|business consultant|sales|portfolio management|risk management|data analyst|business analyst|data scientist|human resources|spécialiste|business risk consulting|process reengineering|financial controller|data engineer|customer service representative)\b/i.test(
          clean
        ) && safeIsRealCvRoleTitle(clean)
      );
    }

    function findSingleWordCvNameFromHeader(headerLines, email, fileNameName) {
      var emailLocal = cleanMessageText(email || "")
        .split("@")[0]
        .toLowerCase()
        .replace(/[^a-zà-ÿ]/g, "");
      var fileTokens = normalizeNameTokens(fileNameName);
      var matched = "";

      (headerLines || []).slice(0, 4).some(function (line) {
        var clean = cleanMessageText(line);
        var compact = clean.toLowerCase().replace(/[^a-zà-ÿ]/g, "");
        if (
          !clean ||
          isCvContactLine(clean) ||
          looksLikeStandaloneLocationLine(clean) ||
          isLikelyCvSectionHeading(clean)
        ) {
          return false;
        }
        if (
          !/^[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]{2,}$|^[A-ZÀ-Ý]{3,}$/.test(clean) ||
          isLikelyNonNameHeaderWord(clean)
        ) {
          return false;
        }
        if (
          (emailLocal && emailLocal.indexOf(compact) !== -1) ||
          fileTokens.indexOf(compact) !== -1
        ) {
          matched = normalizeCvNameCandidate(clean);
          return true;
        }
        return false;
      });

      return matched;
    }

    function scoreCvNameCandidate(line, index) {
      var clean =
        extractLeadingCvNameCandidate(line) ||
        extractCvNameCandidateAnywhere(line) ||
        normalizeCvNameCandidate(line);
      var words;
      var score = 0;
      if (!looksLikeCvName(clean)) {
        return -999;
      }
      words = clean.split(/\s+/).filter(Boolean);
      score += Math.max(0, 8 - index * 2);
      if (words.length >= 2 && words.length <= 4) {
        score += 4;
      }
      if (/^[A-ZÀ-Ý\s'’.-]+$/.test(clean)) {
        score += 3;
      }
      if (!/[|,;:()]/.test(clean)) {
        score += 2;
      }
      if (
        /\b(analyst|associate|manager|director|consultant|intern|officer|lead|partner|executive|finance|investment|strategy)\b/i.test(
          clean
        )
      ) {
        score -= 6;
      }
      return score;
    }

    function getCvHeaderCandidateLines(text, maxLines) {
      var lines = getCvTopLines(text, maxLines || 14);
      var startIndex = 0;
      var firstStrongAnchor = lines.findIndex(function (line) {
        var clean = cleanMessageText(line);
        return (
          clean &&
          (looksLikeCvName(clean) ||
            looksLikeCvTitledNameLine(clean) ||
            isCvContactLine(clean) ||
            looksLikeStandaloneLocationLine(clean))
        );
      });
      if (firstStrongAnchor > 0) {
        var leadingNoise = lines.slice(0, firstStrongAnchor);
        if (
          leadingNoise.every(function (line) {
            var clean = cleanMessageText(line);
            return (
              !clean ||
              looksLikeCvSentenceLine(clean) ||
              looksLikeCvSummaryFragmentLine(clean) ||
              looksLikeCvEducationSignalLine(clean) ||
              isLikelyCvHeaderSummaryLine(clean) ||
              isLikelyCvSectionHeading(clean)
            );
          })
        ) {
          startIndex = firstStrongAnchor;
        }
      }
      lines = lines.slice(startIndex);
      var stopIndex = lines.findIndex(function (line, index) {
        return index > 0 && isLikelyCvSectionHeading(line);
      });
      var headerLines = stopIndex > 0 ? lines.slice(0, stopIndex) : lines;
      var foundCoreHeaderSignal = false;
      var cutIndex = -1;

      headerLines.some(function (line, index) {
        var clean = cleanMessageText(line);
        if (!clean) {
          return false;
        }
        if (hasCoreCvHeaderSignal(clean)) {
          foundCoreHeaderSignal = true;
          return false;
        }
        if (
          foundCoreHeaderSignal &&
          (looksLikeCvSentenceLine(clean) ||
            isLikelyCvHeaderSummaryLine(clean) ||
            isCvBulletLine(clean) ||
            looksLikeCvEducationSignalLine(clean) ||
            looksLikeCvAwardOrLanguageLine(clean) ||
            looksLikeCvRoleMetaLine(clean) ||
            hasCvDateRange(clean))
        ) {
          cutIndex = index;
          return true;
        }
        return false;
      });

      if (cutIndex > 0) {
        return headerLines.slice(0, cutIndex);
      }
      return headerLines;
    }

    function extractStackedCvName(lines) {
      var source = (lines || [])
        .map(function (line) {
          return cleanMessageText(line).replace(
            /^(?:mr|mrs|ms|miss|dr)\.?\s+/i,
            ""
          );
        })
        .filter(Boolean)
        .slice(0, 10);
      var taken = [];
      var candidate = "";
      if (
        source[0] &&
        !isLikelyCvSectionHeading(source[0]) &&
        /^(?:[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]*|[A-ZÀ-Ý]{2,})$/.test(source[0]) &&
        !isLikelyNonNameHeaderWord(source[0])
      ) {
        return source[0];
      }
      source.some(function (line) {
        if (
          isCvContactLine(line) ||
          isLikelyCvSectionHeading(line) ||
          looksLikeStandaloneLocationLine(line)
        ) {
          return false;
        }
        if (!/^(?:[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]*|[A-ZÀ-Ý]{2,})$/.test(line)) {
          return true;
        }
        taken.push(line);
        return taken.length >= 4;
      });
      if (taken.length < 2) {
        return "";
      }
      candidate = cleanMessageText(taken.join(" "));
      return looksLikeCvName(candidate) ? candidate : "";
    }

    function classifyCvHeaderLine(line) {
      var clean = cleanMessageText(line);
      if (!clean) {
        return "empty";
      }
      if (
        looksLikeCvName(clean) ||
        extractLeadingCvNameCandidate(clean) ||
        extractCvNameCandidateAnywhere(clean)
      ) {
        return "name";
      }
      if (isCvContactLine(clean)) {
        return "contact";
      }
      if (looksLikeStandaloneLocationLine(clean)) {
        return "location";
      }
      if (
        looksLikeCvHeaderPersonalDetailLine(clean) ||
        looksLikeCvRoleMetaLine(clean)
      ) {
        return "meta";
      }
      if (looksLikeCvHeadline(clean)) {
        return "headline";
      }
      if (isLikelyCvHeaderSummaryLine(clean)) {
        return "summary";
      }
      return "other";
    }

    function stripLeadingCvNameFromLine(line) {
      var clean = cleanMessageText(line);
      var candidate =
        extractLeadingCvNameCandidate(clean) ||
        extractCvNameCandidateAnywhere(clean);
      var escaped;
      if (!clean || !candidate) {
        return clean;
      }
      escaped = candidate.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return cleanMessageText(
        clean.replace(
          new RegExp("^" + escaped + "(?:\\s*[|,;:\\-–—/]\\s*|\\s+)?", "i"),
          ""
        )
      );
    }

    function addCvHeaderLineToBlock(block, line, index) {
      var clean = cleanMessageText(line);
      var type;
      var extractedName;
      var remainder;
      if (!clean) {
        return;
      }

      type = classifyCvHeaderLine(clean);
      extractedName =
        extractLeadingCvNameCandidate(clean) ||
        extractCvNameCandidateAnywhere(clean);

      if (type === "name") {
        block.names.push({
          value: extractedName || clean,
          score: scoreCvNameCandidate(clean, index),
          index: index,
        });
        remainder = stripLeadingCvNameFromLine(clean);
        if (
          remainder &&
          remainder !== clean &&
          remainder.split(/\s+/).length >= 2
        ) {
          addCvHeaderLineToBlock(block, remainder, index + 0.1);
        }
        return;
      }
      if (type === "contact") {
        block.contacts.push({
          value: clean,
          index: index,
        });
        remainder = extractCvHeadlineFromMixedContactLine(clean);
        if (remainder && remainder !== clean) {
          addCvHeaderLineToBlock(block, remainder, index + 0.1);
        }
        return;
      }
      if (type === "location") {
        block.locations.push({
          value: clean,
          index: index,
        });
        return;
      }
      if (type === "headline") {
        block.headlines.push({
          value: clean,
          score: Math.max(0, 10 - index),
          index: index,
        });
        return;
      }
      if (type === "summary") {
        block.summaries.push({
          value: clean,
          index: index,
        });
        return;
      }
      block.others.push({
        value: clean,
        index: index,
      });
    }

    function findCvEmailInLines(lines) {
      return findCvEmail((lines || []).join(" | "));
    }

    function findCvPhoneInLines(lines) {
      return findCvPhone((lines || []).join(" | "));
    }

    function findCvLinkedInInLines(lines) {
      return findCvLinkedIn((lines || []).join(" | "));
    }

    function findCvHeaderLocationFromLines(lines) {
      return findCvHeaderLocation((lines || []).join("\n"));
    }

    function extractCvHeadlineFromMixedContactLine(line) {
      var clean = cleanMessageText(line);
      var parts;
      if (!clean || !isCvContactLine(clean)) {
        return "";
      }
      parts = clean
        .split(/\s*[|•·▪◦]\s*|\s{2,}/)
        .map(cleanMessageText)
        .filter(Boolean)
        .filter(function (part) {
          return (
            !isCvContactLine(part) &&
            !looksLikeStandaloneLocationLine(part) &&
            !isLikelyCvHeaderSummaryLine(part)
          );
        });
      return (
        parts.find(function (part) {
          return looksLikeCvHeadline(part);
        }) || ""
      );
    }

    function extractCvTargetingHeadline(line) {
      var clean = cleanMessageText(line);
      var match;
      var candidate;
      if (!clean) {
        return "";
      }
      match = clean.match(
        /\btargeting\s+([^.,;|]+?\b(?:roles?|opportunities|positions?)?)\b/i
      );
      if (match && match[1]) {
        return toTitleCaseWords(
          cleanMessageText(match[1]).replace(
            /\b(?:with|for|preferably|mainly|across)\b.*$/i,
            ""
          )
        );
      }
      match = clean.match(
        /^([A-ZÀ-Ý][A-Za-zÀ-ÿ&/'’().,\- ]{2,80}?)\s+with\s+(?:[^.]{0,80}?)\b(?:experience|background)\b/i
      );
      if (match && match[1]) {
        candidate = cleanMessageText(match[1]).replace(/[.,;:\-–—]+$/g, "");
        if (
          candidate.split(/\s+/).length <= 6 &&
          !looksLikeCvName(candidate) &&
          /\b(?:analyst|associate|manager|director|consultant|intern|officer|lead|partner|executive|research|finance|investment|strategy|credit|private equity|venture capital|compliance|accountant|auditor|banker|controller|trader|cashier|teller|lawyer|engineer|specialist|coordinator)\b/i.test(
            candidate
          )
        ) {
          return candidate;
        }
      }
      match = clean.match(
        /^([A-ZÀ-Ý][A-Za-zÀ-ÿ&/'’().,\- ]{2,80}?)\s+(?:seeking|specialising|specializing|focused on)\b/i
      );
      if (match && match[1]) {
        candidate = cleanMessageText(match[1]).replace(/[.,;:\-–—]+$/g, "");
        if (candidate.split(/\s+/).length <= 6 && !looksLikeCvName(candidate)) {
          return candidate;
        }
      }
      match = clean.match(/\btitle\s*[:\-–—]\s*([^|,;]+)$/i);
      if (match && match[1] && looksLikeCvHeadline(match[1])) {
        return cleanMessageText(match[1]);
      }
      return "";
    }

    function extractCvHeadlineFromLine(line) {
      var clean = cleanMessageText(line);
      var targetingHeadline;
      var parts;
      if (!clean || looksLikeCvName(clean) || isLikelyCvSectionHeading(clean)) {
        return "";
      }
      targetingHeadline = extractCvTargetingHeadline(clean);
      if (targetingHeadline) {
        return targetingHeadline;
      }
      if (isLikelyCvHeaderSummaryLine(clean)) {
        return "";
      }
      if (looksLikeCvHeadline(clean)) {
        return clean;
      }
      parts = clean
        .split(/\s*[|•·▪◦]\s*|\s{2,}/)
        .map(cleanMessageText)
        .filter(Boolean)
        .filter(function (part) {
          return (
            !looksLikeCvName(part) &&
            !isCvContactLine(part) &&
            !looksLikeStandaloneLocationLine(part) &&
            !isLikelyCvSectionHeading(part) &&
            !isLikelyCvHeaderSummaryLine(part)
          );
        });
      return (
        parts.find(function (part) {
          return looksLikeCvHeadline(part);
        }) || ""
      );
    }

    function resolveCvHeadline(headerLines, structuredHeader, name) {
      var candidates = [];
      var seen = [];
      function pushCandidate(value, score) {
        var clean = cleanMessageText(value);
        if (
          !clean ||
          clean === cleanMessageText(name) ||
          seen.indexOf(clean.toLowerCase()) !== -1
        ) {
          return;
        }
        seen.push(clean.toLowerCase());
        candidates.push({
          value: clean,
          score: score,
        });
      }

      ((structuredHeader && structuredHeader.headlines) || []).forEach(
        function (item, index) {
          pushCandidate(item && item.value, 20 - index * 2);
        }
      );
      ((structuredHeader && structuredHeader.summaries) || [])
        .slice(0, 3)
        .forEach(function (line, index) {
          var extracted = extractCvTargetingHeadline(line);
          if (extracted) {
            pushCandidate(extracted, 15 - index * 2);
          }
        });

      (headerLines || []).slice(0, 6).forEach(function (line, index) {
        var clean = cleanMessageText(line);
        var extracted = extractCvHeadlineFromLine(clean);
        if (!clean || !extracted) {
          return;
        }
        pushCandidate(extracted, 14 - index * 2);
        if (looksLikeCvHeadline(clean)) {
          pushCandidate(clean, 12 - index * 2);
        }
      });

      candidates.sort(function (a, b) {
        return b.score - a.score;
      });

      return candidates.length ? candidates[0].value : "";
    }

    function buildCvHeaderBlock(text) {
      var lines = getCvHeaderCandidateLines(text, 20);
      var block = {
        names: [],
        contacts: [],
        locations: [],
        headlines: [],
        summaries: [],
        others: [],
      };

      lines.forEach(function (line, index) {
        addCvHeaderLineToBlock(block, line, index);
      });

      block.names.sort(function (a, b) {
        return b.score - a.score || a.index - b.index;
      });
      block.headlines.sort(function (a, b) {
        return b.score - a.score || a.index - b.index;
      });

      return block;
    }

    function isLikelyCvHeaderSummaryLine(line) {
      var clean = cleanMessageText(line);
      if (!clean) {
        return false;
      }
      if (
        isCvContactLine(clean) ||
        looksLikeCvName(clean) ||
        looksLikeCvHeadline(clean)
      ) {
        return false;
      }
      if (
        /(results[- ]driven|experienced|dynamic|finance professional|senior business consultant|banker|profile summary|summary|currently working as|strong experience|hands-on experience|proficient in|adept at|passionate about)/i.test(
          clean
        )
      ) {
        return true;
      }
      return clean.split(/\s+/).length >= 8 && !isLikelyCvSectionHeading(clean);
    }

    function buildStructuredCvHeaderCandidates(text) {
      var block = buildCvHeaderBlock(text);
      return {
        names: block.names,
        headlines: block.headlines,
        summaries: block.summaries.map(function (item) {
          return item.value;
        }),
        contacts: block.contacts.map(function (item) {
          return item.value;
        }),
        locations: block.locations.map(function (item) {
          return item.value;
        }),
      };
    }

    function findCvName(text) {
      var headerLines = getCvHeaderCandidateLines(text, 16);
      var email = findCvEmail(text);
      var fileNameName = extractNameFromCvFileName(
        currentCvFile && currentCvFile.name
      );
      var emailMatched = findEmailMatchedCvName(text, email);
      var emailTokens = getEmailNameTokens(email);
      var fileTokens = normalizeNameTokens(fileNameName);
      var candidates = [];

      headerLines.slice(0, 6).forEach(function (line) {
        var anchoredFromEmail = buildAnchoredNameCandidateFromLine(
          line,
          emailTokens
        );
        var anchoredFromFile = buildAnchoredNameCandidateFromLine(
          line,
          fileTokens
        );
        if (anchoredFromEmail) {
          candidates.push(anchoredFromEmail);
        }
        if (anchoredFromFile) {
          candidates.push(anchoredFromFile);
        }
        [2, 3].forEach(function (size) {
          var candidate = buildTopWordNameCandidate(line, size);
          if (candidate) {
            candidates.push(candidate);
          }
        });
        var extracted =
          extractLeadingCvNameCandidate(line) ||
          extractCvNameCandidateAnywhere(line);
        if (extracted) {
          candidates.push(extracted);
        }
      });

      if (emailMatched) {
        candidates.unshift(emailMatched);
      }
      if (fileNameName) {
        candidates.unshift(fileNameName);
      }

      candidates = dedupeList(candidates)
        .map(function (candidate) {
          return {
            value: candidate,
            score: scoreResolvedNameCandidate(
              candidate,
              fileNameName,
              emailTokens
            ),
          };
        })
        .filter(function (item) {
          return item.score > -999;
        })
        .sort(function (a, b) {
          return b.score - a.score;
        });

      return candidates.length ? cleanMessageText(candidates[0].value) : "";
    }

    function extractNameFromCvFileName(fileName) {
      var clean = cleanMessageText(fileName || "");
      var base;
      var words;

      if (!clean) {
        return "";
      }

      base = clean
        .replace(/\.[A-Za-z0-9]{2,5}$/g, "")
        .replace(
          /\b(?:resume|cv|review|skill\s*farm|updated|complete|final|draft)\b/gi,
          " "
        )
        .replace(/\bcopy\b/gi, " ")
        .replace(/\(\d+\)/g, " ")
        .replace(/\b[a-z]\b/gi, " ")
        .replace(/[_]+/g, " ")
        .replace(/\s*-\s*/g, " ")
        .replace(/\s+/g, " ")
        .trim();

      words = base.split(/\s+/).filter(function (word) {
        return word && !/^\d+$/.test(word);
      });

      if (words.length < 2) {
        return "";
      }

      words = words.slice(0, 6).map(function (word) {
        if (/^[A-ZÀ-Ý][A-Za-zÀ-ÿ'’.-]+$/.test(word)) {
          return word;
        }
        if (/^[A-ZÀ-Ý]{2,}(?:-[A-ZÀ-Ý]{2,})*$/.test(word)) {
          return word.charAt(0) + word.slice(1).toLowerCase();
        }
        if (/^[a-zà-ÿ][A-Za-zÀ-ÿ'’.-]+$/.test(word)) {
          return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        }
        return word;
      });

      base = cleanMessageText(words.join(" "));
      return looksLikeCvName(base) ? base : "";
    }

    function buildCvHeaderModel(text, sections, options) {
      var config = options || {};
      var allowRoleFallback =
        typeof config.allowRoleFallback === "undefined"
          ? true
          : !!config.allowRoleFallback;
      var topLines = getCvTopLines(text, 12);
      var headerLines = getCvHeaderCandidateLines(text, 16);
      var structuredHeader = buildStructuredCvHeaderCandidates(text);
      var headerContactLines = structuredHeader.contacts
        .concat(structuredHeader.locations || [])
        .concat(
          (structuredHeader.headlines || []).map(function (item) {
            return item && item.value ? item.value : "";
          })
        )
        .filter(Boolean);
      var email = findCvEmailInLines(headerContactLines) || findCvEmail(text);
      var phone = findCvPhoneInLines(headerContactLines) || findCvPhone(text);
      var linkedin =
        findCvLinkedInInLines(headerContactLines) || findCvLinkedIn(text);
      var location =
        findCvHeaderLocationFromLines(
          headerContactLines.concat(headerLines.slice(0, 6))
        ) || findCvHeaderLocation(text);
      var fileNameName = extractNameFromCvFileName(
        currentCvFile && currentCvFile.name
      );
      var topNameCandidates = headerLines
        .filter(function (line) {
          return looksLikeCvName(line) || !!extractLeadingCvNameCandidate(line);
        })
        .map(function (line, index) {
          return {
            raw: line,
            value:
              extractLeadingCvNameCandidate(line) || cleanMessageText(line),
            score: scoreCvNameCandidate(line, index),
          };
        })
        .sort(function (a, b) {
          return b.score - a.score;
        });
      var name = "";
      var headline = "";
      var contactParts = [];
      var emailTokens = getEmailNameTokens(email);
      var fileTokens = normalizeNameTokens(fileNameName);
      var emailMatchedName = findEmailMatchedCvName(text, email);
      var singleWordHeaderName = findSingleWordCvNameFromHeader(
        headerLines,
        email,
        fileNameName
      );
      var topWordCandidates = headerLines
        .slice(0, 4)
        .reduce(function (list, line) {
          var anchoredFromEmail = buildAnchoredNameCandidateFromLine(
            line,
            emailTokens
          );
          var anchoredFromFile = buildAnchoredNameCandidateFromLine(
            line,
            fileTokens
          );
          if (anchoredFromEmail) {
            list.push(anchoredFromEmail);
          }
          if (anchoredFromFile) {
            list.push(anchoredFromFile);
          }
          [2, 3].forEach(function (size) {
            var candidate = buildTopWordNameCandidate(line, size);
            if (candidate) {
              list.push(candidate);
            }
          });
          return list;
        }, []);
      var resolvedCandidates = dedupeList(
        []
          .concat(singleWordHeaderName ? [singleWordHeaderName] : [])
          .concat(emailMatchedName ? [emailMatchedName] : [])
          .concat(fileNameName ? [fileNameName] : [])
          .concat(
            (structuredHeader.names || []).map(function (item) {
              return item && item.value ? item.value : "";
            })
          )
          .concat(topWordCandidates)
          .concat(
            topNameCandidates.map(function (item) {
              return item.value;
            })
          )
          .concat(findCvName(text) ? [findCvName(text)] : [])
      )
        .map(function (candidate) {
          return {
            value: cleanMessageText(candidate),
            score: scoreResolvedNameCandidate(
              candidate,
              fileNameName,
              emailTokens
            ),
          };
        })
        .filter(function (item) {
          return item.score > -999;
        })
        .sort(function (a, b) {
          return b.score - a.score;
        });

      if (location && location.label) {
        location.label = sanitizeHeaderLocationLabel(location);
      }

      if (location && location.label) {
        contactParts.push(location.label);
      }
      if (phone) {
        contactParts.push(phone);
      }
      if (email) {
        contactParts.push(email);
      }
      if (linkedin) {
        contactParts.push(linkedin.replace(/^https?:\/\/(www\.)?/i, ""));
      }

      if (resolvedCandidates.length) {
        name = cleanMessageText(resolvedCandidates[0].value || "");
      }
      if (!name) {
        name = extractStackedCvName(headerLines);
      }
      if (!name) {
        name = cleanMessageText(userName || fileNameName || "");
      }
      headline = resolveCvHeadline(headerLines, structuredHeader, name);
      if (!headline) {
        ((structuredHeader && structuredHeader.summaries) || [])
          .slice(0, 4)
          .some(function (line) {
            var extracted = extractCvTargetingHeadline(line);
            if (extracted) {
              headline = extracted;
              return true;
            }
            return false;
          });
      }
      if (!headline) {
        headerLines.slice(0, 8).some(function (line) {
          var extracted = extractCvTargetingHeadline(line);
          if (extracted) {
            headline = extracted;
            return true;
          }
          return false;
        });
      }
      if (!headline) {
        topLines.slice(0, 10).some(function (line) {
          var extracted = extractCvTargetingHeadline(line);
          if (extracted) {
            headline = extracted;
            return true;
          }
          return false;
        });
      }
      if (!headline && sections && sections.length) {
        headline = getPrimaryCoverLetterRoleContext(
          pickRelevantExperienceEntries({}, sections, 1)
        );
      }
      if (!headline) {
        headline = cleanMessageText(
          cvFacts.experienceTitle || (allowRoleFallback ? roleTitle : "") || ""
        );
      }

      return {
        name: name,
        headline: headline,
        contactLine: contactParts.join(" | "),
        location: location && location.label ? location.label : "",
        email: email,
        phone: phone,
        linkedin: linkedin,
      };
    }

    function getProfileSectionItems(sections) {
      return getProfileSourceItems(sections)
        .map(cleanMessageText)
        .filter(Boolean)
        .slice(0, 4);
    }

    function getProfileSectionItemsFromRawText(text) {
      var lines = getCvTopLines(text, 40);
      var startIndex = lines.findIndex(function (line) {
        return /^(?:profile|summary|professional summary|executive summary|personal statement|background)$/i.test(
          cleanMessageText(line)
        );
      });
      var items = [];
      if (startIndex === -1) {
        return [];
      }
      lines.slice(startIndex + 1).some(function (line) {
        var clean = cleanMessageText(line);
        if (!clean) {
          return items.length >= 2;
        }
        if (
          isLikelyCvSectionHeading(clean) ||
          isCvContactLine(clean) ||
          looksLikeCvRoleMetaLine(clean)
        ) {
          return items.length > 0;
        }
        if (clean.split(/\s+/).length < 5) {
          return false;
        }
        items.push(clean);
        return items.length >= 4;
      });
      return dedupeList(items).slice(0, 4);
    }

    function sanitizeHeaderLocationLabel(locationMatch) {
      var label = cleanMessageText(
        (locationMatch && locationMatch.label) || ""
      );
      if (!label) {
        return "";
      }
      if (
        hasCvDateRange(label) ||
        /^[0-9\s/.-]+$/.test(label) ||
        looksLikeCvRoleMetaLine(label)
      ) {
        return "";
      }
      return label;
    }

    function detectCvReviewFamily(text, headerModel, profileItems) {
      var clean = cleanMessageText(
        [
          text || "",
          (headerModel && headerModel.headline) || "",
          (profileItems || []).join(" "),
        ].join(" ")
      ).toLowerCase();
      if (!clean) {
        return "general";
      }
      if (
        /(mechanical engineer|manufacturing|autocad|solidworks|comsol|ansys|fea|cae|cfd|thermoacoustic|structural analysis|sap systems|quality engineer)/i.test(
          clean
        )
      ) {
        return "engineering";
      }
      if (
        /(financial model|valuation|private equity|investment|market research|due diligence|portfolio|credit analysis|equity research|deal)/i.test(
          clean
        )
      ) {
        return "investing";
      }
      if (
        /(accounting|audit|financial reporting|forecast|budget|reconciliation|fund accounting|treasury|fp&a)/i.test(
          clean
        )
      ) {
        return "reporting";
      }
      if (
        /(compliance|risk|kyc|aml|governance|controls|underwriting)/i.test(
          clean
        )
      ) {
        return "risk_ops";
      }
      if (
        /(attorney|legal|law firm|court|advocate|contract|regulatory compliance|recruitment consultant|recruiter|candidate sourcing|talent acquisition|communicate recruitment|agency recruitment)/i.test(
          clean
        )
      ) {
        return "legal_recruitment";
      }
      if (
        /(client|stakeholder|fundraising|investor relations|relationship management|sales|business development)/i.test(
          clean
        )
      ) {
        return "commercial";
      }
      return "general";
    }

    function getReviewPrioritySkills(analysis) {
      var adjacentSignals = getAdjacentProofSignals(analysis);
      var confirmedSignals = getStatementSafeConfirmedSignals(analysis);
      var labels = adjacentSignals
        .concat(confirmedSignals)
        .map(function (signal) {
          return signal && signal.label ? String(signal.label).trim() : "";
        })
        .filter(Boolean);
      return dedupeList(labels).slice(0, 3);
    }

    function isCrossDisciplineReviewCase(draftModel) {
      var roleFamily = getRoleFamilyTone();
      var cvFamily = String((draftModel && draftModel.cvFamily) || "");
      var roleSignals = (draftModel && draftModel.reviewPrioritySkills) || [];
      if (!cvFamily || cvFamily === "general") {
        return false;
      }
      if (roleFamily === cvFamily) {
        return false;
      }
      if (roleFamily === "investing" && cvFamily === "engineering") {
        return true;
      }
      if (roleFamily === "reporting" && cvFamily === "engineering") {
        return true;
      }
      if (
        /^(investing|reporting|risk_ops)$/i.test(roleFamily) &&
        cvFamily === "legal_recruitment"
      ) {
        return true;
      }
      return (
        roleSignals.length === 0 &&
        /^(engineering|legal_recruitment)$/i.test(cvFamily)
      );
    }

    function getReviewFitConfidence(draftModel, analysis) {
      var score = buildReviewScore(draftModel, analysis);
      if (isCrossDisciplineReviewCase(draftModel)) {
        return "transferable";
      }
      if (score >= 82) {
        return "strong";
      }
      if (score >= 70) {
        return "borderline";
      }
      return "transferable";
    }

    function getFocusedEntryOriginalBullet(entry, fallbackItems) {
      var bullet = "";
      if (entry && entry.bullets && entry.bullets.length) {
        bullet = cleanMessageText(entry.bullets[0]);
      }
      if (!bullet && entry && entry.lines && entry.lines.length > 1) {
        bullet = cleanMessageText(entry.lines.slice(1).find(Boolean) || "");
      }
      if (!bullet && fallbackItems && fallbackItems.length) {
        bullet = cleanMessageText(fallbackItems[0]);
      }
      return bullet;
    }

    function buildExperienceRewriteItems(
      analysis,
      focusedEntry,
      fallbackItems,
      reviewHints
    ) {
      var items = [];
      var originalBullet = getFocusedEntryOriginalBullet(
        focusedEntry,
        fallbackItems
      );
      var afterText = cleanMessageText((analysis && analysis.after) || "");
      var signals = getReviewPrioritySkills(analysis).slice(0, 3);
      var originalBullets = focusedEntry
        ? (focusedEntry.bullets || [])
            .map(cleanMessageText)
            .filter(Boolean)
            .slice(0, 3)
        : [];
      var passiveFindings = detectPassiveCvPhrases(
        originalBullets.concat(fallbackItems || [])
      );
      var cvFamily = detectCvReviewFamily(
        capturedCvText,
        {},
        getProfileSectionItemsFromRawText(capturedCvText || "")
      );
      var crossDiscipline =
        getRoleFamilyTone() !== cvFamily &&
        cvFamily === "engineering" &&
        /^(investing|reporting|commercial|risk_ops)$/i.test(
          getRoleFamilyTone()
        );

      if (afterText && !crossDiscipline) {
        items.push(takeLeadingWords(afterText, 24) + ".");
      }
      if (passiveFindings.length) {
        items.push(buildPassiveRewriteExample(passiveFindings[0]));
      }
      (reviewHints || []).slice(0, 1).forEach(function (hint) {
        items.push(hint);
      });
      if (originalBullet && !passiveFindings.length) {
        items.push(takeLeadingWords(originalBullet, 24) + ".");
      }
      if (
        !crossDiscipline &&
        signals.length &&
        !items.some(function (item) {
          return item.toLowerCase().indexOf(signals[0].toLowerCase()) !== -1;
        })
      ) {
        items.push(
          "Highlight " +
            formatNaturalList(signals) +
            " earlier in this role block."
        );
      }

      return dedupeList(items).slice(0, 3);
    }

    function buildSuggestedTailoringBullets(analysis, sections) {
      var bullets = [];
      var confirmed = getWorkspaceConfirmedItems(analysis).slice(0, 3);
      var tighten = getWorkspaceTightenItems(analysis).slice(0, 3);
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 3);
      var titleCompany = [cvFacts.experienceTitle, cvFacts.experienceCompany]
        .filter(Boolean)
        .join(" at ");

      if (titleCompany) {
        bullets.push(
          "Re-anchor the profile around " +
            titleCompany +
            " so the positioning is clearer immediately."
        );
      }
      confirmed.forEach(function (item) {
        bullets.push(
          "Pull " +
            item.toLowerCase() +
            " higher up so it lands faster for the role."
        );
      });
      tighten.forEach(function (item) {
        bullets.push(
          "Rewrite the CV language around " +
            item.toLowerCase() +
            " so it reads more directly."
        );
      });
      roleSignals.forEach(function (item) {
        bullets.push(
          "Add a stronger bullet that connects your experience to " +
            item.toLowerCase() +
            "."
        );
      });

      if (!bullets.length && sections.length) {
        bullets.push(
          "Tighten the opening profile so the most relevant experience is visible straight away."
        );
        bullets.push(
          "Rewrite the most relevant experience bullets with clearer action and outcome language."
        );
      }

      return dedupeList(bullets).slice(0, 6);
    }

    function buildRoleSpecificSuggestions(analysis) {
      var suggestions = [];
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 3);
      var confirmedLabels = getStatementSafeConfirmedSignals(analysis)
        .map(getSignalLabel)
        .filter(Boolean)
        .slice(0, 3);

      if (roleSignals.length) {
        suggestions.push(
          "For " +
            roleTitle +
            ", I want " +
            formatNaturalList(roleSignals) +
            " to show up much more clearly."
        );
      }
      if (confirmedLabels.length) {
        suggestions.push(
          "The evidence I can already use confidently is " +
            formatNaturalList(confirmedLabels) +
            "."
        );
      }
      if ((analysis && analysis.after) || (analysis && analysis.before)) {
        suggestions.push(
          cleanMessageText(
            (analysis && analysis.after) ||
              "I am tightening the language so the role fit is clearer."
          )
        );
      }

      return dedupeList(suggestions).slice(0, 4);
    }

    function buildSummaryReviewItems(draftModel) {
      if (draftModel && isCrossDisciplineReviewCase(draftModel)) {
        return [
          "The current profile reads as " +
            cleanMessageText(
              (draftModel.headerModel && draftModel.headerModel.headline) ||
                "a different discipline"
            ) +
            ". If you are targeting this role, the summary needs to explain the switch credibly rather than imply a direct fit.",
        ];
      }
      var findings = (draftModel.passiveProfileFindings || []).slice(0, 1);
      return dedupeList(
        findings.map(function (finding) {
          return (
            buildAdvancedCommentaryNotes(finding && finding.source, {
              section: "profile",
              isPrimary: true,
            })[0] || buildPassiveReplacementNote(finding)
          );
        })
      ).slice(0, 1);
    }

    function lineHasMissingQuantOpportunity(text) {
      var clean = cleanMessageText(text);
      if (!clean || extractQuantSignals(clean).length) {
        return false;
      }
      return /\b(led|managed|executed|conducted|prepared|created|developed|delivered|built|analysed|analyzed|supported|drove|implemented|improved|liaised|monitored|negotiated|presented)\b/i.test(
        clean
      );
    }

    function buildLineScopedReviewNotes(text, options) {
      var clean = cleanMessageText(text);
      var notes = [];
      var passiveFindings;
      var roleSignals;
      var missingSignals;
      var context = options || {};

      if (!clean) {
        return [];
      }

      passiveFindings = detectPassiveCvPhrases([clean]);
      roleSignals = (context.roleSignals || []).slice(0, 3);
      if (context.section !== "profile") {
        roleSignals =
          context.isPrimary &&
          String(context.section || "")
            .toLowerCase()
            .indexOf("experience") === 0
            ? roleSignals.slice(0, 2)
            : roleSignals;
      }
      notes = buildAdvancedCommentaryNotes(clean, {
        section: context.section || "default",
        isPrimary: context.isPrimary,
        roleSignals: roleSignals,
      });
      if (!notes.length && passiveFindings.length) {
        notes.push(buildPassiveReplacementNote(passiveFindings[0]));
      }
      return dedupeList(notes).slice(0, 2);
    }

    function cleanTargetRoleForSummary(roleName) {
      return cleanMessageText(
        String(roleName || "")
          .replace(/\s+-\s+[^,|]+(?:,.*)?$/g, "")
          .replace(/\s+\|\s+.*$/g, "")
      );
    }

    function buildTailoredExecutiveSummary(
      analysis,
      sections,
      headerModel,
      draftModel
    ) {
      var targetRole = cleanTargetRoleForSummary(
        roleTitle ||
          (headerModel && headerModel.headline) ||
          "Finance professional"
      );
      var years = Math.max(
        Number((analysis && analysis.experience_years) || 0),
        Number(cvFacts.experienceYears || 0)
      );
      var yearsText = years > 0 ? years + "+ years' experience" : "experience";
      var confirmedSignals = getStatementSafeConfirmedSignals(analysis);
      var adjacentSignals = getAdjacentProofSignals(analysis);
      var allSignals = confirmedSignals.concat(adjacentSignals);
      var hardSkills = getReadableSignalLabels(
        getSignalsByCategory(allSignals, "hard_skill"),
        3
      );
      var backgrounds = getReadableSignalLabels(
        getSignalsByCategory(allSignals, "experience_background"),
        3
      );
      var sectors = getReadableSignalLabels(
        getSignalsByCategory(allSignals, "sector_exposure"),
        3
      );
      var qualifications = getReadableSignalLabels(
        getSignalsByCategory(allSignals, ["qualification", "credential"]),
        2
      );
      var roleSignals = getApplyPrioritySkills(analysis).slice(0, 3);
      var quantSignals = extractQuantSignals(capturedCvText || "").slice(0, 2);
      var family = getRoleFamilyTone();
      var cvFamilyForSummary = String(
        (draftModel && draftModel.cvFamily) || ""
      );
      var summary = [];
      var coreSkills = dedupeList(
        roleSignals.concat(hardSkills).concat(backgrounds)
      ).slice(0, 4);
      var skillText = formatNaturalList(coreSkills.slice(0, 3));
      var sectorText = formatNaturalList(sectors.slice(0, 2));
      var quantText = formatNaturalList(quantSignals);
      var qualificationText = qualifications.length ? qualifications[0] : "";

      if (draftModel && isCrossDisciplineReviewCase(draftModel)) {
        summary.push(
          "If you are targeting " +
            targetRole +
            ", the opening summary needs to explain the move from " +
            cleanMessageText(
              (headerModel && headerModel.headline) || "your current discipline"
            ) +
            " into the role instead of reading as a direct match."
        );
        summary.push(
          "Lead with the analytical tools, research exposure, and transferable problem-solving that are genuinely relevant, and avoid claiming finance experience that is not on the CV."
        );
        return dedupeList(summary).slice(0, 2);
      }

      if (
        cvFamilyForSummary === "legal_recruitment" &&
        !/\b(?:legal|law|attorney|recruitment|recruiter|talent)\b/i.test(
          targetRole
        )
      ) {
        summary.push(
          "Legal and recruitment professional with client-facing experience across advisory work, candidate sourcing, stakeholder communication, and business development activity."
        );
        summary.push(
          "For " +
            targetRole +
            ", the CV should lead with transferable commercial proof only where the original CV supports it, rather than presenting the candidate as already established in the target role."
        );
        return dedupeList(summary).slice(0, 2);
      }

      if (family === "investing") {
        summary.push(
          "Results-driven " +
            targetRole +
            " with " +
            yearsText +
            " across " +
            (skillText ||
              "origination, due diligence, execution, and portfolio value creation") +
            "."
        );
      } else if (family === "reporting") {
        summary.push(
          "Commercially minded " +
            targetRole +
            " with " +
            yearsText +
            " across " +
            (skillText ||
              "financial reporting, controls, forecasting, and process improvement") +
            "."
        );
      } else if (family === "commercial") {
        summary.push(
          "Client-facing " +
            targetRole +
            " with " +
            yearsText +
            " across " +
            (skillText ||
              "investor coverage, stakeholder management, fundraising, and market development") +
            "."
        );
      } else if (family === "risk_ops") {
        summary.push(
          "Analytical " +
            targetRole +
            " with " +
            yearsText +
            " across " +
            (skillText ||
              "risk, controls, governance, and regulatory delivery") +
            "."
        );
      } else {
        summary.push(
          "Results-driven " +
            targetRole +
            " with " +
            yearsText +
            " across " +
            (skillText || "finance, analysis, and execution") +
            "."
        );
      }

      if (sectorText && quantText) {
        summary.push(
          "Visible evidence across " +
            sectorText +
            ", with quantified exposure around " +
            quantText +
            "."
        );
      } else if (sectorText) {
        summary.push(
          "Visible evidence across " +
            sectorText +
            ", with role-relevant proof points already on the CV."
        );
      } else if (quantText) {
        summary.push(
          "The CV already shows measurable scale around " +
            quantText +
            ", which should be pulled higher in the opening positioning."
        );
      }

      if (qualificationText) {
        summary.push(
          qualificationText +
            " with experience that aligns well to " +
            formatNaturalList(roleSignals.slice(0, 2)) +
            "."
        );
      } else if (roleSignals.length) {
        summary.push(
          "Particular strength in " +
            formatNaturalList(roleSignals.slice(0, 3)) +
            "."
        );
      }

      return dedupeList(summary).slice(0, 3);
    }

    function buildExperienceReviewItems(
      entry,
      analysis,
      reviewHints,
      passiveFindings,
      sourceBullets
    ) {
      var items = [];
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 2);
      var firstBullet = cleanMessageText((sourceBullets || [])[0] || "");
      var firstBulletLower = firstBullet.toLowerCase();
      var firstBulletWords = firstBullet ? firstBullet.split(/\s+/).length : 0;
      var cvFamily = detectCvReviewFamily(
        capturedCvText,
        {},
        getProfileSectionItemsFromRawText(capturedCvText || "")
      );
      var crossDiscipline =
        getRoleFamilyTone() !== cvFamily &&
        cvFamily === "engineering" &&
        /^(investing|reporting|commercial|risk_ops)$/i.test(
          getRoleFamilyTone()
        );

      if (reviewHints && reviewHints.length) {
        reviewHints.slice(0, 2).forEach(function (hint) {
          items.push(hint);
        });
      }

      if (passiveFindings && passiveFindings.length) {
        items.push(
          buildAdvancedCommentaryNotes(
            passiveFindings[0] && passiveFindings[0].source,
            {
              section: "experience",
              isPrimary: true,
              roleSignals: roleSignals,
            }
          )[0] || buildPassiveReplacementNote(passiveFindings[0])
        );
      }

      if (crossDiscipline) {
        items.push(
          "This role is technically credible, but it is not naturally aligned to the target finance brief. Keep only the analytical evidence that can transfer."
        );
      } else if (roleSignals.length) {
        var missingSignals = roleSignals.filter(function (signal) {
          return (
            firstBulletLower.indexOf(cleanMessageText(signal).toLowerCase()) ===
            -1
          );
        });
        if (
          missingSignals.length &&
          firstBulletWords > 0 &&
          firstBulletWords <= 18 &&
          !extractQuantSignals(firstBullet).length
        ) {
          items.push(
            buildAdvancedCommentaryNotes(firstBullet, {
              section: "experience",
              isPrimary: true,
              roleSignals: missingSignals,
            })[0] ||
              "Bring " +
                formatNaturalList(missingSignals) +
                " into the opening bullet of this role."
          );
        }
      }

      if (
        sourceBullets &&
        sourceBullets.length > 1 &&
        !extractQuantSignals(sourceBullets.join(" ")).length
      ) {
        items.push(
          buildAdvancedCommentaryNotes(sourceBullets.join(" "), {
            section: "experience",
            isPrimary: false,
            roleSignals: roleSignals,
          })[0] ||
            "Add scale, value, or stakeholder numbers to the strongest bullet in this role."
        );
      }

      return dedupeList(items).slice(0, 3);
    }

    function isNoisyDraftReviewTitle(value) {
      var clean = cleanMessageText(value || "");
      var words = clean.split(/\s+/).filter(Boolean);
      if (!clean) {
        return true;
      }
      if (
        /^(?:contact|contact phone|phone|email|e-?mail|website|linkedin|address|references|personal details|profile|summary|work experience|professional experience|education|skills|languages)$/i.test(
          clean
        )
      ) {
        return true;
      }
      if (
        isCvContactLine(clean) ||
        looksLikeStandaloneLocationLine(clean) ||
        looksLikeCvPureDateRangeLine(clean) ||
        looksLikeCvTailoringEducationLine(clean) ||
        isCvTailoringKeywordSoup(clean)
      ) {
        return true;
      }
      if (
        words.length <= 5 &&
        /\b(?:matric|bsc|msc|mba|ba|ma|degree|university|college|school|certificate|certification)\b/i.test(
          clean
        )
      ) {
        return true;
      }
      return false;
    }

    function isNoisyDraftReviewLine(value) {
      var clean = cleanMessageText(stripCvBulletPrefix(value || ""));
      if (!clean) {
        return true;
      }
      if (
        isCvContactLine(clean) ||
        isCvReviewCommentLine(clean) ||
        getCvSectionMetaFromLine(clean) ||
        looksLikeStandaloneLocationLine(clean) ||
        looksLikeCvPureDateRangeLine(clean) ||
        looksLikeCvRoleMetaLine(clean) ||
        isCvTailoringKeywordSoup(clean) ||
        hasBrokenTailoredCvBulletSyntax(clean)
      ) {
        return true;
      }
      return false;
    }

    function isReviewableDraftEvidenceLine(value) {
      var clean = cleanMessageText(stripCvBulletPrefix(value || ""));
      var words = clean.split(/\s+/).filter(Boolean);
      if (!clean || words.length < 5 || clean.length > 340) {
        return false;
      }
      if (
        isNoisyDraftReviewLine(clean) ||
        isCvTailoringNarrativeProfileLine(clean) ||
        looksLikeCvRoleTitleLine(clean, "") ||
        looksLikeDetectedCompanyName(clean)
      ) {
        return false;
      }
      if (
        /^(?:profile|summary|professional summary|executive summary|contact|phone|email|website|linkedin|address)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      return (
        hasCvProfessionalActionSignal(clean) ||
        looksLikeCommercialCvImpactLine(clean) ||
        /\b(?:client|candidate|sourcing|recruitment|recruiting|legal|court|contract|advising|advised|consulting|briefing|drafting|filing|stakeholder|research|analysis|pipeline|business development|financial|investment|transaction|deal)\b/i.test(
          clean
        )
      );
    }

    function isSafeDraftRewriteExample(value, source) {
      var clean = cleanMessageText(value || "");
      var sourceClean = cleanMessageText(source || "");
      if (!clean || clean === sourceClean) {
        return false;
      }
      if (
        clean.split(/\s+/).length < 6 ||
        clean.length > 260 ||
        isCvTailoringNarrativeProfileLine(clean) ||
        hasBrokenTailoredCvBulletSyntax(clean) ||
        /\b(?:Delivered|Managed|Executed|Led|Prepared|Supported)\s+PROFILE\b/i.test(
          clean
        ) ||
        /\busing\s+(?:Delivered|Managed|Executed|Led|Prepared|Supported)\b/i.test(
          clean
        ) ||
        /\band the\.?$/i.test(clean) ||
        /\b(?:25 close-cycle|12 monthly|\$12\.5m|\$45m|100%|18%|20%)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      return true;
    }

    function buildAdditionalDraftSections(sections, analysis) {
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 3);
      var crossDiscipline = isCrossDisciplineReviewCase({
        cvFamily: detectCvReviewFamily(
          capturedCvText,
          buildCvHeaderModel(capturedCvText, sections),
          getProfileSectionItems(sections)
        ),
        reviewPrioritySkills: roleSignals,
      });
      var sectionOrder = {
        highlights: 1,
        skills: 2,
        education: 3,
        certifications: 4,
        awards: 5,
        extracurricular: 6,
        languages: 7,
        projects: 8,
        additional: 9,
      };

      function isAllowedReviewSection(key) {
        return /^(?:highlights|skills|education|certifications|awards|languages|projects)$/i.test(
          String(key || "")
        );
      }

      return (sections || [])
        .filter(function (section) {
          var key = String((section && section.key) || "").toLowerCase();
          return (
            key &&
            key !== "header" &&
            key !== "profile" &&
            key !== "experience" &&
            isAllowedReviewSection(key) &&
            !isNoisyDraftReviewTitle(section && section.title) &&
            (section.items || []).length
          );
        })
        .map(function (section) {
          var key = String((section && section.key) || "").toLowerCase();
          var items = dedupeList(
            (section.items || []).map(cleanMessageText).filter(function (line) {
              return !isNoisyDraftReviewLine(line);
            })
          );
          var passiveFindings = detectPassiveCvPhrases(items);
          var reviewItems = [];

          if (passiveFindings.length) {
            reviewItems.push(buildPassiveReplacementNote(passiveFindings[0]));
          }
          if (key === "highlights") {
            reviewItems = [];
          }
          if (key === "skills" && roleSignals.length && !crossDiscipline) {
            reviewItems.push(
              "Keep " +
                formatNaturalList(roleSignals) +
                " easy to spot in the skills section."
            );
          }
          if (key === "education") {
            reviewItems.push(
              "Keep the institution, qualification, and dates consistently formatted."
            );
          }
          if (key === "certifications") {
            reviewItems.push(
              "Keep certifications concise and directly relevant to the target role."
            );
          }
          if (key === "languages") {
            reviewItems.push(
              "Keep language proficiency clear and standardised."
            );
          }

          return {
            key: key,
            title: cleanMessageText(section.title || key),
            track: cleanMessageText(section.track || "main").toLowerCase(),
            items: items.slice(0, 12),
            reviewItems: dedupeList(reviewItems).slice(0, 2),
          };
        })
        .filter(function (section) {
          return (
            section.items.length &&
            !isNoisyDraftReviewTitle(section.title) &&
            (/^(?:skills|highlights)$/i.test(section.key) ||
              section.reviewItems.length > 0)
          );
        })
        .sort(function (a, b) {
          var aTrack = a.track === "sidebar" ? 0 : 1;
          var bTrack = b.track === "sidebar" ? 0 : 1;
          var aOrder = sectionOrder[a.key] || 99;
          var bOrder = sectionOrder[b.key] || 99;

          if (aTrack !== bTrack) {
            return aTrack - bTrack;
          }
          if (aOrder !== bOrder) {
            return aOrder - bOrder;
          }
          return a.title.localeCompare(b.title);
        });
    }

    function buildRoleBlockModel(entry, analysis, fallbackItems, isPrimary) {
      var meta = buildExperienceEntryMeta(entry);
      var sourceBullets = [];
      var sourceLines = ((entry && entry.lines) || [])
        .map(cleanMessageText)
        .filter(Boolean);
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 2);
      var reviewHints = extractEntryReviewHints(capturedCvText, entry);
      var passiveFindings;
      var rewrittenBullets = [];
      var introLine = "";
      var visibleLines;
      var cvFamily = detectCvReviewFamily(
        capturedCvText,
        {},
        getProfileSectionItemsFromRawText(capturedCvText || "")
      );
      var crossDiscipline =
        getRoleFamilyTone() !== cvFamily &&
        cvFamily === "engineering" &&
        /^(investing|reporting|commercial|risk_ops)$/i.test(
          getRoleFamilyTone()
        );

      if (entry && entry.bullets && entry.bullets.length) {
        sourceBullets = entry.bullets
          .map(stripCvBulletPrefix)
          .map(cleanMessageText)
          .filter(isReviewableDraftEvidenceLine)
          .slice(0, 3);
      } else {
        visibleLines = sourceLines.filter(function (line, index) {
          return (
            index > 0 &&
            line !== meta.metaLine &&
            !looksLikeCvRoleMetaLine(line) &&
            isReviewableDraftEvidenceLine(line)
          );
        });
        sourceBullets = visibleLines.slice(0, 3);
      }

      introLine =
        sourceLines.find(function (line, index) {
          return (
            index > 0 &&
            line !== meta.metaLine &&
            !looksLikeCvRoleMetaLine(line) &&
            !/^[\-\u2022]/.test(line) &&
            isReviewableDraftEvidenceLine(line)
          );
        }) || "";

      passiveFindings = detectPassiveCvPhrases(
        sourceBullets.concat(
          (fallbackItems || []).filter(isReviewableDraftEvidenceLine)
        )
      );

      sourceBullets.forEach(function (bullet) {
        var finding = passiveFindings.find(function (item) {
          return item.source === bullet;
        });
        var rewrite = "";
        if (finding) {
          rewrite = buildPassiveRewriteFromSource(finding);
          if (isSafeDraftRewriteExample(rewrite, bullet)) {
            rewrittenBullets.push(rewrite);
          } else {
            rewrittenBullets.push(bullet);
          }
        } else if (bullet) {
          rewrittenBullets.push(bullet);
        }
      });

      if (!rewrittenBullets.length && fallbackItems && fallbackItems.length) {
        rewrittenBullets = fallbackItems
          .map(stripCvBulletPrefix)
          .map(cleanMessageText)
          .filter(isReviewableDraftEvidenceLine)
          .slice(0, 3);
      }

      return {
        title: cleanMessageText(
          meta.heading || cvFacts.experienceTitle || "Relevant role"
        ),
        metaLine:
          meta.metaLine && meta.metaLine !== meta.heading ? meta.metaLine : "",
        introLine:
          introLine && introLine !== meta.heading && introLine !== meta.metaLine
            ? introLine
            : "",
        sourceBullets: sourceBullets.slice(0, 3),
        rewrittenBullets: dedupeList(rewrittenBullets).slice(0, 3),
        reviewItems: buildExperienceReviewItems(
          entry,
          analysis,
          reviewHints,
          passiveFindings,
          sourceBullets
        ),
      };
    }

    function buildLiveTailoringDraftModel(analysis, sections) {
      var confirmedSignals = getStatementSafeConfirmedSignals(analysis)
        .map(getSignalLabel)
        .filter(Boolean)
        .slice(0, 3);
      var roleSignals = getReviewPrioritySkills(analysis).slice(0, 2);
      var titleCompany = [cvFacts.experienceTitle, cvFacts.experienceCompany]
        .filter(Boolean)
        .join(" at ");
      var focusedEntry = pickRelevantExperienceEntry(analysis, sections);
      var focusedEntries = getExperienceEntries(sections);
      var focusedEntryMeta = buildExperienceEntryMeta(focusedEntry);
      var experienceSourceItems = getExperienceSourceItems(analysis, sections);
      var observationNotes = buildCvObservationNotes(capturedCvText, sections);
      var headerModel = buildCvHeaderModel(capturedCvText, sections);
      var profileSourceItems = getProfileSectionItems(sections);
      var profileItems = [];
      var entryHeading = cleanMessageText(focusedEntryMeta.heading);
      var passiveProfileFindings = detectPassiveCvPhrases(profileSourceItems);
      var passiveExperienceFindings = detectPassiveCvPhrases(
        ((focusedEntry && focusedEntry.bullets) || []).concat(
          experienceSourceItems || []
        )
      );
      var experienceBlocks = [];
      var additionalSections = [];
      var summaryReviewItems = [];
      var draftModel;

      if (!profileSourceItems.length) {
        profileSourceItems = getProfileSectionItemsFromRawText(
          capturedCvText || ""
        );
      }
      profileItems = profileSourceItems.length
        ? dedupeList(profileSourceItems).slice(0, 4)
        : buildTailoredExecutiveSummary(analysis, sections, headerModel, null);
      if (!profileItems.length) {
        if (titleCompany) {
          profileItems.push(
            "Results-driven " +
              cleanTargetRoleForSummary(roleTitle) +
              " with experience anchored around " +
              takeLeadingWords(titleCompany, 12) +
              "."
          );
        } else if (confirmedSignals.length) {
          profileItems.push(
            "Results-driven " +
              cleanTargetRoleForSummary(roleTitle) +
              " with visible strength across " +
              formatNaturalList(confirmedSignals.slice(0, 3)) +
              "."
          );
        } else {
          profileItems.push(
            "Results-driven " +
              cleanTargetRoleForSummary(roleTitle) +
              " with experience that is being sharpened for this role."
          );
        }
      }

      experienceBlocks = focusedEntries
        .map(function (entry, index) {
          return buildRoleBlockModel(
            entry,
            analysis,
            (entry && entry.bullets) || [],
            index === 0
          );
        })
        .filter(function (block) {
          return (
            block &&
            (block.rewrittenBullets.length ||
              block.sourceBullets.length ||
              block.title)
          );
        });

      if (!experienceBlocks.length) {
        experienceBlocks.push({
          title:
            entryHeading ||
            cleanMessageText(
              (analysis && analysis.experience_title) ||
                cvFacts.experienceTitle ||
                "Relevant role"
            ),
          metaLine: "",
          introLine: "",
          sourceBullets: [],
          rewrittenBullets: buildExperienceRewriteItems(
            analysis,
            focusedEntry,
            experienceSourceItems,
            []
          ).slice(0, 3),
          reviewItems: [
            "Bring the strongest evidence and role fit through more clearly in the first role block.",
          ],
        });
      }

      additionalSections = buildAdditionalDraftSections(sections, analysis);

      draftModel = {
        observation:
          observationNotes[0] ||
          "Emily is tightening the opening profile and the first relevant experience line.",
        observationNotes: observationNotes.length
          ? observationNotes
          : ["No major header issues have surfaced in this pass yet."],
        highlightTerms: dedupeList(
          roleSignals
            .concat(confirmedSignals)
            .concat(getPassiveReplacementTerms(passiveProfileFindings))
            .concat(getPassiveReplacementTerms(passiveExperienceFindings))
            .concat(extractQuantSignals(profileSourceItems.join(" ")))
            .concat(
              experienceBlocks.reduce(function (list, block) {
                return list
                  .concat(block.sourceBullets || [])
                  .concat(block.rewrittenBullets || [])
                  .concat(
                    extractQuantSignals((block.sourceBullets || []).join(" "))
                  )
                  .concat(
                    extractQuantSignals(
                      (block.rewrittenBullets || []).join(" ")
                    )
                  );
              }, [])
            )
            .concat(
              additionalSections.reduce(function (list, section) {
                return list.concat(section.items || []);
              }, [])
            )
        ).slice(0, 24),
        profileItems: dedupeList(profileItems).slice(0, 4),
        summaryReviewItems: summaryReviewItems,
        experienceBlocks: experienceBlocks,
        additionalSections: additionalSections,
        experienceSectionTitle:
          entryHeading ||
          cleanMessageText(
            (analysis && analysis.experience_title) ||
              cvFacts.experienceTitle ||
              "Relevant experience"
          ),
        focusedEntry: focusedEntry,
        focusedEntryMeta: focusedEntryMeta,
        headerModel: headerModel,
        cvFamily: detectCvReviewFamily(
          capturedCvText,
          headerModel,
          profileItems
        ),
        reviewPrioritySkills: getReviewPrioritySkills(analysis),
        originalExperienceBullet: getFocusedEntryOriginalBullet(
          focusedEntry,
          experienceSourceItems
        ),
        passiveProfileFindings: passiveProfileFindings,
        passiveExperienceFindings: passiveExperienceFindings,
      };
      summaryReviewItems = buildSummaryReviewItems(draftModel);
      draftModel.summaryReviewItems = summaryReviewItems;
      return draftModel;
    }

    function buildReviewIssueCounts(draftModel) {
      var headerItems = (draftModel.observationNotes || []).filter(Boolean);
      var summaryItems = (draftModel.summaryReviewItems || []).filter(Boolean);
      var experienceCount = (draftModel.experienceBlocks || []).reduce(
        function (count, block) {
          return (
            count +
            ((block && block.reviewItems ? block.reviewItems.length : 0) || 0)
          );
        },
        0
      );
      var supportingCount = (draftModel.additionalSections || []).reduce(
        function (count, section) {
          return (
            count +
            ((section && section.reviewItems
              ? section.reviewItems.length
              : 0) || 0)
          );
        },
        0
      );
      var passiveCount =
        (draftModel.passiveProfileFindings || []).length +
        (draftModel.passiveExperienceFindings || []).length;
      var counts = [];

      if (headerItems.length) {
        counts.push(Math.min(headerItems.length, 4) + " header issues");
      }
      if (summaryItems.length) {
        counts.push(Math.min(summaryItems.length, 4) + " summary issues");
      }
      if (experienceCount) {
        counts.push(Math.min(experienceCount, 6) + " experience fixes");
      }
      if (supportingCount) {
        counts.push(Math.min(supportingCount, 4) + " supporting section fixes");
      }
      if (passiveCount) {
        counts.push(Math.min(passiveCount, 4) + " wording issues");
      }

      return dedupeList(counts).slice(0, 5);
    }

    function buildReviewScore(draftModel, analysis) {
      var score = 58;
      var confirmedCount = getStatementSafeConfirmedSignals(analysis).length;
      var roleSignalCount = (draftModel.reviewPrioritySkills || []).length;
      var quantCount = extractQuantSignals(capturedCvText || "").length;
      var hasEmail = !!(draftModel.headerModel && draftModel.headerModel.email);
      var hasPhone = !!(draftModel.headerModel && draftModel.headerModel.phone);
      var hasLinkedin = !!(
        draftModel.headerModel && draftModel.headerModel.linkedin
      );
      var hasLocation = !!(
        draftModel.headerModel && draftModel.headerModel.location
      );
      var passiveCount =
        (draftModel.passiveProfileFindings || []).length +
        (draftModel.passiveExperienceFindings || []).length;
      var issueCount = buildReviewIssueCounts(draftModel).length;

      score += Math.min(12, confirmedCount * 3);
      score += Math.min(10, roleSignalCount * 2);
      score += Math.min(8, quantCount * 2);
      if (hasEmail) {
        score += 3;
      }
      if (hasPhone) {
        score += 2;
      }
      if (hasLinkedin) {
        score += 3;
      } else {
        score -= 3;
      }
      if (hasLocation) {
        score += 2;
      } else {
        score -= 2;
      }
      score -= Math.min(8, passiveCount * 2);
      score -= Math.min(6, issueCount);
      if (isCrossDisciplineReviewCase(draftModel)) {
        score -= 12;
      }

      return Math.max(52, Math.min(92, Math.round(score)));
    }

    function buildReviewHeroCallout(score, analysis, draftModel) {
      var roleSignals = (
        (draftModel && draftModel.reviewPrioritySkills) ||
        []
      ).slice(0, 2);
      var signalText = roleSignals.length
        ? formatNaturalList(roleSignals)
        : "the target role";
      var fitConfidence = getReviewFitConfidence(draftModel, analysis);

      if (isCrossDisciplineReviewCase(draftModel)) {
        return "This CV is coming from a different discipline. The main issue is not formatting alone. The role fit is weak, so the first question is whether the application story is genuinely credible for this move.";
      }

      if (fitConfidence === "strong") {
        return (
          "This CV already has strong raw material. The main job is to tighten the positioning and make the most relevant evidence for " +
          signalText +
          " easier to spot immediately."
        );
      }
      if (fitConfidence === "borderline") {
        return (
          "This CV is credible, but the story is still doing too much work. The evidence is there. The positioning, ordering, and wording are not yet sharp enough for " +
          signalText +
          "."
        );
      }
      return "There is some transferable material here, but the CV is not yet making a direct case for the role. The main priority is to surface the most relevant evidence honestly and stop the rest from diluting it.";
    }

    function looksLikeExtracurricularCvLine(line) {
      var clean = cleanMessageText(line || "");
      if (!clean) {
        return false;
      }
      return /\b(?:society|club|treasurer|student|student ambassador|student representative|choir|graduation ceremony|sports leaders?|duke of edinburgh|waitress|barista|cashier|volunteer|volunteering|captain|member of the|boxing club|basketball|swimming|cycling|traveller|traveler|hobbies?|interests?)\b/i.test(
        clean
      );
    }

    function looksLikeCommercialCvImpactLine(line) {
      var clean = cleanMessageText(line || "");
      if (!clean) {
        return false;
      }
      if (looksLikeExtracurricularCvLine(clean)) {
        return false;
      }
      return /\b(?:finance|financial|accounting|audit|tax|treasury|report|reporting|forecast|budget|variance|reconciliation|ledger|close|invoice|accounts payable|accounts receivable|payment|payroll|erp|oracle|sap|excel|power bi|dashboard|valuation|model|modelling|modeling|transaction|deal|due diligence|portfolio|investment|equity|credit|risk|compliance|control|cash flow|stakeholder|client|vendor|supplier|operations|process|automation|kpi|board|committee|fund|bank)\b/i.test(
        clean
      );
    }

    function looksLikeQuantifiableCvLine(line) {
      var clean = cleanMessageText(line || "");
      if (!clean || clean.length < 24) {
        return false;
      }
      if (
        hasCvDateRange(clean) ||
        isCvContactLine(clean) ||
        looksLikeCvRoleMetaLine(clean) ||
        isLikelyCvSectionHeading(clean)
      ) {
        return false;
      }
      if (
        /^(?:email|contact|address|skype|linkedin|visa status|organization|designation|tenure|profile summary|core strengths|key skills|responsibilities)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (
        /\b(?:diploma|award|bronze|silver|gold award|sports leaders|duke of edinburgh|languages?|bulgarian|english|spanish|modules include|dissertation|university of|bsc|msc|a-levels?)\b/i.test(
          clean
        )
      ) {
        return false;
      }
      if (!looksLikeCommercialCvImpactLine(clean)) {
        return false;
      }
      return /\b(?:responsible for|supported|prepared|managed|maintained|handled|assisted|conducted|developed|performed|ensuring|recording|generating|reviewing|analysing|analyzing|collaborating|led|built|created|delivered)\b/i.test(
        clean
      );
    }

    function collectQuantificationCandidates(draftModel) {
      var source = [];
      source = source
        .concat(
          (draftModel.experienceBlocks || []).reduce(function (list, block) {
            if (looksLikeExtracurricularCvLine((block && block.title) || "")) {
              return list;
            }
            return list
              .concat(block && block.introLine ? [block.introLine] : [])
              .concat((block && block.sourceBullets) || []);
          }, [])
        )
        .concat(
          (draftModel.additionalSections || []).reduce(function (
            list,
            section
          ) {
            if (
              !/^(projects|highlights)$/i.test(
                String((section && section.key) || "")
              )
            ) {
              return list;
            }
            if (
              looksLikeExtracurricularCvLine((section && section.title) || "")
            ) {
              return list;
            }
            return list.concat((section && section.items) || []);
          },
          [])
        );

      return dedupeList(source.map(cleanMessageText).filter(Boolean))
        .filter(function (line) {
          return (
            isReviewableDraftEvidenceLine(line) &&
            looksLikeQuantifiableCvLine(line) &&
            !extractQuantSignals(line).length
          );
        })
        .slice(0, 3);
    }

    function formatSentenceCase(text) {
      var clean = cleanMessageText(text || "");
      if (!clean) {
        return "";
      }
      return clean.charAt(0).toUpperCase() + clean.slice(1);
    }

    function buildQuantifiedRewriteSuggestion(line) {
      var clean = cleanMessageText(line || "")
        .replace(/^[•❖▪◦■□‣\-–—\*]+\s*/, "")
        .replace(
          /^(?:responsible for|responsibilities include|key deliverables:?|supported and played vital role in|supported|assisted with|worked on|involved in|preparation of)\s+/i,
          ""
        )
        .replace(/\.$/, "")
        .trim();
      var core = "";
      var lead = "Led";
      var lower;

      if (!clean) {
        return "";
      }

      lower = clean.toLowerCase();
      if (
        !isReviewableDraftEvidenceLine(clean) ||
        !looksLikeCommercialCvImpactLine(clean) ||
        looksLikeExtracurricularCvLine(clean)
      ) {
        return "";
      }

      function sentence(text) {
        return escapeHtml(formatSentenceCase(text).replace(/\s+/g, " ").trim());
      }

      function stripLeadingVerb(text) {
        return cleanMessageText(text || "")
          .replace(
            /^(?:to\s+)?(?:prepare|preparing|prepared|maintain|maintaining|managed|manage|handling|handled|handle|supporting|supported|support|assisting|assisted|assist|conducting|conducted|conduct|developing|developed|develop|performing|performed|perform|ensuring|ensured|ensure|recording|recorded|record|generating|generated|generate|reviewing|reviewed|review|analysing|analyzing|analysed|analyzed|analyse|analyze|collaborating|collaborated|collaborate)\s+/i,
            ""
          )
          .trim();
      }

      if (
        /\b(?:budget|forecast|report|reporting|variance|financial statements|management accounts)\b/i.test(
          lower
        )
      ) {
        core = stripLeadingVerb(clean);
        return sentence(
          "Prepared " +
            core +
            ", adding the real reporting cadence, scope, and business decision supported."
        );
      }

      if (
        /\b(?:reconciliation|reconciling|close|month end|month-end|ledger|gl|balance sheet|audit|compliance)\b/i.test(
          lower
        )
      ) {
        core = stripLeadingVerb(clean);
        return sentence(
          "Delivered " +
            core +
            ", stating the actual control scope, reporting period, and outcome achieved."
        );
      }

      if (/\b(?:erp|system|automation|implementation|process)\b/i.test(lower)) {
        core = stripLeadingVerb(clean);
        return sentence(
          "Led " +
            core +
            ", making the system, process scope, and measurable efficiency outcome explicit."
        );
      }

      if (
        /\b(?:investor|portfolio|transaction|deal|due diligence|valuation|model|modelling|modeling)\b/i.test(
          lower
        )
      ) {
        core = stripLeadingVerb(clean);
        return sentence(
          "Supported " +
            core +
            ", adding the actual transaction count, value, stakeholder audience, or decision supported."
        );
      }

      if (
        /\b(?:vendor|supplier|payment|invoice|accounts payable|accounts receivable|bank facilities|payroll)\b/i.test(
          lower
        )
      ) {
        core = stripLeadingVerb(clean);
        return sentence(
          "Managed " +
            core +
            ", specifying the real transaction volume, cash value, and turnaround improvement."
        );
      }

      if (/^(?:supported|assisted)\b/i.test(lower)) {
        lead = "Supported";
      } else if (/^(?:prepared|preparing)\b/i.test(lower)) {
        lead = "Prepared";
      } else if (
        /^(?:managed|manage|maintained|maintaining|handled|handling)\b/i.test(
          lower
        )
      ) {
        lead = "Managed";
      }

      core = stripLeadingVerb(clean);
      if (!core || core.split(/\s+/).length < 4) {
        return "";
      }

      return sentence(
        lead +
          " " +
          core +
          ", adding the real scale, stakeholder group, and result so the bullet reads as evidence rather than a task."
      );
    }

    function buildHtmlExcerptBox(label, lines, modifier) {
      var list = dedupeList(
        (lines || [])
          .map(function (item) {
            return String(item || "").trim();
          })
          .filter(function (item) {
            return cleanMessageText(item).length > 0;
          })
      ).slice(0, 3);

      if (!list.length) {
        return "";
      }

      return (
        '<div class="sffc-crm-apply-chat__draft-report-example' +
        (modifier ? " is-" + modifier : "") +
        '">' +
        (label
          ? '<span class="sffc-crm-apply-chat__draft-report-example-label">' +
            escapeHtml(label) +
            "</span>"
          : "") +
        list
          .map(function (line) {
            return "<p>" + line + "</p>";
          })
          .join("") +
        "</div>"
      );
    }

    function detectRepeatedCvTerms(lines) {
      var counts = {};
      var stop = {
        and: true,
        the: true,
        with: true,
        for: true,
        from: true,
        role: true,
        team: true,
        financial: true,
        finance: true,
        experience: true,
        management: true,
        professional: true,
      };
      (lines || []).forEach(function (line) {
        cleanMessageText(line || "")
          .toLowerCase()
          .split(/[^a-z0-9]+/)
          .forEach(function (word) {
            if (!word || word.length < 5 || stop[word]) {
              return;
            }
            counts[word] = (counts[word] || 0) + 1;
          });
      });
      return Object.keys(counts)
        .filter(function (word) {
          return counts[word] >= 4;
        })
        .sort(function (a, b) {
          return counts[b] - counts[a];
        })
        .slice(0, 3);
    }

    function detectGrammarRepetitionFormatNotes(draftModel) {
      var notes = [];
      var lines = dedupeList(
        (capturedCvText || "")
          .split(/\n+/)
          .map(cleanMessageText)
          .filter(Boolean)
      );
      var repeatedTerms = detectRepeatedCvTerms(lines.slice(0, 80));
      var lowerCaseSentence = lines.find(function (line) {
        return /^[a-z]/.test(line) && line.split(/\s+/).length >= 6;
      });
      var mergedWordLine = lines.find(function (line) {
        return hasProblematicCvMergedWordLine(line);
      });
      var oldStyleObjective = lines.find(function (line) {
        return /^(?:objective|career objective)\b/i.test(line);
      });
      var bulletSoupLine = lines.find(function (line) {
        return (
          (line.match(/[,*•❖▪◦]/g) || []).length >= 3 ||
          /\bprofile summary:skills\b/i.test(line)
        );
      });
      var multiColumnDetected =
        (capturedCvText || "").indexOf("__SFFC_CV_SIDEBAR__") !== -1 ||
        lines.some(function (line) {
          return /\b(?:core strengths|key skills|profile summary:skills|skills & competencies)\b/i.test(
            line
          );
        });

      if (repeatedTerms.length) {
        notes.push(
          "The top of the CV repeats " +
            formatNaturalList(repeatedTerms) +
            " too often without adding new proof."
        );
      }
      if (lowerCaseSentence) {
        notes.push(
          "Some profile lines start weakly or inconsistently. Tighten the sentence case and opening phrasing."
        );
      }
      if (mergedWordLine) {
        notes.push(
          "There are merged words or OCR-style spacing issues. Clean those before sending the CV out."
        );
      }
      if (bulletSoupLine) {
        notes.push(
          "Some sections are packed into keyword-heavy or symbol-heavy blocks. Split them into cleaner bullets or shorter lines."
        );
      }
      if (oldStyleObjective) {
        notes.push(
          "The CV still uses an old-style objective statement. Replace it with a short professional summary tied to the role."
        );
      }
      if (multiColumnDetected) {
        notes.push(
          "This looks like a multi-column or matrix-style CV. For most finance hiring, a single-column layout is easier to scan and safer for ATS parsing."
        );
      }
      if (!notes.length) {
        notes.push(
          "Formatting is broadly workable, but line discipline and consistency can still be tightened."
        );
      }

      return notes.slice(0, 4);
    }

    function buildAdditionalChecksNotes(draftModel) {
      var notes = [];
      var extension = "";
      var fileName = "";
      if (currentCvFile && currentCvFile.name) {
        var match = String(currentCvFile.name).match(/\.([a-z0-9]+)$/i);
        fileName = String(currentCvFile.name);
        extension = match ? match[1].toLowerCase() : "";
      }

      if (extension === "pdf") {
        notes.push(
          "File type is PDF, which is the safest format for most applications."
        );
      } else if (extension) {
        notes.push(
          "Current file type is ." +
            extension +
            ". Export the final CV as a PDF before applying."
        );
      } else {
        notes.push(
          "File type is not obvious. Use a clearly named PDF for the final application."
        );
      }

      if (currentCvPageCount > 2) {
        notes.push(
          "This CV runs to " +
            currentCvPageCount +
            " pages. Trim it to 2 pages unless the role clearly justifies more."
        );
      } else if (currentCvPageCount > 0) {
        notes.push(
          "Page count is " +
            currentCvPageCount +
            ", which is within the normal range."
        );
      } else {
        notes.push(
          "Page count could not be confirmed from the current file preview."
        );
      }

      if (fileName && /[\s()'"]/g.test(fileName)) {
        notes.push(
          "Rename the final file to something cleaner like FirstName_LastName_CV.pdf before applying."
        );
      }

      if (!(draftModel.headerModel && draftModel.headerModel.linkedin)) {
        notes.push(
          "LinkedIn is not clearly visible near the header. Add it if it is current and credible."
        );
      }

      return notes.slice(0, 4);
    }

    function countSharedSignificantWords(sourceA, sourceB) {
      var stopWords = {
        and: true,
        the: true,
        for: true,
        with: true,
        from: true,
        role: true,
        analyst: true,
        associate: true,
        manager: true,
        senior: true,
        junior: true,
        finance: true,
        financial: true,
        investment: true,
      };
      var left = dedupeList(
        cleanMessageText(sourceA || "")
          .toLowerCase()
          .split(/[^a-z0-9]+/)
          .filter(function (word) {
            return word && word.length > 2 && !stopWords[word];
          })
      );
      var right = dedupeList(
        cleanMessageText(sourceB || "")
          .toLowerCase()
          .split(/[^a-z0-9]+/)
          .filter(function (word) {
            return word && word.length > 2 && !stopWords[word];
          })
      );

      if (!left.length || !right.length) {
        return 0;
      }

      return left.filter(function (word) {
        return right.indexOf(word) !== -1;
      }).length;
    }

    function getReviewStatusLabel(score) {
      if (score >= 82) {
        return "Strong";
      }
      if (score >= 70) {
        return "Needs Tightening";
      }
      return "Weak Signal";
    }

    function getReviewStatusTone(score) {
      if (score >= 82) {
        return "good";
      }
      if (score >= 70) {
        return "warn";
      }
      return "bad";
    }

    function buildQuickScanBar(item) {
      var tone = item && item.tone ? item.tone : "good";
      var percent = Math.max(
        0,
        Math.min(100, Number(item && item.percent) || 0)
      );
      return (
        '<article class="sffc-crm-apply-chat__draft-quick-scan-item is-' +
        escapeHtml(tone) +
        '">' +
        '<div class="sffc-crm-apply-chat__draft-quick-scan-label-row">' +
        "<strong>" +
        escapeHtml(item.label || "") +
        "</strong>" +
        "<span>" +
        escapeHtml(item.status || "") +
        "</span>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__draft-quick-scan-bar">' +
        '<span class="sffc-crm-apply-chat__draft-quick-scan-fill" style="width:' +
        escapeHtml(String(percent)) +
        '%"></span>' +
        "</div>" +
        "<p>" +
        escapeHtml(item.note || "") +
        "</p>" +
        "</article>"
      );
    }

    function buildAtsScoreInline(score, tone) {
      var percent = Math.max(0, Math.min(100, Number(score) || 0));
      return (
        '<div class="sffc-crm-apply-chat__draft-ats-score is-' +
        escapeHtml(tone || "warn") +
        '">' +
        '<span class="sffc-crm-apply-chat__draft-ats-score-label">ATS Score</span>' +
        '<div class="sffc-crm-apply-chat__draft-ats-score-track">' +
        '<span class="sffc-crm-apply-chat__draft-ats-score-fill" style="width:' +
        escapeHtml(String(percent)) +
        '%"></span>' +
        "</div>" +
        '<strong class="sffc-crm-apply-chat__draft-ats-score-value">' +
        escapeHtml(String(percent)) +
        "%</strong>" +
        "</div>"
      );
    }

    function buildReviewQuickScanItems(draftModel, analysis, score) {
      var matchedKeywords = dedupeList(
        (analysis && analysis.matched_keywords) || []
      );
      var missingKeywords = dedupeList(
        (analysis && analysis.missing_keywords) || []
      );
      var roleKeywords = dedupeList(matchedKeywords.concat(missingKeywords));
      var allConfirmedSignals = getStatementSafeConfirmedSignals(analysis);
      var adjacentSignals = getAdjacentProofSignals(analysis);
      var skillSignals = getSignalsByCategory(
        allConfirmedSignals.concat(adjacentSignals),
        ["hard_skill", "experience_background", "sector_exposure"]
      );
      var skillTotal = Math.max(skillSignals.length, roleKeywords.length, 1);
      var skillFound = Math.min(
        skillTotal,
        dedupeList(skillSignals.map(getSignalLabel).filter(Boolean)).length
      );
      var qualificationSignals = dedupeList(
        getSignalsByCategory(
          ((analysis && analysis.confirmed_signals) || []).concat(
            (analysis && analysis.unconfirmed_signals) || []
          ),
          ["qualification", "credential"]
        )
          .map(getSignalLabel)
          .filter(Boolean)
      );
      var qualificationGaps = (
        (analysis && analysis.requirement_gaps) ||
        []
      ).filter(function (gap) {
        return gap && gap.type === "qualification";
      });
      var qualificationTotal = Math.max(
        qualificationSignals.length,
        qualificationGaps.length,
        1
      );
      var qualificationFound = Math.max(
        0,
        qualificationTotal - qualificationGaps.length
      );
      var experienceBlocks = draftModel.experienceBlocks || [];
      var usableExperienceCount = experienceBlocks.filter(function (block) {
        return (
          block &&
          ((block.sourceBullets && block.sourceBullets.length) ||
            (block.rewrittenBullets && block.rewrittenBullets.length))
        );
      }).length;
      var experienceTotal = Math.max(
        Math.min(experienceBlocks.length || 0, 4),
        1
      );
      var headerModel = draftModel.headerModel || {};
      var headerHeadline = headerModel.headline || "";
      var headlineWordsMatched = countSharedSignificantWords(
        roleTitle || "",
        headerHeadline
      );
      var topRoleText = [
        cvFacts.experienceTitle,
        headerHeadline,
        draftModel.experienceSectionTitle,
      ]
        .filter(Boolean)
        .join(" ");
      var titleWordsMatched = countSharedSignificantWords(
        roleTitle || "",
        topRoleText
      );
      var titlePercent = Math.max(
        8,
        Math.min(
          100,
          Math.round(
            ((headlineWordsMatched + titleWordsMatched) /
              Math.max(
                2,
                cleanMessageText(roleTitle || "").split(/\s+/).length - 1
              )) *
              100
          )
        )
      );
      var titleStatus =
        titlePercent >= 80
          ? "Full Match"
          : titlePercent >= 52
          ? "Partial Match"
          : "Weak Match";
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);

      return [
        {
          label: "Skills",
          status: "Found " + skillFound + " of " + skillTotal,
          percent: Math.round((skillFound / Math.max(1, skillTotal)) * 100),
          tone: crossDiscipline
            ? "bad"
            : skillFound >= Math.max(2, Math.ceil(skillTotal * 0.55))
            ? "good"
            : skillFound >= 1
            ? "warn"
            : "bad",
          note: crossDiscipline
            ? "The CV is not currently signalling finance-relevant strengths strongly enough for this role."
            : skillFound >= Math.max(2, Math.ceil(skillTotal * 0.55))
            ? "Relevant strengths are present, but the best ones should be easier to scan."
            : "Core role skills are either buried or not being stated clearly enough.",
        },
        {
          label: "Qualifications",
          status: qualificationGaps.length
            ? qualificationGaps.length +
              " missing requirement" +
              (qualificationGaps.length > 1 ? "s" : "")
            : "Requirements visible",
          percent: Math.round(
            (qualificationFound / Math.max(1, qualificationTotal)) * 100
          ),
          tone: qualificationGaps.length ? "warn" : "good",
          note: qualificationGaps.length
            ? "Qualification gaps or missing mentions need to be handled explicitly."
            : "Core qualification requirements appear to be covered or supportable.",
        },
        {
          label: "Experience",
          status: crossDiscipline
            ? "Different domain"
            : usableExperienceCount >= Math.min(2, experienceTotal)
            ? "Strong evidence blocks"
            : "Needs stronger bullets",
          percent: Math.round(
            (usableExperienceCount / Math.max(1, experienceTotal)) * 100
          ),
          tone: crossDiscipline
            ? "warn"
            : usableExperienceCount >= Math.min(2, experienceTotal)
            ? "good"
            : usableExperienceCount
            ? "warn"
            : "bad",
          note: crossDiscipline
            ? "The experience itself may be strong, but it is not naturally aligned to the finance brief."
            : usableExperienceCount >= Math.min(2, experienceTotal)
            ? "There is real experience here. The main job is selecting and surfacing it properly."
            : "The experience section needs sharper action-result bullets and clearer commercial proof.",
        },
        {
          label: "Relevant Keywords",
          status:
            "Found " +
            matchedKeywords.length +
            " of " +
            Math.max(1, roleKeywords.length),
          percent: Math.round(
            (matchedKeywords.length / Math.max(1, roleKeywords.length)) * 100
          ),
          tone: crossDiscipline
            ? "bad"
            : matchedKeywords.length >=
              Math.max(2, Math.ceil(roleKeywords.length * 0.5))
            ? "good"
            : matchedKeywords.length
            ? "warn"
            : "bad",
          note: crossDiscipline
            ? "The CV language is not yet mapping convincingly to the core finance requirements."
            : matchedKeywords.length >=
              Math.max(2, Math.ceil(roleKeywords.length * 0.5))
            ? "Keyword coverage is workable, but the strongest ones should sit higher up."
            : "The CV is not yet signalling enough of the role language quickly enough.",
        },
      ];
    }

    function buildReviewScoreChips(draftModel, analysis, score) {
      var roleSignals = (draftModel.reviewPrioritySkills || []).length;
      var quantCount = extractQuantSignals(capturedCvText || "").length;
      var passiveCount =
        (draftModel.passiveProfileFindings || []).length +
        (draftModel.passiveExperienceFindings || []).length;
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);
      var chips = [
        {
          label: "Positioning",
          value: Math.max(55, Math.min(92, score - 4)) + "%",
          note: crossDiscipline
            ? "The opening needs to explain the discipline switch credibly."
            : roleSignals
            ? "Role signals are visible, but they need clearer prioritisation."
            : "The opening positioning needs tightening.",
        },
        {
          label: "Content Quality",
          value: Math.max(58, Math.min(94, score + 4)) + "%",
          note: quantCount
            ? "There is measurable experience here. It needs cleaner presentation."
            : "The experience needs clearer evidence and scale.",
        },
        {
          label: "Formatting",
          value: Math.max(50, Math.min(90, score - passiveCount)) + "%",
          note: "Section structure and line discipline need to feel more controlled.",
        },
        {
          label: "Role Fit Signal",
          value:
            Math.max(52, Math.min(93, score + (roleSignals ? 2 : -3))) + "%",
          note: crossDiscipline
            ? "The current CV reads as a different profession."
            : roleSignals
            ? "The CV can make the case, but not yet quickly enough."
            : "The fit story needs to be made explicit.",
        },
      ];

      return chips;
    }

    function buildReviewActionCards(draftModel, analysis) {
      var headerModel = draftModel.headerModel || {};
      var roleSignals = (draftModel.reviewPrioritySkills || []).slice(0, 3);
      var focusedExperience = (draftModel.experienceBlocks || [])[0] || {};
      var currentSummary = (draftModel.profileItems || []).slice(0, 2);
      var currentProof = dedupeList(
        [focusedExperience.introLine].concat(
          focusedExperience.sourceBullets || []
        )
      )
        .filter(Boolean)
        .slice(0, 2);
      var rewrittenProof = (focusedExperience.rewrittenBullets || [])
        .filter(Boolean)
        .slice(0, 1);
      var cards = [];
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);

      cards.push({
        tone: "bad",
        title: "Fix First",
        kicker: "Header and positioning",
        note: crossDiscipline
          ? "The opening currently reads as " +
            cleanMessageText(headerModel.headline || "a different profession") +
            ". If you target this role, the first screen needs to explain the transition credibly."
          : roleSignals.length
          ? "Make " +
            formatNaturalList(roleSignals) +
            " visible in the first screenful of the CV."
          : "Clarify the target role and the value proposition immediately in the header and summary.",
        excerpts: buildExcerptBox(
          "Needs update",
          [buildCurrentHeaderExcerpt(headerModel)]
            .concat(currentSummary)
            .filter(Boolean)
            .slice(0, 2),
          "problem"
        ),
        examples: "",
      });

      cards.push({
        tone: "warn",
        title: "Strengthen",
        kicker: "Evidence and bullets",
        note: crossDiscipline
          ? "Only keep experience that can be translated into analytical relevance. Remove or demote the rest."
          : "Replace vague duty-led lines with action, scale, and commercial outcome.",
        excerpts: buildExcerptBox("Needs update", currentProof, "problem"),
        examples: buildExcerptBox(
          "Rewrite direction",
          rewrittenProof,
          "rewrite"
        ),
      });

      cards.push({
        tone: "good",
        title: "Keep",
        kicker: "Credible material already present",
        note: "Do not rewrite everything. Keep the real proof and just move it higher, tighten it, and connect it to the role.",
        excerpts: buildExcerptBox(
          "Worth keeping",
          (draftModel.highlightTerms || []).slice(0, 3),
          "keep"
        ),
        examples: "",
      });

      return cards
        .map(function (card) {
          return (
            '<article class="sffc-crm-apply-chat__draft-action-card is-' +
            escapeHtml(card.tone) +
            '">' +
            '<div class="sffc-crm-apply-chat__draft-action-card-head">' +
            '<span class="sffc-crm-apply-chat__draft-action-card-kicker">' +
            escapeHtml(card.kicker) +
            "</span>" +
            "<strong>" +
            escapeHtml(card.title) +
            "</strong>" +
            "</div>" +
            "<p>" +
            escapeHtml(card.note) +
            "</p>" +
            (card.excerpts || "") +
            (card.examples || "") +
            "</article>"
          );
        })
        .join("");
    }

    function buildReviewDiagnosticCards(draftModel, analysis) {
      var quantLines = collectQuantificationCandidates(draftModel);
      var quantRewrites = quantLines
        .map(buildQuantifiedRewriteSuggestion)
        .filter(Boolean);
      var cards = [];
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);

      cards.push(
        buildReviewSectionCard("Quantifying Outcomes", {
          intro: crossDiscipline
            ? "Even in a cross-discipline application, the strongest transferable bullets should show impact with numbers."
            : "Every strong finance CV should show impact with numbers. These lines are currently too qualitative.",
          excerpts: quantLines.length
            ? quantLines
            : [
                "The current bullets are not using enough scale, value, or time-based proof.",
              ],
          excerptLabel: "Before",
          excerptTone: "problem",
          notes: quantLines.length
            ? [
                "Add hard numbers to the best bullets first: values, percentages, stakeholder counts, or reporting cadence.",
              ]
            : ["The strongest bullets still need harder numerical proof."],
          solutions: [
            "Add numbers to the strongest bullets first: values, percentages, stakeholder counts, or monthly cadence.",
            "Quantify the outcome, not just the task.",
            "Prioritise work bullets over education or certificate lines.",
          ],
          tone: "bad",
        })
      );

      cards.push(
        '<article class="sffc-crm-apply-chat__draft-review-card is-warn">' +
          '<div class="sffc-crm-apply-chat__draft-review-card-head">' +
          "<h4>Suggested Rewrites</h4>" +
          '<button type="button" class="sffc-crm-apply-chat__draft-section-adjust" aria-label="Adjust suggested rewrites">Adjust</button>' +
          "</div>" +
          "<p>" +
          escapeHtml(
            crossDiscipline
              ? "Use real numbers where the CV supports them. Do not overstate finance experience or add metrics that are not evidenced."
              : "Use real numbers where the CV supports them. The examples below show structure only; they do not invent values."
          ) +
          "</p>" +
          buildSolutionBox("How to fix it", [
            "Take the strongest current bullet, replace weak openings, and add a measurable result.",
            "Add only figures the candidate can evidence: deal value, portfolio size, stakeholder count, cadence, or conversion result.",
            "Keep the rewrite grounded in what the CV already proves.",
          ]) +
          buildHtmlExcerptBox(
            "Rewrite direction",
            quantRewrites.length
              ? quantRewrites
              : [
                  escapeHtml(
                    "Add real numbers to the main work-experience bullets so the impact is measurable, not implied."
                  ),
                ],
            "rewrite"
          ) +
          "</article>"
      );

      cards.push(
        buildReviewSectionCard("Grammar, Repetition & Format", {
          intro:
            "The CV should read cleanly in one pass. Repetition, merged words, and layout friction slow the reader down.",
          notes: detectGrammarRepetitionFormatNotes(draftModel),
          solutions: [
            "Remove repeated terms that do not add new proof.",
            "Split dense blocks into short bullets or shorter lines.",
            "If the CV is multi-column, convert it to a single-column layout for easier scanning.",
          ],
          tone: "warn",
        })
      );

      cards.push(
        buildReviewSectionCard("Additional Checks", {
          intro:
            "These are low-effort checks that still affect how the CV lands.",
          notes: buildAdditionalChecksNotes(draftModel),
          solutions: [
            "Save the final file as a cleanly named PDF.",
            "Keep the CV to two pages unless the target role genuinely justifies more.",
            "Make sure core contact details and LinkedIn are visible at the top.",
          ],
          tone: "warn",
        })
      );

      return cards.filter(Boolean).join("");
    }

    function buildPriorityFixes(draftModel, analysis) {
      var fixes = [];
      var roleSignals = (draftModel.reviewPrioritySkills || []).slice(0, 3);
      var summaryItems = (draftModel.summaryReviewItems || []).filter(Boolean);
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);

      fixes = fixes
        .concat((draftModel.observationNotes || []).filter(Boolean))
        .concat(summaryItems)
        .concat(
          (draftModel.experienceBlocks || []).reduce(function (list, block) {
            return list.concat((block && block.reviewItems) || []);
          }, [])
        )
        .concat(
          (draftModel.additionalSections || []).reduce(function (
            list,
            section
          ) {
            return list.concat((section && section.reviewItems) || []);
          },
          [])
        );

      if (crossDiscipline) {
        fixes.unshift(
          "Be explicit that the current background is in " +
            cleanMessageText(
              (draftModel.headerModel && draftModel.headerModel.headline) ||
                "a different discipline"
            ) +
            " and that the role fit is not naturally strong."
        );
      } else if (roleSignals.length) {
        fixes.unshift(
          "Make " +
            formatNaturalList(roleSignals) +
            " easier to spot in the strongest evidence first."
        );
      }

      return dedupeList(fixes).filter(Boolean).slice(0, 5);
    }

    function buildCurrentHeaderExcerpt(headerModel) {
      var parts = [];
      var headline = cleanMessageText(
        (headerModel && headerModel.headline) || ""
      );
      if (headerModel && headerModel.name) {
        parts.push(headerModel.name);
      }
      if (
        headline &&
        headline.split(/\s+/).length <= 8 &&
        !/[,.]/.test(headline) &&
        !looksLikeCvSentenceLine(headline) &&
        !looksLikeCvRoleMetaLine(headline) &&
        !/^(?:education|work experience|professional experience|languages|personal achievements|technical skills)\b/i.test(
          headline
        )
      ) {
        parts.push(headline);
      }
      if (headerModel && headerModel.contactLine) {
        parts.push(headerModel.contactLine);
      }
      return dedupeList(parts).join("\n");
    }

    function buildExcerptBox(label, lines, modifier) {
      var list = dedupeList(
        (lines || [])
          .map(function (item) {
            return cleanMessageText(toDisplayText(item));
          })
          .filter(Boolean)
      ).slice(0, 3);

      if (!list.length) {
        return "";
      }

      return (
        '<div class="sffc-crm-apply-chat__draft-report-example' +
        (modifier ? " is-" + modifier : "") +
        '">' +
        (label
          ? '<span class="sffc-crm-apply-chat__draft-report-example-label">' +
            escapeHtml(label) +
            "</span>"
          : "") +
        list
          .map(function (line) {
            return "<p>" + escapeHtml(line) + "</p>";
          })
          .join("") +
        "</div>"
      );
    }

    function buildSolutionBox(label, lines) {
      var list = dedupeList(
        (lines || [])
          .map(function (item) {
            return cleanMessageText(toDisplayText(item));
          })
          .filter(Boolean)
      ).slice(0, 4);

      if (!list.length) {
        return "";
      }

      return (
        '<div class="sffc-crm-apply-chat__draft-report-example is-solution">' +
        (label
          ? '<span class="sffc-crm-apply-chat__draft-report-example-label">' +
            escapeHtml(label) +
            "</span>"
          : "") +
        list
          .map(function (line) {
            return "<p>" + escapeHtml(line) + "</p>";
          })
          .join("") +
        "</div>"
      );
    }

    function buildReviewNoteList(items) {
      var list = dedupeList(
        (items || [])
          .map(function (item) {
            return cleanMessageText(toDisplayText(item));
          })
          .filter(Boolean)
      ).slice(0, 4);
      if (!list.length) {
        return "";
      }
      function getReviewNoteTone(item) {
        var clean = cleanMessageText(item || "").toLowerCase();
        if (!clean) {
          return "warn";
        }
        if (
          /^(good |phone number found|email found|good professional email|linkedin profile(?: link)? (?:found|is visible)|location found|current contact details|based in |file type is pdf|page count is \d+.*within the normal range)/i.test(
            clean
          )
        ) {
          return "good";
        }
        return "warn";
      }
      return (
        "<ul>" +
        list
          .map(function (item) {
            var tone = getReviewNoteTone(item);
            return (
              '<li class="is-' +
              escapeHtml(tone) +
              '"><span>' +
              escapeHtml(item) +
              "</span></li>"
            );
          })
          .join("") +
        "</ul>"
      );
    }

    function buildReviewSectionCard(title, options) {
      var opts = options || {};
      var excerptHtml = buildExcerptBox(
        opts.excerptLabel,
        opts.excerpts || [],
        opts.excerptTone
      );
      var exampleHtml = buildExcerptBox(
        opts.exampleLabel,
        opts.examples || [],
        "rewrite"
      );
      var solutionHtml = buildSolutionBox(
        opts.solutionLabel || "How to fix it",
        opts.solutions || []
      );
      var noteHtml = buildReviewNoteList(opts.notes || []);
      var metaHtml = opts.meta
        ? '<div class="sffc-crm-apply-chat__draft-review-card-meta">' +
          escapeHtml(opts.meta) +
          "</div>"
        : "";
      var introHtml = opts.intro ? "<p>" + escapeHtml(opts.intro) + "</p>" : "";
      var toneClass = opts.tone ? " is-" + opts.tone : "";

      if (
        !excerptHtml &&
        !exampleHtml &&
        !solutionHtml &&
        !noteHtml &&
        !introHtml
      ) {
        return "";
      }

      return (
        '<article class="sffc-crm-apply-chat__draft-review-card' +
        toneClass +
        '">' +
        '<div class="sffc-crm-apply-chat__draft-review-card-head">' +
        '<div class="sffc-crm-apply-chat__draft-review-card-head-main">' +
        "<h4>" +
        escapeHtml(title) +
        "</h4>" +
        (opts.headContent || "") +
        "</div>" +
        '<button type="button" class="sffc-crm-apply-chat__draft-section-adjust" aria-label="Adjust ' +
        escapeHtml(String(title || "section").toLowerCase()) +
        '">Adjust</button>' +
        "</div>" +
        metaHtml +
        introHtml +
        excerptHtml +
        noteHtml +
        solutionHtml +
        exampleHtml +
        (opts.footerContent || "") +
        "</article>"
      );
    }

    function buildCompactQuickScanBars(items) {
      var list = (items || []).slice(0, 5);
      if (!list.length) {
        return "";
      }
      return (
        '<div class="sffc-crm-apply-chat__draft-compact-scan">' +
        list
          .map(function (item) {
            var tone = item && item.tone ? item.tone : "good";
            var percent = Math.max(
              0,
              Math.min(100, Number(item && item.percent) || 0)
            );
            return (
              '<div class="sffc-crm-apply-chat__draft-compact-scan-item is-' +
              escapeHtml(tone) +
              '">' +
              '<div class="sffc-crm-apply-chat__draft-compact-scan-row">' +
              '<span class="sffc-crm-apply-chat__draft-compact-scan-label">' +
              escapeHtml(item.label || "") +
              "</span>" +
              '<span class="sffc-crm-apply-chat__draft-compact-scan-value">' +
              escapeHtml(String(percent)) +
              "%</span>" +
              "</div>" +
              '<div class="sffc-crm-apply-chat__draft-compact-scan-track"><span class="sffc-crm-apply-chat__draft-compact-scan-fill" style="width:' +
              escapeHtml(String(percent)) +
              '%"></span></div>' +
              "</div>"
            );
          })
          .join("") +
        "</div>"
      );
    }

    function buildSectionBySectionReview(draftModel, analysis) {
      var cards = [];
      var headerExcerpt = buildCurrentHeaderExcerpt(
        draftModel.headerModel || {}
      );
      var summaryExcerpt = (draftModel.profileItems || []).slice(0, 2);
      var roleSignals = (draftModel.reviewPrioritySkills || []).slice(0, 3);
      var score = buildReviewScore(draftModel, analysis);
      var scoreTone = getReviewStatusTone(score);
      var roleFitCard = "";
      var headerCard = "";
      var openingSummaryCard = "";
      var diagnosticCards = "";
      var crossDiscipline = isCrossDisciplineReviewCase(draftModel);
      var quickScanItems = buildReviewQuickScanItems(
        draftModel,
        analysis,
        score
      );

      headerCard = buildReviewSectionCard("Header", {
        intro:
          "The issue here is not the absence of information. It is the way the header is being presented and prioritised.",
        excerpts: headerExcerpt ? [headerExcerpt] : [],
        excerptLabel: "Before",
        notes: (draftModel.observationNotes || []).slice(0, 4),
        solutions: [
          "Keep the header to name, location, phone, email, and LinkedIn only.",
          "Separate the professional headline from the contact line so the reader can scan both quickly.",
          "Make the location visible on the first line of contact details.",
        ],
        excerptTone: "problem",
        tone: "bad",
        headContent: buildAtsScoreInline(score, scoreTone),
        footerContent: buildCompactQuickScanBars(quickScanItems),
      });

      openingSummaryCard = buildReviewSectionCard("Opening Summary", {
        intro:
          "The opening summary should tell the reader quickly what you do, what scale you have handled, and why you fit this role.",
        excerpts: summaryExcerpt,
        excerptLabel: "Before",
        notes: (draftModel.summaryReviewItems || []).slice(0, 3),
        examples: buildTailoredExecutiveSummary(
          analysis,
          parseCvSectionsFromText(capturedCvText),
          draftModel.headerModel,
          draftModel
        ).slice(0, 1),
        exampleLabel: "After",
        solutions: crossDiscipline
          ? [
              "State the current discipline clearly, then explain the move into the target role.",
              "Lead with transferable analytical tools and research exposure, not a direct finance claim.",
              "Keep the summary to 2 or 3 lines with no filler.",
            ]
          : [
              "Start with the target identity you want the reader to remember.",
              "Add the strongest technical strengths and most relevant sector or deal exposure.",
              "Keep it short enough to scan in one pass.",
            ],
        excerptTone: "problem",
        tone: "warn",
      });

      if (headerCard) {
        cards.push(headerCard);
      }
      if (openingSummaryCard) {
        cards.push(openingSummaryCard);
      }

      diagnosticCards = buildReviewDiagnosticCards(draftModel, analysis);
      if (diagnosticCards) {
        cards.push(diagnosticCards);
      }

      (draftModel.additionalSections || [])
        .filter(function (section) {
          return /^(skills|highlights)$/i.test(
            String((section && section.key) || "")
          );
        })
        .forEach(function (section) {
          cards.push(
            buildReviewSectionCard(section.title, {
              intro: /skills/i.test(section.key)
                ? "This section should make the role-relevant strengths easy to scan."
                : "This section contains strong evidence, but the ordering and emphasis still matter.",
              excerpts: (section.items || []).slice(0, 4),
              excerptLabel: "Before",
              notes: (section.reviewItems || []).slice(0, 3),
              solutions: /skills/i.test(section.key)
                ? [
                    "Keep the most role-relevant technical skills first.",
                    "Remove weak filler terms and combine overlapping tools.",
                    "Use a clean one-line or short grouped format.",
                  ]
                : [
                    "Keep only highlights that strengthen the target application.",
                    "Move weaker or unrelated items lower down or out of the first page.",
                    "Make each highlight specific enough to be credible.",
                  ],
              excerptTone: "problem",
              tone: "warn",
            })
          );
        });

      (draftModel.experienceBlocks || [])
        .filter(function (block) {
          return (
            block &&
            !isNoisyDraftReviewTitle(block.title) &&
            ((block.sourceBullets && block.sourceBullets.length) ||
              (block.reviewItems && block.reviewItems.length))
          );
        })
        .slice(0, 4)
        .forEach(function (block) {
          var currentWording = dedupeList(
            [block.introLine].concat(block.sourceBullets || [])
          )
            .filter(Boolean)
            .slice(0, 2);
          var exampleRewrite = (block.rewrittenBullets || [])
            .filter(function (line) {
              return currentWording.indexOf(line) === -1;
            })
            .slice(0, 1);

          cards.push(
            buildReviewSectionCard(block.title, {
              meta: block.metaLine,
              intro:
                "This role already contains relevant evidence. The main job is to sharpen what the reader sees first.",
              excerpts: currentWording,
              excerptLabel: "Before",
              notes: (block.reviewItems || []).slice(0, 3),
              examples: exampleRewrite,
              exampleLabel: "After",
              solutions: [
                "Start the bullet with a strong action verb, not a weak setup like worked on or responsible for.",
                "Add scale, value, volume, or cadence wherever the evidence supports it.",
                "Make the business or analytical outcome explicit at the end of the bullet.",
              ],
              excerptTone: "problem",
              tone: "warn",
            })
          );
        });

      (draftModel.additionalSections || [])
        .filter(function (section) {
          return (
            !/^(skills|highlights)$/i.test(
              String((section && section.key) || "")
            ) &&
            section &&
            !isNoisyDraftReviewTitle(section.title) &&
            (section.reviewItems || []).length
          );
        })
        .forEach(function (section) {
          cards.push(
            buildReviewSectionCard(section.title, {
              excerpts: (section.items || []).slice(0, 3),
              excerptLabel: "Before",
              notes: (section.reviewItems || []).slice(0, 2),
              solutions: [
                "Keep formatting consistent across the whole section.",
                "Trim anything that does not help the target role directly.",
                "Use short, readable lines instead of dense blocks.",
              ],
              excerptTone: "problem",
              tone: "warn",
            })
          );
        });

      if (crossDiscipline) {
        roleFitCard = buildReviewSectionCard("Role Fit", {
          intro:
            "The main issue here is not simply wording. The CV currently reads as a different discipline from the role.",
          notes: [
            "Do not force a direct finance fit where the underlying background is mechanical engineering or another unrelated field.",
            "If the application still goes ahead, build the case through transferable analysis, research exposure, and why the move is credible.",
          ],
          solutions: [
            "Decide whether the application story is genuinely defensible before tailoring the CV further.",
            "If you still apply, lead with transferable analytical work and remove exaggerated finance claims.",
            "Make the transition rationale explicit near the top of the CV.",
          ],
          tone: "bad",
        });
      } else if (roleSignals.length) {
        roleFitCard = buildReviewSectionCard("Role Fit", {
          intro:
            "The strongest version of this CV should make the target role fit obvious almost immediately.",
          notes: [
            "Pull " +
              formatNaturalList(roleSignals) +
              " higher in the document where the evidence already exists.",
            "Do not spread the role fit across too many sections. Make the strongest examples do the work.",
          ],
          solutions: [
            "Move the strongest matching evidence into the first screenful of the CV.",
            "Use the same language the role uses where the proof is already real.",
            "Cut or demote unrelated detail that weakens the fit story.",
          ],
          tone: "bad",
        });
      }

      if (roleFitCard) {
        cards.splice(2, 0, roleFitCard);
      }

      return cards.filter(Boolean).join("");
    }

    function buildLiveTailoringDraftHtml(analysis, phase) {
      var sections = parseCvSectionsFromText(capturedCvText);
      var draftModel = buildLiveTailoringDraftModel(analysis, sections);
      var html = '<div class="sffc-crm-apply-chat__draft-workspace">';
      var headerModel = draftModel.headerModel || {};
      var score = buildReviewScore(draftModel, analysis);
      var issueCounts = buildReviewIssueCounts(draftModel);
      var priorityFixes = buildPriorityFixes(draftModel, analysis);
      var heroCallout = buildReviewHeroCallout(score, analysis, draftModel);
      var sectionReviewHtml = buildSectionBySectionReview(draftModel, analysis);
      var actionCards = buildReviewActionCards(draftModel, analysis);

      html += '<div class="sffc-crm-apply-chat__draft-document">';
      html +=
        '<article class="sffc-crm-apply-chat__draft-sheet sffc-crm-apply-chat__draft-sheet--report">' +
        '<section class="sffc-crm-apply-chat__draft-report-section">' +
        '<div class="sffc-crm-apply-chat__draft-review-card-list">' +
        sectionReviewHtml +
        "</div>" +
        "</section>" +
        '<section class="sffc-crm-apply-chat__draft-report-section">' +
        '<div class="sffc-crm-apply-chat__draft-section-head"><div class="sffc-crm-apply-chat__draft-section-title">Main Issues I Would Fix First</div><button type="button" class="sffc-crm-apply-chat__draft-section-adjust" aria-label="Adjust main issues">Adjust</button></div>' +
        (issueCounts.length
          ? '<div class="sffc-crm-apply-chat__draft-report-issue-counts">' +
            issueCounts
              .map(function (item) {
                return (
                  '<div class="sffc-crm-apply-chat__draft-report-issue-pill">' +
                  escapeHtml(item) +
                  "</div>"
                );
              })
              .join("") +
            "</div>"
          : "") +
        '<div class="sffc-crm-apply-chat__draft-report-priority-box">' +
        buildReviewNoteList(priorityFixes) +
        "</div>" +
        "</section>" +
        '<section class="sffc-crm-apply-chat__draft-report-section">' +
        '<div class="sffc-crm-apply-chat__draft-section-head"><div class="sffc-crm-apply-chat__draft-section-title">How This CV Reads Right Now</div><button type="button" class="sffc-crm-apply-chat__draft-section-adjust" aria-label="Adjust review summary">Adjust</button></div>' +
        '<div class="sffc-crm-apply-chat__draft-report-prose">' +
        "<p>" +
        escapeHtml(heroCallout) +
        "</p>" +
        "<p>The underlying experience is there. The main problem is that the reader still has to work too hard to find the strongest proof points, the role fit, and the most commercially relevant evidence.</p>" +
        "</div>" +
        "</section>" +
        "</article>";

      html += "</div></div>";
      return html;
    }

    function getCoverLetterSalutation() {
      return "Dear Hiring Manager:";
    }

    function getCoverLetterVariantSeed() {
      if (!coverLetterVariantSeed) {
        coverLetterVariantSeed =
          ensureApplyChatSessionToken() + "|" + Date.now().toString(36);
      }
      return coverLetterVariantSeed;
    }

    function chooseCoverLetterVariant(list, label, contextText) {
      return chooseVariant(
        list,
        getCoverLetterVariantSeed() +
          "|" +
          String(label || "") +
          "|" +
          cleanMessageText(contextText || "")
      );
    }

    function normalizeCoverLetterSignalLabel(label) {
      var clean = cleanMessageText(label || "");
      var lower;
      if (!clean) {
        return "";
      }
      lower = clean.toLowerCase();
      if (lower === "kpis and charts") {
        return "KPI reporting and chart-based analysis";
      }
      if (lower === "credit legal documentation") {
        return "credit documentation";
      }
      if (lower === "fund accounting") {
        return "fund accounting";
      }
      if (lower === "m&a") {
        return "M&A";
      }
      return clean
        .replace(/\bkpis\b/gi, "KPIs")
        .replace(
          /\bkpi reporting and chart-based analysis\b/gi,
          "KPI reporting and management reporting"
        )
        .replace(/\bcharts\b/gi, "management reporting")
        .replace(/\bcrm\b/g, "CRM")
        .replace(/\blp\b/gi, "LP")
        .replace(/\birr\b/gi, "IRR")
        .replace(/\bmoic\b/gi, "MOIC")
        .replace(/\baum\b/gi, "AUM")
        .replace(/\bnav\b/gi, "NAV");
    }

