    function getCoverLetterRoleProfile() {
      var title = cleanMessageText(roleTitle || "").toLowerCase();
      var brief = cleanMessageText(roleBriefText || "").toLowerCase();
      var full = [title, brief].join(" ");
      var profile = {
        family: "general",
        overlay: "general",
        seniority: "general",
      };

      if (
        /(managing director|director|associate director|associate vice president|head of|principal|partner|vice president|vp|senior manager|senior specialist|finance director|investment director|senior private banker|senior portfolio strategist|strategic project lead|senior investment research manager)/i.test(
          full
        )
      ) {
        profile.seniority = "senior";
      } else if (
        /(associate|assistant manager|manager|officer|controller|advisor|adviser|banker)/i.test(
          full
        )
      ) {
        profile.seniority = "mid";
      } else if (/(intern|junior|analyst)/i.test(full)) {
        profile.seniority = "junior";
      }

      if (
        /(investment banking|healthcare - investment banking|healthcare investment banking|m&a|mergers|acquisition|sell-side|buy-side advisory|corporate finance|debt advisory|capital advisory|global debt advisory)/i.test(
          full
        )
      ) {
        profile.family = "investment_banking";
      } else if (
        /(private equity|buyout|growth equity|portfolio company|lbo|infrastructure pe|strategic finance \(private equity\)|strategic finance private equity)/i.test(
          full
        )
      ) {
        profile.family = "private_equity";
      } else if (
        /(venture capital|vc|series a|series b|startup|founder|deal flow|cap table|innovation & venture|innovation and venture|cvc)/i.test(
          full
        )
      ) {
        profile.family = "venture_capital";
      } else if (
        /(strategy|strategic project lead|strategic asset allocation|managing consultant|strategy consultant|business analyst|strategic planning|international projects)/i.test(
          full
        )
      ) {
        profile.family = "strategy";
      } else if (
        /(product manager|product analyst|product specialist)/i.test(full)
      ) {
        profile.family = "product";
      } else if (
        /(research analyst|equity research|credit research|macro research|research associate|investment research|investment research manager)/i.test(
          full
        )
      ) {
        profile.family = "research";
      } else if (
        /(investor relations|capital partnerships|lp communications|fundraising|capital raising|ddq|investor communication)/i.test(
          full
        )
      ) {
        profile.family = "investor_relations";
      } else if (
        /(credit|global credit|underwriting|covenant|direct lending|structured credit|leveraged finance|debt)/i.test(
          full
        )
      ) {
        profile.family = "credit";
      } else if (
        /(fund accounting|finance manager|finance director|finance advisor|fp&a|treasury|financial control|management reporting|budgeting|forecasting|financial accountant|accounting|controller|transfer pricing)/i.test(
          full
        )
      ) {
        profile.family = "finance";
      } else if (
        /(portfolio manager|portfolio implementation|asset management associate|asset management|strategic asset allocation|multi-asset|fixed income|equity portfolio|aum|public markets|fund manager|swf|sovereign wealth|investment associate.+real assets|real assets)/i.test(
          full
        )
      ) {
        profile.family = "asset_management";
      } else if (
        /(corporate development|corp dev|strategic planning|services business development|business development manager|business development associate)/i.test(
          full
        )
      ) {
        profile.family = "corporate_development";
      } else if (
        /(wealth manager|private wealth|private banker|relationship manager|investment advisor|family office)/i.test(
          full
        )
      ) {
        profile.family = "wealth_management";
      } else if (
        /(trader|trading|cash equities|sales trader|equity sales|fixed income sales|institutional sales)/i.test(
          full
        )
      ) {
        profile.family = "trading";
      } else if (
        /(real estate|property|acquisitions|asset manager|argus|noi|lease)/i.test(
          full
        )
      ) {
        profile.family = "real_estate";
      } else if (
        /(compliance|aml|kyc|fraud analyst|regulatory affairs|compliance officer|aml officer|kyc officer)/i.test(
          full
        )
      ) {
        profile.family = "compliance";
      } else if (
        /(risk|operational risk|market risk|governance|middle office|trade support|operations)/i.test(
          full
        )
      ) {
        profile.family = "risk_ops";
      }

      if (/(investment associate.+real assets|real assets)/i.test(full)) {
        profile.overlay = "real_assets";
      } else if (
        /(healthcare - investment banking|healthcare investment banking|healthcare\b)/i.test(
          full
        ) &&
        /investment banking|m&a|corporate finance/i.test(full)
      ) {
        profile.overlay = "healthcare_ib";
      } else if (/(capital partnerships)/i.test(full)) {
        profile.overlay = "capital_partnerships";
      } else if (
        /(strategic finance \(private equity\)|strategic finance private equity|strategic finance)/i.test(
          full
        )
      ) {
        profile.overlay = "strategic_finance";
      } else if (/(portfolio implementation)/i.test(full)) {
        profile.overlay = "portfolio_implementation";
      } else if (/(growth equity)/i.test(full)) {
        profile.overlay = "growth_equity";
      } else if (/(buyout)/i.test(full)) {
        profile.overlay = "buyout";
      } else if (/(venture capital|vc|startup|founder)/i.test(full)) {
        profile.overlay = "venture_capital";
      } else if (
        /(private credit|direct lending|sponsor finance)/i.test(full)
      ) {
        profile.overlay = "private_credit";
      } else if (/(m&a|mergers|acquisition)/i.test(full)) {
        profile.overlay = "ma";
      } else if (/(corporate finance)/i.test(full)) {
        profile.overlay = "corporate_finance";
      } else if (
        /(investor relations|lp|fundraising|capital raising)/i.test(full)
      ) {
        profile.overlay = "fundraising";
      } else if (/(family office)/i.test(full)) {
        profile.overlay = "family_office";
      } else if (/(private banker|private wealth)/i.test(full)) {
        profile.overlay = "private_banking";
      } else if (/(strategic asset allocation|asset allocation)/i.test(full)) {
        profile.overlay = "strategic_asset_allocation";
      } else if (/(sovereign wealth|swf)/i.test(full)) {
        profile.overlay = "sovereign_wealth";
      } else if (
        /(debt advisory|capital & debt advisory|global debt advisory)/i.test(
          full
        )
      ) {
        profile.overlay = "debt_advisory";
      } else if (
        /(infrastructure pe|energy & infrastructure|infrastructure)/i.test(full)
      ) {
        profile.overlay = "infrastructure";
      } else if (
        /(services business development|business development)/i.test(full)
      ) {
        profile.overlay = "business_development";
      } else if (
        /(innovation & venture|innovation and venture|cvc)/i.test(full)
      ) {
        profile.overlay = "innovation_venture";
      } else if (
        /(product manager|product analyst|product specialist)/i.test(full)
      ) {
        profile.overlay = "product";
      } else if (
        /(strategy|strategic planning|strategy consultant|managing consultant)/i.test(
          full
        )
      ) {
        profile.overlay = "strategy";
      } else if (/(fraud|forensic)/i.test(full)) {
        profile.overlay = "fraud";
      } else if (/(financial accountant|accounting)/i.test(full)) {
        profile.overlay = "financial_accounting";
      } else if (/(transfer pricing)/i.test(full)) {
        profile.overlay = "transfer_pricing";
      } else if (/(corporate credit)/i.test(full)) {
        profile.overlay = "corporate_credit";
      } else if (/(global credit)/i.test(full)) {
        profile.overlay = "global_credit";
      } else if (/(institutional sales|cash equities)/i.test(full)) {
        profile.overlay = "institutional_sales";
      } else if (
        /(finance director|head of finance|group finance director|director of finance)/i.test(
          full
        )
      ) {
        profile.overlay = "finance_director";
      } else if (
        /(finance manager|commercial finance manager|fp&a manager|finance business partner)/i.test(
          full
        )
      ) {
        profile.overlay = "finance_manager";
      } else if (/(fp&a|forecasting|budgeting|variance analysis)/i.test(full)) {
        profile.overlay = "fpanda";
      } else if (/(fund controller|waterfall|carried interest)/i.test(full)) {
        profile.overlay = "fund_controller";
      } else if (/(controller|close process|financial control)/i.test(full)) {
        profile.overlay = "controllership";
      } else if (
        /(audit|external audit|internal audit|assurance)/i.test(full)
      ) {
        profile.overlay = "audit";
      } else if (/(tax|vat|corporate tax|international tax)/i.test(full)) {
        profile.overlay = "tax";
      } else if (
        /(insurance|statutory accounting|surplus management|alm)/i.test(full)
      ) {
        profile.overlay = "insurance";
      } else if (
        /(research|equity research|credit research|macro)/i.test(full)
      ) {
        profile.overlay = "research";
      } else if (
        /(fund accounting|capital calls|distributions|nav)/i.test(full)
      ) {
        profile.overlay = "fund_accounting";
      } else if (/(treasury|cash management|liquidity)/i.test(full)) {
        profile.overlay = "treasury";
      } else if (
        /(structured finance|structured products|clo|abs|rmbs|cmbs)/i.test(full)
      ) {
        profile.overlay = "structured_finance";
      } else if (/(securitization|securitisation|tranche|intex)/i.test(full)) {
        profile.overlay = "securitization";
      } else if (
        /(aml|transaction monitoring|sanctions|suspicious activity)/i.test(full)
      ) {
        profile.overlay = "aml";
      } else if (/(kyc|client onboarding|cdd|edd)/i.test(full)) {
        profile.overlay = "kyc";
      } else if (/(compliance|regulatory)/i.test(full)) {
        profile.overlay = "compliance";
      } else if (
        /(chief operating officer|coo|operating model|scalability)/i.test(full)
      ) {
        profile.overlay = "coo";
      } else if (/(operations|trade support|middle office)/i.test(full)) {
        profile.overlay = "operations";
      } else if (/(wealth|relationship manager|family office)/i.test(full)) {
        profile.overlay = "wealth_management";
      } else if (
        /(portfolio manager|portfolio construction|asset allocation)/i.test(
          full
        )
      ) {
        profile.overlay = "portfolio";
      } else if (/(acquisitions|broker relations|loi|cap rate)/i.test(full)) {
        profile.overlay = "acquisitions";
      } else if (
        /(real estate|property|acquisitions|asset manager)/i.test(full)
      ) {
        profile.overlay = "real_estate";
      } else if (/(hedge fund|long\/short|alpha|trading)/i.test(full)) {
        profile.overlay = "hedge_funds";
      } else if (
        /(public markets|equity portfolio|fixed income|multi-asset)/i.test(full)
      ) {
        profile.overlay = "public_markets";
      } else if (/(equity research)/i.test(full)) {
        profile.overlay = "equity_research";
      } else if (/(credit research)/i.test(full)) {
        profile.overlay = "credit_research";
      } else if (/(macro research)/i.test(full)) {
        profile.overlay = "macro_research";
      } else if (
        /(quantitative|python|statistics|machine learning)/i.test(full)
      ) {
        profile.overlay = "quantitative";
      } else {
        profile.overlay = profile.family;
      }

      return profile;
    }

