    function showEndChatPrompt() {
      endChatPrompt.hidden = false;
      desk.classList.add("is-end-chat-open");
    }

    function hideEndChatPrompt() {
      endChatPrompt.hidden = true;
      desk.classList.remove("is-end-chat-open");
    }

    function primeAudio() {
      var AudioContextConstructor =
        window.AudioContext || window.webkitAudioContext;
      if (!AudioContextConstructor) {
        return;
      }
      if (!audioContext) {
        audioContext = new AudioContextConstructor();
      }
      if (audioContext.state === "suspended") {
        audioContext.resume();
      }
    }

    function playTone() {
      var now;
      var gain;
      var first;
      var second;
      if (!audioContext) {
        return;
      }

      now = audioContext.currentTime;
      gain = audioContext.createGain();
      first = audioContext.createOscillator();
      second = audioContext.createOscillator();
      first.type = "sine";
      second.type = "sine";
      first.frequency.setValueAtTime(740, now);
      second.frequency.setValueAtTime(980, now + 0.08);
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.exponentialRampToValueAtTime(0.03, now + 0.018);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.22);
      first.connect(gain);
      second.connect(gain);
      gain.connect(audioContext.destination);
      first.start(now);
      second.start(now + 0.08);
      first.stop(now + 0.18);
      second.stop(now + 0.24);
    }

    function scrollToLatest() {
      if (
        isMobileWorkspaceView &&
        isMobileWorkspaceView() &&
        suppressAutoScrollUntil > Date.now()
      ) {
        return;
      }
      if (
        pinnedWorkspaceCardNode &&
        pinnedWorkspaceCardUntil > Date.now() &&
        messages.contains(pinnedWorkspaceCardNode)
      ) {
        scrollToWorkspaceCard(pinnedWorkspaceCardNode);
        return;
      }
      if (pendingMessagesScrollRaf) {
        return;
      }
      pendingMessagesScrollRaf = window.requestAnimationFrame(function () {
        pendingMessagesScrollRaf = 0;
        messages.scrollTop = messages.scrollHeight;
        if (pendingMessagesScrollTimeout) {
          window.clearTimeout(pendingMessagesScrollTimeout);
        }
        pendingMessagesScrollTimeout = window.setTimeout(function () {
          pendingMessagesScrollTimeout = 0;
          messages.scrollTop = messages.scrollHeight;
        }, 70);
      });
    }

    function scrollToWorkspaceCard(row, options) {
      var opts = options || {};
      var card = row
        ? row.querySelector(
            ".sffc-crm-apply-chat__quick-insights, .sffc-crm-apply-chat__tailoring-preview-card, .sffc-crm-apply-results, .sffc-crm-apply-chat__draft-review-chat-card"
          )
        : null;
      var target = card || row;
      var top;
      if (!messages || !target) {
        return;
      }
      top = Math.max(0, target.offsetTop - (opts.offset || 28));
      if (pendingMessagesScrollRaf) {
        window.cancelAnimationFrame(pendingMessagesScrollRaf);
        pendingMessagesScrollRaf = 0;
      }
      if (pendingMessagesScrollTimeout) {
        window.clearTimeout(pendingMessagesScrollTimeout);
        pendingMessagesScrollTimeout = 0;
      }
      messages.scrollTop = top;
      window.setTimeout(function () {
        if (
          pinnedWorkspaceCardNode === row &&
          pinnedWorkspaceCardUntil > Date.now() &&
          messages.contains(row)
        ) {
          messages.scrollTop = Math.max(
            0,
            target.offsetTop - (opts.offset || 28)
          );
        }
      }, 90);
    }

    function clearPinnedApplyResultsScroll() {
      if (
        pinnedWorkspaceCardNode &&
        messages &&
        messages.contains(pinnedWorkspaceCardNode) &&
        pinnedWorkspaceCardNode.querySelector(".sffc-crm-apply-results")
      ) {
        pinnedWorkspaceCardNode = null;
        pinnedWorkspaceCardUntil = 0;
      }
    }

    function pinWorkspaceCardScroll(row, duration) {
      if (!row) {
        return;
      }
      if (row.querySelector(".sffc-crm-apply-results")) {
        pinnedWorkspaceCardNode = row;
        pinnedWorkspaceCardUntil = Date.now() + (duration || 9000);
        scrollToWorkspaceCard(row, {
          offset: isMobileWorkspaceView && isMobileWorkspaceView() ? 8 : 18,
        });
        return;
      }
      pinnedWorkspaceCardNode = row;
      pinnedWorkspaceCardUntil = Date.now() + (duration || 9000);
      scrollToWorkspaceCard(row);
    }

