    function getStandaloneMemberDeskActivityItems(mode, limit) {
      var stageNode = mode === "intros" ? introsStage : sentStage;
      return Array.prototype.slice
        .call(
          (stageNode &&
            stageNode.querySelectorAll(
              ".sffc-crm-apply-chat__activity-card"
            )) ||
            [],
          0,
          typeof limit === "number" ? limit : 3
        )
        .map(function (card) {
          var titleNode = card.querySelector(
            ".sffc-crm-apply-chat__activity-card-copy strong"
          );
          var companyNode = card.querySelector(
            ".sffc-crm-apply-chat__activity-card-copy span"
          );
          var metaNode = card.querySelector(
            ".sffc-crm-apply-chat__activity-card-copy small"
          );
          var linkNode = card.querySelector(
            ".sffc-crm-apply-chat__activity-link"
          );
          return {
            title: cleanMessageText(titleNode ? titleNode.textContent : ""),
            company: cleanMessageText(
              companyNode ? companyNode.textContent : ""
            ),
            meta: cleanMessageText(metaNode ? metaNode.textContent : ""),
            link: cleanMessageText(
              linkNode ? linkNode.getAttribute("href") : ""
            ),
          };
        })
        .filter(function (item) {
          return item.title;
        });
    }

    function buildStandaloneMemberDeskActivityHtml() {
      var sentItems = getStandaloneMemberDeskActivityItems("sent", 3);
      var introItems = getStandaloneMemberDeskActivityItems("intros", 2);
      var html = "";
      if (sentItems.length) {
        html +=
          '<div class="sffc-crm-apply-chat__formatted"><ul>' +
          sentItems
            .map(function (item) {
              return (
                "<li><strong>" +
                escapeHtml(item.title) +
                "</strong>" +
                (item.company ? " · " + escapeHtml(item.company) : "") +
                "</li>"
              );
            })
            .join("") +
          "</ul></div>";
      }
      if (introItems.length) {
        html +=
          '<div class="sffc-crm-apply-chat__formatted"><p>' +
          escapeHtml(
            "I have also prepared " +
              introItems.length +
              " recruiter intro" +
              (introItems.length > 1 ? "s" : "") +
              " around the same search."
          ) +
          "</p></div>";
      }
      return html;
    }

