    function askStandaloneMemberDeskRefineRoles() {
      removeChoiceBlock();
      botMessage(
        "Tell me the roles you want me to focus on more clearly from here.",
        humanComposeDelay(
          "Tell me the roles you want me to focus on more clearly from here.",
          1800,
          3200
        ),
        function () {
          setPromptState(
            "member_desk_refine_roles",
            {
              no: function () {
                askStandaloneMemberDeskRefineSectors();
              },
              other: function (value) {
                if (
                  /(?:no change|keep it|same|leave it|as is)/i.test(
                    String(value || "")
                  )
                ) {
                  askStandaloneMemberDeskRefineSectors();
                  return;
                }
                applyLoggedInMemberTargetFunction(value);
                mergeConversationFacts(value);
                botMessage(
                  "Understood. I'll tighten the role focus around that.",
                  humanComposeDelay(
                    "Understood. I'll tighten the role focus around that.",
                    1400,
                    2400
                  ),
                  function () {
                    askStandaloneMemberDeskRefineSectors();
                  },
                  humanReadDelay(value, 420)
                );
              },
            },
            "Tell me the roles you want me focused on"
          );
          addChoices(
            [
              {
                label: "No change",
                onClick: function () {
                  userMessage("No change");
                  clearPromptState();
                  askStandaloneMemberDeskRefineSectors();
                },
              },
            ],
            "clarify"
          );
          focusComposer("Tell me the roles you want me focused on");
        }
      );
    }

