    function handleStandaloneMemberDeskReply(value) {
      var semantics = parseMessageSemantics(value);
      var cleanValue = cleanMessageText(value || "");
      var clean = cleanMessageText(value || "").toLowerCase();
      var facts;
      if (!clean) {
        return false;
      }
      if (
        /(application links?|apply links?|show links?|give me the links?|let me apply myself|apply myself|view role links?)/i.test(
          clean
        )
      ) {
        respondWithStandaloneMemberDeskLinks("applications");
        return true;
      }
      if (
        /(recruiter contacts?|contacts?|reach out|intro routes?|show contacts?|who can i contact|recruiter routes?)/i.test(
          clean
        )
      ) {
        respondWithStandaloneMemberDeskLinks("contacts");
        return true;
      }
      if (
        /(refine|tighten|change the search|update the search|different roles?|different sectors?|different locations?|change locations?|change sectors?)/i.test(
          clean
        )
      ) {
        askStandaloneMemberDeskRefineRoles();
        return true;
      }
      if (
        /(new cv|upload cv|replace cv|different cv|updated cv)/i.test(clean)
      ) {
        startConsultantFlow("review_profile");
        return true;
      }
      if (
        semantics.mentions_sector_targeting ||
        (semantics.location_hints && semantics.location_hints.length) ||
        (semantics.role_hints && semantics.role_hints.length) ||
        /(?:focus on|target|prioritise|prioritize|keep in play|exclude|remove|only|instead|widen|broaden|narrow|tighten|sector|location|market|roles?)/i.test(
          clean
        ) ||
        cleanValue.split(/\s+/).length >= 4
      ) {
        facts = extractConversationFacts(value);
        if (facts.target_functions && facts.target_functions.length) {
          applyLoggedInMemberTargetFunction(facts.target_functions[0]);
        }
        if (
          facts.location_intent &&
          facts.location_intent.current &&
          facts.location_intent.current.length
        ) {
          applyLoggedInMemberTargetLocation(facts.location_intent.current[0]);
        } else if (facts.target_locations && facts.target_locations.length) {
          applyLoggedInMemberTargetLocation(facts.target_locations[0]);
        }
        mergeConversationFacts(value);
        botMessage(
          "Understood. I'll update the brief around that and keep the search moving.",
          humanComposeDelay(
            "Understood. I'll update the brief around that and keep the search moving.",
            1500,
            2600
          ),
          function () {
            showStandaloneMemberDeskChoices();
            focusComposer(
              "Tell me if you want links, contacts, or another change"
            );
          },
          humanReadDelay(value, 420)
        );
        return true;
      }
      return false;
    }

    function showStandaloneMemberDesk() {
      var hasActivity =
        getStandaloneMemberDeskActivityItems("sent", 1).length > 0 ||
        getStandaloneMemberDeskActivityItems("intros", 1).length > 0;
      activePath = "member_desk";
      step = "member_desk";
      clearPromptState();
      removeChoiceBlock();
      setDeskIdentity("emily");
      botMessageNow(
        hasActivity
          ? buildStandaloneMemberDeskActiveHtml()
          : buildStandaloneMemberDeskFirstTimeHtml()
      );
      showStandaloneMemberDeskChoices();
      focusComposer("Choose an option or type a message");
    }

    function getInitialLauncherMode() {
      // Prioritize role_entry when user clicked Apply on a specific role
      // This applies to both logged-in and guest users
      if (launchMode === "role_entry") {
        return "role_entry";
      }
      if (hasConcreteRoleEntryContext()) {
        return "role_entry";
      }
      if (isStandaloneMemberDesk && hasLoggedInChatSession()) {
        return "member_desk";
      }
      if (hasLoggedInChatSession()) {
        return "logged_in_desk";
      }
      if (hasReturningConversationMemory()) {
        return "guest_returning";
      }
      return "guest_cold";
    }

