    function maybeAddPromptRecoveryChoices(state) {
      var bubble;
      var choices;
      if (getPromptAskCount(state) < 2) {
        return false;
      }
      bubble = messages.lastElementChild
        ? messages.lastElementChild.querySelector(
            ".sffc-crm-apply-chat__bubble"
          )
        : null;
      if (!bubble || bubble.querySelector(".sffc-crm-apply-chat__choices")) {
        return false;
      }
      choices = getPromptRecoveryChoices(state);
      if (!choices.length) {
        return false;
      }
      addChoices(
        choices.map(function (item) {
          return {
            label: item.label,
            onClick: function () {
              triggerPromptRecoveryChoice(item.label, item.reply);
            },
          };
        }),
        "clarify"
      );
      return true;
    }

    function showPromptRecoveryMessage(
      state,
      message,
      placeholder,
      readSource,
      onReady
    ) {
      var resolvedState = cleanMessageText(state || promptState || "");
      registerPromptRepeatAsk(resolvedState);
      botMessage(
        message,
        humanComposeDelay(message, 1000, 2200),
        function () {
          focusComposer(placeholder || getComposerPlaceholder("reply"));
          maybeAddPromptRecoveryChoices(resolvedState);
          if (typeof onReady === "function") {
            onReady();
          }
        },
        humanReadDelay(readSource || lastUserInputText, 420)
      );
    }

