    function continueJobSearchFromSavedCv() {
      uploadButton.hidden = true;
      input.disabled = false;
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Preparing your profile for role search",
        note: "I'm using the active CV already saved on your account, so the search can continue without another upload.",
        fileName: getLoggedInActiveCvLabel(),
        cvStatus: "Saved CV ready for search",
        coverStatus: "Not in scope yet",
        activeTab: "original",
      });
      if (
        loggedInResumeContext &&
        loggedInResumeContext.activeFileUrl &&
        loggedInResumeContext.activeFileType === "pdf"
      ) {
        setWorkspacePreviewFromPdfUrl(loggedInResumeContext.activeFileUrl);
      }
      ensureLoggedInSavedCvText()
        .then(function (ready) {
          if (!ready) {
            throw new Error(
              "I could not load the saved CV from your account just now."
            );
          }
          return fetchCvAnalysis(capturedCvText)
            .then(function (analysis) {
              mergeCvFacts(analysis || {});
              return true;
            })
            .catch(function () {
              return true;
            });
        })
        .then(function () {
          window.setTimeout(function () {
            continueJobSearchAfterCvUpload();
          }, randomBetween(300, 650));
        })
        .catch(function (error) {
          botMessage(
            escapeHtml(
              error && error.message
                ? error.message
                : "I could not load the saved CV from your account just now."
            ),
            humanComposeDelay(
              cleanMessageText(
                error && error.message
                  ? error.message
                  : "I could not load the saved CV from your account just now."
              ),
              1800,
              3600
            ),
            function () {
              uploadButton.hidden = false;
              input.disabled = false;
              focusComposer(getUploadCvPlaceholder());
            }
          );
        });
    }

