    function clampApplyIntroScore(value, fallback) {
      var number = parseInt(value, 10);
      if (!isFinite(number)) {
        number = fallback;
      }
      return Math.max(35, Math.min(96, number));
    }

    function normaliseApplyIntroConcept(value) {
      return cleanMessageText(value || "")
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
    }

    function buildApplyIntroAssessment(analysis) {
      var source = analysis || {};
      var items = getApplyQuickRoleInsightItems(source);
      var scores = getApplyQuickInsightsScorePair(source, items);
      var matchedKeywords = uniqueCleanItems(
        []
          .concat(source.matched_keywords || [])
          .concat(source.priority_skills || [])
          .concat(source.detected_skills || [])
      );
      var strengths = matchedKeywords.slice(0, 4).map(function (skill) {
        return {
          concept: normaliseApplyIntroConcept(skill),
          evidence: normaliseApplyIntroConcept(skill),
          confidence: 0.86,
        };
      });
      if (!strengths.length) {
        strengths = [
          {
            concept: normaliseApplyIntroConcept(
              source.experience_title || "Relevant experience"
            ),
            evidence: normaliseApplyIntroConcept(
              source.company_signal || getApplyIntroRoleName()
            ),
            confidence: 0.72,
          },
        ];
      }
      var gaps = items.slice(0, 5).map(function (item) {
        var concept = normaliseApplyIntroConcept(
          (item && (item.label || item.title || item.keyword || item.issue)) ||
            ""
        );
        var severity = item && item.severity ? item.severity : "important";
        return {
          concept: concept || "Application positioning",
          requirementImportance:
            severity === "critical"
              ? 0.95
              : severity === "suggested"
              ? 0.54
              : 0.78,
          cvEvidenceStrength: severity === "critical" ? 0.2 : 0.42,
          issue:
            (item && (item.summary || item.copy || item.message)) ||
            "Relevant evidence is not obvious enough yet.",
          severity: severity,
        };
      });
      var hardRequirements = gaps
        .filter(function (gap) {
          var confirmedHardRequirement = normaliseApplyIntroConcept(
            source.hard_requirement_confirmed || ""
          ).toLowerCase();
          return (
            /arabic|language|visa|authori[sz]ation|licen[cs]e|clearance|qualification|mandatory|required/i.test(
              gap.concept + " " + gap.issue
            ) &&
            confirmedHardRequirement !==
              normaliseApplyIntroConcept(gap.concept || "").toLowerCase()
          );
        })
        .map(function (gap) {
          return {
            concept: gap.concept,
            jobRequirement: /mandatory|required/i.test(gap.issue)
              ? "required"
              : "preferred",
            cvStatus: "not_found",
          };
        });
      var overallFit = clampApplyIntroScore(
        source.overall_fit ||
          source.overallFit ||
          source.match_score ||
          source.score ||
          scores.current,
        scores.current || 72
      );
      return {
        overallFit: overallFit,
        eligibility: {
          status: hardRequirements.some(function (requirement) {
            return requirement.jobRequirement === "required";
          })
            ? "clarification_required"
            : "likely_eligible",
          blockers: hardRequirements.filter(function (requirement) {
            return requirement.jobRequirement === "required";
          }),
        },
        strengths: strengths,
        gaps: gaps,
        missingEvidence: gaps.slice(0, 3).map(function (gap) {
          return { concept: gap.concept, confidence: 0.74 };
        }),
        hardRequirements: hardRequirements,
        positioningIssues: gaps,
        adjacentRoles: getApplyIntroAdjacentRoles(source),
        marketOpportunity: {
          market: getApplyIntroMarketName(),
          source: "current_job",
          confidence: roleLocation ? 0.68 : 0.4,
          status: roleLocation ? "inferred" : "unknown",
        },
        recommendation: determineApplyIntroRouteRecommendation(
          overallFit,
          gaps
        ),
      };
    }

    function determineApplyIntroRouteRecommendation(overallFit, gaps) {
      var issueCount = (gaps || []).length;
      if (overallFit >= 76 && issueCount >= 2) {
        return {
          type: "managed_search",
          strength: "strong",
          copy: "This role is worth pursuing, but I wouldn't make it your only route.",
        };
      }
      return {
        type: "single_application",
        strength: "neutral",
        copy: "We can keep this simple and work on this application only. If you're actively looking beyond it, I can also use this profile to run the wider search.",
      };
    }

    function getApplyIntroAdjacentRoles(analysis) {
      var baseRole = getApplyIntroRoleName();
      if (/private equity|investment/i.test(baseRole)) {
        return [
          "Investment Analyst",
          "Investment Associate",
          "Private Credit Analyst",
        ];
      }
      if (/business development|operations/i.test(baseRole)) {
        return [
          "Business Development Associate",
          "Operations Associate",
          "Strategy Associate",
        ];
      }
      if (/finance|analyst/i.test(baseRole)) {
        return [
          "Financial Analyst",
          "Investment Analyst",
          "Corporate Finance Analyst",
        ];
      }
      return uniqueCleanItems([
        baseRole,
        analysis && analysis.experience_title,
        "Related analyst roles",
      ]).slice(0, 3);
    }

    function renderApplyIntroAnalysisProgressCard() {
      return (
        '<section class="sffc-crm-apply-chat__analysis-progress-card">' +
        "<h3>Reviewing your CV...</h3>" +
        "<ul>" +
        [
          "Experience",
          "Seniority",
          "Skills",
          "Role requirements",
          "Keywords",
          "Application positioning",
        ]
          .map(function (item) {
            return (
              '<li><span aria-hidden="true">✓</span>' +
              escapeHtml(item) +
              "</li>"
            );
          })
          .join("") +
        "</ul>" +
        "</section>"
      );
    }

    function renderApplyIntroApplicationInsightCard(assessment) {
      var score = clampApplyIntroScore(assessment && assessment.overallFit, 72);
      var strengths = ((assessment && assessment.strengths) || []).slice(0, 3);
      var gaps = ((assessment && assessment.gaps) || []).slice(0, 3);
      return (
        '<section class="sffc-crm-apply-chat__application-insight-card">' +
        '<div class="sffc-crm-apply-chat__application-insight-head">' +
        "<span>Your application</span>" +
        "<strong>" +
        score +
        "%</strong>" +
        "<p>" +
        (score >= 78 ? "Strong potential fit" : "Potential fit with fixes") +
        "</p>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__application-insight-grid">' +
        "<div><h4>Strong</h4><ul>" +
        strengths
          .map(function (item) {
            return (
              "<li>✓ " +
              escapeHtml(item.concept || item.evidence || "Relevant evidence") +
              "</li>"
            );
          })
          .join("") +
        "</ul></div>" +
        "<div><h4>Could be stronger</h4><ul>" +
        gaps
          .map(function (item) {
            return (
              "<li>! " + escapeHtml(item.concept || "Positioning") + "</li>"
            );
          })
          .join("") +
        "</ul></div>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__application-insight-foot">' +
        escapeHtml(String(gaps.length || 0)) +
        " improvements identified</div>" +
        "</section>"
      );
    }

    function shouldShowApplyIntroRouteSelector() {
      return !hasPremiumMemberChatAccess();
    }

    function getPremiumApplyIntroSelectionPrompt() {
      return "Choose Tailor CV, Original CV, or type a new search.";
    }

    function getPremiumApplyIntroSelectedRole() {
      return normalizeCommercialApplyQueueItem(
        Object.assign({}, getCommercialApplyQueueMainItem(), {
          status: "Ready",
        }),
        "Ready"
      );
    }

    function beginPremiumApplyIntroSelectedRoleFlow() {
      var selected = getPremiumApplyIntroSelectedRole();
      selected = setCurrentApplicationContextFromQueueItem(selected);
      selected = Object.assign({}, selected, {
        status: "Ready",
        cvMode: "tailored",
      });
      pendingApplyResultsSelection = selected;
      activePath = "apply_for_me";
      step = "apply_upload";
      commercialApplyQueueInitialized = true;
      commercialApplyQueueActivated = false;
      commercialApplyQueueDetailsMode = true;
      commercialApplyQueueActiveTab = "shortlist";
      commercialApplyQueueFilter = "all";
      jobsWorkspaceSearchQuery = "";
      commercialApplyQueueItemsState = [selected];
      rememberCommercialApplyQueueCatalogItems([selected]);
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Ready to apply",
        note: "Premium member path: selected role is ready for application execution.",
        fileName: getLoggedInActiveCvLabel(),
        cvStatus: "Saved CV ready",
        coverStatus: "Not started yet",
        activeTab: "original",
      });
      botMessage(
        "I’ve got the role and your saved CV. Choose whether I should tailor the CV for this role first, or apply with the current version." +
          renderCommercialApplyQueueCard(commercialApplyQueueItemsState, {
            active: false,
            showButton: false,
            eyebrow: "Selected role",
            title: "Selected role",
          }),
        humanComposeDelay("Premium selected role ready.", 900, 1700),
        function () {
          setPromptState(
            "premium_apply_intro_selected_role",
            {
              yes: function (value) {
                startApplyResultsSelectedRoleFlow(selected.key, "tailored", {
                  echoLabel: value || "Tailor CV",
                  directApplication: true,
                });
              },
              no: function (value) {
                startApplyResultsSelectedRoleFlow(selected.key, "original", {
                  echoLabel: value || "Original CV",
                  directApplication: true,
                });
              },
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                if (
                  /tailor|tailored|improve|fix|strengthen|optimise|optimize/.test(
                    clean
                  )
                ) {
                  startApplyResultsSelectedRoleFlow(selected.key, "tailored", {
                    echoLabel: value || "Tailor CV",
                    directApplication: true,
                  });
                  return;
                }
                if (
                  /original|current|same cv|as is|without tailoring|don'?t tailor/.test(
                    clean
                  )
                ) {
                  startApplyResultsSelectedRoleFlow(selected.key, "original", {
                    echoLabel: value || "Original CV",
                    directApplication: true,
                  });
                  return;
                }
                if (
                  looksLikeConcreteApplyChatJobSearch(
                    value,
                    detectIntent(value)
                  )
                ) {
                  searchActualJobPostsInChat(value);
                  return;
                }
                focusComposer(getPremiumApplyIntroSelectionPrompt());
              },
            },
            getPremiumApplyIntroSelectionPrompt(),
            { selected_role_key: selected.key }
          );
          focusComposer(getPremiumApplyIntroSelectionPrompt());
        }
      );
    }

