    function showApplyIntroPostAnalysisDecision(analysis) {
      var assessment = buildApplyIntroAssessment(analysis || {});
      var hardBlocker =
        assessment.eligibility &&
        assessment.eligibility.blockers &&
        assessment.eligibility.blockers[0];
      applicationAssessment = assessment;
      applyCvAnalysis = analysis || {};
      applyIntroCommercialContext.routeOffered =
        shouldShowApplyIntroRouteSelector();
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Choosing how Senna should help",
        note: "I have compared the CV with the role and separated the current-application path from the wider job-search route.",
        cvStatus: "CV compared with role",
        coverStatus: "Not started yet",
        activeTab: "original",
      });
      var diagnosis =
        assessment.overallFit >= 76
          ? "You have a strong base for it. Your most relevant experience lines up well, but there are a few things I'd address before applying."
          : "There is a workable base here, but a few parts of the CV need clearer evidence before this application is as strong as it could be.";
      if (!shouldShowApplyIntroRouteSelector()) {
        applyIntroCommercialContext.routeSelected = "single_application";
        applyIntroCommercialContext.paidSearchSuppressed = true;
        activePath = "apply_for_me";
        step = "apply_upload";
        pendingApplyResultsSelection = getPremiumApplyIntroSelectedRole();
        pendingApplyResultsSelection = Object.assign(
          {},
          setCurrentApplicationContextFromQueueItem(
            pendingApplyResultsSelection
          ),
          {
            status: "Ready",
            cvMode: "tailored",
          }
        );
        commercialApplyQueueItemsState = [pendingApplyResultsSelection];
        commercialApplyQueueInitialized = true;
        commercialApplyQueueActivated = false;
        commercialApplyQueueDetailsMode = true;
        commercialApplyQueueActiveTab = "shortlist";
        commercialApplyQueueFilter = "all";
        rememberCommercialApplyQueueCatalogItems(
          commercialApplyQueueItemsState
        );
        botMessage(
          "I’ve compared your CV with this role." +
            renderApplyIntroApplicationInsightCard(assessment),
          humanComposeDelay("Your application fit is ready.", 900, 1600),
          function () {
            askApplyResultsSelectedRoleNextStep(
              pendingApplyResultsSelection,
              pendingApplyResultsSelection.key || ""
            );
          }
        );
        return;
      }
      if (hardBlocker) {
        askApplyIntroHardRequirementQuestion(hardBlocker);
        return;
      }
      botMessage(
        "I’ve compared your CV with the role. " +
          escapeHtml(diagnosis) +
          renderApplyIntroApplicationInsightCard(assessment) +
          renderApplyQuickPathSelector(),
        humanComposeDelay("Choose the CV version.", 1200, 2300),
        function () {
          setPromptState(
            "apply_cv_decision",
            {
              yes: function (value) {
                var selectedTailored = getPremiumApplyIntroSelectedRole();
                startApplyResultsSelectedRoleFlow(
                  selectedTailored && selectedTailored.key,
                  "tailored",
                  {
                    echoLabel: value || "Use Tailored CV",
                    directApplication: true,
                  }
                );
              },
              no: function (value) {
                var selectedOriginal = getPremiumApplyIntroSelectedRole();
                startApplyResultsSelectedRoleFlow(
                  selectedOriginal && selectedOriginal.key,
                  "original",
                  {
                    echoLabel: value || "Continue with original",
                    directApplication: true,
                  }
                );
              },
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                if (
                  /tailor|tailored|use.*cv|include|yes|better|improved/.test(
                    clean
                  )
                ) {
                  promptHandlers.yes(value || "Use Tailored CV");
                  return;
                }
                if (/original|current|old|continue|without|no|skip/.test(clean)) {
                  promptHandlers.no(value || "Continue with original");
                  return;
                }
                showPromptRecoveryMessage(
                  "apply_cv_decision",
                  "Quick check: should I include the tailored CV, or continue with the original?",
                  "Use Tailored CV or Continue with original",
                  value
                );
              },
            },
            "Use Tailored CV or Continue with original"
          );
          focusComposer("Use Tailored CV or Continue with original");
        }
      );
    }

    function askApplyIntroHardRequirementQuestion(requirement) {
      var concept =
        normaliseApplyIntroConcept(requirement && requirement.concept) ||
        "a required item";
      var question =
        "Before we change your CV, there's something more important. This role appears to require " +
        concept +
        ", and I can't find that clearly on your CV. Is this something you genuinely have?";
      botMessage(
        question,
        humanComposeDelay(cleanMessageText(question), 1200, 2400),
        function () {
          setPromptState(
            "apply_intro_hard_requirement",
            {
              yes: function (value) {
                echoPromptChoice(value || "Yes");
                clearPromptState();
                showApplyIntroPostAnalysisDecision(
                  Object.assign({}, applyCvAnalysis || {}, {
                    hard_requirement_confirmed: concept,
                  })
                );
              },
              no: function (value) {
                echoPromptChoice(value || "No");
                clearPromptState();
                botMessage(
                  "Then I wouldn't recommend tailoring your CV specifically for this role. I can still help you apply, or I can help you find similar roles where this requirement is less likely to block the application.",
                  humanComposeDelay(
                    "Then I wouldn't recommend tailoring your CV specifically for this role.",
                    1200,
                    2300
                  ),
                  function () {
                    setPromptState(
                      "apply_intro_blocker_next",
                      {
                        yes: function (reply) {
                          startApplyIntroManagedSearchRoute(
                            reply || "Find similar roles"
                          );
                        },
                        no: function (reply) {
                          startApplyIntroSingleApplicationRoute(
                            reply || "Apply anyway"
                          );
                        },
                        other: function (reply) {
                          if (
                            /similar|search|other/.test(
                              cleanMessageText(reply).toLowerCase()
                            )
                          ) {
                            startApplyIntroManagedSearchRoute(reply);
                            return;
                          }
                          startApplyIntroSingleApplicationRoute(
                            reply || "Apply anyway"
                          );
                        },
                      },
                      "Find similar roles or apply anyway"
                    );
                    addChoices(
                      [
                        {
                          label: "Find similar roles",
                          onClick: function () {
                            promptHandlers.yes("Find similar roles");
                          },
                        },
                        {
                          label: "Apply anyway",
                          onClick: function () {
                            promptHandlers.no("Apply anyway");
                          },
                        },
                      ],
                      "clarify"
                    );
                  }
                );
              },
              other: function (value) {
                showPromptRecoveryMessage(
                  "apply_intro_hard_requirement",
                  "I only need to know whether this is genuinely part of your background.",
                  "Yes or no",
                  value
                );
              },
            },
            "Yes or no"
          );
          addChoices(
            [
              {
                label: "Yes",
                onClick: function () {
                  promptHandlers.yes("Yes");
                },
              },
              {
                label: "No",
                onClick: function () {
                  promptHandlers.no("No");
                },
              },
            ],
            "clarify"
          );
        }
      );
    }

    function startApplyIntroManagedSearchRoute(value) {
      if (value) {
        echoPromptChoice(value);
      }
      clearPromptState();
      applyIntroCommercialContext.routeSelected = "managed_search";
      applyIntroCommercialContext.paidSearchSuppressed = false;
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Building your search strategy",
        note: "I am using the CV and current role as the starting point, without treating inferred preferences as confirmed preferences.",
        cvStatus: "Search profile drafted",
      });
      botSequenceForCurrentTurn(
        [
          {
            html: "Based on your background and this role, I'd start with this search.",
            delay: humanComposeDelay(
              "Based on your background and this role, I'd start with this search.",
              900,
              1600
            ),
          },
          {
            html: renderApplyIntroSearchStrategyCard(
              applicationAssessment ||
                buildApplyIntroAssessment(applyCvAnalysis || {})
            ),
            delay: humanComposeDelay(
              "Your search strategy is ready.",
              450,
              850
            ),
          },
        ],
        function () {
          setApplyIntroSearchStrategyPrompt();
        }
      );
    }

    function setApplyIntroSearchStrategyPrompt() {
      setPromptState(
        "apply_intro_search_strategy_confirm",
        {
          yes: function (reply) {
            confirmApplyIntroSearchStrategy(reply || "Looks right");
          },
          no: function (reply) {
            echoPromptChoice(reply || "Change something");
            focusComposer("Type what you want changed");
          },
          other: function (reply) {
            if (/change|edit|different|another/i.test(reply || "")) {
              echoPromptChoice(reply);
              focusComposer("Type what you want changed");
              return;
            }
            if (isMeaningfulFreeTextCaptureReply(reply)) {
              echoPromptChoice(reply);
              ensureApplyIntroState().constraints = cleanMessageText(
                reply || ""
              );
              botMessage(
                "I'll treat that as an adjustment to the search plan.",
                humanComposeDelay(
                  "I'll treat that as an adjustment to the search plan.",
                  700,
                  1300
                ),
                function () {
                  confirmApplyIntroSearchStrategy("");
                }
              );
              return;
            }
            confirmApplyIntroSearchStrategy(reply || "Looks right");
          },
        },
        "Looks right or change something"
      );
      focusComposer("Looks right or change something");
    }

    function confirmApplyIntroSearchStrategy(value) {
      if (value) {
        echoPromptChoice(value);
      }
      clearPromptState();
      if (hasPremiumMemberChatAccess()) {
        askApplyIntroSearchIntensity(value ? "" : "Looks right");
        return;
      }
      botSequenceForCurrentTurn(
        [
          {
            html: "I'd keep the search focused rather than going very broad. Your strongest positioning is still closest to this role, and that's where your current evidence will carry the most weight.",
            delay: humanComposeDelay(
              "I'd keep the search focused rather than going very broad.",
              1100,
              2100
            ),
          },
          {
            html: "That's how I'd run it. Instead of you repeatedly searching, tailoring your CV and working out who to contact, I can handle those parts with you as one ongoing search.",
            delay: humanComposeDelay("That's how I'd run it.", 1100, 2100),
          },
          {
            html: renderApplyIntroPackageCard(),
            delay: humanComposeDelay("Senna Job Search package", 450, 850),
          },
        ],
        function () {
          applyIntroCommercialContext.membershipOffered = true;
          setPromptState(
            "apply_intro_package_choice",
            {
              yes: function (reply) {
                askApplyIntroSearchIntensity(reply || "Start my job search");
              },
              no: function (reply) {
                startApplyIntroSingleApplicationRoute(
                  reply || "Just apply to this role"
                );
              },
              other: function (reply) {
                var clean = cleanMessageText(reply || "").toLowerCase();
                if (/start|membership|job search|monthly|package/.test(clean)) {
                  askApplyIntroSearchIntensity(reply);
                  return;
                }
                startApplyIntroSingleApplicationRoute(
                  reply || "Just apply to this role"
                );
              },
            },
            "Start my job search or just apply to this role"
          );
          focusComposer("Start my job search or just apply to this role");
        }
      );
    }

    function askApplyIntroSearchIntensity(value) {
      if (value) {
        echoPromptChoice(value);
      }
      clearPromptState();
      botMessage(
        renderApplyIntroSearchIntensityCard(),
        humanComposeDelay("How actively should I run the search?", 600, 1100),
        function () {
          setPromptState(
            "apply_intro_search_intensity",
            {
              yes: function (reply) {
                applyIntroSearchIntensitySelected(
                  "focused",
                  reply || "Focused"
                );
              },
              no: function (reply) {
                applyIntroSearchIntensitySelected("active", reply || "Active");
              },
              other: function (reply) {
                var clean = cleanMessageText(reply || "").toLowerCase();
                if (/aggressive|broad|high/.test(clean)) {
                  applyIntroSearchIntensitySelected("aggressive", reply);
                  return;
                }
                if (/focused|small|relevant/.test(clean)) {
                  applyIntroSearchIntensitySelected("focused", reply);
                  return;
                }
                applyIntroSearchIntensitySelected("active", reply || "Active");
              },
            },
            "Focused, Active or Aggressive"
          );
          focusComposer("Focused, Active or Aggressive");
        }
      );
    }

    function applyIntroSearchIntensitySelected(intensity, value) {
      var state = ensureApplyIntroState();
      echoPromptChoice(value);
      clearPromptState();
      state.supportMode = "both";
      state.priority = intensity === "focused" ? "fit" : "speed";
      state.applicationsPerWeek =
        intensity === "focused"
          ? "5"
          : intensity === "aggressive"
          ? "15"
          : "10";
      state.introsPerWeek =
        intensity === "focused" ? "1" : intensity === "aggressive" ? "5" : "3";
      state.lanePreference = intensity === "aggressive" ? "wider" : "close";
      continueApplyIntroToEmailCheck();
    }

    function startApplyIntroSingleApplicationRoute(value) {
      if (value) {
        echoPromptChoice(value);
      }
      clearPromptState();
      applyIntroCommercialContext.routeSelected = "single_application";
      applyIntroCommercialContext.paidSearchSuppressed = true;
      applyIntroCommercialContext.cvTailoringOffered = true;
      activePath = "apply_for_me";
      step = "apply_upload";
      botSequenceForCurrentTurn(
        [
          {
            html: "Absolutely. Let's just get this application right.",
            delay: humanComposeDelay(
              "Absolutely. Let's just get this application right.",
              750,
              1400
            ),
          },
          {
            html:
              "I found " +
              String(
                ((applicationAssessment && applicationAssessment.gaps) || [])
                  .length || 3
              ) +
              " things in your CV that could weaken it for this role.",
            delay: humanComposeDelay(
              "I found a few things in your CV that could weaken it for this role.",
              1000,
              1900
            ),
          },
        ],
        function () {
          continueApplyAfterAnalysis(applyCvAnalysis || {});
        }
      );
    }

    function getApplyIntroModeLabel(mode) {
      if (isArabicChat()) {
        if (mode === "applications") {
          return "طلبات توظيف فقط";
        }
        if (mode === "intros") {
          return "تعريفات مباشرة فقط";
        }
        return "الاثنان";
      }
      if (mode === "applications") {
        return "Applications only";
      }
      if (mode === "intros") {
        return "Recruiter intros only";
      }
      return "Both";
    }

    function getHomeLauncherEntryMode() {
      if (isReviewOnlyLauncher || launchMode === "profile_review") {
        return "profile_review";
      }
      if (launchMode === "role_entry") {
        return "apply_for_me";
      }
      if (isHomeLauncher) {
        return "apply_intro";
      }
      return homeLauncherMode ? homeLauncherMode.value : "search_apply";
    }

    function buildHomeLauncherProfileReviewContext(query, locationOverride) {
      return {
        profileReviewStart: true,
        entryRoute: "profile_review_home",
        query: cleanMessageText(query || ""),
        location: cleanMessageText(locationOverride || ""),
      };
    }

    function buildHomeLauncherApplyIntroContext(query, locationOverride) {
      var cleanQuery = cleanMessageText(query || "");
      var structured = parseStructuredSearchReply(cleanQuery);
      var facts = extractConversationFacts(cleanQuery);
      var location = structured.location || locationOverride || "";
      return {
        entryRoute: "apply_intro_home",
        query: cleanQuery,
        mode: "apply_intro",
        roleTarget: structured.roleTarget || "",
        location: location,
        schedule: structured.schedule || "",
        qualifications: dedupeList(
          (facts.target_qualifications || []).concat(
            structured.qualifications || []
          )
        ),
        experienceYears: Math.max(
          Number(facts.experience_years || 0),
          Number(structured.experienceYears || 0) || 0
        ),
        facts: facts,
      };
    }

    function buildHomeLauncherApplyForMeContext(query, locationOverride) {
      var context = buildHomeLauncherApplyIntroContext(query, locationOverride);
      context.entryRoute = "apply_for_me_role_discovery_home";
      context.mode = "apply_for_me";
      return context;
    }

    function buildActiveLauncherContext(query) {
      var entryMode = getHomeLauncherEntryMode();
      if (entryMode === "profile_review") {
        return buildHomeLauncherProfileReviewContext(
          query,
          homeLauncherSelectedLocation
        );
      }
      if (entryMode === "apply_for_me") {
        return buildHomeLauncherApplyForMeContext(
          query,
          homeLauncherSelectedLocation
        );
      }
      if (isHomeLauncher) {
        return buildHomeLauncherApplyIntroContext(
          query,
          homeLauncherSelectedLocation
        );
      }
      return buildLauncherSearchContext(
        query,
        getHomeLauncherEntryMode(),
        homeLauncherSelectedLocation
      );
    }

    function buildHomeTrendingJobLaunchContext(card) {
      var title = cleanMessageText(
        card ? card.getAttribute("data-role-title") || "" : ""
      );
      var company = cleanMessageText(
        card ? card.getAttribute("data-role-company") || "" : ""
      );
      var location = cleanMessageText(
        card ? card.getAttribute("data-role-location") || "" : ""
      );
      var roleUrl = cleanMessageText(
        card ? card.getAttribute("data-role-url") || "" : ""
      );
      return {
        entryRoute: "home_trending_job",
        mode: "apply_for_me",
        query: [title, company ? "at " + company : "", location]
          .filter(Boolean)
          .join(" "),
        roleTarget: title,
        location: location,
        selectedRole: {
          title: title,
          company: company,
          location: location,
          sector: cleanMessageText(
            card ? card.getAttribute("data-role-sector") || "" : ""
          ),
          seniority: cleanMessageText(
            card ? card.getAttribute("data-role-seniority") || "" : ""
          ),
          salary: cleanMessageText(
            card ? card.getAttribute("data-role-salary") || "" : ""
          ),
          companyLogo: cleanMessageText(
            card ? card.getAttribute("data-role-logo") || "" : ""
          ),
          viewUrl: roleUrl,
          applyUrl: roleUrl,
          postId: cleanMessageText(
            card ? card.getAttribute("data-role-post-id") || "" : ""
          ),
          jobsPostId: cleanMessageText(
            card ? card.getAttribute("data-role-jobs-post-id") || "" : ""
          ),
        },
      };
    }

    function isHomeApplyIntroLaunchContext(context) {
      return !!(
        isHomeLauncher &&
        context &&
        cleanMessageText(context.entryRoute || "") === "apply_intro_home"
      );
    }

    function classifyApplyIntroVolumeReply(value, allowed) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      var options = Array.isArray(allowed) ? allowed : [];
      var number = "";
      if (!clean) {
        return "";
      }
      if (
        /\b(?:15|fifteen)\b(?:\s+(?:applications?|apps?|intros?|introductions?|contacts?|recruiter contacts?))?/i.test(
          clean
        ) ||
        /(?:١٥|خمسة عشر)(?:\s*(?:طلبات|تقديمات|تعريفات|جهات تواصل))?/i.test(
          clean
        )
      ) {
        number = "15";
      } else if (
        /\b(?:10|ten)\b(?:\s+(?:applications?|apps?|intros?|introductions?|contacts?|recruiter contacts?))?/i.test(
          clean
        ) ||
        /(?:١٠|عشرة)(?:\s*(?:طلبات|تقديمات|تعريفات|جهات تواصل))?/i.test(clean)
      ) {
        number = "10";
      } else if (
        /\b(?:5|five)\b(?:\s+(?:applications?|apps?|intros?|introductions?|contacts?|recruiter contacts?))?/i.test(
          clean
        ) ||
        /(?:٥|خمسة)(?:\s*(?:طلبات|تقديمات|تعريفات|جهات تواصل))?/i.test(clean)
      ) {
        number = "5";
      } else if (
        /\b(?:3|three)\b(?:\s+(?:applications?|apps?|intros?|introductions?|contacts?|recruiter contacts?))?/i.test(
          clean
        ) ||
        /(?:٣|ثلاثة)(?:\s*(?:طلبات|تقديمات|تعريفات|جهات تواصل))?/i.test(clean)
      ) {
        number = "3";
      } else if (
        /\b(?:1|one)\b(?:\s+(?:applications?|apps?|intros?|introductions?|contacts?|recruiter contacts?))?/i.test(
          clean
        ) ||
        /(?:١|واحد|واحدة)(?:\s*(?:طلبات|تقديمات|تعريفات|جهات تواصل))?/i.test(
          clean
        )
      ) {
        number = "1";
      }
      if (!number || options.indexOf(number) === -1) {
        return "";
      }
      return number;
    }

    function formatApplyIntroVolumeLabel(count, type) {
      var cleanCount = cleanMessageText(count || "");
      if (!cleanCount) {
        return "";
      }
      if (isArabicChat()) {
        if (type === "applications") {
          return cleanCount + " طلبات أسبوعياً";
        }
        return cleanCount + " تعريفات أسبوعياً";
      }
      return cleanCount + " per week";
    }

    function getApplyIntroVolumePrompt(type) {
      if (isArabicChat()) {
        if (type === "applications") {
          return "كم طلب توظيف مخصص تريدينني أن أعمل عليه كل أسبوع؟";
        }
        return "كم تعريف مباشر تريدينني أن أجهزه لك كل أسبوع؟";
      }
      if (type === "applications") {
        return "How many tailored applications do you want me to work on each week?";
      }
      return "How many recruiter intros do you want me to prepare each week?";
    }

    function getApplyIntroVolumeClarify(type) {
      if (isArabicChat()) {
        if (type === "applications") {
          return "فقط اختاري: 5 أسبوعياً، أو 10 أسبوعياً، أو 15 أسبوعياً.";
        }
        return "فقط اختاري: 1 أسبوعياً، أو 3 أسبوعياً، أو 5 أسبوعياً.";
      }
      if (type === "applications") {
        return "Just choose 5 per week, 10 per week, or 15 per week.";
      }
      return "Just choose 1 per week, 3 per week, or 5 per week.";
    }

    function getApplyIntroMembershipAccountType() {
      var state = ensureApplyIntroState();
      return state.supportMode === "intros" ? "mentorship" : "all_access";
    }

    function classifyApplyIntroModeReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      if (!clean) {
        return "";
      }
      if (
        /\b(?:both|all of it|all three|the two of them|everything|both routes|applications? and intros?|intros? and applications?|do both|both please|both of those|both would help|all of the above|the full thing|full support|all together|run both|cover both)\b/i.test(
          clean
        ) ||
        /(?:الاثنين|الاثنان|كلاهما|الاثنين معًا|الاثنين معا|الكل|كلهم|أبغى الاثنين|ابي الاثنين|أريد الاثنين|الاثنين يفيدوني|أبغى الكل|أبي الكل|أريد الكل|سوّي الاثنين|اعملي الاثنين)/i.test(
          clean
        )
      ) {
        return "both";
      }
      if (
        /\b(?:tailored job applications?|job applications?|applications?|apps?|apply for roles?|application side|tailored applications?|tailor the applications?|help me apply|do the applications?|application route|apply for me|submission support|send applications? for me|handle the applications?|application help)\b/i.test(
          clean
        ) ||
        /(?:طلبات توظيف|التقديمات|التقديمات المخصصة|التقديمات|جهة التقديم|مسار التقديم|قدمي لي|ساعديني بالتقديم|أبغى التقديم|ابي التقديم|أريد التقديم|التقديم فقط|الطلبات فقط|ارسلي التقديمات|قدمي عني)/i.test(
          clean
        )
      ) {
        return "applications";
      }
      if (
        /\b(?:direct recruiter intros?|recruiter intros?|recruiter intro|direct intros?|intros?|contact recruiters?|recruiter contacts?|intro route|reach out to recruiters?|do the intros?|recruiter outreach|outreach only|contact route|speak to recruiters|message recruiters)\b/i.test(
          clean
        ) ||
        /(?:تعريفات مباشرة|تعريفات|التعريفات|تعريف مباشر|جهات التوظيف|المجندين|المُجندين|التواصل مع جهات التوظيف|تواصل مع المجندين|أبغى تعريفات|ابي تعريفات|أريد تعريفات|التواصل فقط|تعريفات فقط|وصّليني بجهات التوظيف|تواصلي مع المجندين)/i.test(
          clean
        )
      ) {
        return "intros";
      }
      return "";
    }

    function classifyApplyIntroLaneReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      if (!clean) {
        return "";
      }
      if (
        /\b(?:keep it close|close to that|stay close|keep it in that lane|recent background|same lane|main lane|current lane|close to my background|keep it tight|stay in lane|closer to my cv|more like my recent work|stick close|stay focused|keep it relevant|same kind of roles?)\b/i.test(
          clean
        ) ||
        /(?:خليه قريب|خلّيها قريبة|خلها قريبة|خليها قريبه|أبقيه قريباً|قريب من خبرتي|قريب من خلفيتي|خليه على نفس المسار|نفس المسار|في نفس المسار|قريب من عملي الأخير|خلك قريب|قريب من السي في|خلّه مركز|بنفس نوع الأدوار)/i.test(
          clean
        )
      ) {
        return "close";
      }
      if (
        /\b(?:stretch|stretch a bit|widen|go wider|adjacent|bridge|use it as a bridge|broaden|move beyond|different lane|branch out|a bit wider|slightly wider|more adjacent|open it up|go broader|push it wider|expand it)\b/i.test(
          clean
        ) ||
        /(?:وسعها|وسّعها|وسعها شوي|وسعها قليل|وسعها قليلاً|أوسعها|أوسعه|أوسّعه|وسع المسار|مجال مجاور|شيء مجاور|كجسر|استخدمه كجسر|مسار مختلف|أبعد شوي|خارج مساري شوي|افتحها شوي|بشكل أوسع|أوسع شوي)/i.test(
          clean
        )
      ) {
        return "wider";
      }
      return "";
    }

    function classifyApplyIntroPriorityReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      if (!clean) {
        return "";
      }
      if (
        /\b(?:speed|faster|fastest|quicker|quickest|move fast|faster interviews?|get interviews? faster|speed first|prioriti[sz]e speed|optimis[ze] for speed)\b/i.test(
          clean
        ) ||
        /\b(?:intro first|intros first|recruiter intro first|recruiter intros first|contacts first|start with intros|do the intro first|recruiter first|lead with intros|begin with intros|start on the intros)\b/i.test(
          clean
        ) ||
        /(?:السرعة|أسرع|بسرعة|مقابلات أسرع|سرعة أولاً|السرعة أولاً|ركزي على السرعة)/i.test(
          clean
        ) ||
        /(?:التعريف أولاً|التعريف اولا|ابدئي بالتعريف|ابدأ بالتعريف|التواصل أول|جهات التوظيف أول|المجندين أول|التعريف في البداية|ابدئي بالتعريفات|التعريفات أولاً)/i.test(
          clean
        )
      ) {
        return "speed";
      }
      if (
        /\b(?:fit|better fit|best fit|closer fit|tighter fit|stronger fit|quality first|better matched roles?|better-fit roles?|optimis[ze] for fit|prioriti[sz]e fit)\b/i.test(
          clean
        ) ||
        /\b(?:application first|applications first|apply first|job applications first|tailored applications first|start with the application|start with the apps?|do the applications first|lead with applications|begin with applications|start on the applications|apps? first)\b/i.test(
          clean
        ) ||
        /(?:الملاءمة|أنسب|أفضل ملاءمة|أفضل تطابق|جودة أعلى|ركزي على الملاءمة|الملاءمة أولاً)/i.test(
          clean
        ) ||
        /(?:التقديم أولاً|التقديم اولا|ابدئي بالتقديم|ابدأ بالتقديم|خل التقديم أول|التقديم أول|ابدئي بالتطبيق|التقديم في البداية|ابدئي بالطلبات|خل الطلبات أول|التقديمات أولاً)/i.test(
          clean
        )
      ) {
        return "fit";
      }
      return "";
    }

    function isApplyIntroNoExtraReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return (
        /^(?:no|none|nothing|nothing else|nope|nah|you'?re good|youre good|all good|that'?s it|thats it|no that'?s all|no thats all|nothing to add|no constraints|none from me|nah nothing major|nothing major|no major constraints?)$/i.test(
          clean
        ) ||
        /^(?:لا|مافي|ما فيه|ولا شيء|ولا شي|بس كذا|هذا كل شيء|هذا كل شي|ما عندي شيء|ما عندي شي|ما عندي قيود|أنتِ تمام|انتي تمام)$/i.test(
          clean
        )
      );
    }

    function classifyApplyIntroHomeRoleReply(value, fallbackRole) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      var fallback = cleanMessageText(fallbackRole || "");
      if (!clean) {
        return "";
      }
      if (
        fallback &&
        /(?:keep that|keep it there|stick with that|same role|same lane|that role|that lane|keep the same focus|use that focus|same focus|carry on with that|that one|same thing|keep that focus)/i.test(
          clean
        )
      ) {
        return fallback;
      }
      if (
        fallback &&
        /(?:خله|خلّه|خليها|خلّيها|نفسه|نفسها|نفس المسار|نفس الدور|أبقيه|أبقيها|خليه كما هو|خليها كما هي|على نفس التركيز)/i.test(
          clean
        )
      ) {
        return fallback;
      }
      if (isMeaningfulFreeTextCaptureReply(value)) {
        return cleanMessageText(value);
      }
      return "";
    }

    function isApplyIntroNoSectorPreferenceReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return (
        /^(?:no|none|nothing specific|no sector preference|no sector|open|open to sectors?|any sector|no preference|nothing there)$/i.test(
          clean
        ) ||
        /^(?:لا|مافي|ما فيه|بدون قطاع محدد|أي قطاع|مفتوح|لا تفضيل|لا يوجد تفضيل)$/i.test(
          clean
        )
      );
    }

    function isApplyIntroKeepMarketReply(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return (
        /(?:keep that market|keep this market|same market|stick with that market|use that market|keep it there|keep that location|same location|stay there)/i.test(
          clean
        ) ||
        /(?:خله على نفس السوق|خلّه على نفس السوق|نفس السوق|أبقي السوق|على نفس الموقع|نفس الموقع|خله هناك|خلّه هناك)/i.test(
          clean
        )
      );
    }

