    function askApplyIntroHomeMarketQuestion() {
      var state = ensureApplyIntroState();
      var prompt = getApplyIntroHomeMarketPrompt();
      botMessage(
        prompt,
        humanComposeDelay(cleanMessageText(prompt), 1100, 2000),
        function () {
          setPromptState(
            "apply_intro_home_market",
            {
              other: function (value) {
                var extractedLocations = extractMentionedSearchLocations(value);
                clearPromptState();
                echoPromptChoice(value);
                if (
                  state.preferredMarket &&
                  isApplyIntroKeepMarketReply(value)
                ) {
                  askApplyIntroHelpfulQuestion();
                  return;
                }
                if (isApplyIntroNoExtraReply(value)) {
                  state.preferredMarket = "";
                  askApplyIntroHelpfulQuestion();
                  return;
                }
                if (extractedLocations.length) {
                  state.preferredMarket = extractedLocations[0];
                  jobSearchPreferredLocation = state.preferredMarket;
                  askApplyIntroHelpfulQuestion();
                  return;
                }
                if (isMeaningfulFreeTextCaptureReply(value)) {
                  state.preferredMarket = cleanMessageText(value);
                  jobSearchPreferredLocation = state.preferredMarket;
                  askApplyIntroHelpfulQuestion();
                  return;
                }
                showPromptRecoveryMessage(
                  "apply_intro_home_market",
                  isArabicChat()
                    ? "قولي لي السوق الذي تريدينه، أو قولي لا إذا لا يوجد تفضيل."
                    : "Tell me the market you want in focus, or just say no if there is no preference.",
                  getComposerPlaceholder("reply"),
                  value
                );
              },
            },
            getComposerPlaceholder("reply")
          );
          focusComposer(getComposerPlaceholder("reply"));
          addChoices(
            [
              state.preferredMarket
                ? {
                    label: state.preferredMarket,
                    onClick: function () {
                      userMessage(state.preferredMarket);
                      clearPromptState();
                      askApplyIntroHelpfulQuestion();
                    },
                  }
                : null,
              {
                label: isArabicChat() ? "سأكتب السوق" : "I'll type the market",
                onClick: function () {
                  triggerPromptRecoveryChoice(
                    isArabicChat() ? "سأكتب السوق" : "I'll type the market",
                    "Another market"
                  );
                },
              },
            ].filter(Boolean),
            "clarify"
          );
        }
      );
    }

