    function continueApplyIntroAfterCvUpload() {
      var previousState;
      if (jobSearchCvAcknowledged) {
        return;
      }
      jobSearchCvAcknowledged = true;
      previousState = ensureApplyIntroState();
      resetApplyIntroState();
      applyIntroState.homeEntry = !!previousState.homeEntry;
      applyIntroState.queryConfirmed = !!previousState.queryConfirmed;
      applyIntroState.desiredRole = previousState.desiredRole || "";
      applyIntroState.preferredSectors = previousState.preferredSectors || "";
      applyIntroState.preferredMarket = previousState.preferredMarket || "";
      applyIntroState.originalBrief = previousState.originalBrief || "";
      step = "apply_intro_analysis";
      if (hasPremiumMemberChatAccess()) {
        updateWorkspace({
          visible: getAutoWorkspaceVisibility(),
          stage: "Preparing selected role",
          note: "Premium member path: saved CV and selected role are ready for application execution.",
          cvStatus: "Saved CV ready",
          coverStatus: "Not started yet",
        });
        showApplyIntroPostAnalysisDecision(applyCvAnalysis || {});
        return;
      }
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Reviewing CV",
        note: "I am comparing the CV directly with this role before recommending the next route.",
        cvStatus: "Reviewing CV",
        coverStatus: "Not started yet",
      });
      botMessage(
        renderApplyIntroAnalysisProgressCard(),
        humanComposeDelay("Reviewing your CV", 900, 1600),
        function () {
          window.setTimeout(function () {
            showApplyIntroPostAnalysisDecision(applyCvAnalysis || {});
          }, randomBetween(900, 1700));
        }
      );
    }

    function continueApplyIntroFromSavedCv() {
      uploadButton.hidden = true;
      input.disabled = false;
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: hasPremiumMemberChatAccess()
          ? "Preparing selected role"
          : "Reading your CV for the application and intro route",
        note: hasPremiumMemberChatAccess()
          ? "I'm using the active CV already saved on the member account and keeping the flow centered on the selected application."
          : "I'm using the active CV already saved on your account, so I can move straight into the route planning.",
        fileName: getLoggedInActiveCvLabel(),
        cvStatus: hasPremiumMemberChatAccess()
          ? "Saved CV ready"
          : "Saved CV ready for route planning",
        coverStatus: "Not started yet",
        activeTab: "original",
      });
      if (
        loggedInResumeContext &&
        loggedInResumeContext.activeFileUrl &&
        loggedInResumeContext.activeFileType === "pdf"
      ) {
        setWorkspacePreviewFromPdfUrl(loggedInResumeContext.activeFileUrl);
      }
      if (hasPremiumMemberChatAccess()) {
        ensureLoggedInSavedCvText()
          .then(function (ready) {
            if (!ready) {
              throw new Error(
                "I could not load the saved CV from your account just now."
              );
            }
            return fetchCvAnalysis(capturedCvText)
              .then(function (analysis) {
                mergeCvFacts(analysis || {});
                applyCvAnalysis = analysis || {};
                return analysis || {};
              })
              .catch(function () {
                return {};
              });
          })
          .then(function () {
            beginPremiumApplyIntroSelectedRoleFlow();
          })
          .catch(function () {
            if (loggedInResumeContext) {
              loggedInResumeContext = normalizeLoggedInResumeContext(
                Object.assign({}, loggedInResumeContext, {
                  has_cv: false,
                  cv_text: "",
                  active_file_url: "",
                })
              );
            }
            botMessage(
              "I couldn't read the saved CV properly just now. Upload a fresh copy and I'll use that for this application.",
              humanComposeDelay(
                "I couldn't read the saved CV properly just now.",
                1200,
                2400
              ),
              function () {
                uploadButton.hidden = false;
                focusComposer("Upload the CV for this application");
              }
            );
          });
        return;
      }
      botMessage(
        "I've already got your CV. I'll compare it with the role now.",
        humanComposeDelay(
          "I've already got your CV. I'll compare it with the role now.",
          1500,
          2800
        ),
        function () {
          ensureLoggedInSavedCvText()
            .then(function (ready) {
              if (!ready) {
                throw new Error(
                  "I could not load the saved CV from your account just now."
                );
              }
              return fetchCvAnalysis(capturedCvText)
                .then(function (analysis) {
                  mergeCvFacts(analysis || {});
                  return analysis || {};
                })
                .catch(function () {
                  return {};
                });
            })
            .then(function (analysis) {
              applyCvAnalysis = analysis || applyCvAnalysis || {};
              continueApplyIntroAfterCvUpload();
            })
            .catch(function () {
              if (loggedInResumeContext) {
                loggedInResumeContext = normalizeLoggedInResumeContext(
                  Object.assign({}, loggedInResumeContext, {
                    has_cv: false,
                    cv_text: "",
                    active_file_url: "",
                  })
                );
              }
              botMessage(
                "I couldn't read the saved CV properly just now. If you want, upload a fresh copy and I'll use that instead.",
                humanComposeDelay(
                  "I couldn't read the saved CV properly just now.",
                  1800,
                  3600
                ),
                function () {
                  uploadButton.hidden = false;
                  focusComposer("Upload your CV or paste it here");
                }
              );
            });
        }
      );
    }

