    function askLoggedInMemberNewDirection() {
      var prompt = isArabicChat()
        ? "ما الاتجاه الجديد الذي تريدينني أن أتعامل معه؟"
        : "What new direction do you want me to treat as primary?";
      botMessage(
        prompt,
        humanComposeDelay(cleanMessageText(prompt), 1500, 2600),
        function () {
          setPromptState(
            "job_search_member_new_direction",
            {
              other: function (value) {
                var signals = extractJobSearchPreferenceSignals(value);
                var clean = cleanMessageText(value || "");
                var inferredTarget = cleanMessageText(
                  (signals.roleTargets && signals.roleTargets[0]) || clean
                );
                if (!inferredTarget) {
                  showPromptRecoveryMessage(
                    "job_search_member_new_direction",
                    isArabicChat()
                      ? "اذكري لي الدور أو المسار الذي تريدينني أن أبني حوله البحث."
                      : "Tell me the role lane or search direction you want me to build around.",
                    isArabicChat()
                      ? "اذكري الاتجاه"
                      : "Tell me the new direction",
                    value
                  );
                  return;
                }
                clearPromptState();
                echoPromptChoice(value);
                applyLoggedInMemberTargetFunction(inferredTarget);
                if (signals.hasMeaningfulSignals) {
                  applyJobSearchPreferenceSignals(signals);
                }
                botMessage(
                  isArabicChat()
                    ? "واضح. سأتعامل مع " +
                        escapeHtml(inferredTarget) +
                        " كاتجاه جديد بدلاً من خلطه ببحثك السابق."
                    : "Understood. I’ll treat " +
                        escapeHtml(inferredTarget) +
                        " as a new search direction rather than mixing it into the old one.",
                  humanComposeDelay(
                    cleanMessageText(inferredTarget),
                    1600,
                    2800
                  ),
                  askLoggedInMemberTargetMarket
                );
              },
            },
            isArabicChat() ? "اذكري الاتجاه" : "Tell me the new direction"
          );
          focusComposer(
            isArabicChat() ? "اذكري الاتجاه" : "Tell me the new direction"
          );
        }
      );
    }

    function showLoggedInMemberSearchKickoff() {
      var firstName = cleanMessageText(
        userName || getConfig().currentUserFirstName || ""
      );
      var prioritySnapshot = getLoggedInMemberPrioritySnapshot();
      var previousFocus = getLoggedInMemberPreviousFocusSummary();
      var roleType = getLoggedInMemberPrimaryTarget();
      var sectorFocus = getLoggedInMemberPrimarySector();
      var locationFocus = getLoggedInMemberPreferredLocation();
      var rememberedFocus = [
        roleType ? roleType + " roles" : "",
        sectorFocus ? "in " + sectorFocus : "",
        locationFocus ? "in " + locationFocus : "",
      ]
        .filter(Boolean)
        .join(" ");
      var intro = isArabicChat()
        ? (firstName ? "أهلاً بعودتك، " + firstName + ". " : "أهلاً بعودتك. ") +
          "ما زلت أحتفظ بملفك وسياق بحثك السابق، لذلك لن نبدأ من الصفر."
        : (firstName ? "Welcome back, " + firstName + ". " : "Welcome back. ") +
          (rememberedFocus
            ? "Are you still looking for " + rememberedFocus + "?"
            : "I still have your profile and previous search context, so we do not need to start again.");
      var focusLine = previousFocus
        ? isArabicChat()
          ? "عندما كنت هنا آخر مرة، كان التركيز على " +
            escapeHtml(previousFocus) +
            "."
          : "When you were last here, we were focused on " +
            escapeHtml(previousFocus) +
            "."
        : isArabicChat()
        ? "لدي سياقك السابق محفوظ بالفعل."
        : "I still have the shape of your earlier search in mind.";
      var proactiveLine =
        prioritySnapshot && prioritySnapshot.recommendationLine
          ? prioritySnapshot.recommendationLine
          : isArabicChat()
          ? "أريد أن أتعامل مع هذا كبحث حي: ما الذي تغير، وما الذي يستحق الاهتمام الآن، وما الذي ينبغي أن أفعله تالياً."
          : "We can continue the search from there, or update the criteria before I show the next batch of roles.";
      resetLoggedInMemberStrategyState();
      ensureLoggedInMemberStrategyState().previousFocus = previousFocus;
      botSequenceForCurrentTurn(
        [
          {
            html: intro,
            delay: humanComposeDelay(cleanMessageText(intro), 1500, 2600),
          },
          {
            html: focusLine,
            delay: humanComposeDelay(cleanMessageText(focusLine), 1500, 2600),
            pause: humanReadDelay(cleanMessageText(intro), 260),
          },
          {
            html: proactiveLine,
            delay: humanComposeDelay(
              cleanMessageText(proactiveLine),
              1700,
              3000
            ),
            pause: humanReadDelay(cleanMessageText(focusLine), 260),
          },
        ],
        function () {
          showLoggedInLauncherChoices();
        }
      );
    }

    function handleLoggedInMemberSeededIntent() {
      var intentMode = cleanMessageText(
        (jobSearchSeedContext && jobSearchSeedContext.memberLaunchIntent) || ""
      );
      var query = cleanMessageText(
        (jobSearchSeedContext && jobSearchSeedContext.query) || ""
      );
      var answer = "";
      if (
        !getConfig().isLoggedIn ||
        !hasReturningConversationMemory() ||
        !intentMode ||
        !query
      ) {
        return false;
      }
      if (intentMode === "career_direction") {
        answer = getKnowledgeAnswer("career_direction", query);
      } else if (intentMode === "salary_market") {
        answer = getKnowledgeAnswer("job_search_strategy", query);
      } else if (intentMode === "daily_brief") {
        answer = buildLoggedInDailyBriefAdvice();
      } else if (intentMode === "strategy_review") {
        answer = buildLoggedInStrategyReviewAdvice();
      } else if (intentMode === "blockers_review") {
        answer = buildLoggedInBlockersReviewAdvice();
      } else if (intentMode === "market_watch") {
        answer = buildLoggedInMarketWatchAdvice();
      } else if (intentMode === "priority_tasks") {
        answer = buildLoggedInPriorityTasksAdvice();
      } else if (intentMode === "pipeline_desk") {
        answer = buildLoggedInPipelineDeskAdvice();
      } else if (intentMode === "recruiter_activity") {
        answer = buildLoggedInRecruiterActivityAdvice();
      } else if (intentMode === "recruiter_strategy") {
        answer = buildLoggedInRecruiterStrategyAdvice(query);
      } else if (intentMode === "search_health") {
        answer = buildLoggedInSearchHealthAdvice();
      } else if (intentMode === "application_desk") {
        answer = buildLoggedInApplicationDeskAdvice();
      } else if (intentMode === "interview_desk") {
        answer = buildLoggedInInterviewDeskAdvice();
      }
      if (!answer) {
        return false;
      }
      botMessage(
        answer,
        humanComposeDelay(cleanMessageText(answer), 1800, 3200),
        function () {
          beginJobSearchContinuityConversation("returning_member");
        }
      );
      return true;
    }

    function startConsultantFlow(route) {
      resetMatchingCvConversationState();
      resetJobSearchContinuityState();
      resetLoggedInMemberStrategyState();
      resetApplyIntroState();
      if (route === "job_search") {
        if (getConfig().isLoggedIn) {
          beginLoggedInJobSearchFlow(jobSearchSeedContext, {
            mode: jobSearchSelectedPackage || "",
            launchMode: jobSearchLaunchMode || "",
          });
          return;
        }
        activePath = route;
        step = "job_search_upload";
        jobSearchCvAcknowledged = false;
        var transferToEmilyCopy = getInterfaceCopy("transfer_emily");
        addTransferNotice(transferToEmilyCopy);
        setDeskIdentity("emily");
        var introLine = getJobSearchEmilyIntroLine();
        var backgroundSearchLine = getJobSearchBackgroundSearchLine();
        var uploadPromptLine = getJobSearchUploadPromptLine();
        botSequenceForCurrentTurn(
          [
            {
              html: introLine,
              delay: humanComposeDelay(introLine, 1800, 3400),
              pause: humanReadDelay(transferToEmilyCopy, 420),
            },
            {
              html: backgroundSearchLine,
              delay: humanComposeDelay(backgroundSearchLine, 2200, 4200),
              pause: humanReadDelay(introLine, 420),
            },
            {
              html: uploadPromptLine,
              delay: humanComposeDelay(uploadPromptLine, 1800, 3400),
              pause: humanReadDelay(backgroundSearchLine, 420),
            },
          ],
          function () {
            if (hasLoggedInSavedCv()) {
              continueJobSearchFromSavedCv();
              return;
            }
            uploadButton.hidden = false;
            focusComposer(getUploadCvPlaceholder());
          }
        );
        return;
      }

      if (route === "apply_intro") {
        if (getConfig().isLoggedIn && hasLoggedInSavedCv()) {
          activePath = route;
          addTransferNotice(getInterfaceCopy("transfer_consultant"));
          setDeskIdentity("emily");
          continueApplyIntroFromSavedCv();
          return;
        }
        activePath = route;
        step = "apply_intro_upload";
        jobSearchCvAcknowledged = false;
        addTransferNotice(getInterfaceCopy("transfer_consultant"));
        setDeskIdentity("emily");
        botSequenceForCurrentTurn(
          [
            {
              html: isArabicChat()
                ? "سأتولى هذا معك."
                : "Emily here. I’ll handle this with you.",
              delay: humanComposeDelay(
                "Emily here. I’ll handle this with you.",
                1100,
                2000
              ),
            },
            {
              html: isArabicChat()
                ? "أرسلِي الـCV أولاً. سأستخدمه مع هذا الدور حتى أقرر أفضل طريقة أساعدك بها."
                : "Start with your CV so I can read this role against your actual background before we choose the best route.",
              delay: humanComposeDelay(
                "Start with your CV so I can read this role against your actual background before we choose the best route.",
                1500,
                2800
              ),
              pause: humanReadDelay("Emily here. I’ll handle this with you.", 320),
            },
          ],
          function () {
            uploadButton.hidden = false;
            focusComposer(getUploadCvPlaceholder());
          }
        );
        return;
      }

      if (route !== "review_profile") {
        if (getConfig().isLoggedIn && hasLoggedInSavedCv()) {
          activePath = route;
          addTransferNotice(getInterfaceCopy("transfer_consultant"));
          setDeskIdentity("emily");
          beginApplyForMeFlow();
          return;
        }
        activePath = route;
        step = "apply_upload";
        addTransferNotice(getInterfaceCopy("transfer_consultant"));
        var consultantIntro = getApplyConsultantIntro(route);
        setDeskIdentity("emily");
        botMessage(
          consultantIntro,
          humanComposeDelay(cleanMessageText(consultantIntro), 3200, 6200),
          function () {
            uploadButton.hidden = false;
            focusComposer(getUploadCvPlaceholder());
          }
        );
        return;
      }

      var routeCopy =
        route === "review_profile"
          ? pickVariant("consultant_route_review_profile", [
              "I can see you want help reviewing your profile for the " +
                escapeHtml(roleTitle) +
                " role. Is that right?",
              "It looks like you want help reviewing your profile against the " +
                escapeHtml(roleTitle) +
                " role. Is that correct?",
              "I can see you're here for profile feedback on the " +
                escapeHtml(roleTitle) +
                " role. Is that right?",
              "It looks like you want me to review your profile for the " +
                escapeHtml(roleTitle) +
                " role. Is that correct?",
            ])
          : pickVariant("consultant_route_apply_for_me", [
              "I can see you want help applying for the " +
                escapeHtml(roleTitle) +
                " role. Is that right?",
              "It looks like you want help applying for the " +
                escapeHtml(roleTitle) +
                " role. Is that correct?",
              "I can see you're here for help with the " +
                escapeHtml(roleTitle) +
                " application. Is that right?",
              "It looks like you want me to help with the " +
                escapeHtml(roleTitle) +
                " application. Is that correct?",
            ]);

      activePath = route;
      step = "consultant_confirm";
      addTransferNotice(getInterfaceCopy("transfer_consultant"));
      var consultantIntro = getApplyConsultantIntro(route) + " " + routeCopy;
      setDeskIdentity("emily");
      botMessage(
        consultantIntro,
        humanComposeDelay(consultantIntro, 2600, 5200),
        function () {
          setPromptState(
            "consultant_route_confirm",
            {
              yes: function () {
                if (route === "review_profile") {
                  promptForCv();
                  return;
                }
                beginApplyForMeFlow();
              },
              no: function () {
                var clarifyChoiceLabels;
                botMessage(
                  "Okay, just to clarify, are you happy to proceed?",
                  humanComposeDelay(
                    "Okay, just to clarify, are you happy to proceed?",
                    1700,
                    3400
                  ),
                  function () {
                    clarifyChoiceLabels = getBinaryChoiceLabels("clarify");
                    setPromptState(
                      "consultant_route_clarify",
                      {
                        yes: function () {
                          if (route === "review_profile") {
                            promptForCv();
                            return;
                          }
                          beginApplyForMeFlow();
                        },
                        no: function () {
                          var declineCopy = pickVariant(
                            "route_clarify_decline_reply",
                            [
                              "That’s fine. I’ll leave that route alone. Tell me the role, market, CV issue, or career question you want to focus on instead.",
                              "No issue. I won’t move that workflow forward. We can switch to search, CV positioning, role fit, or a career question.",
                              "Understood. I’ll keep the current work paused. Send me what you want to change or look at next.",
                            ]
                          );
                          botMessage(
                            declineCopy,
                            humanComposeDelay(declineCopy, 1800, 3600),
                            function () {
                              resetToLauncher();
                            }
                          );
                        },
                        question: function () {
                          clearPromptState();
                          openQuestionDetour(
                            getQuestionDetourIntro(),
                            getQuestionDetourResumePrompt(
                              "Once we've covered that, you can tell me whether you'd still like to carry on here."
                            )
                          );
                        },
                      },
                      getComposerPlaceholder("reply")
                    );
                    focusComposer(getComposerPlaceholder("reply"));
                    addChoices(
                      [
                        {
                          label: clarifyChoiceLabels.yes,
                          onClick: function () {
                            userMessage(clarifyChoiceLabels.yes);
                            if (route === "review_profile") {
                              promptForCv();
                              return;
                            }
                            beginApplyForMeFlow();
                          },
                        },
                        {
                          label: clarifyChoiceLabels.no,
                          onClick: function () {
                            userMessage(clarifyChoiceLabels.no);
                            var declineCopy = pickVariant(
                              "route_clarify_decline_click_reply",
                              [
                                "That’s fine. I’ll leave that route alone. Tell me the role, market, CV issue, or career question you want to focus on instead.",
                                "No issue. I won’t move that workflow forward. We can switch to search, CV positioning, role fit, or a career question.",
                                "Understood. I’ll keep the current work paused. Send me what you want to change or look at next.",
                              ]
                            );
                            botMessage(
                              declineCopy,
                              humanComposeDelay(declineCopy, 1800, 3600),
                              function () {
                                resetToLauncher();
                              }
                            );
                          },
                        },
                      ],
                      "clarify"
                    );
                  }
                );
              },
              question: function () {
                clearPromptState();
                openQuestionDetour(
                  getQuestionDetourIntro(),
                  route === "review_profile"
                    ? "And if you'd still like me to review your profile for this role after that, just say so."
                    : "And if you'd still like help applying for this role after that, just say so."
                );
              },
            },
            getComposerPlaceholder("reply")
          );
          focusComposer(getComposerPlaceholder("reply"));
        }
      );
    }

    function showInitialLauncher() {
      var launcherMode;
      var launchContext;
      if (!chatLanguageLocked) {
        if (getConfig().isLoggedIn) {
          setChatLanguage(
            (applyChatMemory && applyChatMemory.preferredUiLanguage) === "ar"
              ? "ar"
              : "en"
          );
        } else if (
          pendingLaunchContext &&
          cleanMessageText(pendingLaunchContext.entryRoute || "") ===
            "landing_filter_search"
        ) {
          setChatLanguage("en");
        } else if (hasConcreteRoleEntryContext()) {
          setChatLanguage(getDefaultEntryLanguage());
        } else {
          setChatLanguage("en");
        }
      }
      if (shouldShowPremiumMemberOnboarding()) {
        showPremiumMemberOnboarding();
        return;
      }
      if (pendingLaunchContext) {
        launchContext = pendingLaunchContext;
        pendingLaunchContext = null;
        routePendingLaunchContext(launchContext);
        return;
      }
      setDeskIdentity(getConfig().isLoggedIn ? "emily" : "senna");
      launcherMode = getInitialLauncherMode();
      if (
        shouldUseLockedResultsPreviewMode() &&
        getRailResultsCount() &&
        launcherMode !== "role_entry"
      ) {
        activeRailView = "results";
      }
      if (launcherMode === "logged_in_desk") {
        if (shouldPreferLoggedInResultsRail()) {
          activeRailView = "results";
        }
        showLoggedInLauncherWithMatchingJobs();
        return;
      }
      if (launcherMode === "member_desk") {
        showStandaloneMemberDesk();
        return;
      }
      if (launcherMode === "role_entry") {
        showRoleEntryLauncher();
        return;
      }
      if (launcherMode === "guest_returning") {
        var launcherIntro =
          getReturningLauncherIntroCopy() || getLauncherIntroCopy();
        botMessageNow(launcherIntro);
        botMessageNow(
          '<div class="sffc-crm-apply-chat__launcher-copy" aria-hidden="true"></div>',
          "system"
        );
        addChoices(
          [
            {
              label: getLauncherChoiceLabel("job_search"),
              iconSvg: getLauncherChoiceIconSvg("tailor"),
              recommended: true,
              recommendedLabel: getLauncherRecommendedLabel(),
              onClick: function () {
                queueTransferTyping();
                startConsultantFlow("job_search");
              },
            },
            {
              label: getLauncherChoiceLabel("apply_direct"),
              iconSvg: getLauncherChoiceIconSvg("apply_direct"),
              onClick: function () {
                queueTransferTyping();
                offerDirectApply();
              },
            },
          ],
          "launcher"
        );
        return;
      }
      showGuestColdLauncher();
    }

    function routeLauncherIntent(intent, value) {
      if (
        /^(?:find_job|job_search_help|job_search_strategy|matching_jobs|opportunity_search|get_hired_help|career_direction|application_follow_up)$/.test(
          String(intent || "")
        )
      ) {
        startConsultantFlow("job_search");
        return true;
      }
      if (
        /^(?:apply_for_me|review_cv|cv_review_help|cv_improvement|application_strategy|application_decision|profile_fit|interview_chance|rejection_analysis|role_help|specific_role_interest)$/.test(
          String(intent || "")
        )
      ) {
        startConsultantFlow(
          intent === "apply_for_me" ? "apply_for_me" : "review_profile"
        );
        return true;
      }
      if (intent === "role_question") {
        if (
          /(?:this role|the role|this job|the job|help me with this|review my cv|check my cv|review my profile|am i a fit|fit for this|fit for the role|apply\+? cv review)/i.test(
            cleanMessageText(value || "")
          )
        ) {
          startConsultantFlow("review_profile");
          return true;
        }
        if (
          /(?:find me a job|help me find a job|any roles|similar roles|other roles|what roles|what jobs|what's out there|whats out there)/i.test(
            cleanMessageText(value || "")
          )
        ) {
          startConsultantFlow("job_search");
          return true;
        }
      }
      return false;
    }

    function hasReturningConversationMemory() {
      return !!(
        applyChatMemory &&
        applyChatMemory.hasHistory &&
        (applyChatMemory.lastFlow ||
          applyChatMemory.lastLauncherSearch ||
          applyChatMemory.targetFunctions.length ||
          applyChatMemory.targetLocations.length ||
          applyChatMemory.cvState)
      );
    }

    function resetLoggedInMemberStrategyState() {
      loggedInMemberStrategyState = null;
      clearLoggedInMemberDeskCaches();
    }

    function ensureLoggedInMemberStrategyState() {
      if (!loggedInMemberStrategyState) {
        loggedInMemberStrategyState = {
          previousFocus: "",
          targetFunction: "",
          targetLocation: "",
          employerTypes: [],
          relocationStatus: "",
          workAuthorization: "",
          relocationTiming: "",
          candidateGeo: "",
          languagePreference: "",
          regionalExposure: "",
          compensationFocus: "",
        };
      }
      return loggedInMemberStrategyState;
    }

    function isPrivateEquityTargetLabel(label) {
      return /\b(?:private equity|direct investments?|co-?investments?|buy-side|principal investments?|growth equity|investment associate|investment analyst|fund investments?)\b/i.test(
        cleanMessageText(label || "")
      );
    }

    function isRiyadhLikeLocation(label) {
      return /\b(?:riyadh|الرياض)\b/i.test(cleanMessageText(label || ""));
    }

    function isLondonLikeLocation(label) {
      return /\b(?:london|uk|united kingdom|england|لندن)\b/i.test(
        cleanMessageText(label || "")
      );
    }

    function isLegacyInternationalLikeLocation(label) {
      return /\b(?:london|paris|milan|amsterdam|uk|united kingdom|england|france|italy|netherlands|لندن)\b/i.test(
        cleanMessageText(label || "")
      );
    }

    function isDubaiLikeLocation(label) {
      return /\b(?:dubai|uae|united arab emirates|دبي|الإمارات)\b/i.test(
        cleanMessageText(label || "")
      );
    }

    function isSaudiLikeLocation(label) {
      return /\b(?:riyadh|jeddah|dammam|khobar|saudi|saudi arabia|ksa|السعودية|الرياض|جدة|الدمام|الخبر)\b/i.test(
        cleanMessageText(label || "")
      );
    }

    function getLoggedInMemberPreferredLocation() {
      return cleanMessageText(
        jobSearchPreferredLocation ||
          (conversationFacts.targetLocations &&
            conversationFacts.targetLocations[0]) ||
          (applyChatMemory && applyChatMemory.preferredLocation) ||
          ""
      );
    }

    function getLoggedInMemberPrimaryTarget() {
      return cleanMessageText(
        (conversationFacts.targetFunctions &&
          conversationFacts.targetFunctions[0]) ||
          (applyChatMemory &&
            applyChatMemory.targetFunctions &&
            applyChatMemory.targetFunctions[0]) ||
          ""
      );
    }

    function getLoggedInMemberPrimarySector() {
      return cleanMessageText(
        (conversationFacts.targetSectors &&
          conversationFacts.targetSectors[0]) ||
          (applyChatMemory &&
            applyChatMemory.targetSectors &&
            applyChatMemory.targetSectors[0]) ||
          ""
      );
    }

    function getLoggedInMemberPreviousFocusSummary() {
      var functions = dedupeList(
        ((applyChatMemory && applyChatMemory.targetFunctions) || [])
          .map(cleanMessageText)
          .filter(Boolean)
      );
      var sectors = dedupeList(
        ((applyChatMemory && applyChatMemory.targetSectors) || [])
          .map(cleanMessageText)
          .filter(Boolean)
      );
      var locations = dedupeList(
        ((applyChatMemory && applyChatMemory.targetLocations) || [])
          .map(cleanMessageText)
          .filter(Boolean)
      );
      var parts = [];
      if (functions.length) {
        parts.push(formatFactList(functions.slice(0, 2)));
      }
      if (sectors.length) {
        parts.push(
          (isArabicChat() ? "ضمن " : "in ") +
            formatFactList(sectors.slice(0, 2))
        );
      }
      if (locations.length) {
        parts.push(
          (isArabicChat() ? "في " : "in ") +
            formatFactList(locations.slice(0, 2))
        );
      }
      return parts.join(" ");
    }

    function getLocationAwareMemberSearchSignals(locationLabel, targetLabel) {
      var cleanLocation = cleanMessageText(locationLabel || "");
      var cleanTarget = cleanMessageText(targetLabel || "");
      if (isLegacyInternationalLikeLocation(cleanLocation)) {
        return {
          marketLabel: "GCC",
          intro: isArabicChat()
            ? "سأتعامل مع هذا كسوق خليجي يتطلب وضوحاً في المسار وصدقية قوية على مستوى السيرة الذاتية."
            : "I’ll treat this as a GCC market where lane clarity and shortlist credibility matter from the start.",
          prompt: isArabicChat()
            ? "سأعطي وزناً أكبر لتوافق المستوى، وقوة السيرة الذاتية، والجهة المناسبة، وأي احتكاك متعلق بحق العمل أو الانتقال."
            : "I’ll weight level fit, CV sharpness, employer fit and any right-to-work or relocation friction before I rank anything highly.",
          employerTypes: [
            "Private equity funds",
            "Credit funds",
            "Asset managers",
            "Family offices",
            "Advisory firms",
          ],
          candidateQuestion: isArabicChat()
            ? "هل تريد دبي فقط، أم تريد أبوظبي أو الرياض أو الدوحة في البحث أيضاً؟"
            : "Is this Dubai only, or do you want Abu Dhabi, Riyadh, or Doha in play too?",
          workAuthQuestion: isArabicChat()
            ? "وأحتاج أيضاً أن أعرف ما إذا كان حق العمل أو الانتقال يمثل احتكاكاً حقيقياً هنا."
            : "I also need to know whether right-to-work or relocation friction is still real here.",
          fitWarning: isArabicChat()
            ? "هنا سأكون أكثر صرامة على صدقية المسار واحتمال عبور الفرز الأول."
            : "Here I’ll be stricter on direct lane fit and first-screen credibility.",
        };
      }
      if (isDubaiLikeLocation(cleanLocation)) {
        return {
          marketLabel: "Dubai",
          intro: isArabicChat()
            ? "سأتعامل مع هذا كسوق يعتمد أكثر على السرعة، والمستوى، ووضوح الراتب، وصلاحية العمل في الإمارات."
            : "I’ll treat this as a market where speed, level, package clarity and UAE work status matter early.",
          prompt: isArabicChat()
            ? "سأشدد على مدى احتياجك للكفالة، وسرعة الانتقال، ومدى منطقية المستوى، وما إذا كان السوق يفضل local hires أو يقبل الانتقال."
            : "I’ll weight sponsorship need, relocation timing, level realism and whether the route is local-hire biased or genuinely open to relocators.",
          employerTypes: [
            "Private equity funds",
            "Asset managers",
            "Family offices",
            "Investment banks",
            "Holding companies",
          ],
          candidateQuestion: isArabicChat()
            ? "هل أنت داخل الإمارات الآن، أم سيكون هذا انتقالاً؟"
            : "Are you already in the UAE, or would this be a relocation move?",
          workAuthQuestion: isArabicChat()
            ? "وهل لديك وضع عمل قابل للنقل، أم ستحتاج إلى جهة ترعاك؟"
            : "Do you already have transferable work status there, or would you need sponsorship?",
          fitWarning: isArabicChat()
            ? "هنا سأوازن بين منطقية الحركة وسرعة التنفيذ، لا مجرد التشابه الوظيفي."
            : "Here I’ll balance role fit against execution speed and local-hire friction, not just title overlap.",
        };
      }
      if (isLondonLikeLocation(cleanLocation)) {
        return {
          marketLabel: "London",
          intro: isArabicChat()
            ? "سأتعامل مع هذا كسوق أكثر اعتماداً على المسار المباشر، وجودة الـCV، وقوة القصة المهنية."
            : "I’ll treat this as a market that leans harder on direct lane credibility, CV sharpness and story clarity.",
          prompt: isArabicChat()
            ? "سأعطي وزناً أكبر لمدى وضوح انتقالك المهني، وتوافق المستوى، واحتمال تجاوز أول فرز، أكثر من تعقيدات الانتقال نفسها."
            : "I’ll weight lane clarity, level fit and shortlist credibility more heavily here than relocation complexity.",
          employerTypes: [
            "Private equity funds",
            "Credit funds",
            "Asset managers",
            "Investment banks",
            "Advisory firms",
          ],
          candidateQuestion: isArabicChat()
            ? "هل تركيزك الأساسي يبقى لندن فقط، أم تريد إضافة أسواق قريبة أيضاً؟"
            : "Is London still the primary market, or do you want nearby markets in play as well?",
          workAuthQuestion: isArabicChat()
            ? "وأحتاج فقط أن أثبت وضعك من ناحية الحق في العمل إذا كان هناك أي احتكاك هناك."
            : "I only need to pin down right-to-work friction there if that still matters.",
          fitWarning: isArabicChat()
            ? "في لندن سأكون أقسى قليلاً على ملاءمة المسار المباشر وعلى احتمال عبور الفرز الأول."
            : "In London I’ll be stricter on direct lane fit and first-screen credibility.",
        };
      }
      return {
        marketLabel:
          cleanLocation || (isArabicChat() ? "هذا السوق" : "this market"),
        intro: isArabicChat()
          ? "سأتعامل مع هذا كسوق مستقل له منطقه العملي، لا كنسخة من آخر بحث."
          : "I’ll treat this as its own market with its own practical filters, not as a copy of the last search.",
        prompt: isArabicChat()
          ? "سأضبط التوصيات على الموقع، والأهلية، وطبيعة الجهة، ومدى منطقية الانتقال، لا على المسمى فقط."
          : "I’ll tune the recommendations around location, eligibility, employer type and move realism, not just the title.",
        employerTypes:
          cleanTarget && isPrivateEquityTargetLabel(cleanTarget)
            ? [
                "Private equity funds",
                "Institutional investors",
                "Family offices",
              ]
            : [],
        candidateQuestion: isArabicChat()
          ? "هل هذا السوق أساسي لك الآن أم مجرد خيار إضافي؟"
          : "Is this market primary for you now, or just one option in the mix?",
        workAuthQuestion: isArabicChat()
          ? "وأحتاج أيضاً أن أعرف ما إذا كانت الأهلية للعمل هناك تمثل احتكاكاً حقيقياً أم لا."
          : "I also need to know whether work eligibility there is real friction or not.",
        fitWarning: isArabicChat()
          ? "سأفصل بين ملاءمة الدور وملاءمة السوق نفسه."
          : "I’ll separate role fit from market-fit friction.",
      };
    }

    function buildLoggedInMemberSearchSnapshot() {
      var state = ensureLoggedInMemberStrategyState();
      var targetFunction = cleanMessageText(
        state.targetFunction || getLoggedInMemberPrimaryTarget()
      );
      var targetLocation = cleanMessageText(
        state.targetLocation || getLoggedInMemberPreferredLocation()
      );
      var marketSignals = getLocationAwareMemberSearchSignals(
        targetLocation,
        targetFunction
      );
      return {
        previousFocus: cleanMessageText(
          state.previousFocus || getLoggedInMemberPreviousFocusSummary()
        ),
        targetFunction: targetFunction,
        targetLocation: targetLocation,
        marketSignals: marketSignals,
        workAuthorization: cleanMessageText(
          state.workAuthorization ||
            conversationFacts.workAuthorizationStatus ||
            ""
        ),
        relocationStatus: cleanMessageText(state.relocationStatus || ""),
        employerTypes: (
          state.employerTypes ||
          marketSignals.employerTypes ||
          []
        ).slice(0),
        languagePreference: cleanMessageText(state.languagePreference || ""),
        regionalExposure: cleanMessageText(state.regionalExposure || ""),
        compensationFocus: cleanMessageText(state.compensationFocus || ""),
      };
    }

    function classifyLoggedInMemberSearchStrength(score) {
      var numeric = Number(score || 0);
      if (numeric >= 72) {
        return "strong";
      }
      if (numeric >= 56) {
        return "stretch";
      }
      return "longshot";
    }

    function getLocationAwareEmployerLabel(item) {
      var haystack = buildMatchingRoleHaystack(item || {});
      if (
        /(?:sovereign wealth|swf|public investment fund|pif|adala|mubadala|government-backed|state-backed)/i.test(
          haystack
        )
      ) {
        return "Sovereign / government-backed";
      }
      if (
        /(?:family office|principal capital|private office|uhnw)/i.test(
          haystack
        )
      ) {
        return "Family office";
      }
      if (
        /(?:private equity|buyout|growth equity|direct investments|co-investments)/i.test(
          haystack
        )
      ) {
        return "Private equity platform";
      }
      if (
        /(?:asset management|institutional investor|pension|endowment|investment platform)/i.test(
          haystack
        )
      ) {
        return "Institutional investor";
      }
      return "";
    }

    function getLocationAwareConstraintFlags(item, snapshot) {
      var haystack = buildMatchingRoleHaystack(item || {});
      var flags = [];
      var cleanLocation = cleanMessageText(
        (snapshot && snapshot.targetLocation) || ""
      );
      if (isSaudiLikeLocation(cleanLocation)) {
        if (
          /(?:arabic (?:required|essential|fluency)|fluent arabic|arabic speaker|arabic language)/i.test(
            haystack
          )
        ) {
          flags.push("Arabic may be required");
        }
        if (
          /(?:saudi nationals? only|saudi national preferred|nationals only|ksa nationals? only)/i.test(
            haystack
          )
        ) {
          flags.push("May be limited to Saudi nationals");
        }
        if (
          /(?:gcc experience|middle east experience|regional experience|saudi market experience)/i.test(
            haystack
          )
        ) {
          flags.push("Regional experience may be preferred");
        }
        if (
          !/(?:visa sponsorship|sponsorship available|relocation support|international candidates|will sponsor)/i.test(
            haystack
          ) &&
          cleanMessageText((snapshot && snapshot.workAuthorization) || "") ===
            "needed"
        ) {
          flags.push("Sponsorship is not clearly confirmed");
        }
      }
      if (isDubaiLikeLocation(cleanLocation)) {
        if (
          /(?:local candidates only|uae experience|gcc experience|immediate joiners?|own visa|transferable visa)/i.test(
            haystack
          )
        ) {
          flags.push("May lean toward local or region-ready candidates");
        }
      }
      if (isLondonLikeLocation(cleanLocation)) {
        if (
          /(?:uk experience|right to work in the uk|must have uk work authorization|no sponsorship)/i.test(
            haystack
          )
        ) {
          flags.push("Right-to-work friction could matter");
        }
      }
      return dedupeList(flags).slice(0, 3);
    }

    function buildLoggedInMemberRecommendedRoleHtml(entry, snapshot) {
      var match = entry || null;
      var item;
      var recruiter;
      var fitScore;
      var companyType;
      var roleMeta;
      var strengths;
      var blockers;
      if (!match) {
        return "";
      }
      item = match.item || {};
      recruiter = getRoleRecruiterPreview(item);
      fitScore = Math.max(
        0,
        Math.round(Number(match.score || item.match_score || 0))
      );
      companyType = getLocationAwareEmployerLabel(item);
      roleMeta = [
        cleanMessageText(item.company || ""),
        cleanMessageText(item.location || ""),
        cleanMessageText(item.salary || ""),
      ]
        .filter(Boolean)
        .join(" · ");
      strengths = dedupeList(
        (match.whyMatches || []).concat(match.cvSupport || [])
      ).slice(0, 4);
      blockers = dedupeList(
        (match.missing || []).concat(
          getLocationAwareConstraintFlags(item, snapshot)
        )
      ).slice(0, 4);
      return (
        '<section class="sffc-crm-apply-chat__results-briefing">' +
        '<div class="sffc-crm-apply-chat__results-briefing-head">' +
        '<span class="sffc-crm-apply-chat__results-briefing-kicker">Recommended first role</span>' +
        "<strong>" +
        escapeHtml(item.title || "Role") +
        "</strong>" +
        (roleMeta ? "<span>" + escapeHtml(roleMeta) + "</span>" : "") +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metrics">' +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(String(fitScore)) +
        "%</strong><span>Profile fit</span></div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(
          classifyLoggedInMemberSearchStrength(fitScore) === "strong"
            ? "High"
            : classifyLoggedInMemberSearchStrength(fitScore) === "stretch"
            ? "Moderate"
            : "Low"
        ) +
        "</strong><span>Interview probability</span></div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(companyType || "Market route") +
        "</strong><span>Employer type</span></div>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-columns">' +
        '<div class="sffc-crm-apply-chat__results-briefing-column">' +
        "<strong>Why I selected it</strong>" +
        "<ul>" +
        strengths
          .map(function (line) {
            return "<li>" + escapeHtml(line) + "</li>";
          })
          .join("") +
        "</ul>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-column is-warning">' +
        "<strong>What may hold you back</strong>" +
        "<ul>" +
        blockers
          .map(function (line) {
            return "<li>" + escapeHtml(line) + "</li>";
          })
          .join("") +
        "</ul>" +
        "</div>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-actions">' +
        (item.url
          ? '<a class="sffc-crm-apply-chat__match-role-action" href="' +
            escapeHtml(item.url) +
            '" target="_blank" rel="noopener noreferrer">View full role</a>'
          : "") +
        (recruiter.name
          ? '<span class="sffc-crm-apply-chat__artifact-link-note">' +
            escapeHtml(
              hasPremiumAccess
                ? "Recruiter route available from the next step."
                : "Recruiter details can be unlocked from the next step."
            ) +
            "</span>"
          : "") +
        "</div>" +
        "</section>"
      );
    }

    function buildLoggedInMemberSearchResultsSummary() {
      var cacheKey = [
        cleanMessageText(cvRoleMatchesCacheKey || ""),
        cleanMessageText(matchingRolesFilterCacheKey || ""),
        cleanMessageText(loggedInMemberDeskCacheKey || ""),
        cleanMessageText(
          buildLoggedInMemberSearchSnapshot().targetFunction || ""
        ),
        cleanMessageText(
          buildLoggedInMemberSearchSnapshot().targetLocation || ""
        ),
        hasPremiumAccess ? "premium" : "guest",
      ].join("::");
      if (
        loggedInMemberSearchResultsSummaryCacheKey === cacheKey &&
        loggedInMemberSearchResultsSummaryCacheValue
      ) {
        return loggedInMemberSearchResultsSummaryCacheValue;
      }
      var matches = buildCvRoleMatches();
      if (!matches.length) {
        matches = filterMatchingRoles()
          .slice(0, 12)
          .map(function (item, index) {
            var rawScore = Number(
              (item && (item.match_score || item.fit_score || item.score)) || 0
            );
            var fallbackScore =
              rawScore > 0 ? rawScore : Math.max(42, 68 - index * 6);
            return {
              item: item,
              score: fallbackScore,
              fitType: fallbackScore >= 72 ? "Direct fit" : "Stretch fit",
              whyMatches: [
                cleanMessageText(
                  item && item.title ? item.title : "The role title"
                ) +
                  " still sits close enough to the active search direction to review properly.",
              ],
              cvSupport: [
                "The broader live shortlist still sees enough overlap to keep this role in play.",
              ],
              missing: getLocationAwareConstraintFlags(
                item,
                buildLoggedInMemberSearchSnapshot()
              ),
            };
          });
      }
      var snapshot = buildLoggedInMemberSearchSnapshot();
      var strongCount = 0;
      var stretchCount = 0;
      var longshotCount = 0;
      matches.forEach(function (entry) {
        var band = classifyLoggedInMemberSearchStrength(entry && entry.score);
        if (band === "strong") {
          strongCount += 1;
        } else if (band === "stretch") {
          stretchCount += 1;
        } else {
          longshotCount += 1;
        }
      });
      loggedInMemberSearchResultsSummaryCacheValue = {
        total: matches.length,
        strongCount: strongCount,
        stretchCount: stretchCount,
        longshotCount: longshotCount,
        resultItems: matches
          .map(function (entry) {
            return entry && entry.item ? entry.item : entry;
          })
          .filter(Boolean),
        topMatchesHtml: renderActualJobPostSearchResults(
          matches.map(function (entry) {
            return entry.item || entry;
          }),
          cleanMessageText(snapshot && snapshot.query ? snapshot.query : ""),
          {
            hideSummary: true,
            hideControls: true,
            includeOriginalCvAction: true,
            groupTitle: "Best matches",
            groupSubtitle: "Sorted by CV fit and role relevance",
          }
        ),
        recommendedHtml: buildLoggedInMemberRecommendedRoleHtml(
          matches[0] || null,
          snapshot
        ),
        leadEntry: matches[0] || null,
        snapshot: snapshot,
      };
      loggedInMemberSearchResultsSummaryCacheKey = cacheKey;
      return loggedInMemberSearchResultsSummaryCacheValue;
    }

    function getLoggedInResultsRailBandLabel(band) {
      if (band === "strong") {
        return "Strong matches";
      }
      if (band === "stretch") {
        return "Stretch roles";
      }
      return "Longer-shot roles";
    }

    function getLoggedInResultsRailBandOrder(band) {
      if (band === "strong") {
        return 0;
      }
      if (band === "stretch") {
        return 1;
      }
      return 2;
    }

    function getDecoratedResultsRailItems(items) {
      return (items || []).map(function (item, index) {
        var recruiter = getRoleRecruiterPreview(item);
        var fit = getJobListBriefingFitData(item);
        var fitScore = Math.max(
          0,
          Math.round(
            Number(
              (fit && fit.score) ||
                (item && (item.match_score || item.fit_score || item.score)) ||
                0
            )
          )
        );
        return {
          item: item,
          index: index,
          recruiter: recruiter,
          fit: fit,
          fitScore: fitScore,
          band: classifyLoggedInMemberSearchStrength(fitScore),
        };
      });
    }

    function sortDecoratedResultsRailItems(items) {
      return (items || []).slice(0).sort(function (left, right) {
        var bandDelta =
          getLoggedInResultsRailBandOrder(left.band) -
          getLoggedInResultsRailBandOrder(right.band);
        if (bandDelta !== 0) {
          return bandDelta;
        }
        if (right.fitScore !== left.fitScore) {
          return right.fitScore - left.fitScore;
        }
        return String((left.item && left.item.title) || "").localeCompare(
          String((right.item && right.item.title) || "")
        );
      });
    }

    function buildLoggedInResultsRailOverviewHtml(decoratedItems, listKey) {
      var isMemberDesk =
        getConfig().isLoggedIn && hasReturningConversationMemory();
      var priority;
      var summary;
      var lead;
      var recruiterCount = 0;
      var strongCount = 0;
      var stretchCount = 0;
      var longshotCount = 0;
      var marketLabel = "";
      var bestRoleLabel = "";
      if (!isMemberDesk || !decoratedItems.length) {
        return "";
      }
      priority = getLoggedInMemberPrioritySnapshot();
      summary =
        listKey === "matching_cv"
          ? buildLoggedInMemberSearchResultsSummary()
          : null;
      decoratedItems.forEach(function (entry) {
        if (entry.band === "strong") {
          strongCount += 1;
        } else if (entry.band === "stretch") {
          stretchCount += 1;
        } else {
          longshotCount += 1;
        }
      });
      recruiterCount = Number((priority && priority.recruiterCount) || 0);
      marketLabel = cleanMessageText(
        (priority && priority.snapshot && priority.snapshot.targetLocation) ||
          ""
      );
      lead =
        summary && summary.leadEntry && summary.leadEntry.item
          ? summary.leadEntry
          : decoratedItems[0];
      bestRoleLabel = cleanMessageText(
        (lead && lead.item && lead.item.title) || "the strongest role"
      );
      return (
        '<section class="sffc-crm-apply-chat__results-briefing sffc-crm-apply-chat__results-briefing--rail">' +
        '<div class="sffc-crm-apply-chat__results-briefing-head">' +
        '<span class="sffc-crm-apply-chat__results-briefing-kicker">Best first move</span>' +
        "<strong>" +
        escapeHtml(bestRoleLabel) +
        "</strong>" +
        (marketLabel ? "<span>" + escapeHtml(marketLabel) + "</span>" : "") +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metrics">' +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(String(strongCount)) +
        "</strong><span>Strong</span></div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(String(stretchCount)) +
        "</strong><span>Stretch</span></div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(String(longshotCount)) +
        "</strong><span>Long-shot</span></div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-metric"><strong>' +
        escapeHtml(String(recruiterCount)) +
        "</strong><span>Access routes</span></div>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-columns">' +
        '<div class="sffc-crm-apply-chat__results-briefing-column">' +
        "<strong>What to do first</strong>" +
        "<ul>" +
        "<li>" +
        escapeHtml(
          "Start with the cleanest role before widening the queue again."
        ) +
        "</li>" +
        "<li>" +
        escapeHtml(
          recruiterCount > 0
            ? "Rank recruiter access against the shortlist instead of treating it as a separate workstream."
            : "Keep the shortlist honest before spending effort on access or outreach."
        ) +
        "</li>" +
        "</ul>" +
        "</div>" +
        "</div>" +
        "</section>"
      );
    }

    function getResultsCardRouteFrictionLabel(item, recruiter, hasFullAccess) {
      if (recruiter && recruiter.name) {
        if (hasFullAccess) {
          return "Route friction: recruiter route available";
        }
        return "Route friction: recruiter route is member-gated";
      }
      if (item && (item.apply_url || item.url || applicationUrl)) {
        return "Route friction: direct application route only";
      }
      return "Route friction: access route not clear yet";
    }

    function getResultsCardMarketFrictionLabel(item) {
      var snapshot = buildLoggedInMemberSearchSnapshot();
      var flags = getLocationAwareConstraintFlags(item, snapshot);
      if (flags.length) {
        return "Market friction: " + flags[0];
      }
      return "Market friction: no obvious market blocker";
    }

    function buildLoggedInMemberRiyadhSearchBriefHtml() {
      var snapshot = buildLoggedInMemberSearchSnapshot();
      var strengths = [
        "CFA qualification",
        "Risk analysis",
        "Downside assessment",
        "Investment judgement",
        "Portfolio exposure",
      ];
      var gaps = [
        "Direct transaction execution",
        "LBO modelling",
        "Commercial due diligence",
        "Regional investment track record",
      ];
      return (
        '<section class="sffc-crm-apply-chat__results-briefing is-search-brief">' +
        '<div class="sffc-crm-apply-chat__results-briefing-head">' +
        '<span class="sffc-crm-apply-chat__results-briefing-kicker">Search brief</span>' +
        "<strong>" +
        escapeHtml(snapshot.targetFunction || "Target search") +
        "</strong>" +
        (snapshot.targetLocation
          ? "<span>" + escapeHtml(snapshot.targetLocation) + "</span>"
          : "") +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-columns">' +
        '<div class="sffc-crm-apply-chat__results-briefing-column">' +
        "<strong>What I am prioritising</strong>" +
        "<ul>" +
        "<li>" +
        escapeHtml(
          formatNaturalList((snapshot.employerTypes || []).slice(0, 4))
        ) +
        "</li>" +
        "<li>" +
        escapeHtml(
          snapshot.workAuthorization === "needed"
            ? "Employers more likely to support sponsorship or relocation"
            : "Routes with cleaner market-fit and work eligibility"
        ) +
        "</li>" +
        "<li>" +
        escapeHtml(
          (snapshot.marketSignals && snapshot.marketSignals.fitWarning) ||
            "Role fit separated from market friction"
        ) +
        "</li>" +
        "</ul>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-column is-warning">' +
        "<strong>What I am stress-testing</strong>" +
        "<ul>" +
        gaps
          .map(function (line) {
            return "<li>" + escapeHtml(line) + "</li>";
          })
          .join("") +
        "</ul>" +
        "</div>" +
        "</div>" +
        '<div class="sffc-crm-apply-chat__results-briefing-columns">' +
        '<div class="sffc-crm-apply-chat__results-briefing-column">' +
        "<strong>Transferable strengths</strong>" +
        "<ul>" +
        strengths
          .map(function (line) {
            return "<li>" + escapeHtml(line) + "</li>";
          })
          .join("") +
        "</ul>" +
        "</div>" +
        "</div>" +
        "</section>"
      );
    }

    function getLoggedInCareerTargetLanes(profile) {
      var cvProfile = profile || buildCvRoleMatchProfile({ cvOnly: true });
      var quals = dedupeList(
        (cvProfile.qualifications || []).map(function (item) {
          return cleanMessageText(item).toUpperCase();
        })
      );
      var hasCfa =
        quals.indexOf("CFA") !== -1 ||
        /\bCFA\b/i.test(cleanMessageText(cvProfile.summaryText || ""));
      var lanes = [];
      if ((cvProfile.families || []).indexOf("investment") !== -1) {
        lanes.push({
          label: "Private Equity Associate",
          rationale:
            "You already have buy-side or transaction-adjacent evidence, so the strongest upside move is toward direct investing rather than staying generic.",
        });
      }
      if (
        (cvProfile.families || []).indexOf("risk_compliance") !== -1 &&
        ((cvProfile.families || []).indexOf("investment") !== -1 || hasCfa)
      ) {
        lanes.push({
          label: "Private Credit / Direct Lending",
          rationale:
            "Your downside-analysis and risk judgement can be positioned as investment discipline rather than back-office oversight.",
        });
      }
      if (
        (cvProfile.families || []).indexOf("investment") !== -1 &&
        /\b(?:python|sql|technology|saas|software|market research|equity research)\b/i.test(
          cleanMessageText(cvProfile.summaryText || "")
        )
      ) {
        lanes.push({
          label: "Growth Equity / Tech Investing",
          rationale:
            "The profile can credibly bridge into growth-oriented investing if the analytical and market-evaluation side is sharper than the pure deal-execution side.",
        });
      }
      if (
        (cvProfile.families || []).indexOf("risk_compliance") !== -1 &&
        !lanes.length
      ) {
        lanes.push({
          label: "Investment Risk / Portfolio Risk",
          rationale:
            "That is the cleanest high-credibility lane from the current evidence and keeps the market reading you correctly.",
        });
      }
      if (!lanes.length && cvProfile.title) {
        lanes.push({
          label: cvProfile.title,
          rationale:
            "That is still the cleanest lane the CV currently supports without overstretching the story.",
        });
      }
      return lanes.slice(0, 3);
    }

    function getLoggedInCareerMarketAdvice(locationLabel, profile) {
      var cvProfile = profile || buildCvRoleMatchProfile({ cvOnly: true });
      var cleanLocation = cleanMessageText(
        locationLabel || getLoggedInMemberPreferredLocation() || ""
      );
      var quals = dedupeList(
        (cvProfile.qualifications || []).map(function (item) {
          return cleanMessageText(item).toUpperCase();
        })
      );
      var hasCfa =
        quals.indexOf("CFA") !== -1 ||
        /\bCFA\b/i.test(cleanMessageText(cvProfile.summaryText || ""));
      if (isDubaiLikeLocation(cleanLocation)) {
        return {
          label: "Dubai",
          verdict:
            "A good move if you want a tax-efficient regional platform without giving up too much international market visibility.",
          strengths: [
            hasCfa
              ? "The CFA signal carries well in regional investment and sovereign-adjacent hiring."
              : "A clean analytical profile can still travel well into Dubai if the lane is positioned sharply.",
            "The market gives you access to PE, asset management, sovereign-adjacent and holding-company routes from one base.",
            "The lifestyle and employer mix can make Dubai easier to test than a more region-specific relocation move.",
          ],
          cautions: [
            "The market is smaller than London, so plan-B depth is thinner if the first fund is the wrong fit.",
            "Local-hire bias and visa timing can matter more than people admit.",
            "If the move is purely for title inflation, it can look attractive but still be weaker in long-term pedigree.",
          ],
        };
      }
      if (isRiyadhLikeLocation(cleanLocation)) {
        return {
          label: "GCC",
          verdict:
            "A stronger move if you want broader GCC optionality and care about long-term finance market depth as much as tax efficiency.",
          strengths: [
            hasCfa
              ? "The CFA signal remains legible with funds, asset managers and institution-led investors."
              : "Rigorous analytical backgrounds still travel well if the lane is positioned sharply.",
            "The market depth across the GCC gives you more plan-B options if the first platform is not the right fit.",
            "Cross-border private equity, credit and portfolio roles are easier to triangulate from one search base.",
          ],
          cautions: [
            "Competition is denser and the market is less forgiving of fuzzy transitions.",
            "If the CV signal is not sharp enough, competitive GCC finance markets punish ambiguity quickly.",
            "Compensation can look weaker net of tax than Dubai even when the role pedigree is stronger.",
          ],
        };
      }
      if (isLondonLikeLocation(cleanLocation)) {
        return {
          label: "London",
          verdict:
            "Still the strongest market if the priority is pure deal-flow density, employer depth and long-term PE pedigree rather than tax efficiency.",
          strengths: [
            "The market depth is still hard to beat for lateral optionality and plan-B routes.",
            "If your story is strongest in traditional investment hiring, London makes that easier to defend.",
            "The employer variety reduces the risk of one bad move boxing you in.",
          ],
          cautions: [
            "The competition is denser and the market is less forgiving of fuzzy transitions.",
            "If the CV signal is not sharp enough, London punishes ambiguity quickly.",
            "Financially, it is often weaker net of tax than Dubai.",
          ],
        };
      }
      return null;
    }

    function buildLoggedInCareerDirectionAdvice(sourceText) {
      var text = cleanMessageText(sourceText || "");
      var profile = buildCvRoleMatchProfile({ cvOnly: true });
      var lanes = getLoggedInCareerTargetLanes(profile);
      var marketAdvice = getLoggedInCareerMarketAdvice(
        extractMentionedSearchLocations(text)[0] ||
          getLoggedInMemberPreferredLocation(),
        profile
      );
      var opener =
        "Based on the CV you already have in here, I would treat this as a career-direction decision rather than a generic job-search question.";
      var laneLines = lanes.map(function (lane, index) {
        return index + 1 + ". " + lane.label + " — " + lane.rationale;
      });
      var recommendation = lanes[0]
        ? "The best immediate move is to anchor the search on " +
          lanes[0].label +
          ", then keep " +
          lanes
            .slice(1)
            .map(function (lane) {
              return lane.label;
            })
            .join(" and ") +
          " as secondary lanes if they still fit the market."
        : "The best immediate move is to anchor the search on the strongest lane the CV already supports, then keep adjacent options secondary rather than scattering.";
      var parts = [opener];
      if (laneLines.length) {
        parts.push(laneLines.join(" "));
      }
      parts.push(recommendation);
      if (marketAdvice) {
        parts.push(
          "On " + marketAdvice.label + " specifically: " + marketAdvice.verdict
        );
        parts.push(
          "Why it could work: " + marketAdvice.strengths.slice(0, 2).join(" ")
        );
        parts.push(
          "What I would watch: " + marketAdvice.cautions.slice(0, 2).join(" ")
        );
      }
      parts.push(
        "If you want, I can turn that into a live search, a recruiter route, or a CV repositioning pass instead of leaving it at advice."
      );
      return parts.join(" ");
    }

    function summarizeSavedSearchFocus() {
      var parts = [];
      var functions = dedupeList(
        (conversationFacts.targetFunctions || []).concat(
          (applyChatMemory && applyChatMemory.targetFunctions) || []
        )
      );
      var locations = dedupeList(
        (conversationFacts.targetLocations || []).concat(
          (applyChatMemory && applyChatMemory.targetLocations) || []
        )
      );
      if (functions.length) {
        parts.push(formatFactList(functions));
      }
      if (locations.length) {
        parts.push(
          functions.length
            ? (isArabicChat() ? "في " : "in ") + formatFactList(locations)
            : formatFactList(locations)
        );
      }
      return parts.join(" ");
    }

    function inferPendingIntentFromPromptState(state) {
      var prompt = String(state || "");
      if (!prompt) {
        return "";
      }
      if (
        /job_search_(?:location|visa|similar_roles|target_roles_text|other_roles|other_roles_text|anything_missed)/.test(
          prompt
        )
      ) {
        return "job_search_help";
      }
      if (
        /apply_(?:work_authorization_check|qualification_check|qualification_present|qualification_alternative|qualification_alternative_detail)/.test(
          prompt
        )
      ) {
        return "application_strategy";
      }
      if (
        /apply_(?:cover_letter_check|tailoring_progress_check|tailored_versions|cv_action_choice|cv_decision|matching_roles|role_search_type|other_roles_text)/.test(
          prompt
        )
      ) {
        return "apply_for_me";
      }
      if (
        /job_search_(?:confirm_email|check_inbox|email_received|delivery_frequency|reuse_preferred_email|package_choice)/.test(
          prompt
        )
      ) {
        return "job_search_help";
      }
      if (
        /apply_(?:account_check|account_email|waiting_for_signup|select_pricing_option|confirm_preferred_email|collect_preferred_email|collect_full_name)/.test(
          prompt
        )
      ) {
        return "account_access_issue";
      }
      if (/account_signup_check/.test(prompt)) {
        return "account_access_issue";
      }
      if (
        /review_clarification_check|continue_fix|confirm_recent_role|show_issue_decision/.test(
          prompt
        )
      ) {
        return "cv_review_help";
      }
      return "";
    }

    function updateFollowUpState(patch) {
      var current = normalizeFollowUpState(followUpState || {});
      Object.keys(patch || {}).forEach(function (key) {
        current[key] = patch[key];
      });
      current.updatedAt = new Date().toISOString();
      followUpState = current;
      queueApplyChatMemoryPersist();
    }

    function markPendingFollowUp(state, placeholder) {
      updateFollowUpState({
        pendingPromptState: cleanMessageText(state || ""),
        pendingPromptPlaceholder: cleanMessageText(placeholder || ""),
        pendingIntent: inferPendingIntentFromPromptState(state),
        pendingSummary: cleanMessageText(placeholder || ""),
      });
    }

    function clearPendingFollowUp() {
      updateFollowUpState({
        pendingPromptState: "",
        pendingPromptPlaceholder: "",
        pendingIntent: "",
        pendingSummary: "",
      });
    }

    function rememberAnsweredConversationIntent(sourceText, answeredIntent) {
      var secondaryClause;
      var clauseIntents;
      var userIntent = sourceText ? detectIntent(sourceText) : "";
      clauseIntents = sourceText
        ? extractClauseIntentSequence(sourceText, answeredIntent)
        : [];
      secondaryClause = clauseIntents.length ? clauseIntents[0] : null;
      updateFollowUpState({
        lastAnsweredIntent: cleanMessageText(answeredIntent || ""),
        lastUserIntent: cleanMessageText(userIntent || ""),
        secondaryIntent:
          secondaryClause && secondaryClause.intent
            ? secondaryClause.intent
            : "",
        secondarySummary:
          secondaryClause && secondaryClause.summary
            ? secondaryClause.summary
            : "",
        turnCount: Number((followUpState && followUpState.turnCount) || 0) + 1,
      });
      if (secondaryClause && secondaryClause.intent) {
        updateFollowUpState({
          pendingIntent: secondaryClause.intent,
          pendingSummary: secondaryClause.summary || "",
          pendingPromptState: "",
          pendingPromptPlaceholder: "",
        });
      }
    }

    function getLastLauncherSearchSummary() {
      var lastSearch =
        applyChatMemory && applyChatMemory.lastLauncherSearch
          ? normalizeApplyChatLauncherSearch(applyChatMemory.lastLauncherSearch)
          : null;
      var query;
      var roleTarget;
      var location;
      if (!lastSearch) {
        return "";
      }
      query = cleanMessageText(lastSearch.query || "");
      roleTarget = cleanMessageText(lastSearch.roleTarget || "");
      location = cleanMessageText(lastSearch.location || "");
      if (query) {
        if (
          location &&
          query.toLowerCase().indexOf(location.toLowerCase()) === -1
        ) {
          return query + " in " + location;
        }
        return query;
      }
      if (roleTarget && location) {
        return roleTarget + " roles in " + location;
      }
      if (roleTarget) {
        return roleTarget + " roles";
      }
      if (location) {
        return "roles in " + location;
      }
      return "";
    }

