    function handlePaymentFailureDetails(nextValue) {
      var issue = detectPaymentFailureBucket(nextValue);
      var guidance;

      if (issue.bucket && issue.bucket !== "unknown_failure") {
        clearPromptState();
        guidance = getPaymentFailureGuidance(issue.bucket);
        botMessage(
          guidance +
            (isArabicChat()
              ? " وإذا ظهرت رسالة ثانية بعدها، انسخيها هنا وأنا أوضحها لك أيضاً."
              : " If a different error comes up after that, paste it here and I'll narrow that down too."),
          humanComposeDelay(cleanMessageText(guidance), 2400, 5200),
          function () {
            focusComposer(
              isArabicChat()
                ? "إذا ظهر خطأ دفع ثاني قولي لي"
                : "Tell me if another payment error comes up"
            );
          },
          humanReadDelay(nextValue, 500)
        );
        return;
      }

      botMessage(
        getPaymentFailureGuidance("unknown_failure"),
        humanComposeDelay(
          cleanMessageText(getPaymentFailureGuidance("unknown_failure")),
          2400,
          5200
        ),
        function () {
          focusComposer(
            isArabicChat()
              ? "انسخي رسالة الخطأ هنا"
              : "Paste the payment error here"
          );
        },
        humanReadDelay(nextValue, 500)
      );
    }

    function askForPaymentFailureDetails(value) {
      var prompt = getPaymentFailurePrompt();
      botMessage(
        prompt,
        humanComposeDelay(cleanMessageText(prompt), 2200, 4200),
        function () {
          setPromptState(
            "payment_failure_detail",
            {
              other: handlePaymentFailureDetails,
            },
            isArabicChat()
              ? "انسخي رسالة الدفع هنا"
              : "Paste the payment error here"
          );
          focusComposer(
            isArabicChat()
              ? "انسخي رسالة الدفع هنا"
              : "Paste the payment error here"
          );
        },
        humanReadDelay(value, 500)
      );
    }

    function sendHumanHandoffRequest(message, requestKind) {
      var config = getConfig();
      var formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_request_human_followup");
      formData.append("nonce", config.requestHumanNonce || config.nonce || "");
      formData.append("session_token", ensureApplyChatSessionToken());
      formData.append(
        "post_id",
        postId || jobsPostId || root.getAttribute("data-post-id") || ""
      );
      formData.append("jobs_post_id", jobsPostId || "");
      formData.append("role_title", roleTitle || "");
      formData.append(
        "message",
        cleanMessageText(message || lastUserInputText || "")
      );
      formData.append("active_path", activePath || "");
      formData.append("prompt_state", promptState || "");
      formData.append("page_url", window.location.href || "");
      formData.append("conversation_focus", describeConversationFocus());
      formData.append("cv_profile", describeCvProfile());
      formData.append("context_summary", buildContextSummary());
      formData.append(
        "preferred_email",
        cleanMessageText(applyOnboardingPreferredEmail || "")
      );
      formData.append(
        "full_name",
        cleanMessageText(applyOnboardingFullName || "")
      );
      formData.append(
        "request_kind",
        cleanMessageText(requestKind || "general_handoff")
      );

      return window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          if (!payload || !payload.success) {
            throw new Error(
              (payload && payload.data && payload.data.message) ||
                "I couldn't send that through right now."
            );
          }
          return payload.data || {};
        });
    }

    function getApplyForMeModal() {
      return root.querySelector("[data-sffc-apply-for-me-modal]");
    }

    function closeApplyForMeModal() {
      var modal = getApplyForMeModal();
      if (!modal) {
        return;
      }

      modal.hidden = true;
      root.__sffcApplyForMeTrigger = null;
      document.documentElement.classList.remove(
        "sffc-community-editorial-modal-open"
      );
      document.body.classList.remove("sffc-community-editorial-modal-open");
    }

    function openApplyForMeModal(button) {
      var modal = getApplyForMeModal();
      var dialog = modal
        ? modal.querySelector(".sffc-community-editorial__apply-for-me-dialog")
        : null;
      var form = modal
        ? modal.querySelector("[data-sffc-apply-for-me-form]")
        : null;
      var roleEl = modal
        ? modal.querySelector("[data-sffc-apply-for-me-role]")
        : null;
      var companyEl = modal
        ? modal.querySelector("[data-sffc-apply-for-me-company]")
        : null;
      var recruiterEl = modal
        ? modal.querySelector("[data-sffc-apply-for-me-recruiter]")
        : null;
      var avatarFallback = modal
        ? modal.querySelector("[data-sffc-apply-for-me-avatar-fallback]")
        : null;
      var feedback = modal
        ? modal.querySelector("[data-sffc-apply-for-me-feedback]")
        : null;
      var role = cleanMessageText(
        button.getAttribute("data-sffc-community-role-title") || roleTitle || ""
      );
      var company = cleanMessageText(
        button.getAttribute("data-sffc-community-discovery-company") ||
          button.getAttribute("data-sffc-community-company") ||
          ""
      );
      var recruiterName = cleanMessageText(
        button.getAttribute("data-sffc-community-discovery-name") ||
          button.getAttribute("data-sffc-community-recruiter-name") ||
          ""
      );
      var recruiterEmail = cleanMessageText(
        button.getAttribute("data-sffc-community-discovery-email") ||
          button.getAttribute("data-sffc-community-recruiter-email") ||
          ""
      );
      var postId = cleanMessageText(
        button.getAttribute("data-sffc-community-post-id") ||
          root.getAttribute("data-post-id") ||
          ""
      );
      var initial = cleanMessageText(
        button.getAttribute("data-sffc-community-discovery-initial") ||
          recruiterName.charAt(0) ||
          "S"
      );

      if (!modal || !form) {
        return;
      }

      root.__sffcApplyForMeTrigger = button;
      form.reset();
      form.elements.post_id.value = postId;
      form.elements.role_title.value = role;
      form.elements.company_name.value = company;
      form.elements.recruiter_name.value = recruiterName;
      form.elements.recruiter_email.value = recruiterEmail;

      if (roleEl) {
        roleEl.textContent = role || (isArabicChat() ? "الفرصة" : "Role");
      }
      if (companyEl) {
        companyEl.textContent =
          company || (isArabicChat() ? "الشركة" : "Company");
      }
      if (recruiterEl) {
        recruiterEl.textContent = recruiterName
          ? recruiterName + (recruiterEmail ? " · " + recruiterEmail : "")
          : isArabicChat()
          ? "مسار جهة التوظيف"
          : "Recruiter route";
      }
      if (avatarFallback) {
        avatarFallback.textContent = initial || "S";
      }
      if (feedback) {
        feedback.hidden = true;
        feedback.textContent = "";
        feedback.classList.remove("is-error", "is-success");
      }

      modal.hidden = false;
      document.documentElement.classList.add(
        "sffc-community-editorial-modal-open"
      );
      document.body.classList.add("sffc-community-editorial-modal-open");
      if (dialog && typeof dialog.focus === "function") {
        window.setTimeout(function () {
          dialog.focus();
        }, 20);
      }
    }

    function submitApplyForMeModal(form) {
      var feedback = form
        ? form.querySelector("[data-sffc-apply-for-me-feedback]")
        : null;
      var submitButton = form
        ? form.querySelector("[data-sffc-apply-for-me-submit]")
        : null;
      var cvSelect = form
        ? form.querySelector("[data-sffc-apply-for-me-cv]")
        : null;
      var selectedOption = cvSelect
        ? cvSelect.options[cvSelect.selectedIndex]
        : null;
      var storedCvUrl = cvSelect ? cleanMessageText(cvSelect.value || "") : "";
      var storedCvName = selectedOption
        ? cleanMessageText(
            selectedOption.getAttribute("data-cv-name") ||
              selectedOption.textContent ||
              ""
          )
        : "";
      var notes =
        form && form.elements.apply_for_me_notes
          ? cleanMessageText(form.elements.apply_for_me_notes.value || "")
          : "";
      var role =
        form && form.elements.role_title
          ? cleanMessageText(form.elements.role_title.value || "")
          : "";
      var company =
        form && form.elements.company_name
          ? cleanMessageText(form.elements.company_name.value || "")
          : "";
      var recruiterName =
        form && form.elements.recruiter_name
          ? cleanMessageText(form.elements.recruiter_name.value || "")
          : "";
      var recruiterEmail =
        form && form.elements.recruiter_email
          ? cleanMessageText(form.elements.recruiter_email.value || "")
          : "";
      var postId =
        form && form.elements.post_id
          ? cleanMessageText(form.elements.post_id.value || "")
          : "";
      var trigger = root.__sffcApplyForMeTrigger || null;
      var originalLabel = trigger
        ? cleanMessageText(trigger.textContent || "Apply for Me")
        : "Apply for Me";
      var requestMessage;
      var config = getConfig();
      var formData;

      if (!form || typeof window.fetch !== "function") {
        return;
      }

      if (!storedCvUrl) {
        if (feedback) {
          feedback.hidden = false;
          feedback.classList.add("is-error");
          feedback.classList.remove("is-success");
          feedback.textContent = isArabicChat()
            ? "اختاري سيرة ذاتية محفوظة أولاً."
            : "Choose a saved CV first.";
        }
        if (cvSelect) {
          cvSelect.focus();
        }
        return;
      }

      requestMessage = [
        "Apply for Me request",
        role ? "Role: " + role : "",
        company ? "Company: " + company : "",
        recruiterName ? "Recruiter: " + recruiterName : "",
        recruiterEmail ? "Recruiter email: " + recruiterEmail : "",
        storedCvName ? "Saved CV: " + storedCvName : "",
        notes ? "Notes: " + notes : "",
      ]
        .filter(Boolean)
        .join(" | ");

      formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_request_human_followup");
      formData.append("nonce", config.requestHumanNonce || config.nonce || "");
      formData.append("session_token", ensureApplyChatSessionToken());
      formData.append(
        "post_id",
        postId || root.getAttribute("data-post-id") || ""
      );
      formData.append("role_title", role || roleTitle || "");
      formData.append("message", requestMessage);
      formData.append("active_path", activePath || "community_editorial");
      formData.append("prompt_state", promptState || "community_apply_for_me");
      formData.append("page_url", window.location.href || "");
      formData.append("conversation_focus", "community_editorial_apply_for_me");
      formData.append(
        "cv_profile",
        [storedCvName, storedCvUrl].filter(Boolean).join(" · ")
      );
      formData.append("context_summary", requestMessage);
      formData.append("request_kind", "apply_for_me");

      if (feedback) {
        feedback.hidden = true;
        feedback.textContent = "";
        feedback.classList.remove("is-error", "is-success");
      }
      if (submitButton) {
        submitButton.disabled = true;
        submitButton.textContent = isArabicChat()
          ? "جارٍ الإرسال..."
          : "Sending...";
      }

      window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          if (!payload || !payload.success) {
            throw new Error(
              (payload && payload.data && payload.data.message) ||
                "I couldn't send that through right now."
            );
          }
          closeApplyForMeModal();
          if (trigger) {
            trigger.disabled = true;
            trigger.setAttribute("aria-disabled", "true");
            trigger.textContent = isArabicChat() ? "تم الإرسال" : "Requested";
          }
          botMessage(
            isArabicChat()
              ? "تم إرسال هذا الطلب للفريق مع السيرة الذاتية التي اخترتها، وسيبدؤون من هناك."
              : "I have sent this through to the team with the saved CV you selected, so they can start from there.",
            humanComposeDelay(
              cleanMessageText(
                isArabicChat()
                  ? "تم إرسال هذا الطلب للفريق مع السيرة الذاتية التي اخترتها، وسيبدؤون من هناك."
                  : "I have sent this through to the team with the saved CV you selected, so they can start from there."
              ),
              1800,
              3400
            )
          );
        })
        .catch(function (error) {
          if (feedback) {
            feedback.hidden = false;
            feedback.classList.add("is-error");
            feedback.classList.remove("is-success");
            feedback.textContent =
              (error && error.message) ||
              (isArabicChat()
                ? "تعذر إرسال الطلب الآن."
                : "We could not send that request right now.");
          }
          if (submitButton) {
            submitButton.disabled = false;
            submitButton.textContent = isArabicChat()
              ? "أرسل الطلب"
              : "Send request";
          }
          if (trigger) {
            trigger.disabled = false;
            trigger.removeAttribute("aria-disabled");
            trigger.textContent = originalLabel;
          }
        });
    }

    function getJobSearchEmailRolePayload() {
      var filteredRoles = filterMatchingRoles();
      var cvMatchEntries = buildCvRoleMatches();
      var cvMatchMap = {};
      var targetTitle = cleanMessageText(roleTitle || "");
      var recentRoleTitle = cleanMessageText(cvFacts.experienceTitle || "");
      var recentRoleCompany = cleanMessageText(cvFacts.experienceCompany || "");
      var isArabic = isArabicChat();

      function getRoleKey(item) {
        return [
          cleanMessageText((item && item.title) || "").toLowerCase(),
          cleanMessageText((item && item.company) || "").toLowerCase(),
          cleanMessageText((item && item.url) || "").toLowerCase(),
        ].join("::");
      }

      function getNormalizedSearchRankScore(index, total) {
        if (total <= 1) {
          return 100;
        }
        return Math.max(
          52,
          Math.round(100 - (index / Math.max(1, total - 1)) * 32)
        );
      }

      function countTermOverlap(text, terms) {
        var haystack = cleanMessageText(text || "").toLowerCase();
        return (terms || []).reduce(function (count, term) {
          return haystack.indexOf(term) !== -1 ? count + 1 : count;
        }, 0);
      }

      function buildCompanyDescriptor(item) {
        var sector = cleanMessageText((item && item.sector) || "").replace(
          /_/g,
          " "
        );
        var seniority = cleanMessageText(
          (item && item.seniority) || ""
        ).replace(/_/g, " ");
        var location = cleanMessageText((item && item.location) || "");
        var descriptor = [];
        if (sector) {
          descriptor.push(sector);
        }
        if (seniority) {
          descriptor.push(
            isArabic
              ? seniority + " ضمن مسار التوظيف"
              : seniority + " hiring lane"
          );
        }
        if (location) {
          descriptor.push(location);
        }
        return descriptor.join(" · ");
      }

      function buildFallbackFitSummary(item, cvEntry) {
        var summaries = [];
        var itemTitle = cleanMessageText((item && item.title) || "");
        var itemLocation = cleanMessageText((item && item.location) || "");
        var itemHaystack = cleanMessageText(
          [
            item && item.title,
            item && item.snippet,
            item && item.skills,
            item && item.requirements,
          ].join(" ")
        ).toLowerCase();

        // Check for Arabic language requirement
        if (
          /\b(?:arabic|عربي|fluent in arabic|arabic speaker|arabic fluency|native arabic)\b/i.test(
            itemHaystack
          )
        ) {
          summaries.push(
            isArabic
              ? "يتطلب إجادة اللغة العربية - وهذا يناسب ملفك."
              : "Requires Arabic fluency - which aligns with your profile."
          );
        }

        // Check for specific language requirements
        if (
          /\b(?:french|fluent in french|french speaker)\b/i.test(itemHaystack)
        ) {
          summaries.push(
            isArabic
              ? "يتطلب اللغة الفرنسية."
              : "French language skills are valued for this role."
          );
        }

        // Check for visa/sponsorship mentions
        if (
          /\b(?:visa sponsorship|sponsor(?:ed)?|work permit|right to work)\b/i.test(
            itemHaystack
          )
        ) {
          summaries.push(
            isArabic
              ? "قد تتوفر رعاية تأشيرة لهذا الدور."
              : "Visa sponsorship may be available for this role."
          );
        }

        // Add CV skill matches if available
        if (cvEntry && cvEntry.whyMatches && cvEntry.whyMatches.length > 0) {
          // Find skill-related match
          var skillMatch = cvEntry.whyMatches.find(function (match) {
            return /overlap|skill|experience|qualification|support/i.test(
              match
            );
          });
          if (skillMatch) {
            summaries.push(cleanMessageText(skillMatch));
          }
        }

        // Add CV support context if available
        if (cvEntry && cvEntry.cvSupport && cvEntry.cvSupport.length > 0) {
          var supportLine = cvEntry.cvSupport.find(function (line) {
            return /signal|include|detected/i.test(line);
          });
          if (supportLine && summaries.length < 2) {
            summaries.push(cleanMessageText(supportLine));
          }
        }

        // Fallback to title/background match
        if (summaries.length === 0 && targetTitle && itemTitle) {
          summaries.push(
            isArabic
              ? "يتماشى مع مسار " + targetTitle + " الذي تبحث عنه."
              : "Aligns with the " + targetTitle + " path you're exploring."
          );
        }

        if (summaries.length === 0 && recentRoleTitle) {
          summaries.push(
            isArabic
              ? "يبني على خبرتك الأخيرة كـ " + recentRoleTitle + "."
              : "Builds on your recent " + recentRoleTitle + " experience."
          );
        }

        // Location alignment
        if (
          itemLocation &&
          getJobSearchLocationFilter() &&
          summaries.length < 2
        ) {
          summaries.push(
            isArabic
              ? "يقع في " + itemLocation + " التي تستهدفها."
              : "Based in " + itemLocation + ", matching your target market."
          );
        }

        // Combine up to 2 insights
        if (summaries.length >= 2) {
          return summaries.slice(0, 2).join(" ");
        }
        return (
          summaries[0] ||
          (isArabic
            ? "هذه الفرصة تقع داخل مسار البحث الذي تعطيه سنّا الأولوية لك."
            : "This role sits inside the search lane MENA Careers is prioritising for you.")
        );
      }

      cvMatchEntries.forEach(function (entry) {
        var key = getRoleKey((entry && entry.item) || {});
        if (key) {
          cvMatchMap[key] = entry;
        }
      });

      return filteredRoles
        .map(function (item, index) {
          var recruiterPreview = getRoleRecruiterPreview(item);
          var key = getRoleKey(item);
          var cvEntry = cvMatchMap[key] || null;
          var recentTerms = getMatchingRoleTitleTerms(
            recentRoleTitle + " " + recentRoleCompany
          );
          var titleTerms = getMatchingRoleTitleTerms(targetTitle);
          var titleOverlap = countTermOverlap(item.title, titleTerms);
          var recentOverlap = countTermOverlap(
            [item.title, item.company, item.sector, item.snippet].join(" "),
            recentTerms
          );
          var searchRankScore = getNormalizedSearchRankScore(
            index,
            filteredRoles.length
          );
          var cvScore = cvEntry
            ? Math.max(0, Math.round(Number(cvEntry.score || 0)))
            : 0;
          var matchScore = Math.round(
            Math.max(
              cvEntry ? 58 : 46,
              Math.min(
                98,
                searchRankScore * 0.52 +
                  cvScore * 0.38 +
                  titleOverlap * 4 +
                  recentOverlap * 3 +
                  (cleanMessageText(item.title).toLowerCase() ===
                  targetTitle.toLowerCase()
                    ? 5
                    : 0)
              )
            )
          );
          var fitSummary = buildFallbackFitSummary(item, cvEntry);
          var recruiterInitials =
            cleanMessageText(recruiterPreview.name || item.recruiter || "R")
              .split(/\s+/)
              .filter(Boolean)
              .slice(0, 2)
              .map(function (part) {
                return part.charAt(0).toUpperCase();
              })
              .join("") || "R";
          return {
            title: cleanMessageText(item.title || ""),
            company: cleanMessageText(item.company || ""),
            location: cleanMessageText(item.location || ""),
            seniority: cleanMessageText(item.seniority || ""),
            sector: cleanMessageText(item.sector || ""),
            salary: cleanMessageText(item.salary || ""),
            company_descriptor: buildCompanyDescriptor(item),
            fit_summary: fitSummary,
            fit_label: cvEntry
              ? cleanMessageText(
                  cvEntry.fitType || (isArabic ? "مطابقة" : "Fit")
                )
              : isArabic
              ? "مطابقة"
              : "Match",
            match_score: matchScore,
            recruiter_initials: recruiterInitials,
            recent_role_title: recentRoleTitle,
            url: cleanMessageText(item.url || ""),
            recruiter_name: cleanMessageText(
              recruiterPreview.name || item.recruiter || ""
            ),
            recruiter_title: cleanMessageText(
              recruiterPreview.title || item.recruiter_title || ""
            ),
            recruiter_company: cleanMessageText(
              recruiterPreview.company || item.company || ""
            ),
            recruiter_location: cleanMessageText(
              recruiterPreview.location || item.location || ""
            ),
            recruiter_regions: cleanMessageText(recruiterPreview.regions || ""),
            recruiter_email: cleanMessageText(
              recruiterPreview.email || item.recruiter_email || ""
            ),
            recruiter_phone: cleanMessageText(recruiterPreview.phone || ""),
            recruiter_linkedin: cleanMessageText(
              recruiterPreview.linkedin || ""
            ),
          };
        })
        .filter(function (item) {
          return item.title && item.url;
        })
        .sort(function (left, right) {
          return Number(right.match_score || 0) - Number(left.match_score || 0);
        })
        .slice(0, 6);
    }

    function getJobSearchEmailRecruiterPayload() {
      return filterMatchingRecruiters()
        .slice(0, 3)
        .map(function (item) {
          return {
            name: cleanMessageText(item.name || ""),
            title: cleanMessageText(item.title || ""),
            company: cleanMessageText(item.company || ""),
            location: cleanMessageText(item.location || ""),
            regions: cleanMessageText(item.regions || ""),
          };
        })
        .filter(function (item) {
          return item.name;
        });
    }

    function sendJobSearchMatchesEmail(email, options) {
      var config = getConfig();
      var payloadOptions = options || {};
      var formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_send_matches_email");
      formData.append(
        "nonce",
        config.matchesEmailNonce ||
          config.chatSessionNonce ||
          config.nonce ||
          ""
      );
      formData.append("email", cleanMessageText(email || ""));
      formData.append(
        "full_name",
        cleanMessageText(applyOnboardingFullName || "")
      );
      formData.append("role_title", cleanMessageText(roleTitle || ""));
      formData.append("focus", describeConversationFocus());
      formData.append("cv_profile", describeCvProfile());
      formData.append("language", isArabicChat() ? "ar" : "en");
      formData.append("post_id", postId || "");
      formData.append("hero_role_url", cleanMessageText(roleUrl || ""));
      formData.append("roles", JSON.stringify(getJobSearchEmailRolePayload()));
      formData.append(
        "recruiters",
        JSON.stringify(getJobSearchEmailRecruiterPayload())
      );
      formData.append(
        "email_variant",
        cleanMessageText(payloadOptions.variant || "job_search")
      );
      formData.append(
        "support_mode",
        cleanMessageText(payloadOptions.supportMode || "")
      );
      formData.append(
        "priority",
        cleanMessageText(payloadOptions.priority || "")
      );
      formData.append(
        "route_summary",
        cleanMessageText(payloadOptions.routeSummary || "")
      );
      formData.append(
        "applications_per_week",
        cleanMessageText(payloadOptions.applicationsPerWeek || "")
      );
      formData.append(
        "intros_per_week",
        cleanMessageText(payloadOptions.introsPerWeek || "")
      );
      formData.append(
        "lane_preference",
        cleanMessageText(payloadOptions.lanePreference || "")
      );
      formData.append(
        "constraints_text",
        cleanMessageText(payloadOptions.constraintsText || "")
      );
      formData.append(
        "highlight_text",
        cleanMessageText(payloadOptions.highlightText || "")
      );
      formData.append(
        "preferred_email",
        cleanMessageText(payloadOptions.preferredEmail || email || "")
      );

      return window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          if (!payload || !payload.success) {
            throw new Error(
              (payload && payload.data && payload.data.message) ||
                "I couldn't send the test email just now."
            );
          }

          function sendApplyIntroWelcomeEmail() {
            var state = ensureApplyIntroState();
            var targetEmail = cleanMessageText(
              state.email || applyOnboardingPreferredEmail || ""
            );
            if (!targetEmail || state.welcomeEmailSent) {
              return Promise.resolve({ skipped: true });
            }
            return sendJobSearchMatchesEmail(targetEmail, {
              variant: "apply_intro_welcome",
              supportMode: state.supportMode || "",
              priority: state.priority || "",
              routeSummary: getApplyIntroRouteSummary(),
              applicationsPerWeek: state.applicationsPerWeek || "",
              introsPerWeek: state.introsPerWeek || "",
              lanePreference: state.lanePreference || "",
              constraintsText: state.constraints || "",
              highlightText: state.highlight || state.introAngle || "",
              preferredEmail: targetEmail,
            }).then(function (payload) {
              state.welcomeEmailSent = true;
              return payload;
            });
          }
          return payload.data || {};
        });
    }

