    function answerKnowledgeQuestion(intent, nextPlaceholder, sourceText) {
      var answer = composeKnowledgeAnswer(
        intent,
        sourceText || lastUserInputText
      );
      if (!answer) {
        return false;
      }
      rememberAnsweredConversationIntent(
        sourceText || lastUserInputText,
        intent
      );
      botMessage(
        answer,
        humanComposeDelay(answer, 2200, 5200),
        function () {
          focusComposer(nextPlaceholder || getComposerPlaceholder("message"));
        },
        humanReadDelay(lastUserInputText, 450)
      );
      return true;
    }

    function getCvRequiredResumePrompt() {
      var ctx = getEmilyVoiceContext();
      if (ctx.roleTitle || ctx.roleCompany) {
        return getContextualCvRequestLine(ctx.role, "compare");
      }
      if (ctx.isPaying) {
        return pickVariant("cv_required_resume_prompt_paying", [
          (ctx.firstName ? ctx.firstName + ", " : "") +
            "I do not have an active CV saved in this chat yet. Upload it once and I’ll use it across the roles we review.",
          "Add the CV you want me to use for this search. I’ll keep it attached so we do not keep restarting.",
          "I can keep the search moving, but the CV is what lets me rank the roles around your actual evidence.",
        ]);
      }
      return pickVariant("cv_required_resume_prompt_guest", [
        "Upload your CV when you want the search to become personal rather than just keyword-based.",
        "Add your CV and I’ll use it to separate realistic matches from roles that only look right by title.",
        "Once your CV is in, I can judge fit properly and keep the stronger roles in focus.",
        "You can keep searching without a CV, but upload it when you want me to assess the match properly.",
      ]);
    }

    function isExplicitMemoryContextRequest(text) {
      var clean = normalizeCareerIntentText(cleanMessageText(text || ""));
      if (!clean) {
        return false;
      }
      return /(?:what did i say my name was|what cv did i upload|what resume did i upload|repeat what i told you|repeat everything i told you|what'?s my email address|whats my email address|do you remember me|remember me from yesterday|remember what i told you|what did we talk about|what did i say before|وش قلت لك قبل|تتذكرني|وش رفعته|وش كان بريدي|وش اسمي)/i.test(
        clean
      );
    }

    function shouldUseCvUploadContextBridge(intent) {
      return /^(?:how_help|job_search_help|job_search_strategy|opportunity_search|matching_jobs|find_job|get_hired_help|career_direction|career_growth|role_help|specific_role_interest|company_research|recruiter_networking|linkedin_visibility_strategy|hidden_market_roles|hiring_friction_diagnosis|uae_local_candidate_bias|emotional_support|struggling_help|location_preferences|salary_question|market_activity|market_compensation_reality|offer_decision|rejection_help|skill_gap_help|cv_upload_stage)$/.test(
        String(intent || "")
      );
    }

    function getCvUploadContextBridge(intent, sourceText) {
      var targetSummary = getSourceTargetSummary(sourceText || "");
      if (intent === "cv_upload_stage") {
        return getCvRequiredResumePrompt();
      }
      if (isArabicChat()) {
        if (targetSummary) {
          return (
            "وبمجرد أن ترسلي الـCV، أقدر أحول هذا من كلام عام إلى قراءة دقيقة حول " +
            targetSummary +
            "."
          );
        }
        return pickVariant("cv_upload_context_bridge_ar", [
          "وبمجرد أن ترسلي الـCV، أقدر أجعل هذا محدداً على خلفيتك بدل أن يبقى عاماً.",
          "وإذا أرسلتي الـCV بعد ذلك، أقدر أربط هذا مباشرة بخبرتك الفعلية.",
          "الـCV هنا فقط حتى أحول هذا من نصيحة عامة إلى توجيه دقيق على وضعك.",
        ]);
      }
      if (targetSummary) {
        return (
          "Once you send the CV, I can turn that from general advice into something specific around " +
          targetSummary +
          "."
        );
      }
      return pickVariant("cv_upload_context_bridge", [
        "Once you send the CV, I can make that specific to your background instead of keeping it general.",
        "If you send the CV after that, I can tie this directly to your actual experience.",
        "The CV is there so I can turn this from generic advice into a precise read on your situation.",
      ]);
    }

