    function finishCommercialApplyQueueProcessing() {
      if (isGreenhouseAdminTestEnabled()) {
        showGreenhouseTestSummary();
        return;
      }
      if (isTeamtailorAdminTestEnabled()) {
        showTeamtailorTestSummary();
        return;
      }
      if (isWorkdayAdminTestEnabled()) {
        botMessage(
          renderProviderTestResultCard(workableTestResults, "Workday"),
          humanComposeDelay("Workday test result.", 700, 1400),
          function () {
            focusComposer("Run another test or search another role");
          }
        );
        return;
      }
      if (isSuccessFactorsAdminTestEnabled()) {
        showSuccessFactorsTestSummary();
        return;
      }
      if (isSimpleDropAdminTestEnabled()) {
        showSimpleDropTestSummary();
        return;
      }
      if (isWorkableAdminTestEnabled()) {
        showWorkableTestSummary();
        return;
      }
      var submittedCount = commercialApplyQueueItemsState.filter(function (
        item
      ) {
        return /^(submitted|complete|completed)$/i.test(
          cleanMessageText(item.status || "")
        );
      }).length;
      var referredCount = commercialApplyQueueItemsState.filter(function (
        item
      ) {
        return /^referred$/i.test(cleanMessageText(item.status || ""));
      }).length;
      var queuedCount = commercialApplyQueueItemsState.filter(function (item) {
        return /^(in queue|queued|ready)$/i.test(
          cleanMessageText(item.status || "")
        );
      }).length;
      var message =
        commercialApplyQueueItemsState.length === 1 && submittedCount < 1
          ? "I have not submitted this application. The role is still selected, and I need either employer confirmation, a manual review step, or your instruction before moving it forward."
          : queuedCount > 0
          ? "I’ve processed the roles that can run through the application worker now. The remaining roles are still in the queue, and I can keep searching from here."
          : "I’ve finished submitting the shortlisted applications. Do you want me to continue the search?";
      if (referredCount > 0 && submittedCount > 0) {
        message =
          "I’ve finished processing the shortlist. " +
          submittedCount +
          " application" +
          (submittedCount === 1 ? " is" : "s are") +
          " submitted and " +
          referredCount +
          " " +
          (referredCount === 1 ? "has" : "have") +
          " been referred for manual submission. Do you want me to continue the search?";
      } else if (referredCount > 0) {
        message =
          "I’ve finished processing the shortlist. The roles that could not be safely submitted automatically have been referred for manual submission. Do you want me to continue the search?";
      }
      botMessage(message, humanComposeDelay(message, 1000, 2200), function () {
        focusComposer("Tell me whether to continue the search");
      });
    }

    function getSuccessFactorsProfilePayload() {
      var profile = {};
      var text = cleanMessageText(capturedCvText || "");
      var headerModel = null;
      if (text) {
        try {
          headerModel = buildCvHeaderModel(text, parseCvSectionsFromText(text));
        } catch (error) {
          headerModel = null;
        }
        if (headerModel && headerModel.location) {
          profile.country_of_residence = cleanMessageText(
            headerModel.location || ""
          );
        } else {
          var countryMatch = text.match(
            /\b(United Arab Emirates|Saudi Arabia|Qatar|United Kingdom|France|Morocco|Singapore|India|United States)\b/i
          );
          if (countryMatch && countryMatch[1]) {
            profile.country_of_residence = cleanMessageText(countryMatch[1]);
          }
        }
        var nationalityMatch = text.match(
          /\bnationality\s*(?:is|:|-)?\s*([A-Za-z ]{2,40})/i
        );
        if (nationalityMatch && nationalityMatch[1]) {
          profile.nationality = cleanMessageText(nationalityMatch[1]).replace(
            /\s+national(?:ity)?$/i,
            ""
          );
        }
      }
      return Object.assign({}, profile, successFactorsProfileDraft || {});
    }

    function ensureWorkdayAccountChoiceThenQueue(
      queueItem,
      startQueueCallback
    ) {
      if (!isWorkdayQueueItem(queueItem || {})) {
        startQueueCallback();
        return;
      }
      if (!workdayAccountPreference) {
        workdayAccountPreference = "create";
        workdayAccountPassword = "";
        botMessage(
          "This employer uses Workday. I’m creating a tenant-specific account using your application email if the form requires it.",
          humanComposeDelay("Creating Workday account route.", 900, 1800),
          startQueueCallback
        );
        return;
      }
      if (workdayAccountPreference) {
        startQueueCallback();
        return;
      }
      botMessage(
        "This employer uses Workday, so I need the account route before I can send it to the worker. Should I create a new Workday account for this employer, or use an existing one?",
        humanComposeDelay("Workday needs an account route.", 1200, 2600),
        function () {
          setPromptState(
            "workday_account_route",
            {
              create: function (value) {
                workdayAccountPreference = "create";
                workdayAccountPassword = "";
                clearPromptState();
                echoPromptChoice(value || "Create a new Workday account");
                startQueueCallback();
              },
              existing: function (value) {
                workdayAccountPreference = "sign_in";
                clearPromptState();
                echoPromptChoice(value || "Use existing Workday account");
                botMessage(
                  "Send the password for this employer’s Workday account. I’ll only attach it to this application task.",
                  humanComposeDelay(
                    "Existing Workday password required.",
                    900,
                    1800
                  ),
                  function () {
                    setPromptState(
                      "workday_account_password",
                      {
                        other: function (passwordValue) {
                          var cleanPassword = String(
                            passwordValue || ""
                          ).trim();
                          if (!cleanPassword) {
                            focusComposer("Enter the Workday account password");
                            return;
                          }
                          workdayAccountPassword = cleanPassword;
                          clearPromptState();
                          userMessage("Workday password provided");
                          startQueueCallback();
                        },
                      },
                      "Enter the Workday account password",
                      { provider: "workday" }
                    );
                    focusComposer("Enter the Workday account password");
                  }
                );
              },
              other: function () {
                focusComposer(
                  "Choose Create new account or Use existing account"
                );
              },
            },
            "Choose Workday account route",
            { provider: "workday" }
          );
          botMessage(
            '<div class="sffc-crm-apply-chat__inline-action-row">' +
              '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-workday-account-route="create">Create new account</button>' +
              '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-workday-account-route="existing">Use existing account</button>' +
              "</div>",
            0
          );
          focusComposer("Choose a Workday account route");
        }
      );
    }

