    function bumpCommercialApplyQueueRunToken() {
      commercialApplyQueueRunToken += 1;
      return commercialApplyQueueRunToken;
    }

    function isCommercialApplyQueueRunCurrent(runToken) {
      return !!(
        commercialApplyQueueActivated &&
        runToken &&
        runToken === commercialApplyQueueRunToken
      );
    }

    function queueCommercialApplyQueueWorkerTask(itemIndex, runToken) {
      if (!isCommercialApplyQueueRunCurrent(runToken)) {
        return Promise.resolve({ status: "cancelled" });
      }
      var item = commercialApplyQueueItemsState[itemIndex] || {};
      var providerLabel = getCommercialApplyQueueProviderLabel(item);
      var queueTask =
        isGreenhouseAdminTestEnabled() && isGreenhouseQueueItem(item)
          ? queueGreenhouseAdminTestApplicationTask
          : isTeamtailorAdminTestEnabled() && isTeamtailorQueueItem(item)
          ? queueTeamtailorAdminTestApplicationTask
          : isWorkableAdminTestEnabled() && isWorkableQueueItem(item)
          ? queueWorkableAdminTestApplicationTask
          : isSimpleDropAdminTestEnabled() && isSimpleDropQueueItem(item)
          ? queueSimpleDropAdminTestApplicationTask
          : isSuccessFactorsAdminTestEnabled() &&
            isSuccessFactorsQueueItem(item)
          ? queueSuccessFactorsAdminTestApplicationTask
          : isWorkdayAdminTestEnabled() && isWorkdayQueueItem(item)
          ? queueWorkdayAdminTestApplicationTask
          : getBrowserApplicationQueueTask();
      updateCommercialQueueItemStatus(
        itemIndex,
        "Checking form",
        "Emily is checking the next form"
      );
      announceCommercialApplyQueueProgress(
        itemIndex,
        "checking_form",
        "I’m checking the " +
          providerLabel +
          " form and employer-required fields now.",
        providerLabel + " form check",
        runToken
      );
      return new Promise(function (resolve, reject) {
        var queueAfterRequiredAnswers = function () {
          if (!isCommercialApplyQueueRunCurrent(runToken)) {
            resolve({ status: "cancelled" });
            return;
          }
          ensureWorkdayAccountChoiceThenQueue(item, function () {
            if (!isCommercialApplyQueueRunCurrent(runToken)) {
              resolve({ status: "cancelled" });
              return;
            }
            ensureSuccessFactorsAccountChoiceThenQueue(item, function () {
              if (!isCommercialApplyQueueRunCurrent(runToken)) {
                resolve({ status: "cancelled" });
                return;
              }
              ensureSuccessFactorsProfileThenQueue(item, function () {
                if (!isCommercialApplyQueueRunCurrent(runToken)) {
                  resolve({ status: "cancelled" });
                  return;
                }
                if (typeof queueTask !== "function") {
                  reject(
                    new Error(
                      "I could not start the application worker from this chat session."
                    )
                  );
                  return;
                }
                announceCommercialApplyQueueProgress(
                  itemIndex,
                  "worker_start",
                  "I’m opening the " + providerLabel + " application page now.",
                  providerLabel + " application opening",
                  runToken
                );
                queueTask(item).then(resolve).catch(reject);
              });
            });
          });
        };
        if (typeof ensureApplicationWorkerAnswersThenQueue === "function") {
          ensureApplicationWorkerAnswersThenQueue(queueAfterRequiredAnswers);
          return;
        }
        queueAfterRequiredAnswers();
      }).then(function (data) {
        if (!isCommercialApplyQueueRunCurrent(runToken)) {
          return { status: "cancelled" };
        }
        var taskUuid = cleanMessageText((data && data.task_uuid) || "");
        if (
          taskUuid &&
          isGreenhouseAdminTestEnabled() &&
          isGreenhouseQueueItem(item)
        ) {
          window.__sffcGreenhouseLastTaskUuid = taskUuid;
        }
        if (
          taskUuid &&
          isWorkableAdminTestEnabled() &&
          isWorkableQueueItem(item)
        ) {
          window.__sffcWorkableLastTaskUuid = taskUuid;
        }
        if (
          taskUuid &&
          isTeamtailorAdminTestEnabled() &&
          isTeamtailorQueueItem(item)
        ) {
          window.__sffcTeamtailorLastTaskUuid = taskUuid;
        }
        if (
          taskUuid &&
          isWorkdayAdminTestEnabled() &&
          isWorkdayQueueItem(item)
        ) {
          window.__sffcWorkdayLastTaskUuid = taskUuid;
        }
        commercialApplyQueueItemsState = commercialApplyQueueItemsState.map(
          function (candidate, index) {
            if (index !== itemIndex) {
              return candidate;
            }
            return Object.assign({}, candidate, {
              status: taskUuid ? "Running" : "Referred",
              applicationTaskUuid: taskUuid,
            });
          }
        );
        if (
          !refreshCommercialApplyQueueCardStatus({
            active: true,
            showButton: false,
            eyebrow: "Application queue",
            title: "Emily is working through this list",
            preserveScroll: true,
            pinScroll: false,
          })
        ) {
          updateCommercialApplyQueueCard({
            active: true,
            showButton: false,
            eyebrow: "Application queue",
            title: "Emily is working through this list",
            preserveScroll: true,
            pinScroll: false,
          });
        }
        if (!taskUuid) {
          if (
            isGreenhouseAdminTestEnabled() ||
            isTeamtailorAdminTestEnabled() ||
            isWorkableAdminTestEnabled() ||
            isSuccessFactorsAdminTestEnabled() ||
            isWorkdayAdminTestEnabled() ||
            isSimpleDropAdminTestEnabled()
          ) {
            workableTestResults.push({
              item: item,
              data: {
                status: "failed",
                last_error: "WordPress did not return a worker task ID.",
              },
            });
          }
          askApplyResultsOfflineEmailConfirmation(itemIndex, {
            status: "failed",
            last_error: "WordPress did not return a worker task ID.",
          });
          return { status: "failed", sffcOfflinePrompted: true };
        }
        return pollCommercialApplyQueueWorkerTask(
          taskUuid,
          itemIndex,
          0,
          runToken
        ).then(function (result) {
          if (!isCommercialApplyQueueRunCurrent(runToken)) {
            return { status: "cancelled" };
          }
          if (
            typeof shouldRetryWorkableTestWithAdminAnswers === "function" &&
            typeof askWorkableTestCustomQuestions === "function" &&
            shouldRetryWorkableTestWithAdminAnswers(itemIndex, result || {})
          ) {
            commercialApplyQueueItemsState = commercialApplyQueueItemsState.map(
              function (candidate, index) {
                if (index !== itemIndex) {
                  return candidate;
                }
                return Object.assign({}, candidate, {
                  status: "Needs answer",
                  workableTestRetryCount:
                    Number(candidate.workableTestRetryCount || 0) + 1,
                });
              }
            );
            refreshCommercialApplyQueueCardStatus({
              active: true,
              showButton: false,
              eyebrow: "Workable admin test",
              title: "Workable needs an admin answer",
              preserveScroll: true,
              pinScroll: false,
            });
            return askWorkableTestCustomQuestions(itemIndex, result || {}).then(
              function (answered) {
                if (answered) {
                  updateCommercialQueueItemStatus(
                    itemIndex,
                    "Retrying",
                    "Emily is retrying the Workable form"
                  );
                  return queueCommercialApplyQueueWorkerTask(
                    itemIndex,
                    runToken
                  );
                }
                return result;
              }
            );
          }
          if (
            isGreenhouseAdminTestEnabled() ||
            isTeamtailorAdminTestEnabled() ||
            isWorkableAdminTestEnabled() ||
            isSuccessFactorsAdminTestEnabled() ||
            isWorkdayAdminTestEnabled() ||
            isSimpleDropAdminTestEnabled()
          ) {
            workableTestResults.push({
              item: item,
              data: result || data || { status: "failed" },
            });
          }
          return result;
        });
      });
    }

