    function getUpdatedCvRequestLine() {
      var ctx = getEmilyVoiceContext(pendingApplyResultsSelection);
      var subject = escapeHtml(getEmilyRoleSubject(ctx));
      return pickVariant("emily_updated_cv_request", [
        "Add the CV you want me to use for " +
          subject +
          ". I’ll keep this role selected while you upload it.",
        "Okay. Upload or paste the version I should use for " +
          subject +
          ", and I’ll continue from this exact role.",
        "No problem. I’ll wait for the replacement CV before moving " +
          subject +
          " forward.",
      ]);
    }

    function getContextualSearchPreferenceAck(feedback, sourceText) {
      var ctx = getEmilyVoiceContext();
      var updates = feedback && feedback.updates ? feedback.updates : [];
      var providerClear = updates.some(function (update) {
        return update.field === "providerFilter" && update.action === "clear";
      });
      var seniority = updates.some(function (update) {
        return update.field === "targetSeniority";
      });
      var location = updates
        .filter(function (update) {
          return update.field === "targetLocations";
        })
        .map(function (update) {
          return cleanMessageText(update.value || "");
        })
        .filter(Boolean)[0];
      if (providerClear) {
        return pickVariant("emily_search_ack_provider_clear", [
          "Done. I’ll stop restricting this to one ATS and search across every application route again.",
          "I’ve removed the ATS restriction. The next results can include Workday, Greenhouse, Teamtailor, SuccessFactors, Workable, and direct forms.",
          "Good call. I’ll widen the provider filter and rank the roles on fit rather than application system.",
        ]);
      }
      if (location) {
        return pickVariant("emily_search_ack_location", [
          "Got it. I’ll move the search toward " +
            location +
            " and refresh the roles.",
          "I’ll shift the market to " +
            location +
            " and keep the rest of the search logic intact.",
          "Understood. I’m updating the location signal to " +
            location +
            " before I rerun the results.",
        ]);
      }
      if (seniority) {
        return pickVariant("emily_search_ack_seniority", [
          "That makes sense. I’ll recalibrate the seniority instead of showing more of the same level.",
          "I’ll adjust the level now, then rerank the roles so the next set is closer to what you meant.",
          "I’ve taken that as seniority feedback. I’ll refresh the list with that in mind.",
        ]);
      }
      if (ctx.lastObjection || cleanMessageText(sourceText || "")) {
        return pickVariant("emily_search_ack_feedback", [
          "Got it. I’ll use that as search feedback and refresh the roles.",
          "That helps. I’ll update the search around what you just ruled in and out.",
          "I’ll treat that as a preference change, not a one-off comment, and rerun the search.",
        ]);
      }
      return pickVariant("emily_search_ack_generic", [
        "Got it. I’ll refresh the roles with that change.",
        "I’ll update the search and bring back a cleaner set.",
        "I’ll rerun the search with the latest criteria.",
      ]);
    }

    function getContextualClarifyingRouteLine() {
      var ctx = getEmilyVoiceContext();
      var subject = getEmilyRoleSubject(ctx);
      if (ctx.roleTitle || ctx.roleCompany) {
        return pickVariant("emily_clarify_with_role", [
          "I want to answer the right thing. Are we still working on " +
            subject +
            ", changing the search, or talking through a career question?",
          "Quick check before I move anything: do you want me to keep focus on " +
            subject +
            ", update the search, or answer this as general career advice?",
          "I’m not certain whether that was about " +
            subject +
            " or the wider search. Which one should I use?",
        ]);
      }
      return pickVariant("emily_clarify_no_role", [
        "I want to route that properly. Are you trying to search for roles, work on an application, or ask a career question?",
        "Quick check: should I treat that as a new job search, an application instruction, or a career question?",
        "I can help, but I need one bit of direction first: search, application, or career advice?",
      ]);
    }

    function getNoActiveApplicationStatusLine() {
      var ctx = getEmilyVoiceContext();
      var focus = getEmilySearchFocusSummary(ctx);
      if (focus) {
        return pickVariant("emily_status_no_application_with_search", [
          "There isn’t an active application running right now. The live context I have is your search around " +
            focus +
            ". Choose a result and I’ll track the application from there.",
          "No application is currently in progress. I still have the search context around " +
            focus +
            ", so the next step is to pick a role or refine that search.",
          "I have a search active, not a submitted application. Pick one of the results and I’ll show the application status from that role onward.",
        ]);
      }
      return pickVariant("emily_status_no_application", [
        "There is not an active application in this chat yet. Search for a role or choose a result and I’ll track the status from there.",
        "I do not have an application underway right now. Once you choose a role, I’ll keep the status tied to that employer link.",
        "Nothing has been submitted or started yet. Send a role search or pick a result, and I’ll keep the application state clear from there.",
      ]);
    }

    function classifyCareerConversationMessage(
      value,
      state,
      semantics,
      intent
    ) {
      var clean = cleanMessageText(value || "");
      var lower = normalizeCareerIntentText(clean).toLowerCase();
      var promptKey = String(state || "");
      var resolvedIntent = intent || detectIntent(clean);
      var hasQuestion = !!(
        (semantics && semantics.has_question) ||
        /^(?:how|what|where|why|should|can|could|would|which)\b/i.test(lower)
      );
      var mentionsDubai = /\b(?:dubai|dxb|uae|united arab emirates)\b/i.test(
        lower
      );
      var mentionsRiyadh = /\b(?:riyadh|saudi|ksa|saudi arabia)\b/i.test(lower);
      var mentionsAbuDhabi = /\babu\s+dhabi\b/i.test(lower);
      var mentionsMiddleEast = /\b(?:middle east|mena|gcc|gulf)\b/i.test(lower);
      var explicitPause =
        /\b(?:don'?t|do not|dont|not)\s+(?:want\s+to\s+)?apply\b/i.test(
          lower
        ) ||
        /\b(?:pause|stop|hold off|wait)\s*(?:,|\s)+(?:the\s+)?(?:application|applying|apply|i want|let me|before)\b/i.test(
          lower
        ) ||
        /\b(?:not apply yet|don'?t apply yet|dont apply yet|forget the application|leave the application|don'?t submit yet|dont submit yet|pause before submission|wait stop|stop again)\b/i.test(
          lower
        ) ||
        (hasActiveApplicationLikeTask() &&
          /^(?:stop|pause|wait|hold off|not yet|cancel)$/i.test(lower));
      var resumeApplication =
        /\b(?:back to|resume|carry on with|continue|go back to|proceed with)\s+(?:the\s+)?(?:application|applying|apply)\b/i.test(
          lower
        ) ||
        /^(?:ok|okay|yes|fine|sure)\s+(?:continue|carry on|resume|proceed|go ahead)\s+(?:with\s+)?(?:the\s+)?(?:application|applying|apply)\b/i.test(
          lower
        ) ||
        /\b(?:continue|carry on|resume|pick it back up|proceed)\s+(?:from\s+)?(?:where|exactly where)\s+(?:we|you)\s+(?:stopped|left off|paused)\b/i.test(
          lower
        ) ||
        /\b(?:fine carry on|ok carry on|okay carry on|carry on)\b/i.test(lower);
      var applicationStatus =
        /\b(?:what is happening|what's happening|where are we|status|progress|how far|what stage|where do we stand)\b.*\b(?:application|applying|apply|role)\b/i.test(
          lower
        ) ||
        /\b(?:application|applying|apply)\b.*\b(?:status|progress|where are we|what stage|what is happening|what's happening)\b/i.test(
          lower
        );
      var careerPlanning =
        /\b(?:stuck|help me plan|make a plan|career plan|career planning|don'?t know what i want|dont know what i want|what jobs suit me|career direction|help me with my career|what should i do next)\b/i.test(
          lower
        );
      var careerDecisionQuestion = looksLikeCareerDecisionQuestion(clean);
      var noInterviews =
        /\b(?:not getting interviews|no interviews|not getting calls|low response|getting rejected|rejections?|rejected)\b/i.test(
          lower
        );
      var salary =
        /\b(?:salary|compensation|pay|earn|package|aed|sar|bonus)\b/i.test(
          lower
        );
      var jobSearchAdvice =
        hasQuestion &&
        /\b(?:how|where|what)\b/i.test(lower) &&
        /\b(?:get|find|land|search|look for|apply|break into|get into)\b/i.test(
          lower
        ) &&
        /\b(?:job|jobs|role|roles|work|private equity|investment|banking|consulting|strategy|operations|finance|tech|technology)\b/i.test(
          lower
        );
      var marketComparison =
        (mentionsDubai ||
          mentionsRiyadh ||
          mentionsAbuDhabi ||
          mentionsMiddleEast) &&
        /\b(?:or|vs|versus|better|should i|which|compare|move)\b/i.test(lower);
      var recruiter =
        /\b(?:recruiter|recruiters|headhunter|hiring manager|network|outreach|referral)\b/i.test(
          lower
        );
      var interview = /\b(?:interview|interviews|interviewing|prepare)\b/i.test(
        lower
      );
      var cv =
        /\b(?:cv|resume|profile|linkedin)\b/i.test(lower) &&
        /\b(?:bad|fix|improve|review|tailor|position|positioning|weak|strong)\b/i.test(
          lower
        );
      var companyQuestion = !!(
        (semantics && semantics.asks_company_research) ||
        resolvedIntent === "company_research" ||
        resolvedIntent === "company_details" ||
        /\b(?:who|what)\s+(?:is|are)\s+(?:this|that|the)\s+compan(?:y|ies)\b/i.test(
          lower
        ) ||
        /\b(?:who|what)\s+(?:is|are)\s+(?:this|that)\s+employer\b/i.test(
          lower
        ) ||
        /\bwhat\s+do\s+they\s+(?:actually\s+)?do\b/i.test(lower)
      );

      if (!clean) {
        return null;
      }
      if (looksLikeSennaContactQuestion(clean)) {
        return {
          primaryIntent: "SUPPORT_CONTACT",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.96,
        };
      }
      if (
        looksLikeAnswerQualityComplaint(clean) ||
        looksLikeMisroutedSearchComplaint(clean)
      ) {
        return {
          primaryIntent: "ANSWER_QUALITY_COMPLAINT",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.95,
        };
      }
      if (looksLikeRecruiterNonResponseQuestion(clean)) {
        return {
          primaryIntent: "RECRUITER_NON_RESPONSE",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.97,
        };
      }
      if (careerDecisionQuestion) {
        return {
          primaryIntent: "CAREER_DECISION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.97,
        };
      }
      if (applicationStatus) {
        return {
          primaryIntent: "APPLICATION_STATUS",
          relationshipToCurrentTask: "CONTINUES_TASK",
          confidence: 0.95,
        };
      }
      if (
        resumeApplication &&
        (getLatestPausedCareerTask() || hasActiveApplicationLikeTask())
      ) {
        return {
          primaryIntent: "APPLICATION_RESUME",
          relationshipToCurrentTask: "RESUME_TASK",
          confidence: 0.94,
        };
      }
      if (explicitPause && companyQuestion) {
        return {
          primaryIntent: "COMPANY_RESEARCH",
          secondaryIntent: "APPLICATION_PAUSE",
          relationshipToCurrentTask: "INTERRUPTION",
          shouldPauseCurrentTask: true,
          confidence: 0.96,
        };
      }
      if (explicitPause) {
        return {
          primaryIntent: "APPLICATION_PAUSE",
          secondaryIntent: careerPlanning
            ? "CAREER_PLANNING"
            : "APPLICATION_PAUSE",
          relationshipToCurrentTask: "TASK_PAUSE",
          shouldPauseCurrentTask: true,
          confidence: 0.98,
        };
      }
      if (careerPlanning) {
        return {
          primaryIntent: "CAREER_PLANNING",
          secondaryIntent: /\bstuck\b/i.test(lower)
            ? "USER_STUCK"
            : "CAREER_DIRECTION",
          relationshipToCurrentTask: promptKey ? "TASK_CHANGE" : "NEW_GOAL",
          shouldPauseCurrentTask: !!promptKey || hasActiveApplicationLikeTask(),
          confidence: 0.96,
        };
      }
      if (mentionsDubai && jobSearchAdvice) {
        return {
          primaryIntent: "JOB_SEARCH_ADVICE",
          secondaryIntent: "MARKET_ENTRY",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          entities: { location: "Dubai" },
          confidence: 0.97,
        };
      }
      if (marketComparison) {
        return {
          primaryIntent: "MARKET_COMPARISON",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          entities: {
            locations: [
              mentionsDubai ? "Dubai" : "",
              mentionsAbuDhabi ? "Abu Dhabi" : "",
              mentionsRiyadh ? "Riyadh" : "",
            ].filter(Boolean),
          },
          confidence: 0.94,
        };
      }
      if (
        (mentionsDubai ||
          mentionsRiyadh ||
          mentionsAbuDhabi ||
          mentionsMiddleEast) &&
        (resolvedIntent === "get_hired_help" ||
          resolvedIntent === "location_preferences")
      ) {
        return {
          primaryIntent: mentionsDubai
            ? "JOB_SEARCH_ADVICE"
            : "MARKET_COMPARISON",
          secondaryIntent: "MARKET_ENTRY",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          entities: mentionsDubai
            ? { location: "Dubai" }
            : {
                locations: [
                  mentionsDubai ? "Dubai" : "",
                  mentionsAbuDhabi ? "Abu Dhabi" : "",
                  mentionsRiyadh ? "Riyadh" : "",
                ].filter(Boolean),
              },
          confidence: 0.91,
        };
      }
      if (
        salary &&
        (hasQuestion || mentionsDubai || mentionsRiyadh || mentionsMiddleEast)
      ) {
        return {
          primaryIntent: "SALARY_QUESTION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          entities: {
            locations: [
              mentionsDubai ? "Dubai" : "",
              mentionsAbuDhabi ? "Abu Dhabi" : "",
              mentionsRiyadh ? "Riyadh" : "",
            ].filter(Boolean),
          },
          confidence: 0.92,
        };
      }
      if (resolvedIntent === "market_compensation_reality") {
        return {
          primaryIntent: "SALARY_QUESTION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.9,
        };
      }
      if (noInterviews || resolvedIntent === "rejection_analysis") {
        return {
          primaryIntent: "LOW_INTERVIEW_RATE",
          relationshipToCurrentTask: promptKey ? "TASK_CHANGE" : "NEW_GOAL",
          confidence: 0.95,
        };
      }
      if (
        (recruiter && hasQuestion) ||
        resolvedIntent === "recruiter_networking"
      ) {
        return {
          primaryIntent: "RECRUITER_QUESTION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.9,
        };
      }
      if ((interview && hasQuestion) || resolvedIntent === "interview_prep") {
        return {
          primaryIntent: "INTERVIEW_HELP",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.9,
        };
      }
      if (
        (cv && hasQuestion) ||
        resolvedIntent === "cv_review_help" ||
        resolvedIntent === "cv_improvement"
      ) {
        return {
          primaryIntent: "CV_QUESTION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.88,
        };
      }
      if (
        resolvedIntent === "career_direction" ||
        resolvedIntent === "job_search_strategy" ||
        resolvedIntent === "get_hired_help" ||
        resolvedIntent === "location_preferences"
      ) {
        return {
          primaryIntent: "CAREER_QUESTION",
          relationshipToCurrentTask: promptKey ? "INTERRUPTION" : "NEW_GOAL",
          confidence: 0.86,
        };
      }
      return null;
    }

    function getCareerAdvisorChoiceActions(kind) {
      var choices;
      if (kind === "planning") {
        choices = [
          ["What roles suit my CV?", "Role fit"],
          ["Why am I not getting interviews?", "Interviews"],
          ["Help me choose a career direction", "Direction"],
          ["Should I move markets?", "Move markets"],
        ];
      } else if (kind === "market") {
        choices = [
          ["Compare Dubai, Abu Dhabi and Riyadh for me", "Compare markets"],
          ["Search current Dubai roles for my profile", "Dubai roles"],
          ["Search current Saudi roles for my profile", "Saudi roles"],
          ["What salary should I target?", "Salary"],
        ];
      } else {
        choices = [
          ["Find current roles that match my CV", "Find roles"],
          ["Review my CV against my target roles", "Review CV"],
          ["Help me prepare for interviews", "Interview prep"],
          ["What salary should I target?", "Salary"],
        ];
      }
      return (
        '<div class="sffc-crm-apply-chat__inline-action-row sffc-crm-apply-chat__career-followups" data-sffc-career-followups="1">' +
        choices
          .map(function (choice, index) {
            return (
              '<button type="button" class="sffc-crm-apply-chat__inline-action' +
              (index === 0 ? " is-primary" : "") +
              '" data-sffc-apply-chat-welcome-prompt="' +
              escapeHtml(choice[0]) +
              '">' +
              escapeHtml(choice[1]) +
              "</button>"
            );
          })
          .join("") +
        "</div>"
      );
    }

    function buildCareerAdvisorResponse(decision, context) {
      var intent = decision.primaryIntent || "";
      var coachingResult;
      var cvLine = context.hasCv
        ? "I already have enough CV context to make this specific rather than generic."
        : "If you share your CV later, I can make this much more specific to your background.";
      var profile = context.cvProfile || context.searchFocus || "";
      var roleLine = profile
        ? "Based on what I can see so far, I’d keep the advice anchored around " +
          escapeHtml(profile) +
          "."
        : "";
      if (
        isCareerCoachingEngineEligible(
          normalizeDecisionIntentType(intent),
          decision.sourceText || "",
          { allowConcreteTasks: false }
        )
      ) {
        coachingResult = runCareerCoachingEngine(decision.sourceText || "", {
          context: context,
        });
        recordCareerCoachingEngineAudit(coachingResult, "advisor_response");
        if (coachingResult.handled) {
          return {
            html: coachingResult.html,
            actions: getCareerAdvisorChoiceActions("general"),
            topic: coachingResult.topic || "career_coaching",
          };
        }
      }
      if (intent === "APPLICATION_RESUME") {
        return {
          html:
            context.pausedTask && context.pausedTask.roleTitle
              ? "Yes. I’ll pick the application back up for <strong>" +
                escapeHtml(context.pausedTask.roleTitle) +
                "</strong>" +
                (context.pausedTask.roleCompany
                  ? " at " + escapeHtml(context.pausedTask.roleCompany)
                  : "") +
                "."
              : "Yes. I’ll pick the application back up where we left it.",
          actions: "",
          topic: "application_resume",
          resumeTask: true,
        };
      }
      if (intent === "APPLICATION_PAUSE") {
        return {
          html:
            "Paused. I will not move the application forward or submit anything unless you tell me to continue." +
            "<br><br>" +
            "Current status: <strong>paused before submission</strong>.",
          actions: "",
          topic: "application_pause",
        };
      }
      if (intent === "CAREER_PLANNING") {
        var pauseIntro =
          context.activeTask || context.pausedTask
            ? "Of course. I’ll leave the application where it is.<br><br>"
            : "Of course. We do not need to start with applications.<br><br>";
        return {
          html:
            pauseIntro +
            "Let’s work on the bigger picture instead. " +
            cvLine +
            "<br><br>" +
            "I’d start by separating the problem into <strong>direction</strong> and <strong>execution</strong>. Direction means whether you are targeting the right roles and markets. Execution means CV positioning, applications, recruiter outreach, and interview conversion.<br><br>" +
            "What feels closest right now?",
          actions: getCareerAdvisorChoiceActions("planning"),
          topic: "career_planning",
        };
      }
      if (
        intent === "JOB_SEARCH_ADVICE" &&
        decision.entities &&
        decision.entities.location === "Dubai"
      ) {
        return {
          html:
            "Yes. I’d approach Dubai as a targeted search, not just a volume exercise.<br><br>" +
            roleLine +
            (roleLine ? "<br><br>" : "") +
            "For Dubai, I’d work on three things at the same time:<br><br>" +
            "<strong>1. Targeting</strong> - focus on employers that actually hire your profile and level, not every open role with a familiar title.<br><br>" +
            "<strong>2. Positioning</strong> - make the CV show the evidence Dubai employers are most likely to value: commercial ownership, regional relevance, sector fit, and seniority signal.<br><br>" +
            "<strong>3. Route in</strong> - combine direct applications with recruiter or hiring-team outreach where the employer pool is concentrated.<br><br>" +
            cvLine +
            "<br><br>Want me to start by showing the roles I’d target with your background?",
          actions: getCareerAdvisorChoiceActions("market"),
          topic: "dubai_market_entry",
        };
      }
      if (intent === "MARKET_COMPARISON") {
        return {
          html:
            "I would not treat Dubai, Abu Dhabi and Riyadh as the same market.<br><br>" +
            "<strong>Dubai</strong> is usually the broader testing market: more employer variety, more lateral options, and a deeper private-sector hiring pool.<br><br>" +
            "<strong>Abu Dhabi</strong> becomes more interesting if your profile points toward investment institutions, sovereign-linked organisations, infrastructure, private markets, or government-linked platforms.<br><br>" +
            "<strong>Riyadh</strong> can be stronger if the role gives you materially more responsibility, transformation exposure, or compensation upside, but I would check the role quality carefully rather than move just because the market is active.<br><br>" +
            roleLine +
            (roleLine ? "<br><br>" : "") +
            "My default would be to rank them by <strong>career value x probability of landing the role x compensation</strong>, not by job-count alone.",
          actions: getCareerAdvisorChoiceActions("market"),
          topic: "middle_east_market_comparison",
        };
      }
      if (intent === "SALARY_QUESTION") {
        return {
          html:
            "I can help with that, but I would not give a single number without checking role level, sector, and whether the package includes housing, bonus, schooling, relocation, or tax trade-offs.<br><br>" +
            "For Middle East moves, I’d think in terms of <strong>total package</strong> and <strong>career value after the move</strong>. A higher headline salary can still be a bad move if the role narrows your options in two years.<br><br>" +
            roleLine +
            (roleLine ? "<br><br>" : "") +
            "The useful next step is to map the realistic role families from your CV, then estimate which of those can credibly support the salary target.",
          actions: getCareerAdvisorChoiceActions("market"),
          topic: "salary_strategy",
        };
      }
      if (intent === "LOW_INTERVIEW_RATE") {
        return {
          html:
            "I wouldn’t assume the CV is the only problem.<br><br>" +
            "When someone is not getting interviews, I’d diagnose four things separately: <strong>role level</strong>, <strong>market fit</strong>, <strong>CV positioning</strong>, and <strong>application route</strong>.<br><br>" +
            "For Middle East roles, the route matters more than people expect. Some roles are fine through direct applications, but others need recruiter outreach or a warmer contact path because the public advert is only one part of the hiring channel.<br><br>" +
            cvLine +
            " I can review whether the problem looks more like role selection, positioning, or application route.",
          actions: getCareerAdvisorChoiceActions("planning"),
          topic: "low_interview_rate",
        };
      }
      if (intent === "RECRUITER_QUESTION") {
        return {
          html:
            "Recruiters matter when they give you a better route into a concentrated market, not just because they have job titles in their database.<br><br>" +
            "The useful version is targeted: which recruiters understand your sector, which markets they cover, and whether they handle roles at your level. For UAE and Saudi, I’d separate investment, corporate, consulting, technology, and government-linked hiring routes.",
          actions: getCareerAdvisorChoiceActions("general"),
          topic: "recruiter_strategy",
        };
      }
      if (intent === "RECRUITER_NON_RESPONSE") {
        return {
          html: getRecruiterNonResponseAnswer(),
          actions: "",
          topic: "recruiter_non_response",
        };
      }
      if (intent === "CAREER_DECISION") {
        return {
          html: getMoveOrStayCareerDecisionAnswer(),
          actions: "",
          topic: "career_move_decision",
        };
      }
      if (intent === "SUPPORT_CONTACT") {
        return {
          html: getSennaContactAnswer(),
          actions: "",
          topic: "senna_contact",
        };
      }
      if (intent === "ANSWER_QUALITY_COMPLAINT") {
        return {
          html: getAnswerQualityRecoveryAnswer(sourceText || ""),
          actions: "",
          topic: "answer_quality_recovery",
        };
      }
      if (intent === "INTERVIEW_HELP") {
        return {
          html:
            "Yes. Interview prep should start from the role’s buying criteria, not a generic question list.<br><br>" +
            "I’d prepare three layers: the story for why this move makes sense, the evidence behind your strongest claims, and the likely objections based on seniority, market, or sector fit.",
          actions: getCareerAdvisorChoiceActions("general"),
          topic: "interview_help",
        };
      }
      if (intent === "CV_QUESTION") {
        return {
          html:
            "Yes. The key question is not whether the CV is generally good, but whether it makes the right reader reach the right conclusion quickly.<br><br>" +
            "For Middle East roles, I’d check seniority signal, sector relevance, regional transferability, language or visa signals where relevant, and whether the strongest proof appears early enough.",
          actions: getCareerAdvisorChoiceActions("general"),
          topic: "cv_positioning",
        };
      }
      return {
        html:
          "Yes. We can treat this as a career conversation rather than forcing it into an application step.<br><br>" +
          cvLine +
          "<br><br>Tell me whether you want to work on role direction, market choice, CV positioning, applications, recruiters, or interviews.",
        actions: getCareerAdvisorChoiceActions("general"),
        topic: "career_advisor",
      };
    }

    function handleCareerAdvisorChoice(choice) {
      var cleanChoice = cleanMessageText(choice || "").toLowerCase();
      var currentTopic = cleanMessageText(
        careerConversationMemory.activeTopic || ""
      ).toLowerCase();
      var contextualSearchQuery =
        getContextualApplyChatSearchQuery() ||
        summarizeSavedSearchFocus() ||
        "roles that fit my CV";
      var affirmativeAction =
        /^(?:yes|yeah|yep|sure|ok|okay|please|do it|go ahead|sounds good|that sounds good|yes do that|yeah do that|let'?s do it|lets do it)$/i.test(
          cleanChoice
        );
      clearPromptState();
      if (!claimConversationTurn("career_advisor_choice", {
        choice: cleanChoice,
        topic: currentTopic,
      })) {
        return;
      }
      if (
        /\b(?:use my cv|use the cv|work from my cv|use my resume|work from that)\b/i.test(
          cleanChoice
        )
      ) {
        botMessage(
          "Yes. I’ll work from the CV context I already have and use it to map the strongest role families, likely markets, and positioning gaps before pushing you into applications.",
          humanComposeDelay("Use existing CV for career mapping.", 1200, 2600),
          function () {
            if (hasApplyChatCvAvailable()) {
              focusComposer("Ask about roles, markets, salary, or CV fit");
            } else {
              activePath = "review_profile";
              step = "profile_upload";
              if (uploadButton) {
                uploadButton.hidden = false;
              }
              focusComposer("Upload your CV or paste it here");
            }
          }
        );
        return;
      }
      if (affirmativeAction) {
        if (/market|dubai|riyadh|abu_dhabi|salary/i.test(currentTopic)) {
          botMessage(
            "Good. I’ll compare the realistic markets against your profile rather than treating them as generic relocation options.",
            humanComposeDelay("Confirm market comparison.", 1200, 2600),
            function () {
              focusComposer(
                "Tell me if Dubai, Abu Dhabi or Riyadh matters most"
              );
            }
          );
          return;
        }
        if (
          /career_planning|low_interview|career_direction/i.test(currentTopic)
        ) {
          botMessage(
            "Good. I’ll use your CV and recent search context to separate the issue into direction, positioning, and execution before recommending the next move.",
            humanComposeDelay("Confirm career planning.", 1200, 2600),
            function () {
            focusComposer("Tell me what feels most unclear");
          }
        );
        return;
      }
        searchActualJobPostsInChat(contextualSearchQuery);
        return;
      }
      if (
        cleanChoice === "target_roles" ||
        cleanChoice === "direction" ||
        /\b(?:what jobs suit|roles? suit|target roles?|career direction|don'?t know my direction|dont know my direction)\b/i.test(
          cleanChoice
        )
      ) {
        botMessage(
          "I’d start by mapping your background into realistic role families, then testing which one gives you the best combination of credibility, compensation, and progression. Send me the direction you are leaning toward, or say “use my CV” and I’ll work from that.",
          humanComposeDelay("Career direction choice.", 1200, 2600),
          function () {
            focusComposer("Tell me the direction you are leaning toward");
          }
        );
        return;
      }
      if (
        cleanChoice === "execution" ||
        cleanChoice === "review_search" ||
        /\b(?:not getting interviews|no interviews|no replies|not getting replies|getting rejected|review my search|search diagnosis)\b/i.test(
          cleanChoice
        )
      ) {
        botMessage(
          "Then I’d diagnose the search rather than just send more applications: role level, CV positioning, market fit, and route in. The first question is whether you are getting no replies at all, or getting interviews but not converting.",
          humanComposeDelay("Search diagnosis choice.", 1200, 2600),
          function () {
            focusComposer("No replies, or interviews not converting?");
          }
        );
        return;
      }
      if (
        cleanChoice === "markets" ||
        cleanChoice === "compare_markets" ||
        /\b(?:market|markets|dubai|riyadh|abu dhabi|compare|move markets|move to)\b/i.test(
          cleanChoice
        )
      ) {
        botMessage(
          "I’d compare Dubai, Abu Dhabi and Riyadh against your actual profile, not as generic relocation options. The decision should include employer pool, seniority fit, compensation, relocation friction, and the quality of the role after you land it.",
          humanComposeDelay("Market comparison choice.", 1200, 2600),
          function () {
            focusComposer("Tell me which markets you want compared");
          }
        );
        return;
      }
      if (
        cleanChoice === "find_roles" ||
        /\b(?:find roles|find jobs|show roles|show jobs|roles that fit|jobs that fit)\b/i.test(
          cleanChoice
        )
      ) {
        searchActualJobPostsInChat(contextualSearchQuery);
        return;
      }
      if (
        cleanChoice === "salary" ||
        /\b(?:salary|pay|compensation|earn|package)\b/i.test(cleanChoice)
      ) {
        botMessage(
          "For salary, I’d anchor on the role family and level first, then convert it into total package. Tell me the monthly target you have in mind, or say you want the biggest realistic jump.",
          humanComposeDelay("Salary choice.", 1200, 2600),
          function () {
            focusComposer("Tell me your salary target");
          }
        );
        return;
      }
      if (
        cleanChoice === "improve_cv" ||
        /\b(?:cv|resume|improve my cv|fix my cv|review my cv)\b/i.test(
          cleanChoice
        )
      ) {
        activePath = "review_profile";
        step = "profile_upload";
        if (uploadButton) {
          uploadButton.hidden = false;
        }
        botMessage(
          hasApplyChatCvAvailable()
            ? "I can review the CV context I have and focus on structure, evidence, role fit and gaps. Tell me the role or market you want it assessed against."
            : "Share your CV and I’ll review it properly: structure, evidence, role fit, missing signals and what I’d change first.",
          humanComposeDelay("CV review choice.", 1000, 2200),
          function () {
            focusComposer(
              hasApplyChatCvAvailable()
                ? "Tell me the role or market"
                : "Upload your CV or paste it here"
            );
          }
        );
        return;
      }
      botMessage(
        "Tell me what you want to work on and I’ll keep it as a career conversation first.",
        humanComposeDelay("Career advisor fallback.", 900, 1800),
        function () {
          focusComposer("Ask Emily anything about your career");
        }
      );
    }

    function handleCareerConversationFirst(value, options) {
      var opts = options || {};
      var semantics = opts.semantics || parseMessageSemantics(value);
      var intent = opts.intent || detectIntent(value);
      var state = opts.promptState || promptState || "";
      var decision = classifyCareerConversationMessage(
        value,
        state,
        semantics,
        intent
      );
      var context;
      var planned;
      if (looksLikeUnsupportedCvClaimInstruction(value)) {
        return answerUnsupportedCvClaimInstruction(value);
      }
      if (!decision || decision.confidence < 0.84) {
        return false;
      }
      decision.sourceText = value || "";
      context = buildCareerContextSnapshot();
      planned = buildCareerAdvisorResponse(decision, context);
      if (decision.primaryIntent === "APPLICATION_STATUS") {
        return executeConversationDecision(
          {
            nextAction: { type: "answer_application_status", params: {} },
            intent: { type: "application_status" },
            activeTask: getConversationDecisionActiveTask(),
            relationshipToTask: "continues_task",
          },
          value
        );
      }
      if (
        state !== "career_advisor_focus" &&
        (decision.shouldPauseCurrentTask ||
          decision.relationshipToCurrentTask === "TASK_PAUSE" ||
          decision.relationshipToCurrentTask === "TASK_CHANGE" ||
          decision.relationshipToCurrentTask === "INTERRUPTION") &&
        hasActiveApplicationLikeTask()
      ) {
        pauseActiveWorkflowForCareerConversation(decision.primaryIntent);
      }
      if (planned.resumeTask) {
        careerConversationMemory.pausedTasks = [];
        activePath = "apply_for_me";
        step = "apply_upload";
        botMessage(
          planned.html,
          humanComposeDelay(planned.html, 900, 1800),
          function () {
            if (pendingApplyResultsSelection) {
              askApplyResultsSameCvThenStart();
            } else {
              focusComposer("Tell me which application to continue");
            }
          },
          humanReadDelay(value, 400)
        );
        return true;
      }
      pushCareerConversationTopic(planned.topic);
      careerConversationMemory.lastAdvisorIntent = cleanMessageText(
        decision.primaryIntent || ""
      );
      botMessage(
        planned.html + (planned.actions || ""),
        humanComposeDelay(planned.html, 1800, 4200),
        function () {
          setPromptState(
            "career_advisor_focus",
            {
              other: function (reply) {
                var replyDecision = classifyCareerConversationMessage(
                  reply,
                  "career_advisor_focus",
                  parseMessageSemantics(reply),
                  detectIntent(reply)
                );
                if (
                  replyDecision &&
                  handleCareerConversationFirst(reply, {
                    promptState: "career_advisor_focus",
                    semantics: parseMessageSemantics(reply),
                    intent: detectIntent(reply),
                  })
                ) {
                  return;
                }
                handleCareerAdvisorChoice(reply);
              },
            },
            "Ask Emily anything about your career",
            { career_decision: decision }
          );
          focusComposer("Ask Emily anything about your career");
        },
        humanReadDelay(value, 420)
      );
      return true;
    }

    function getCommercialApplyQueueProviderKey(item) {
      var source = item || {};
      var provider = cleanMessageText(
        source.autoSubmitProvider ||
          source.auto_submit_provider ||
          source.provider ||
          source.sourceProvider ||
          source.source_provider ||
          source.sourcePlatform ||
          source.source_platform ||
          source.platform ||
          ""
      ).toLowerCase();
      if (isInternalSennaProviderValue(provider)) {
        provider = "";
      }
      var url = getApplicationQueueRoleModalUrl(source);
      if (
        /^(workday|myworkdayjobs)$/i.test(provider) ||
        isWorkdayApplicationUrl(url)
      ) {
        return "workday";
      }
      if (
        /^(successfactors|sap successfactors|sap-successfactors)$/i.test(
          provider
        ) ||
        isSuccessFactorsApplicationUrl(url)
      ) {
        return "successfactors";
      }
      if (
        /^(greenhouse|greenhouse_io|greenhouse.io)$/i.test(provider) ||
        isGreenhouseApplicationUrl(url)
      ) {
        return "greenhouse";
      }
      if (
        /^(workable|workable_board)$/i.test(provider) ||
        isWorkableApplicationUrl(url)
      ) {
        return "workable";
      }
      if (
        /^(teamtailor|teamtailor_rss)$/i.test(provider) ||
        isTeamtailorApplicationUrl(url)
      ) {
        return "teamtailor";
      }
      if (
        /^(simple_form|simple-form|basic_form|basic-form|simpledrop|simple_drop)$/i.test(
          provider
        ) ||
        isSimpleFormApplicationWorkerUrl(url, provider)
      ) {
        return "simple_form";
      }
      return provider || "";
    }

    function getCommercialApplyQueueProviderLabel(item) {
      var source = item || {};
      var rawProvider = cleanMessageText(
        source.sourcePlatform ||
          source.source_platform ||
          source.autoSubmitProvider ||
          source.auto_submit_provider ||
          source.provider ||
          ""
      );
      if (isInternalSennaProviderValue(rawProvider)) {
        rawProvider = "";
      }
      var url = getApplicationQueueRoleModalUrl(source);
      var rawProviderLabel = getAutoSubmitProviderLabel(rawProvider);
      var urlProviderLabel = url ? getApplicationUrlProviderLabel(url) : "";
      var providerKey = getCommercialApplyQueueProviderKey(source);
      if (
        urlProviderLabel &&
        !/^the employer(?: site)?$/i.test(urlProviderLabel)
      ) {
        return urlProviderLabel;
      }
      if (rawProviderLabel) {
        return rawProviderLabel;
      }
      if (
        rawProvider &&
        !/^(simple_form|simple-form|basic_form|basic-form|simpledrop|simple_drop)$/i.test(
          rawProvider
        )
      ) {
        return rawProvider
          .replace(/[_-]+/g, " ")
          .replace(/\b\w/g, function (letter) {
            return letter.toUpperCase();
          });
      }
      if (providerKey) {
        return getAutoSubmitProviderLabel(providerKey) || providerKey;
      }
      return "the employer";
    }

    function getCommercialApplyQueuePreparationMessage(item, providerLabel) {
      var cleanProviderLabel = cleanMessageText(providerLabel || "");
      var isGenericProvider =
        !cleanProviderLabel ||
        /^the employer(?: site)?$/i.test(cleanProviderLabel);
      var usesTailoredCv = getSelectedApplicationCvMode(item) === "tailored";
      if (usesTailoredCv) {
        return isGenericProvider
          ? "I’m preparing the tailored CV for the employer application now."
          : "I’m tailoring the CV for the " +
              cleanProviderLabel +
              " application now.";
      }
      return isGenericProvider
        ? "I’m preparing the employer application with your current CV now."
        : "I’m preparing the " +
            cleanProviderLabel +
            " application with your current CV now.";
    }

    function hasVisibleEmilyMessageText(message) {
      var clean = cleanMessageText(message || "");
      if (!clean || !messages) {
        return false;
      }
      return Array.prototype.some.call(
        messages.querySelectorAll(
          ".sffc-crm-apply-chat__message.is-emily:not(.is-typing)"
        ),
        function (row) {
          return (
            cleanMessageText(row.textContent || row.innerText || "") === clean
          );
        }
      );
    }

    function announceCommercialApplyQueueProgress(
      itemIndex,
      noticeKey,
      message,
      delayText,
      runToken
    ) {
      var clean = cleanMessageText(message || "");
      var key =
        cleanMessageText(noticeKey || "") + ":" + clean.toLowerCase();
      if (runToken && !isCommercialApplyQueueRunCurrent(runToken)) {
        return;
      }
      if (
        !clean ||
        commercialApplyQueueProgressNotices[key] ||
        hasVisibleEmilyMessageText(clean)
      ) {
        return;
      }
      commercialApplyQueueProgressNotices[key] = true;
      botMessage(clean, humanComposeDelay(delayText || clean, 900, 1900));
    }

    function renderApplyResultsOfflineEmailActions() {
      return (
        '<div class="sffc-crm-apply-chat__inline-action-row">' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-offline-email="yes">Yes, use that email</button>' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-offline-email="no">Use another email</button>' +
        "</div>"
      );
    }

    function renderApplyResultsOfflineNextActions() {
      return (
        '<div class="sffc-crm-apply-chat__inline-action-row">' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-offline-next="review_next">Review next match</button>' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-offline-next="wait">Wait for this application</button>' +
        "</div>"
      );
    }

    function getApplyResultsFallbackApplicationUrl(item) {
      var source =
        item ||
        pendingApplyResultsOfflineItem ||
        pendingApplyResultsSelection ||
        {};
      return cleanMessageText(getApplicationQueueRoleModalUrl(source) || "");
    }

    function renderApplyResultsFailureFallbackCard(itemIndex, data) {
      var item =
        commercialApplyQueueItemsState[itemIndex] ||
        pendingApplyResultsSelection ||
        {};
      var reason = cleanMessageText((data && data.last_error) || "");
      var url = getApplyResultsFallbackApplicationUrl(item);
      var provider = getCommercialApplyQueueProviderKey(item);
      var providerLabel = getCommercialApplyQueueProviderLabel(item);
      var reviewDecision = getEmployerReviewSurfaceDecision(
        item || {},
        url,
        provider
      );
      var roleLabel = cleanMessageText(
        [
          item.title || roleTitle || "this role",
          item.company || roleCompany
            ? "at " + (item.company || roleCompany)
            : "",
        ]
          .filter(Boolean)
          .join(" ")
      );
      url = reviewDecision.url;
      var previewId =
        "sffc-apply-fallback-preview-" +
        String(Date.now()) +
        "-" +
        String(itemIndex || 0);
      return (
        '<section class="sffc-crm-apply-results sffc-crm-apply-results--fallback" data-sffc-apply-results-fallback-card data-sffc-apply-results-review-mode="' +
        escapeHtml(reviewDecision.surface) +
        '" data-sffc-apply-results-review-reason="' +
        escapeHtml(reviewDecision.reason) +
        '">' +
        '<div class="sffc-crm-apply-results__topbar">' +
        "<div><strong>" +
        escapeHtml("Application needs fallback") +
        "</strong><span>" +
        escapeHtml(roleLabel) +
        "</span></div>" +
        (url
          ? '<a class="sffc-crm-apply-results__review-link" href="' +
            escapeHtml(url) +
            '" target="_blank" rel="noopener noreferrer">Open employer form</a>'
          : "") +
        "</div>" +
        '<p class="sffc-crm-apply-results__snippet">' +
        escapeHtml(
          reason
            ? "Emily could not complete the automated " +
                providerLabel +
                " step: " +
                reason +
                "."
            : "Emily could not complete the automated " +
                providerLabel +
                " step."
        ) +
        "</p>" +
        (url && reviewDecision.canFrameUrl
          ? !reviewDecision.shouldRenderIframe
            ? '<div class="sffc-crm-apply-results__review-fallback">' +
              escapeHtml(
                reviewDecision.surface === "remote_browser"
                  ? "This employer form blocks a standard embed. I’ll use the secure browser route when it is available, with a preview as backup."
                  : "This employer form may block embeds. I’ll show a preview where possible and keep the employer form link ready."
              ) +
              "</div>"
            : '<div class="sffc-crm-apply-results__review-frame-wrap">' +
              '<iframe class="sffc-crm-apply-results__review-frame" title="' +
              escapeHtml(roleLabel || "Employer application") +
              '" data-sffc-apply-results-review-frame data-src="' +
              escapeHtml(url) +
              '" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>' +
              "</div>"
          : '<div class="sffc-crm-apply-results__review-fallback">I do not have a usable employer form link for this role yet.</div>') +
        renderApplyResultsRemoteBrowser(
          item,
          url,
          provider,
          reviewDecision,
          "sffc-apply-fallback-" + String(itemIndex || 0),
          reviewDecision.shouldStartRemoteBrowser
        ) +
        (reviewDecision.shouldRequestScreenshot
          ? '<div id="' +
            escapeHtml(previewId) +
            '" class="sffc-crm-apply-results__review-screenshot' +
            " is-loading" +
            '"' +
            ' data-sffc-apply-results-preview-url="' +
            escapeHtml(url) +
            '" data-sffc-apply-results-preview-provider="' +
            escapeHtml(provider) +
            '" data-sffc-apply-results-preview-title="' +
            escapeHtml(item.title || roleTitle || "") +
            '" data-sffc-apply-results-preview-company="' +
            escapeHtml(item.company || roleCompany || "") +
            '" data-sffc-apply-results-preview-role-url="' +
            escapeHtml(item.viewUrl || item.url || roleUrl || url) +
            '" data-sffc-apply-results-preview-jobs-post-id="' +
            escapeHtml(
              String(
                item.jobsPostId ||
                  item.jobs_post_id ||
                  item.wpPostId ||
                  item.wp_post_id ||
                  jobsPostId ||
                  ""
              )
            ) +
            '" data-sffc-apply-results-preview-crm-post-id="' +
            escapeHtml(
              cleanMessageText(root.getAttribute("data-crm-post-id") || "")
            ) +
            '">' +
            renderApplyResultsPreviewLoader("Preparing employer page preview...") +
            "</div>"
          : "") +
        '<div class="sffc-crm-apply-results__actions">' +
        (url && reviewDecision.canFrameUrl
          ? '<button type="button" class="sffc-crm-apply-results__btn sffc-crm-apply-results__btn--secondary" data-sffc-apply-results-fallback-action="preview" data-sffc-apply-results-preview-target="' +
            escapeHtml(previewId) +
            '">Refresh preview</button>'
          : "") +
        '<button type="button" class="sffc-crm-apply-results__btn sffc-crm-apply-results__btn--primary" data-sffc-apply-results-fallback-action="retry" data-sffc-apply-results-fallback-index="' +
        escapeHtml(String(itemIndex || 0)) +
        '">Try again</button>' +
        '<button type="button" class="sffc-crm-apply-results__btn sffc-crm-apply-results__btn--secondary" data-sffc-apply-results-fallback-action="email">Send me email updates</button>' +
        (itemIndex + 1 < commercialApplyQueueItemsState.length
          ? '<button type="button" class="sffc-crm-apply-results__btn sffc-crm-apply-results__btn--secondary" data-sffc-apply-results-fallback-action="review_next">Review next match</button>'
          : "") +
        "</div>" +
        "</section>"
      );
    }

    function sendApplyResultsOfflineRoleNote(email, item, reason) {
      var source =
        item ||
        pendingApplyResultsOfflineItem ||
        pendingApplyResultsSelection ||
        {};
      var lines = [
        "Offline application follow-up",
        cleanMessageText(source.title || roleTitle || "")
          ? "Role: " + cleanMessageText(source.title || roleTitle || "")
          : "",
        cleanMessageText(source.company || roleCompany || "")
          ? "Company: " + cleanMessageText(source.company || roleCompany || "")
          : "",
        cleanMessageText(source.location || roleLocation || "")
          ? "Location: " +
            cleanMessageText(source.location || roleLocation || "")
          : "",
        getCommercialApplyQueueProviderLabel(source)
          ? "Provider: " + getCommercialApplyQueueProviderLabel(source)
          : "",
        cleanMessageText(email || "")
          ? "Candidate email: " + cleanMessageText(email || "")
          : "",
        cleanMessageText(reason || "")
          ? "Reason: " + cleanMessageText(reason || "")
          : "",
        cleanMessageText(
          source.applyUrl ||
            source.applicationWorkspaceUrl ||
            applicationUrl ||
            ""
        )
          ? "Application URL: " +
            cleanMessageText(
              source.applyUrl ||
                source.applicationWorkspaceUrl ||
                applicationUrl ||
                ""
            )
          : "",
      ].filter(Boolean);
      return sendHumanHandoffRequest(
        lines.join(" | "),
        "application_queue_offline_followup"
      );
    }

    function finishApplyResultsOfflineEmailConfirmation(emailValue) {
      var email = cleanMessageText(
        emailValue ||
          applyOnboardingPreferredEmail ||
          applyOnboardingEmailSuggestion ||
          ""
      );
      var item =
        pendingApplyResultsOfflineItem || pendingApplyResultsSelection || {};
      if (!email || !/@/.test(email)) {
        botMessage(
          "Send the email address I should use for the offline application update.",
          humanComposeDelay("Need email for offline update.", 800, 1600),
          function () {
            setPromptState(
              "apply_results_offline_collect_email",
              {
                other: function (value) {
                  var extracted = extractEmailCandidate(value || "");
                  if (!extracted) {
                    focusComposer("Send the email address");
                    return;
                  }
                  applyOnboardingPreferredEmail = extracted;
                  clearPromptState();
                  echoPromptChoice(extracted);
                  finishApplyResultsOfflineEmailConfirmation(extracted);
                },
              },
              "Send the email address",
              { selected_role_key: getCommercialApplyQueueItemKey(item) }
            );
            focusComposer("Send the email address");
          }
        );
        return;
      }
      applyOnboardingPreferredEmail = email;
      sendApplyResultsOfflineRoleNote(
        email,
        item,
        "Worker needs offline handling"
      )
        .catch(function () {
          return false;
        })
        .then(function () {
          botMessage(
            "Ok, I’ve just sent a note of the role. Great. Do you want to review the next match or wait until I process the last application?",
            humanComposeDelay("Offline role note sent.", 1000, 2200),
            function () {
              setPromptState(
                "apply_results_offline_next_choice",
                {
                  review_next: function (value) {
                    var nextIndex = pendingApplyResultsOfflineItemIndex + 1;
                    clearPromptState();
                    echoPromptChoice(value || "Review next match");
                    if (
                      nextIndex > 0 &&
                      nextIndex < commercialApplyQueueItemsState.length
                    ) {
                      botMessage(
                        "I’ll review the next match now.",
                        humanComposeDelay("Review next match.", 700, 1400),
                        function () {
                          commercialApplyQueueActivated = true;
                          processCommercialApplyQueueItem(
                            nextIndex,
                            0,
                            bumpCommercialApplyQueueRunToken()
                          );
                        }
                      );
                      return;
                    }
                    botMessage(
                      "I’ll show you the next match now.",
                      humanComposeDelay("Review next match.", 700, 1400),
                      function () {
                        focusComposer(
                          "Choose the next role when you are ready"
                        );
                      }
                    );
                  },
                  wait: function (value) {
                    clearPromptState();
                    echoPromptChoice(value || "Wait for this application");
                    botMessage(
                      "Ok, as I said earlier I’ll have to take this offline so I can make sure your application is submitted properly. Let’s catch up over email.",
                      humanComposeDelay("Continue offline.", 900, 1800),
                      function () {
                        focusComposer("I’ll catch up with you over email");
                      }
                    );
                  },
                  other: function (value) {
                    var clean = cleanMessageText(value || "").toLowerCase();
                    if (
                      /\b(next|review|another|match|continue|show)\b/.test(
                        clean
                      )
                    ) {
                      promptHandlers.review_next(value);
                      return;
                    }
                    if (
                      /\b(wait|last|process|email|offline|later|pause|hold)\b/.test(
                        clean
                      )
                    ) {
                      promptHandlers.wait(value);
                      return;
                    }
                    focusComposer(
                      "Choose Review next match or Wait for this application"
                    );
                  },
                },
                "Review next match or wait?",
                { selected_role_key: getCommercialApplyQueueItemKey(item) }
              );
              botMessage(renderApplyResultsOfflineNextActions(), 0);
              focusComposer("Review next match or wait?");
            }
          );
        });
    }

    function promptApplyResultsOfflineEmailConfirmation(itemIndex, data) {
      var item =
        commercialApplyQueueItemsState[itemIndex] ||
        pendingApplyResultsSelection ||
        {};
      var reason = cleanMessageText((data && data.last_error) || "");
      pendingApplyResultsOfflineItem = item;
      pendingApplyResultsOfflineItemIndex = Number(itemIndex || 0);
      botMessage(
        "I’m stuck on something in the employer form" +
          (reason ? ": " + escapeHtml(reason) : "") +
          ". I can continue working on this one in the background and let you know by email when it’s sent. Am I still using " +
          escapeHtml(
            cleanMessageText(
              applyOnboardingPreferredEmail ||
                applyOnboardingEmailSuggestion ||
                "the same email you provided earlier"
            )
          ) +
          "?",
        humanComposeDelay(
          "Offline application email confirmation.",
          1000,
          2200
        ),
        function () {
          setPromptState(
            "apply_results_offline_email_confirm",
            {
              yes: function (value) {
                clearPromptState();
                echoPromptChoice(value || "Yes, use that email");
                finishApplyResultsOfflineEmailConfirmation(
                  applyOnboardingPreferredEmail ||
                    applyOnboardingEmailSuggestion ||
                    ""
                );
              },
              no: function (value) {
                clearPromptState();
                echoPromptChoice(value || "Use another email");
                finishApplyResultsOfflineEmailConfirmation("");
              },
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                var extracted = extractEmailCandidate(value || "");
                if (extracted) {
                  clearPromptState();
                  echoPromptChoice(extracted);
                  finishApplyResultsOfflineEmailConfirmation(extracted);
                  return;
                }
                if (
                  /^(?:yes|y|same|correct|use it|that'?s right|go ahead|sure|ok|okay)\b/i.test(
                    clean
                  )
                ) {
                  promptHandlers.yes(value);
                  return;
                }
                if (/^(?:no|n|new|different|another|change)\b/i.test(clean)) {
                  promptHandlers.no(value);
                  return;
                }
                focusComposer("Confirm yes, or send another email");
              },
            },
            "Use the same email?",
            { selected_role_key: getCommercialApplyQueueItemKey(item) }
          );
          botMessage(renderApplyResultsOfflineEmailActions(), 0);
          focusComposer("Confirm yes, or send another email");
        }
      );
    }

    function handleApplyResultsFallbackAction(action, itemIndex, value) {
      var normalizedAction = cleanMessageText(action || "").toLowerCase();
      var normalizedIndex = Number(
        itemIndex || pendingApplyResultsOfflineItemIndex || 0
      );
      if (normalizedAction === "retry") {
        clearPromptState();
        echoPromptChoice(value || "Try again");
        updateCommercialQueueItemStatus(
          normalizedIndex,
          "Retrying",
          "Emily is retrying the employer form"
        );
        botMessage(
          "I’ll try the employer form again from the same selected role.",
          humanComposeDelay("Retrying employer form.", 700, 1400),
          function () {
            commercialApplyQueueActivated = true;
            processCommercialApplyQueueItem(
              normalizedIndex,
              0,
              bumpCommercialApplyQueueRunToken()
            );
          }
        );
        return true;
      }
      if (normalizedAction === "email") {
        clearPromptState();
        echoPromptChoice(value || "Send me email updates");
        promptApplyResultsOfflineEmailConfirmation(normalizedIndex, {
          last_error: "Worker needs offline handling",
        });
        return true;
      }
      if (normalizedAction === "review_next") {
        clearPromptState();
        echoPromptChoice(value || "Review next match");
        if (
          normalizedIndex + 1 > 0 &&
          normalizedIndex + 1 < commercialApplyQueueItemsState.length
        ) {
          commercialApplyQueueActivated = true;
          processCommercialApplyQueueItem(
            normalizedIndex + 1,
            0,
            bumpCommercialApplyQueueRunToken()
          );
          return true;
        }
        botMessage(
          "There is not another queued match after this one right now.",
          humanComposeDelay("No next match.", 700, 1400),
          function () {
            focusComposer("Open the form, retry, or send email updates");
          }
        );
        return true;
      }
      return false;
    }

    function askApplyResultsOfflineEmailConfirmation(itemIndex, data) {
      var item =
        commercialApplyQueueItemsState[itemIndex] ||
        pendingApplyResultsSelection ||
        {};
      var reason = cleanMessageText((data && data.last_error) || "");
      pendingApplyResultsOfflineItem = item;
      pendingApplyResultsOfflineItemIndex = Number(itemIndex || 0);
      botMessage(
        "I couldn’t finish the automated employer-form step" +
          (reason ? ": " + escapeHtml(reason) : "") +
          ". I’m keeping the application context open and switching to fallbacks.",
        humanComposeDelay("Application fallback ready.", 900, 1800),
        function () {
          botMessage(
            renderApplyResultsFailureFallbackCard(
              Number(itemIndex || 0),
              data || {}
            ),
            0,
            function () {
              var fallbackCards = root.querySelectorAll(
                "[data-sffc-apply-results-fallback-card]"
              );
              var fallbackCard = fallbackCards.length
                ? fallbackCards[fallbackCards.length - 1]
                : null;
              var fallbackPreview = fallbackCard
                ? fallbackCard.querySelector(
                    "[data-sffc-apply-results-preview-url]"
                  )
                : null;
              var fallbackPanel = fallbackCard || null;
              if (fallbackPanel) {
                hydrateApplyResultsReviewPanel(fallbackPanel);
              }
              if (
                fallbackPreview &&
                !fallbackPreview.hidden &&
                fallbackPreview.getAttribute("data-sffc-preview-state") !==
                  "loading" &&
                fallbackPreview.getAttribute("data-sffc-preview-state") !==
                  "ready"
              ) {
                requestApplyResultsApplicationPreview(fallbackPreview);
              }
              setPromptState(
                "apply_results_failure_fallback",
                {
                  retry: function (choiceValue) {
                    handleApplyResultsFallbackAction(
                      "retry",
                      itemIndex,
                      choiceValue
                    );
                  },
                  email: function (choiceValue) {
                    handleApplyResultsFallbackAction(
                      "email",
                      itemIndex,
                      choiceValue
                    );
                  },
                  review_next: function (choiceValue) {
                    handleApplyResultsFallbackAction(
                      "review_next",
                      itemIndex,
                      choiceValue
                    );
                  },
                  other: function (choiceValue) {
                    var clean = cleanMessageText(
                      choiceValue || ""
                    ).toLowerCase();
                    if (/\b(?:retry|try again|again)\b/.test(clean)) {
                      handleApplyResultsFallbackAction(
                        "retry",
                        itemIndex,
                        choiceValue
                      );
                      return;
                    }
                    if (/\b(?:email|send|update|offline)\b/.test(clean)) {
                      handleApplyResultsFallbackAction(
                        "email",
                        itemIndex,
                        choiceValue
                      );
                      return;
                    }
                    if (/\b(?:next|review next|another|match)\b/.test(clean)) {
                      handleApplyResultsFallbackAction(
                        "review_next",
                        itemIndex,
                        choiceValue
                      );
                      return;
                    }
                    focusComposer(
                      "Choose retry, email updates, or open the form"
                    );
                  },
                },
                "Choose a fallback",
                { selected_role_key: getCommercialApplyQueueItemKey(item) }
              );
              focusComposer("Choose a fallback or open the employer form");
            }
          );
        }
      );
    }

    function setCurrentApplicationContextFromQueueItem(item) {
      var source = normalizeCommercialApplyQueueItem(item || {}, "Ready");
      var employerApplicationUrl = getApplicationQueueRoleModalUrl(source);
      roleTitle = cleanMessageText(source.title || roleTitle || "");
      roleCompany = cleanMessageText(source.company || roleCompany || "");
      roleLocation = cleanMessageText(source.location || roleLocation || "");
      postId = cleanMessageText(source.postId || postId || "");
      jobsPostId = cleanMessageText(source.jobsPostId || jobsPostId || "");
      applicationUrl = cleanMessageText(employerApplicationUrl || "");
      applicationWorkspaceUrl = cleanMessageText(
        source.applicationWorkspaceUrl || employerApplicationUrl || ""
      );
      roleUrl = cleanMessageText(
        source.viewUrl || roleUrl || employerApplicationUrl || "#"
      );
      roleCompanyLogo = cleanMessageText(
        source.companyLogo || roleCompanyLogo || ""
      );
      autoSubmitProvider = cleanMessageText(
        source.autoSubmitProvider ||
          source.sourcePlatform ||
          autoSubmitProvider ||
          ""
      );
      autoSubmitSupported = !!(
        source.autoSubmitSupported ||
        isApplicationWorkerSubmitProvider(autoSubmitProvider) ||
        isGreenhouseApplicationUrl(applicationWorkspaceUrl || applicationUrl) ||
        isWorkableApplicationUrl(applicationWorkspaceUrl || applicationUrl) ||
        isWorkdayApplicationUrl(applicationWorkspaceUrl || applicationUrl) ||
        isSuccessFactorsApplicationUrl(
          applicationWorkspaceUrl || applicationUrl
        ) ||
        isTeamtailorApplicationUrl(applicationWorkspaceUrl || applicationUrl) ||
        isSimpleFormApplicationWorkerUrl(
          applicationWorkspaceUrl || applicationUrl,
          autoSubmitProvider
        )
      );
      autoSubmitSchemaStatus = cleanMessageText(
        source.autoSubmitSchemaStatus || autoSubmitSchemaStatus || ""
      );
      root.setAttribute("data-role-title", roleTitle || "");
      root.setAttribute("data-role-company", roleCompany || "");
      root.setAttribute("data-role-location", roleLocation || "");
      root.setAttribute("data-post-id", postId || "");
      root.setAttribute("data-jobs-post-id", jobsPostId || "");
      root.setAttribute("data-application-url", applicationUrl || "#");
      root.setAttribute(
        "data-application-workspace-url",
        applicationWorkspaceUrl || ""
      );
      root.setAttribute("data-role-url", roleUrl || applicationUrl || "#");
      root.setAttribute("data-company-logo", roleCompanyLogo || "");
      root.setAttribute("data-auto-submit-provider", autoSubmitProvider || "");
      root.setAttribute(
        "data-auto-submit-supported",
        autoSubmitSupported ? "1" : "0"
      );
      root.setAttribute(
        "data-auto-submit-schema-status",
        autoSubmitSchemaStatus || ""
      );
      applicationWorkspaceSchema = null;
      applicationAnswerDraft = {};
      applicationEmployerBulkAsked = false;
      pendingApplicationQuestionQueueCallback = null;
      careerConversationMemory.currentSelectedRole =
        normalizeApplyChatMemoryRoleEntity(source);
      if (careerConversationMemory.currentSelectedRole) {
        careerConversationMemory.recentResultEntities =
          normalizeApplyChatMemoryRoleEntityList(
            (careerConversationMemory.recentResultEntities || []).concat([
              careerConversationMemory.currentSelectedRole,
            ])
          );
      }
      syncApplyChatCanonicalState("selected_role_set", {
        selectedRole: careerConversationMemory.currentSelectedRole,
      });
      queueApplyChatMemoryPersist();
      return source;
    }

    function renderApplyResultsSelectedRoleActions(options) {
      var settings = options || {};
      if (settings.premium) {
        if (settings.afterComparison) {
          return (
            '<div class="sffc-crm-apply-chat__inline-action-row">' +
            '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-selected-next="tailored">Tailor CV</button>' +
            '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-selected-next="original">Original CV</button>' +
            "</div>"
          );
        }
        return (
          '<div class="sffc-crm-apply-chat__inline-action-row">' +
          '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-selected-next="tailored">Tailor CV</button>' +
          '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-selected-next="compare">Improve CV first</button>' +
          '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-selected-next="original">Original CV</button>' +
          "</div>"
        );
      }
      if (settings.afterComparison) {
        return (
          '<div class="sffc-crm-apply-chat__inline-action-row">' +
          '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-selected-next="tailored">Tailor CV</button>' +
          '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-selected-next="original">Jump to application</button>' +
          "</div>"
        );
      }
      return (
        '<div class="sffc-crm-apply-chat__inline-action-row">' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-selected-next="compare">Compare to my CV</button>' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-selected-next="original">Jump to application</button>' +
        "</div>"
      );
    }

    function renderApplyResultsSameCvActions() {
      return (
        '<div class="sffc-crm-apply-chat__inline-action-row">' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action is-primary" data-sffc-apply-results-same-cv="yes">Yes, use the same CV</button>' +
        '<button type="button" class="sffc-crm-apply-chat__inline-action" data-sffc-apply-results-same-cv="no">No, I’ll upload another</button>' +
        "</div>"
      );
    }

    function hasApplyChatCvAvailable() {
      return !!(currentCvFile || capturedCvText || hasLoggedInSavedCv());
    }

    function askForCvBeforeSelectedRoleApplication(selected, reason) {
      var source =
        selected ||
        pendingApplyResultsSelection ||
        getCurrentConversationDecisionSelectedRole();
      var cvSlotState;
      if (source) {
        pendingApplyResultsSelection = normalizeCommercialApplyQueueItem(
          source,
          "Ready"
        );
        setCurrentApplicationContextFromQueueItem(pendingApplyResultsSelection);
        commercialApplyQueueItemsState = [pendingApplyResultsSelection];
        commercialApplyQueueInitialized = true;
        commercialApplyQueueActivated = false;
        commercialApplyQueueDetailsMode = true;
        commercialApplyQueueActiveTab = "shortlist";
        commercialApplyQueueFilter = "all";
        rememberCommercialApplyQueueCatalogItems(
          commercialApplyQueueItemsState
        );
      }
      activePath = "apply_for_me";
      step = "apply_upload";
      clearPromptState();
      if (shouldSuppressRepeatedPromptSlotAsk("cv_upload", 45000)) {
        recordPromptSlotEvent("suppressed_duplicate_ask", "cv_upload", {
          promptState: "apply_upload",
          reason: cleanMessageText(reason || ""),
        });
        if (uploadButton) {
          uploadButton.hidden = false;
        }
        input.disabled = false;
        focusComposer("Upload your CV or paste it here");
        return;
      }
      cvSlotState = markPromptSlotAsked("apply_upload", {
        reason: cleanMessageText(reason || ""),
        source: "askForCvBeforeSelectedRoleApplication",
      });
      recordConversationAuditEvent("cv_upload_prompt_request", {
        slotId: cvSlotState && cvSlotState.slotId,
        reason: cleanMessageText(reason || ""),
      });
      botMessage(
        getContextualCvRequestLine(pendingApplyResultsSelection, reason),
        humanComposeDelay("Need CV for selected role.", 900, 1800),
        function () {
          if (uploadButton) {
            uploadButton.hidden = false;
          }
          input.disabled = false;
          focusComposer("Upload your CV or paste it here");
        }
      );
    }

    function renderApplyResultsCvComparisonHtml(item) {
      var source = item || pendingApplyResultsSelection || {};
      var match = null;
      var score = 0;
      var strengths = [];
      var gaps = [];
      try {
        match = buildCvRoleMatch(source);
      } catch (error) {
        match = null;
      }
      score = Math.max(
        0,
        Math.round(Number((match && match.score) || source.matchScore || 0))
      );
      strengths = dedupeList(
        ((match && match.whyMatches) || [])
          .concat((match && match.cvSupport) || [])
          .map(cleanMatchNarrativeLine)
          .filter(Boolean)
      ).slice(0, 3);
      gaps = dedupeList(
        ((match && match.missing) || [])
          .map(cleanMatchNarrativeLine)
          .filter(Boolean)
      ).slice(0, 2);
      return (
        '<div class="sffc-crm-apply-chat__formatted">' +
        "<p><strong>CV comparison for " +
        escapeHtml(cleanMessageText(source.title || roleTitle || "this role")) +
        "</strong></p>" +
        "<p>Match estimate: <strong>" +
        escapeHtml(score ? String(score) + "%" : "needs review") +
        "</strong>" +
        (match && match.fitType ? " · " + escapeHtml(match.fitType) : "") +
        ".</p>" +
        (strengths.length
          ? "<p>Strongest evidence: " + escapeHtml(strengths.join(" ")) + "</p>"
          : "") +
        (gaps.length
          ? "<p>Watch-outs: " + escapeHtml(gaps.join(" ")) + "</p>"
          : "") +
        "</div>"
      );
    }

    function buildApplyResultsRoleSpecificAnalysis(item) {
      var source = item || pendingApplyResultsSelection || {};
      var base = Object.assign({}, applyCvAnalysis || {});
      var match = null;
      var sourceChips = getActualJobPostChips(source || {});
      try {
        match = buildCvRoleMatch(source);
      } catch (error) {
        match = null;
      }
      return Object.assign(base, {
        match_score:
          Number(
            (match && match.score) || source.matchScore || base.match_score || 0
          ) || 0,
        fit_type: cleanMessageText(
          (match && match.fitType) || base.fit_type || ""
        ),
        matched_keywords: dedupeList(
          []
            .concat((base && base.matched_keywords) || [])
            .concat((match && match.cvSupport) || [])
            .concat((match && match.whyMatches) || [])
            .concat(sourceChips || [])
        ).slice(0, 12),
        missing_keywords: dedupeList(
          []
            .concat((base && base.missing_keywords) || [])
            .concat((match && match.missing) || [])
        ).slice(0, 12),
        requirement_gaps: dedupeListByKey(
          [].concat((base && base.requirement_gaps) || []).concat(
            ((match && match.missing) || []).map(function (gap) {
              return {
                label: cleanMatchNarrativeLine(gap),
                type: "role_requirement_gap",
                message: cleanMatchNarrativeLine(gap),
              };
            })
          ),
          function (gap) {
            return cleanMessageText((gap && (gap.label || gap.message)) || "");
          }
        ).slice(0, 8),
      });
    }

    function renderDetailedApplyResultsCvComparisonHtml(item) {
      var source = item || pendingApplyResultsSelection || {};
      var previousRole = roleTitle;
      var previousCompany = roleCompany;
      var previousLocation = roleLocation;
      var previousSector = roleSector;
      var previousSeniority = roleSeniority;
      var html = "";
      if (source && (source.title || source.company)) {
        roleTitle = cleanMessageText(source.title || roleTitle || "");
        roleCompany = cleanMessageText(source.company || roleCompany || "");
        roleLocation = cleanMessageText(source.location || roleLocation || "");
        roleSector = cleanMessageText(source.sector || roleSector || "");
        roleSeniority = cleanMessageText(
          source.seniority || roleSeniority || ""
        );
      }
      html = renderApplyQuickRoleInsights(
        buildApplyResultsRoleSpecificAnalysis(source),
        {
          forceActions: true,
          hideActions: true,
        }
      );
      roleTitle = previousRole;
      roleCompany = previousCompany;
      roleLocation = previousLocation;
      roleSector = previousSector;
      roleSeniority = previousSeniority;
      return html || renderApplyResultsCvComparisonHtml(source);
    }

    function renderApplyResultsCvImprovementPlanHtml(item) {
      var source = item || pendingApplyResultsSelection || {};
      var analysis = buildApplyResultsRoleSpecificAnalysis(source);
      var items = getApplyQuickRoleInsightItems(analysis).slice(0, 4);
      var matched = dedupeList(
        []
          .concat((analysis && analysis.matched_keywords) || [])
          .concat((analysis && analysis.matched_role_keywords) || [])
          .map(cleanMessageText)
          .filter(Boolean)
      ).slice(0, 5);
      var subject = cleanMessageText(
        [
          source.title || roleTitle || "this role",
          source.company || roleCompany
            ? "at " + (source.company || roleCompany)
            : "",
        ]
          .filter(Boolean)
          .join(" ")
      );
      var issueList = items.length
        ? items
            .map(function (item) {
              return (
                "<li><strong>" +
                escapeHtml(item.title || "Improve this signal") +
                ".</strong> " +
                escapeHtml(
                  item.message ||
                    "Make this evidence easier to find before applying."
                )
              );
            })
            .join("</li>") + "</li>"
        : "<li><strong>Make the strongest evidence easier to find.</strong> I’ll bring the role-relevant proof higher in the CV and keep the facts supported by the existing document.</li>";
      return (
        '<div class="sffc-crm-apply-chat__formatted sffc-crm-apply-chat__cv-improvement-plan">' +
        "<p><strong>CV improvement plan for " +
        escapeHtml(subject || "this role") +
        "</strong></p>" +
        "<p>I’ll strengthen the application by making the role-relevant evidence easier to scan, without inventing experience or changing your underlying facts.</p>" +
        "<ul>" +
        issueList +
        "</ul>" +
        (matched.length
          ? "<p><strong>Evidence I’ll preserve:</strong> " +
            escapeHtml(matched.join(", ")) +
            ".</p>"
          : "") +
        "<p>From here, I can apply using the tailored version, or use the original CV if you want to move faster.</p>" +
        renderApplyResultsSelectedRoleActions({
          premium: true,
          afterComparison: true,
        }) +
        "</div>"
      );
    }

    function withApplyResultsCvAnalysis(callback) {
      if (applyCvAnalysis) {
        callback();
        return;
      }
      if (!capturedCvText) {
        callback();
        return;
      }
      fetchCvAnalysis(capturedCvText)
        .then(function (analysis) {
          applyCvAnalysis = analysis || {};
          mergeCvFacts(applyCvAnalysis);
        })
        .catch(function () {})
        .then(callback);
    }

    function askApplyResultsSameCvThenStart() {
      var cvLabel = getApplyResultsSelectedCvLabel();
      var roleKey = cleanMessageText(
        (pendingApplyResultsSelection &&
          (pendingApplyResultsSelection.key ||
            pendingApplyResultsSelection.applicationUrl ||
            pendingApplyResultsSelection.title)) ||
          roleTitle ||
          "selected-role"
      );
      var sameCvKey = roleKey + "::" + cleanMessageText(cvLabel || "cv");

      function loadSelectedRoleCvThen(callback) {
        ensureLoggedInSavedCvText()
          .catch(function () {
            return false;
          })
          .then(function (ready) {
            if (!ready && !currentCvFile && !capturedCvText) {
              botMessage(
                "I could not load the saved CV text into this chat session. Add the CV here and I’ll continue with this selected role.",
                humanComposeDelay("Saved CV unavailable.", 900, 1800),
                function () {
                  if (uploadButton) {
                    uploadButton.hidden = false;
                  }
                  input.disabled = false;
                  focusComposer("Upload your CV or paste it here");
                }
              );
              return;
            }
            callback();
          });
      }

      function startSelectedRoleApplicationAfterCvConfirm() {
        var cvMode =
          pendingApplyResultsSelection &&
          cleanMessageText(
            pendingApplyResultsSelection.cvMode ||
              pendingApplyResultsSelection.cv_mode
          );
        var shouldShowTailoredPreview =
          cvMode !== "original" && applyCvReviewSkipped !== true;

        if (!shouldShowTailoredPreview) {
          var originalStartLine = getSelectedApplicationStartLine("original");
          botMessage(
            originalStartLine,
            humanComposeDelay(originalStartLine, 900, 1800),
            function () {
              loadSelectedRoleCvThen(processCommercialApplyQueueShortlist);
            }
          );
          return;
        }

        var tailoringStartLine =
          "I’ll check the CV against this role first, then you can choose whether to use the tailored version.";
        botMessage(
          tailoringStartLine,
          humanComposeDelay(tailoringStartLine, 900, 1800),
          function () {
            if (uploadButton) {
              uploadButton.hidden = true;
            }
            makeComposerInputInteractive("Reviewing the CV against this role");
            input.placeholder = "Reviewing the CV against this role";
            loadSelectedRoleCvThen(function () {
              withApplyResultsCvAnalysis(function () {
                continueApplyAfterAnalysis(
                  applyCvAnalysis ||
                    buildApplyResultsRoleSpecificAnalysis(
                      pendingApplyResultsSelection
                    ) ||
                    {}
                );
              });
            });
          }
        );
      }

      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(
          pendingApplyResultsSelection,
          "apply"
        );
        return;
      }
      if (currentCvFile || capturedCvText) {
        applyResultsSameCvPromptKey = sameCvKey;
        startSelectedRoleApplicationAfterCvConfirm();
        return;
      }
      if (
        promptState === "apply_results_confirm_same_cv" &&
        applyResultsSameCvPromptKey === sameCvKey
      ) {
        focusComposer("Confirm yes to use the same CV");
        return;
      }
      applyResultsSameCvPromptKey = sameCvKey;
      var sameCvCopy = getExistingCvConfirmationLine(cvLabel);
      botMessage(
        sameCvCopy,
        humanComposeDelay(sameCvCopy, 900, 1800),
        function () {
          setPromptState(
            "apply_results_confirm_same_cv",
            {
              yes: function (value) {
                echoPromptChoice(value || "Yes, use the same CV");
                clearPromptState();
                startSelectedRoleApplicationAfterCvConfirm();
              },
              no: function (value) {
                echoPromptChoice(value || "No, I’ll upload another CV");
                clearPromptState();
                currentCvFile = null;
                currentCvPreviewAsset = null;
                currentCvPageCount = 0;
                clearCurrentStructuredCvParse({ sync: false });
                capturedCvText = "";
                var updatedCvRequest = getUpdatedCvRequestLine();
                botMessage(
                  updatedCvRequest,
                  humanComposeDelay(updatedCvRequest, 900, 1800),
                  function () {
                    if (uploadButton) {
                      uploadButton.hidden = false;
                    }
                    input.disabled = false;
                    focusComposer("Upload the CV for this application");
                  }
                );
              },
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                if (
                  /^(?:yes|y|same|use it|use same|correct|go ahead)/i.test(
                    clean
                  )
                ) {
                  echoPromptChoice(value || "Yes, use the same CV");
                  clearPromptState();
                  startSelectedRoleApplicationAfterCvConfirm();
                  return;
                }
                if (/^(?:no|n|new|different|upload)/i.test(clean)) {
                  echoPromptChoice(value || "No, I’ll upload another CV");
                  clearPromptState();
                  currentCvFile = null;
                  currentCvPreviewAsset = null;
                  currentCvPageCount = 0;
                  clearCurrentStructuredCvParse({ sync: false });
                  capturedCvText = "";
                  var updatedCvRequest = getUpdatedCvRequestLine();
                  botMessage(
                    updatedCvRequest,
                    humanComposeDelay(updatedCvRequest, 900, 1800),
                    function () {
                      if (uploadButton) {
                        uploadButton.hidden = false;
                      }
                      input.disabled = false;
                      focusComposer("Upload the CV for this application");
                    }
                  );
                  return;
                }
                focusComposer(
                  "Confirm yes to use the same CV, or no to upload another"
                );
              },
            },
            "Use the same CV?",
            {
              selected_role_key: getCommercialApplyQueueItemKey(
                pendingApplyResultsSelection || {}
              ),
            }
          );
          botMessage(renderApplyResultsSameCvActions(), 0);
          focusComposer("Confirm yes to use the same CV");
        }
      );
    }

    function showApplyResultsComparisonThenConfirmCv() {
      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(
          pendingApplyResultsSelection,
          "compare"
        );
        return;
      }
      withApplyResultsCvAnalysis(function () {
        botMessage(
          renderDetailedApplyResultsCvComparisonHtml(
            pendingApplyResultsSelection
          ),
          humanComposeDelay("Detailed CV role comparison.", 900, 1800),
          function () {
            setPromptState(
              "apply_results_selected_next_step",
              {
                compare: function () {
                  showApplyResultsComparisonThenConfirmCv();
                },
                tailored: function () {
                  continueApplyResultsSelectedRole("tailored");
                },
                application: function () {
                  continueApplyResultsSelectedRole("original");
                },
                original: function () {
                  continueApplyResultsSelectedRole("original");
                },
                yes: function () {
                  continueApplyResultsSelectedRole("tailored");
                },
                other: function (value) {
                  var clean = cleanMessageText(value || "").toLowerCase();
                  if (
                    /original|current cv|without tailor|don'?t tailor|dont tailor|skip tailor|not tailor|jump|straight/.test(
                      clean
                    )
                  ) {
                    continueApplyResultsSelectedRole("original");
                    return;
                  }
                  if (/apply|tailor|improve|prepare|strengthen/.test(clean)) {
                    continueApplyResultsSelectedRole("tailored");
                    return;
                  }
                  focusComposer(
                    "Prepare the tailored CV, or jump to the application"
                  );
                },
              },
              "Prepare tailored CV or jump to application?",
              {
                selected_role_key: getCommercialApplyQueueItemKey(
                  pendingApplyResultsSelection || {}
                ),
              }
            );
            botMessage(
              renderApplyResultsSelectedRoleActions({
                premium: false,
                afterComparison: true,
              }),
              0
            );
            focusComposer(
              "Prepare the tailored CV, or jump to the application"
            );
          }
        );
      });
    }

    function showApplyResultsComparisonThenChoice() {
      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(
          pendingApplyResultsSelection,
          "compare"
        );
        return;
      }
      withApplyResultsCvAnalysis(function () {
        botMessage(
          renderApplyResultsCvImprovementPlanHtml(pendingApplyResultsSelection),
          humanComposeDelay("Role-specific CV improvement plan.", 900, 1800),
          function () {
            setPromptState(
              "apply_results_selected_next_step",
              {
                compare: function () {
                  focusComposer("Apply with tailored CV, or use original CV");
                },
                application: function () {
                  continueApplyResultsSelectedRole("tailored");
                },
                tailored: function () {
                  continueApplyResultsSelectedRole("tailored");
                },
                original: function () {
                  continueApplyResultsSelectedRole("original");
                },
                yes: function () {
                  continueApplyResultsSelectedRole("tailored");
                },
                other: function (value) {
                  var clean = cleanMessageText(value || "").toLowerCase();
                  if (
                    /original|current cv|without tailor|don'?t tailor|dont tailor|skip tailor|not tailor|jump|straight/.test(
                      clean
                    )
                  ) {
                    continueApplyResultsSelectedRole("original");
                    return;
                  }
                  if (
                    /application|apply|start|go ahead|tailor|prepare/.test(
                      clean
                    )
                  ) {
                    continueApplyResultsSelectedRole("tailored");
                    return;
                  }
                  if (/compare|match|fit|cv|improve|how.*role/.test(clean)) {
                    focusComposer("Apply with tailored CV, or use original CV");
                    return;
                  }
                  focusComposer("Apply with tailored CV, or use original CV");
                },
              },
              "Apply with tailored CV, or use original CV?",
              {
                selected_role_key: getCommercialApplyQueueItemKey(
                  pendingApplyResultsSelection || {}
                ),
              }
            );
            focusComposer("Apply with tailored CV, or use original CV");
          }
        );
      });
    }

    function askApplyResultsCvForComparison() {
      askForCvBeforeSelectedRoleApplication(
        pendingApplyResultsSelection,
        "compare"
      );
    }

    function continueApplyResultsSelectedRole(choice) {
      var cleanChoice = cleanMessageText(choice || "").toLowerCase();
      deactivateVisibleInlineActionRows();
      clearPromptState();
      if (
        /original|current cv|without tailor|don'?t tailor|dont tailor|skip tailor|not tailor/.test(
          cleanChoice
        )
      ) {
        echoPromptChoice("Original CV");
        pendingApplyResultsSelection = Object.assign(
          {},
          pendingApplyResultsSelection || {},
          { cvMode: "original" }
        );
        applyCvReviewSkipped = true;
        if (!hasApplyChatCvAvailable()) {
          askForCvBeforeSelectedRoleApplication(
            pendingApplyResultsSelection,
            "apply"
          );
          return;
        }
        askApplyResultsSameCvThenStart();
        return;
      }
      if (/tailor|tailored|prepare|strengthen/.test(cleanChoice)) {
        echoPromptChoice("Tailor CV");
        pendingApplyResultsSelection = Object.assign(
          {},
          pendingApplyResultsSelection || {},
          { cvMode: "tailored" }
        );
        applyCvReviewSkipped = false;
        if (!hasApplyChatCvAvailable()) {
          askForCvBeforeSelectedRoleApplication(
            pendingApplyResultsSelection,
            "apply"
          );
          return;
        }
        askApplyResultsSameCvThenStart();
        return;
      }
      if (/compare|cv|match|fit|see how|improve/.test(cleanChoice)) {
        echoPromptChoice(
          hasPremiumMemberChatAccess() ? "Improve CV first" : "Compare to my CV"
        );
        if (hasPremiumMemberChatAccess()) {
          showApplyResultsComparisonThenChoice();
        } else {
          showApplyResultsComparisonThenConfirmCv();
        }
        return;
      }
      if (
        /application|jump|straight|start|go ahead/.test(cleanChoice) &&
        !hasPremiumMemberChatAccess()
      ) {
        echoPromptChoice("Jump to application");
        pendingApplyResultsSelection = Object.assign(
          {},
          pendingApplyResultsSelection || {},
          { cvMode: "original" }
        );
        applyCvReviewSkipped = true;
        if (!hasApplyChatCvAvailable()) {
          askForCvBeforeSelectedRoleApplication(
            pendingApplyResultsSelection,
            "apply"
          );
          return;
        }
        askApplyResultsSameCvThenStart();
        return;
      }
      echoPromptChoice("Tailor CV");
      pendingApplyResultsSelection = Object.assign(
        {},
        pendingApplyResultsSelection || {},
        { cvMode: "tailored" }
      );
      applyCvReviewSkipped = false;
      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(
          pendingApplyResultsSelection,
          "apply"
        );
        return;
      }
      askApplyResultsSameCvThenStart();
    }

    function getEmilyDecisionEngineConfig() {
      var config = getConfig();
      var threshold = Number(config.emilyDecisionConfidenceThreshold);
      if (!isFinite(threshold) || threshold <= 0 || threshold >= 1) {
        threshold = 0.6;
      }
      return {
        enabled: config.emilyDecisionEngineEnabled !== false,
        shadowMode: config.emilyDecisionEngineShadowMode === true,
        confidenceThreshold: threshold,
        runtimeSafetyEnabled: config.emilyRuntimeSafetyEnabled !== false,
        disableProbabilisticRouting:
          config.emilyDisableProbabilisticRouting === true,
        disableSemanticRouting: config.emilyDisableSemanticRouting === true,
        disableRouteEnsemble: config.emilyDisableRouteEnsemble === true,
        disableWebSearch: config.emilyDisableWebSearch === true,
        disableApplicationExecution:
          config.emilyDisableApplicationExecution === true,
        strictPromptProtection:
          config.emilyStrictPromptProtection !== false,
        activePromptOverrideConfidence: 0.88,
      };
    }

    function recordEmilyRuntimeSafetyTelemetry(type, details) {
      var event = Object.assign(
        {
          type: cleanMessageText(type || "runtime_safety"),
          createdAt: new Date().toISOString(),
          conversationId: Number(applyChatConversationId || 0) || 0,
        },
        details || {}
      );
      emilyRuntimeSafetyTelemetryLog.push(event);
      emilyRuntimeSafetyTelemetryLog =
        emilyRuntimeSafetyTelemetryLog.slice(-120);
      try {
        window.__sffcEmilyRuntimeSafetyTelemetry =
          emilyRuntimeSafetyTelemetryLog;
        window.__sffcEmilyRuntimeSafetyLatest = event;
      } catch (error) {}
      try {
        recordConversationAuditEvent("runtime_safety", event);
      } catch (error) {}
      return event;
    }

    function buildDisabledEmilyRouteSignal(reason) {
      return {
        route: "clarify",
        probability: 0,
        similarity: 0,
        score: 0,
        calibratedProbability: 0,
        calibrationBand: "disabled",
        confidenceBand: "disabled",
        shouldClarify: true,
        runnerUp: "",
        runnerUpScore: 0,
        margin: 0,
        candidates: [],
        disabled: true,
        reason: cleanMessageText(reason || "disabled"),
      };
    }

    function safeClassifyEmilyDecisionRouteProbability(value, features, config) {
      if (config && config.disableProbabilisticRouting) {
        return buildDisabledEmilyRouteSignal("probabilistic_routing_disabled");
      }
      try {
        return classifyEmilyDecisionRouteProbability(value || "", features || {});
      } catch (error) {
        recordEmilyRuntimeSafetyTelemetry("probabilistic_route_error", {
          message: cleanMessageText((error && error.message) || ""),
        });
        return buildDisabledEmilyRouteSignal("probabilistic_route_error");
      }
    }

    function safeClassifyEmilyDecisionRouteSemantic(value, features, config) {
      if (
        config &&
        (config.disableSemanticRouting || config.disableProbabilisticRouting)
      ) {
        return buildDisabledEmilyRouteSignal("semantic_routing_disabled");
      }
      try {
        return classifyEmilyDecisionRouteSemanticSimilarity(
          value || "",
          features || {}
        );
      } catch (error) {
        recordEmilyRuntimeSafetyTelemetry("semantic_route_error", {
          message: cleanMessageText((error && error.message) || ""),
        });
        return buildDisabledEmilyRouteSignal("semantic_route_error");
      }
    }

    function safeScoreEmilyRoutes(features, context, probability, semantic) {
      var config = (context && context.config) || getEmilyDecisionEngineConfig();
      if (
        config &&
        (config.disableRouteEnsemble || config.disableProbabilisticRouting)
      ) {
        return buildDisabledEmilyRouteSignal("route_ensemble_disabled");
      }
      try {
        return scoreEmilyRoutes(
          features || {},
          context || {},
          probability,
          semantic
        );
      } catch (error) {
        recordEmilyRuntimeSafetyTelemetry("route_ensemble_error", {
          message: cleanMessageText((error && error.message) || ""),
        });
        return buildDisabledEmilyRouteSignal("route_ensemble_error");
      }
    }

