    function getNextCoverLetterTemplate() {
      var templates = getCoverLetterTemplatePool();
      var shown =
        applyChatMemory &&
        Array.isArray(applyChatMemory.shownCoverLetterTemplateIds)
          ? applyChatMemory.shownCoverLetterTemplateIds
          : [];
      var shownMap = {};
      var template = null;
      shown.forEach(function (id) {
        shownMap[cleanMessageText(id)] = true;
      });
      template = templates.filter(function (item) {
        return item && item.id && !shownMap[item.id];
      })[0];
      if (!template) {
        shown = [];
        template = templates[0];
      }
      if (template && applyChatMemory) {
        applyChatMemory.shownCoverLetterTemplateIds = dedupeList(
          shown.concat([template.id])
        ).slice(-templates.length);
        queueApplyChatMemoryPersist();
      }
      return {
        template: template,
        index: templates.indexOf(template) + 1,
        total: templates.length,
      };
    }

    function getCoverLetterTemplateLibraryHtml() {
      var selected = getNextCoverLetterTemplate();
      var template = selected.template || getCoverLetterTemplatePool()[0];
      return renderApplicationMaterialCoverLetterDocument({
        kicker:
          "Cover letter template " +
          String(selected.index || 1) +
          " of " +
          String(selected.total || 20),
        templateName: template.name || "Cover letter template",
        bestFor: template.bestFor || "A role-specific application.",
        candidateName: "[Your Name]",
        roleTitle: "[Role Title]",
        company: "[Company Name]",
        location: "[Company Address / Location]",
        draft: template.draft || "",
      });
    }

    function handleCoverLetterDraftTask(value, preferredRole) {
      var role = getApplicationMaterialRoleForDraft(value || "", preferredRole);
      clearPromptState();
      botMessage(
        buildCoverLetterDraftHtml(role, value || ""),
        humanComposeDelay("Draft cover letter.", 900, 1800),
        function () {
          focusComposer("Ask me to adjust tone, length, or emphasis");
        }
      );
      return true;
    }

    function handleCoverLetterTipsTask() {
      clearPromptState();
      botMessage(
        getCoverLetterTemplateLibraryHtml(),
        humanComposeDelay("Cover letter template.", 900, 1800),
        function () {
          focusComposer(
            "Ask for another template, a draft, or a shorter version"
          );
        }
      );
      return true;
    }

    function handleApplicationMaterialChoice(
      value,
      originalRequest,
      preferredRole
    ) {
      var choice = getApplicationMaterialChoice(value || "");
      if (choice === "cover_letter") {
        return handleCoverLetterDraftTask(
          originalRequest || value || "",
          preferredRole
        );
      }
      clearPromptState();
      botMessage(
        "I can draft that, but I need the exact wording or requirement from the application form so I do not invent an answer. Paste the question and I’ll write a clean first version.",
        humanComposeDelay(
          "Ask for exact application material prompt.",
          900,
          1800
        ),
        function () {
          focusComposer("Paste the exact application question");
        }
      );
      return true;
    }

    function handleApplicationMaterialTask(value, preferredRole) {
      var role = getCurrentTaskRoleForDelegatedTask(preferredRole);
      var subject = getDelegatedTaskRoleSubject(role);
      var materialChoice = getApplicationMaterialChoice(value || "");
      if (materialChoice === "cover_letter") {
        return handleCoverLetterDraftTask(value || "", preferredRole);
      }
      clearPromptState();
      botMessage(
        subject
          ? "I can draft that for <strong>" +
              escapeHtml(subject) +
              "</strong>, but I’ll keep it evidence-based. Send the exact question or choose the application material you need: cover letter, short note, salary expectation, notice period, or motivation answer."
          : "I can draft application materials, but I need the target role first so the answer is not generic. Choose a role or paste the application question.",
        humanComposeDelay("Start application material task.", 900, 1800),
        function () {
          setPromptState(
            "application_material_choice",
            {
              other: function (reply) {
                handleApplicationMaterialChoice(reply, value || "", role);
              },
            },
            "Choose cover letter, short note, salary, notice period, or paste the question"
          );
          focusComposer(
            "Paste the application question or choose the material"
          );
        }
      );
      return true;
    }

    function looksLikeRecruiterNetworkingTask(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      if (looksLikeSennaContactQuestion(clean)) {
        return false;
      }
      return (
        /\b(?:find|who|message|contact|reach out|network|referral|refer|intro|introduction|follow up)\b.*\b(?:recruiter|hiring manager|team|people|someone|alumni|linkedin|referral)\b/i.test(
          clean
        ) ||
        /\b(?:who should i contact|help me network|how can i get a referral|write a linkedin message|write a recruiter message|write a cold email)\b/i.test(
          clean
        )
      );
    }

    function handleRecruiterNetworkingTask(preferredRole) {
      var role = getCurrentTaskRoleForDelegatedTask(preferredRole);
      var subject = getDelegatedTaskRoleSubject(role);
      clearPromptState();
      botMessage(
        subject
          ? "I’ll treat this as a networking task for <strong>" +
              escapeHtml(subject) +
              "</strong>. The useful route is to identify whether the best path is the employer form, recruiter, hiring manager, referral, or alumni contact, then draft the message around your actual fit."
          : "I can help with recruiter or referral outreach. Choose the target company or role first, and I’ll suggest the route and draft the message.",
        humanComposeDelay("Start recruiter networking task.", 900, 1800),
        function () {
          focusComposer(
            subject
              ? "Ask for route, recruiter, referral, or message"
              : "Name the company or choose a role"
          );
        }
      );
      return true;
    }

    function looksLikeSalaryCompensationTask(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return (
        /\b(?:salary|compensation|bonus|pay|package|offer|negotiate|take-home|take home|expectations?)\b/i.test(
          clean
        ) &&
        /\b(?:what|range|should|fair|compare|calculate|ask|negotiate|worth|offer|expect)\b/i.test(
          clean
        )
      );
    }

    function handleSalaryCompensationTask(value, preferredRole) {
      var role = getCurrentTaskRoleForDelegatedTask(preferredRole);
      var salaryAnswer = buildNativeSalaryReasoningAnswer(value, role, {
        includePositioning: true,
      });
      if (role) {
        var salaryRole = normalizeCommercialApplyQueueItem(role, "Ready");
        pendingApplyResultsSelection = salaryRole;
        setCurrentApplicationContextFromQueueItem(salaryRole);
        clearPromptState();
        botMessage(
          salaryAnswer,
          humanComposeDelay("Answer salary task for selected role.", 900, 1800),
          function () {
            focusComposer("Ask about salary, fit, or application next");
          }
        );
        return true;
      }
      clearPromptState();
      botMessage(
        salaryAnswer,
        humanComposeDelay("Ask salary context.", 900, 1800),
        function () {
          focusComposer("Tell me the role, location, and level");
        }
      );
      return true;
    }

    function looksLikeCompanyResearchTask(value) {
      var clean = normalizeCareerIntentText(
        cleanMessageText(value || "")
      ).toLowerCase();
      return (
        /\b(?:tell me about|research|what does|who owns|how big|reputation|culture|good employer|competitors|aum|fund size|portfolio|recent deals|recent exits|investment strategy|is it growing|why are they hiring)\b.*\b(?:company|firm|employer|fund|they|this)\b/i.test(
          clean
        ) ||
        /\b(?:what do they actually do|is this a good company|what should i know before interviewing there)\b/i.test(
          clean
        )
      );
    }

    function handleCompanyResearchTask(value, preferredRole) {
      var role = getCurrentTaskRoleForDelegatedTask(preferredRole);
      if (role) {
        var companyRole = normalizeCommercialApplyQueueItem(role, "Ready");
        pendingApplyResultsSelection = companyRole;
        setCurrentApplicationContextFromQueueItem(companyRole);
        clearPromptState();
        botMessage(
          buildSelectedRoleQuestionReply(value, companyRole),
          humanComposeDelay(
            "Answer company task for selected role.",
            900,
            1800
          ),
          function () {
            focusComposer("Ask about the company or continue applying");
          }
        );
        return true;
      }
      clearPromptState();
      botMessage(
        "I can research the company, but I need the company or role first. Name the employer or choose a role from the results and I’ll keep the answer tied to the job decision.",
        humanComposeDelay("Ask company target.", 900, 1800),
        function () {
          focusComposer("Name the company or choose a role");
        }
      );
      return true;
    }

    function handleHighPriorityTaskCommand(value) {
      var explicitRoleContext = getExplicitRoleContextForQuestion(value);
      if (promptState && classifyExplicitPromptAnswer(value)) {
        return false;
      }
      if (looksLikeEmilyStopCorrection(value)) {
        return handleEmilyStopCorrection();
      }
      if (looksLikeEmilyFrustrationCorrection(value)) {
        return handleEmilyFrustrationCorrection();
      }
      if (
        looksLikeVisibleJobSearchResultsQuestion(value, {
          jobSearchContext: getCurrentJobSearchContextSnapshot(),
        })
      ) {
        return false;
      }
      if (looksLikeMatchCriteriaExplanationRequest(value)) {
        return handleMatchCriteriaExplanationRequest();
      }
      if (looksLikeSearchCriteriaEditRequest(value)) {
        return handleSearchCriteriaEditRequest();
      }
      if (looksLikeCapabilityInventoryTask(value)) {
        return handleCapabilityInventoryTask();
      }
      if (looksLikeApplicationHistoryTask(value)) {
        return handleApplicationHistoryTask();
      }
      if (looksLikeCvInventoryQuestion(value)) {
        return answerCurrentCvInventoryQuestion();
      }
      if (looksLikeCvTailoringTaskRequest(value)) {
        return handleCvTailoringTaskRequest(value);
      }
      if (looksLikeCvReviewTaskRequest(value)) {
        return handleCvReviewTaskRequest(value);
      }
      if (looksLikeInterviewProbabilityOptimization(value)) {
        return handleInterviewProbabilityOptimization(value);
      }
      if (looksLikeCompanyResearchTask(value)) {
        return handleCompanyResearchTask(value, explicitRoleContext);
      }
      if (looksLikeSalaryCompensationTask(value)) {
        return handleSalaryCompensationTask(value, explicitRoleContext);
      }
      if (looksLikeRecruiterNetworkingTask(value)) {
        return handleRecruiterNetworkingTask(explicitRoleContext);
      }
      if (looksLikeInterviewPrepTask(value)) {
        return handleInterviewPrepTask(explicitRoleContext);
      }
      if (looksLikeApplicationMaterialTask(value)) {
        return handleApplicationMaterialTask(value, explicitRoleContext);
      }
      return false;
    }

    function estimateLegacyApplyChatRoute(value) {
      var clean = cleanMessageText(value || "");
      var promptKey = cleanMessageText(promptState || "");
      var route = {
        type: "fallback",
        promptState: promptKey,
        activePath: cleanMessageText(activePath || ""),
        step: cleanMessageText(step || ""),
        material: true,
      };
      if (applyChatHumanTakeoverActive) {
        route.type = "human_takeover";
        route.material = false;
        return route;
      }
      if (promptKey) {
        route.type = "prompt_handler";
        route.material = true;
        return route;
      }
      if (activePath === "member_desk") {
        route.type = "member_desk";
        return route;
      }
      if (step === "choice") {
        route.type = "launcher_choice";
        return route;
      }
      if (looksLikeConcreteApplyChatJobSearch(clean, detectIntent(clean))) {
        route.type = "job_search";
        return route;
      }
      if (hasActiveApplicationLikeTask()) {
        route.type = "active_application_fallback";
        return route;
      }
      route.type = "general_fallback";
      return route;
    }

    function isMaterialConversationDecisionDivergence(decision, legacyRoute) {
      var actionType =
        decision && decision.nextAction && decision.nextAction.type;
      var intentType = decision && decision.intent && decision.intent.type;
      var legacyType = legacyRoute && legacyRoute.type;
      if (!actionType || !legacyType) {
        return false;
      }
      if (
        actionType === "defer_to_prompt_handler" &&
        legacyType === "prompt_handler"
      ) {
        return false;
      }
      if (actionType === "show_job_results" && legacyType === "job_search") {
        return false;
      }
      if (
        actionType === "answer_directly" &&
        /^career_/.test(intentType || "")
      ) {
        return (
          legacyType === "prompt_handler" ||
          legacyType === "active_application_fallback"
        );
      }
      if (
        legacyType === "prompt_handler" &&
        actionType !== "defer_to_prompt_handler"
      ) {
        return true;
      }
      if (
        legacyType === "active_application_fallback" &&
        /^(show_job_results|answer_directly|update_search_preferences|reset_search_preferences|answer_search_filters)$/.test(
          actionType
        )
      ) {
        return true;
      }
      return false;
    }

    function logConversationDecision(value, decision, validation, mode) {
      var legacyRoute = estimateLegacyApplyChatRoute(value);
      var entry = {
        message: cleanMessageText(value || ""),
        decision: decision,
        validation: validation,
        legacyRoute: legacyRoute,
        materialDivergence: isMaterialConversationDecisionDivergence(
          decision,
          legacyRoute
        ),
        mode: mode || "live",
        createdAt: new Date().toISOString(),
      };
      conversationDecisionLog.push(entry);
      conversationDecisionLog = conversationDecisionLog.slice(-80);
      try {
        window.__sffcApplyChatDecisionLog = conversationDecisionLog;
      } catch (error) {}
      try {
        logEmilyDecisionOutcome(value, decision, validation, mode);
      } catch (error) {}
    }

    function getEmilyOutcomeWorkflowState() {
      var activeTask = getConversationDecisionActiveTask
        ? getConversationDecisionActiveTask()
        : {};
      if (activeTask && activeTask.type) {
        return cleanMessageText(activeTask.type);
      }
      if (singleRoleResultActive) return "selected_role";
      if (commercialApplyQueueItemsState.length) return "apply_queue";
      if (matchingRolesSeed && matchingRolesSeed.length) return "job_search";
      return "chat";
    }

    function sanitizeEmilyOutcomeDecision(decision) {
      var intent = (decision && decision.intent) || {};
      var route = (decision && decision.route) || {};
      var routeEnsemble =
        (intent && intent.routeEnsemble) ||
        (decision && decision.debug && decision.debug.routeEnsemble) ||
        null;
      var candidates =
        routeEnsemble && routeEnsemble.candidates
          ? routeEnsemble.candidates.slice(0, 5).map(function (candidate) {
              return {
                route: cleanMessageText((candidate && candidate.route) || ""),
                score: Number((candidate && candidate.score) || 0) || 0,
                calibratedProbability:
                  Number((candidate && candidate.calibratedProbability) || 0) ||
                  0,
              };
            })
          : [];
      return {
        chosenRoute: cleanMessageText((route && route.key) || ""),
        intentType: cleanMessageText((intent && intent.type) || ""),
        actionType: cleanMessageText(
          (decision && decision.nextAction && decision.nextAction.type) || ""
        ),
        confidence:
          Number(
            (decision && decision.reasoningPlan && decision.reasoningPlan.confidence) ||
              (intent && intent.confidence) ||
              0
          ) || 0,
        confidenceBand: routeEnsemble
          ? cleanMessageText(routeEnsemble.calibrationBand || routeEnsemble.confidenceBand || "")
          : "",
        topRoutes: candidates,
      };
    }

    function sanitizeEmilyOutcomeRole(item, match) {
      var structuredFit = match && match.structuredFit ? match.structuredFit : null;
      return {
        id: cleanMessageText(
          (item &&
            (item.id || item.post_id || item.crm_post_id || item.wp_post_id)) ||
            ""
        ),
        title: cleanMessageText((item && item.title) || ""),
        company: cleanMessageText((item && item.company) || ""),
        location: cleanMessageText((item && item.location) || ""),
        provider: cleanMessageText(
          (item &&
            (item.provider ||
              item.apply_provider ||
              item.route ||
              item.application_route)) ||
            ""
        ),
        score: Number((match && match.score) || 0) || 0,
        fitScore: Number((structuredFit && structuredFit.fitScore) || 0) || 0,
        fitBand: cleanMessageText(
          (structuredFit && structuredFit.interviewProbabilityBand) || ""
        ),
        reasonCodes: ((structuredFit && structuredFit.reasonCodes) || []).slice(0, 8),
        risks: ((structuredFit && structuredFit.risks) || []).slice(0, 8),
        rankingScore:
          Number((match && match.learningRank && match.learningRank.score) || 0) ||
          0,
        rankingModel: cleanMessageText(
          (match && match.learningRank && match.learningRank.model) || ""
        ),
      };
    }

    function logEmilyOutcomeEvent(type, payload) {
      var event = Object.assign(
        {
          schemaVersion: 1,
          seq: ++emilyOutcomeEventSeq,
          type: cleanMessageText(type || "event"),
          createdAt: new Date().toISOString(),
          conversationId: Number(applyChatConversationId || 0) || 0,
          userTier: getApplyChatUserTier(),
          workflowState: getEmilyOutcomeWorkflowState(),
        },
        payload || {}
      );
      emilyOutcomeEventLog.push(event);
      emilyOutcomeEventLog = emilyOutcomeEventLog.slice(-250);
      try {
        window.__sffcEmilyOutcomeEventLog = emilyOutcomeEventLog;
        window.__sffcEmilyOutcomeEventLatest = event;
      } catch (error) {}
      return event;
    }

    function logEmilyDecisionOutcome(value, decision, validation, mode) {
      var summary = sanitizeEmilyOutcomeDecision(decision || {});
      return logEmilyOutcomeEvent("decision", {
        message: cleanMessageText(value || "").slice(0, 280),
        decision: summary,
        validation: validation
          ? {
              valid: validation.valid !== false,
              reason: cleanMessageText(validation.reason || ""),
            }
          : null,
        mode: mode || "live",
        outcome: "continued",
      });
    }

    function logEmilyJobOutcomeEvent(type, item, match, extra) {
      return logEmilyOutcomeEvent(type, Object.assign({
        role: sanitizeEmilyOutcomeRole(item || {}, match || null),
      }, extra || {}));
    }

    function getEmilyOutcomeRoleEventKey(item, fallback) {
      var source = item || {};
      return (
        getCommercialApplyQueueComparableKey(source) ||
        [
          cleanMessageText(source.title || ""),
          cleanMessageText(source.company || ""),
          cleanMessageText(source.location || ""),
        ]
          .filter(Boolean)
          .join("|")
          .toLowerCase()
          .replace(/\s+/g, " ") ||
        cleanMessageText(fallback || "")
      );
    }

    function logEmilyJobResultImpressions(items, source) {
      (items || []).slice(0, 12).forEach(function (item, index) {
        var key = getEmilyOutcomeRoleEventKey(
          item,
          "result:" + String(index)
        );
        var eventKey = [source || "results", "impression", key].join(":");
        if (!key || emilyOutcomeImpressionKeys[eventKey]) {
          return;
        }
        emilyOutcomeImpressionKeys[eventKey] = true;
        logEmilyJobOutcomeEvent("job_impression", item, item && item.match, {
          rank: index + 1,
          source: cleanMessageText(source || "results"),
          outcome: "shown",
        });
      });
    }

    function getCareerTaskResumeHint(decision) {
      var activeTask = getConversationDecisionActiveTask();
      var selectedRole =
        pendingApplyResultsSelection ||
        (careerConversationMemory && careerConversationMemory.currentSelectedRole) ||
        null;
      var selectedCtx = selectedRole ? getEmilyVoiceContext(selectedRole) : null;
      var selectedSubject = selectedCtx ? getEmilyRoleSubject(selectedCtx) : "";
      var relationship = cleanMessageText(
        (decision && decision.relationshipToTask) || ""
      );
      if (
        !/^(?:interrupts_task|pauses_task|changes_task)$/.test(relationship) &&
        !(activeTask && activeTask.type)
      ) {
        return "";
      }
      if (
        activePath === "apply_for_me" ||
        /apply|application|selected_role/.test(
          cleanMessageText((activeTask && activeTask.type) || "")
        )
      ) {
        return selectedSubject
          ? "When you’re ready, we can go back to " +
              escapeHtml(selectedSubject) +
              " and continue the application."
          : "When you’re ready, we can return to the application and continue from the same step.";
      }
      if (
        activePath === "job_search" ||
        /search|roles|market/.test(
          cleanMessageText((activeTask && activeTask.type) || "")
        )
      ) {
        return "When you’re ready, we can keep refining the current search.";
      }
      return "When you’re ready, we can continue from the same step.";
    }

    function appendCareerResumeHint(html, decision) {
      var hint = getCareerTaskResumeHint(decision);
      if (!hint) {
        return html;
      }
      return String(html || "") + "<br><br>" + hint;
    }

    function focusCareerFollowUpOrResume(decision) {
      var hint = getCareerTaskResumeHint(decision);
      if (hint && activePath === "apply_for_me") {
        focusComposer("Ask a follow-up, or tell me to continue the application");
        return;
      }
      if (hint && activePath === "job_search") {
        focusComposer("Ask a follow-up, or refine the current search");
        return;
      }
      focusComposer("Ask a follow-up or tell me what to do next");
    }

    function executeConversationDecision(decision, value) {
      var action = decision && decision.nextAction ? decision.nextAction : {};
      if (looksLikeUnsupportedCvClaimInstruction(value)) {
        return answerUnsupportedCvClaimInstruction(value);
      }
      if (action.type === "web_search") {
        if (
          decision.relationshipToTask === "pauses_task" ||
          decision.relationshipToTask === "changes_task" ||
          decision.relationshipToTask === "interrupts_task"
        ) {
          pauseActiveWorkflowForCareerConversation("web_search");
        }
        clearPromptState();
        return searchWebInApplyChat(
          (action.params && action.params.query) || value
        );
      }
      if (handleHighPriorityTaskCommand(value)) {
        return true;
      }
      if (action.type === "defer_to_prompt_handler") {
        return false;
      }
      if (action.type === "ask_clarifying_question") {
        botMessage(
          escapeHtml(
            cleanMessageText((action.params && action.params.prompt) || "")
          ),
          humanComposeDelay("Clarify conversation route.", 800, 1500),
          function () {
            focusComposer("Search, apply, or ask a career question?");
          }
        );
        return true;
      }
      if (action.type === "show_job_results") {
        clearPromptState();
        return searchActualJobPostsInChat(
          (action.params && action.params.query) || value
        );
      }
      if (action.type === "update_search_preferences") {
        clearPromptState();
        var preferenceFeedback = action.params && action.params.feedback;
        var refreshQuery;
        updateSearchPreferencesFromDecision(preferenceFeedback);
        logEmilyOutcomeEvent("user_feedback", {
          feedback: cleanMessageText(preferenceFeedback || "").slice(0, 280),
          source: "conversation_decision",
          outcome: "search_preferences_updated",
        });
        refreshQuery = buildApplyChatPreferenceRefreshQuery(
          preferenceFeedback,
          value
        );
        botMessage(
          getContextualSearchPreferenceAck(preferenceFeedback, value),
          humanComposeDelay("Search preferences updated.", 800, 1500),
          function () {
            searchActualJobPostsInChat(refreshQuery);
          }
        );
        return true;
      }
      if (action.type === "answer_search_filters") {
        clearPromptState();
        botMessage(
          getApplyChatSearchFilterSummaryHtml(),
          humanComposeDelay("Current search filters.", 800, 1500),
          function () {
            focusComposer("Change a filter or search again");
          }
        );
        return true;
      }
      if (action.type === "answer_search_results_question") {
        clearPromptState();
        botMessage(
          getVisibleJobSearchResultsAnswerHtml(value, decision),
          humanComposeDelay(
            "Answer visible job search results question.",
            900,
            1800
          ),
          function () {
            focusComposer(
              "Ask about a result, compare with your CV, or refine the search"
            );
          },
          humanReadDelay(value, 380)
        );
        return true;
      }
      if (action.type === "reset_search_preferences") {
        clearPromptState();
        var resetFeedback = action.params && action.params.feedback;
        var keepLocations = [];
        var keepFunctions = [];
        var keepSectors = [];
        (resetFeedback && resetFeedback.updates
          ? resetFeedback.updates
          : []
        ).forEach(function (update) {
          var value = cleanMessageText(
            update && update.value ? update.value : ""
          );
          if (!value || update.action === "clear") {
            return;
          }
          if (update.field === "targetLocations") {
            keepLocations = [value];
          } else if (update.field === "targetFunctions") {
            keepFunctions = sanitizeRoleTargetList(
              keepFunctions.concat([value])
            );
          } else if (update.field === "targetSectors") {
            keepSectors = dedupeList(keepSectors.concat([value]));
          }
        });
        clearApplyChatSearchFilters({
          targetLocations: keepLocations,
          targetFunctions: keepFunctions,
          targetSectors: keepSectors,
        });
        botMessage(
          keepLocations.length || keepFunctions.length || keepSectors.length
            ? "I’ve reset the old filters and kept the criteria you named."
            : "I’ve cleared the search filters. I’ll start the search from a clean state.",
          humanComposeDelay("Search filters reset.", 800, 1500),
          function () {
            searchActualJobPostsInChat(getContextualApplyChatSearchQuery());
          }
        );
        return true;
      }
      if (action.type === "answer_directly") {
        var directAnswerIntent =
          (decision && decision.intent && decision.intent.type) ||
          detectIntent(value);
        var directCareerAnswer = getDirectCareerQuestionAnswer(
          directAnswerIntent,
          value
        );
        if (directCareerAnswer) {
          var directCareerAnswerHtml = appendCareerResumeHint(
            directCareerAnswer,
            decision
          );
          if (
            decision.relationshipToTask === "pauses_task" ||
            decision.relationshipToTask === "changes_task" ||
            decision.relationshipToTask === "interrupts_task"
          ) {
            pauseActiveWorkflowForCareerConversation(directAnswerIntent);
          }
          botMessage(
            directCareerAnswerHtml,
            humanComposeDelay(directCareerAnswerHtml, 1200, 2600),
            function () {
              focusCareerFollowUpOrResume(decision);
            },
            humanReadDelay(value, 420)
          );
          return true;
        }
        if (
          handleCareerConversationFirst(value, {
            promptState: decision.activeTask && decision.activeTask.promptState,
            intent: detectIntent(value),
          })
        ) {
          return true;
        }
        if (
          decision.relationshipToTask === "pauses_task" ||
          decision.relationshipToTask === "changes_task" ||
          decision.relationshipToTask === "interrupts_task"
        ) {
          pauseActiveWorkflowForCareerConversation(
            decision.intent && decision.intent.type
          );
        }
        botMessage(
          decision.intent && decision.intent.type === "application_pause"
            ? pickVariant("emily_application_pause_fallback", [
                "Paused. I will not move the application forward unless you explicitly tell me to continue.",
                "No problem. I’ll keep the application parked here and we can work through the question first.",
                "I’ve stopped the application path. Nothing gets submitted unless you clearly ask me to resume.",
              ])
            : pickVariant("emily_career_direct_fallback", [
                "I can help with that. I’ll use the role, CV, and search context where it matters instead of giving you a generic answer.",
                "Yes. Let’s treat that as a career question first, then return to the application only if it still makes sense.",
                "I can work through that with you. Give me the part that feels unclear and I’ll tie the answer back to your current search.",
              ]),
          humanComposeDelay("Career conversation fallback.", 900, 1800),
          function () {
            focusComposer("Ask Emily about your career or search");
          }
        );
        return true;
      }
      if (action.type === "answer_application_status") {
        var statusItems = commercialApplyQueueItemsState.length
          ? commercialApplyQueueItemsState
          : pendingApplyResultsSelection
          ? [pendingApplyResultsSelection]
          : [];
        if (
          statusItems.length &&
          !hasConcreteRoleEntryContext() &&
          !isApplyChatRoleEntityVisibleInCurrentResults(statusItems[0])
        ) {
          statusItems = [];
        }
        if (
          statusItems.length &&
          !currentCvFile &&
          !capturedCvText &&
          !hasLoggedInSavedCv()
        ) {
          var waitingRole = statusItems[0] || {};
          var waitingRoleLabel = cleanMessageText(
            [
              waitingRole.title || roleTitle || "this role",
              waitingRole.company || roleCompany
                ? "at " + (waitingRole.company || roleCompany)
                : "",
            ]
              .filter(Boolean)
              .join(" ")
          );
          botMessage(
            getContextualCvRequestLine(waitingRole, "status"),
            humanComposeDelay("Application waiting for CV.", 900, 1800),
            function () {
              if (uploadButton) {
                uploadButton.hidden = false;
              }
              input.disabled = false;
              focusComposer("Upload your CV or paste it here");
            }
          );
          return true;
        }
        if (!statusItems.length) {
          botMessage(
            getNoActiveApplicationStatusLine(),
            humanComposeDelay("No active application status.", 900, 1800),
            function () {
              focusComposer("Search for a role or choose a result");
            }
          );
          return true;
        }
        var primaryStatusItem = normalizeCommercialApplyQueueItem(
          pendingApplyResultsSelection || statusItems[0],
          "Ready"
        );
        var primaryStatusLabel = cleanMessageText(
          [
            primaryStatusItem.title || roleTitle || "this role",
            primaryStatusItem.company || roleCompany
              ? "at " + (primaryStatusItem.company || roleCompany)
              : "",
          ]
            .filter(Boolean)
            .join(" ")
        );
        var primaryStatusStage = cleanMessageText(
          step ||
            promptState ||
            (commercialApplyQueueActivated ? "application running" : "selected")
        );
        botMessage(
          '<section class="sffc-crm-apply-chat__application-status-card">' +
            "<h3>Application status</h3>" +
            "<p><strong>" +
            escapeHtml(primaryStatusLabel || "Selected role") +
            "</strong></p>" +
            "<p>Status: " +
            escapeHtml(
              commercialApplyQueueActivated
                ? "preparing application"
                : "selected, not submitted"
            ) +
            "</p>" +
            "<p>Current step: " +
            escapeHtml(primaryStatusStage || "waiting for next instruction") +
            "</p>" +
            "<p>I have not marked this application as submitted because I do not have employer confirmation evidence.</p>" +
            "</section>",
          humanComposeDelay("Application status summary.", 800, 1500),
          function () {
            focusComposer(
              "Ask about this application or search for another role"
            );
          }
        );
        return true;
      }
      if (action.type === "resume_task") {
        clearPromptState();
        if (pendingApplyResultsSelection) {
          askApplyResultsSameCvThenStart();
          return true;
        }
        botMessage(
          "I can pick the application back up, but I need you to choose the role from the current results again so I use the right employer link.",
          humanComposeDelay("Resume needs selected role.", 900, 1800),
          function () {
            focusComposer("Choose the role to continue");
          }
        );
        return true;
      }
      if (action.type === "render_selected_role") {
        clearPromptState();
        pendingApplyResultsSelection = normalizeCommercialApplyQueueItem(
          action.params && action.params.selectedRole,
          "Ready"
        );
        setCurrentApplicationContextFromQueueItem(pendingApplyResultsSelection);
        activePath = "apply_for_me";
        step = "apply_upload";
        commercialApplyQueueInitialized = true;
        commercialApplyQueueActivated = false;
        commercialApplyQueueDetailsMode = true;
        commercialApplyQueueActiveTab = "shortlist";
        commercialApplyQueueFilter = "all";
        commercialApplyQueueItemsState = [pendingApplyResultsSelection];
        rememberCommercialApplyQueueCatalogItems(
          commercialApplyQueueItemsState
        );
        botMessage(
          renderActualJobPostSearchResults(commercialApplyQueueItemsState, "", {
            hideSummary: true,
            hideControls: true,
            includeOriginalCvAction: true,
            groupTitle: "Selected role",
            groupSubtitle: "Review fit, tailor the CV, or continue with the original CV.",
          }),
          humanComposeDelay("Selected role.", 600, 1100),
          function () {
            askApplyResultsSelectedRoleNextStep(
              pendingApplyResultsSelection,
              pendingApplyResultsSelection.key || ""
            );
          }
        );
        return true;
      }
      if (action.type === "compare_selected_role_cv") {
        clearPromptState();
        pendingApplyResultsSelection = normalizeCommercialApplyQueueItem(
          action.params && action.params.selectedRole,
          "Ready"
        );
        setCurrentApplicationContextFromQueueItem(pendingApplyResultsSelection);
        activePath = "apply_for_me";
        step = "apply_upload";
        commercialApplyQueueInitialized = true;
        commercialApplyQueueActivated = false;
        commercialApplyQueueDetailsMode = true;
        commercialApplyQueueActiveTab = "shortlist";
        commercialApplyQueueFilter = "all";
        commercialApplyQueueItemsState = [pendingApplyResultsSelection];
        rememberCommercialApplyQueueCatalogItems(
          commercialApplyQueueItemsState
        );
        if (!hasApplyChatCvAvailable()) {
          askForCvBeforeSelectedRoleApplication(
            pendingApplyResultsSelection,
            "compare"
          );
          return true;
        }
        botMessage(
          renderActualJobPostSearchResults(commercialApplyQueueItemsState, "", {
            hideSummary: true,
            hideControls: true,
            includeOriginalCvAction: true,
            groupTitle: "Selected role",
            groupSubtitle: "Selected for CV comparison and application review.",
          }),
          humanComposeDelay("Selected role for CV comparison.", 600, 1100),
          function () {
            if (hasPremiumMemberChatAccess()) {
              showApplyResultsComparisonThenChoice();
            } else {
              showApplyResultsComparisonThenConfirmCv();
            }
          }
        );
        return true;
      }
      if (action.type === "answer_role_question") {
        clearPromptState();
        var questionRole = normalizeCommercialApplyQueueItem(
          action.params && action.params.selectedRole,
          "Ready"
        );
        if (questionRole) {
          pendingApplyResultsSelection = questionRole;
          setCurrentApplicationContextFromQueueItem(questionRole);
          careerConversationMemory.currentSelectedRole = questionRole;
          rememberCommercialApplyQueueCatalogItems([questionRole]);
        }
        if (
          decision.relationshipToTask === "interrupts_task" ||
          decision.relationshipToTask === "pauses_task" ||
          (decision._internal &&
            decision._internal.careerDecision &&
            decision._internal.careerDecision.shouldPauseCurrentTask)
        ) {
          pauseActiveWorkflowForCareerConversation("role_question_pause");
        }
        botMessage(
          buildSelectedRoleQuestionReply(value, questionRole),
          humanComposeDelay("Answer selected role question.", 800, 1600),
          function () {
            focusComposer("Ask about this role or tell me to apply");
          }
        );
        return true;
      }
      if (action.type === "start_apply_execution") {
        clearPromptState();
        pendingApplyResultsSelection =
          pendingApplyResultsSelection ||
          normalizeCommercialApplyQueueItem(
            action.params && action.params.selectedRole,
            "Ready"
          );
        if (pendingApplyResultsSelection) {
          setCurrentApplicationContextFromQueueItem(
            pendingApplyResultsSelection
          );
          commercialApplyQueueItemsState = [pendingApplyResultsSelection];
          rememberCommercialApplyQueueCatalogItems(
            commercialApplyQueueItemsState
          );
          activePath = "apply_for_me";
          step = "apply_upload";
          commercialApplyQueueInitialized = true;
          commercialApplyQueueActivated = false;
          commercialApplyQueueDetailsMode = true;
          commercialApplyQueueActiveTab = "shortlist";
          commercialApplyQueueFilter = "all";
        }
        if (!hasApplyChatCvAvailable()) {
          askForCvBeforeSelectedRoleApplication(
            pendingApplyResultsSelection,
            "apply"
          );
          return true;
        }
        askApplyResultsSameCvThenStart();
        return true;
      }
      return false;
    }

    function handleConversationDecisionBeforePrompt(value) {
      var config = getEmilyDecisionEngineConfig();
      var decision;
      var validation;
      recordConversationAuditEvent("decision_engine_check", {
        enabled: !!config.enabled,
        shadowMode: !!config.shadowMode,
        text: cleanMessageText(value || "").slice(0, 220),
      });
      if (!config.enabled) {
        return false;
      }
      decision = buildConversationDecision(value);
      validation = validateConversationDecision(decision, value);
      decision.logging.validatorResult = validation.valid
        ? "pass"
        : validation.reason;
      logConversationDecision(
        value,
        decision,
        validation,
        config.shadowMode ? "shadow" : "live"
      );
      if (config.shadowMode) {
        return false;
      }
      if (!validation.valid) {
        botMessage(
          getContextualClarifyingRouteLine(),
          humanComposeDelay("Decision validation fallback.", 900, 1700),
          function () {
            focusComposer("Search, continue application, or career question?");
          }
        );
        return true;
      }
      if (
        decision.intent.confidence < config.confidenceThreshold ||
        decision.nextAction.type === "defer_to_prompt_handler"
      ) {
        return false;
      }
      if (!claimConversationTurn("decision_engine", {
        intent: cleanMessageText((decision.intent && decision.intent.type) || ""),
        action: cleanMessageText(
          (decision.nextAction && decision.nextAction.type) || ""
        ),
        confidence: Number(decision.intent.confidence || 0),
      })) {
        return true;
      }
      return executeConversationDecision(decision, value);
    }

    function askApplyResultsSelectedRoleNextStep(selected, key) {
      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(selected, "compare");
        return;
      }
      var selectedCtx = getEmilyVoiceContext(selected);
      var selectedSubject = escapeHtml(getEmilyRoleSubject(selectedCtx));
      var nextStepCopy = hasPremiumMemberChatAccess()
        ? pickVariant("selected_role_next_step_paying", [
            "I’ve got " +
              selectedSubject +
              " selected. Do you want me to apply with a tailored CV, strengthen the CV first, or use the original CV and move faster?",
            "For " +
              selectedSubject +
              ", we have three sensible routes: tailor then apply, improve the CV first, or continue with the original CV.",
            "This role is now in focus. Should I optimise the CV for " +
              selectedSubject +
              ", improve the weaker points first, or apply with the original version?",
          ])
        : pickVariant("selected_role_next_step_guest", [
            "Do you want to see how this role compares to your CV, or jump straight into the application?",
            "I can compare your CV against " +
              selectedSubject +
              " first, or we can move straight to the employer application.",
            "Before applying, do you want the fit check or should we go straight to the application?",
          ]);
      botMessage(
        nextStepCopy,
        humanComposeDelay(nextStepCopy, 900, 1800),
        function () {
          setPromptState(
            "apply_results_selected_next_step",
            {
              compare: function () {
                continueApplyResultsSelectedRole("compare");
              },
              application: function () {
                continueApplyResultsSelectedRole("application");
              },
              original: function () {
                continueApplyResultsSelectedRole("original");
              },
              yes: function () {
                continueApplyResultsSelectedRole(
                  hasPremiumMemberChatAccess() ? "application" : "compare"
                );
              },
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                if (/original|current cv|without tailor/.test(clean)) {
                  continueApplyResultsSelectedRole("original");
                  return;
                }
                if (
                  /jump|application|apply|straight|start|go ahead/.test(clean)
                ) {
                  continueApplyResultsSelectedRole("application");
                  return;
                }
                if (
                  /compare|match|fit|cv|how.*role|improve|tailor/.test(clean)
                ) {
                  continueApplyResultsSelectedRole("compare");
                  return;
                }
                focusComposer(
                  hasPremiumMemberChatAccess()
                    ? "Tailor, improve first, or use original CV"
                    : "Compare CV or jump to application"
                );
              },
            },
            hasPremiumMemberChatAccess()
              ? "Tailor, improve first, or use original CV?"
              : "Compare CV or jump to application?",
            { selected_role_key: (selected && selected.key) || key || "" }
          );
          botMessage(
            renderApplyResultsSelectedRoleActions({
              premium: hasPremiumMemberChatAccess(),
            }),
            0
          );
          focusComposer(
            hasPremiumMemberChatAccess()
              ? "Tailor, improve first, or use original CV"
              : "Compare CV or jump to application"
          );
        }
      );
    }

    function startApplyResultsSelectedRoleFlow(key, mode, options) {
      var opts = options || {};
      var found = findJobsWorkspaceItemByKey(key);
      var selected;
      if (
        !found &&
        opts.selectionElement &&
        opts.selectionElement.getAttribute
      ) {
        found = getApplyResultsItemFromSelectionElement(opts.selectionElement);
        if (found && found.title && found.title !== "Selected role") {
          rememberCommercialApplyQueueCatalogItems([found]);
        } else {
          found = null;
        }
      }
      if (!found) {
        botMessage(
          "I could not find that role in the current result set. Refresh the results and choose it again.",
          humanComposeDelay("Selected role missing.", 800, 1600),
          function () {
            focusComposer("Refresh the results and choose the role again");
          }
        );
        return;
      }
      selected = setCurrentApplicationContextFromQueueItem(found);
      selected = Object.assign({}, selected, {
        status: "Ready",
        cvMode: mode === "original" ? "original" : "tailored",
      });
      if (!selected.key) {
        selected.key = getCommercialApplyQueueItemKey(selected);
      }
      logEmilyJobOutcomeEvent(
        mode === "original" ? "job_original_cv" : "job_tailor_cv",
        selected,
        selected && selected.match,
        {
          resultKey: cleanMessageText(key || selected.key || ""),
          source: "selected_role_flow",
          outcome: "selected",
        }
      );
      pendingApplyResultsSelection = selected;
      activePath = "apply_for_me";
      step = "apply_upload";
      commercialApplyQueueInitialized = true;
      commercialApplyQueueActivated = false;
      commercialApplyQueueDetailsMode = true;
      commercialApplyQueueActiveTab = "shortlist";
      commercialApplyQueueFilter = "all";
      commercialApplyQueueItemsState = [selected];
      rememberCommercialApplyQueueCatalogItems([selected]);
      if (mode === "original") {
        applyCvReviewSkipped = true;
      } else {
        applyCvReviewSkipped = false;
      }
      userMessage(
        opts.echoLabel ||
          (mode === "original" ? "Original CV" : "Tailor CV")
      );
      if (!hasApplyChatCvAvailable()) {
        askForCvBeforeSelectedRoleApplication(
          selected,
          opts.directApplication || mode === "original" ? "apply" : "compare"
        );
        return;
      }
      botMessage(
        renderActualJobPostSearchResults(commercialApplyQueueItemsState, "", {
          hideSummary: true,
          hideControls: true,
          includeOriginalCvAction: true,
          groupTitle: "Selected role",
          groupSubtitle: "Review fit, tailor the CV, or continue with the original CV.",
        }),
        humanComposeDelay("Selected role.", 600, 1100),
        function () {
          if (opts.directApplication) {
            askApplyResultsSameCvThenStart();
            return;
          }
          askApplyResultsSelectedRoleNextStep(selected, key);
        }
      );
    }

