          location: button.getAttribute("data-sffc-apply-chat-location") || "",
          salary: button.getAttribute("data-sffc-apply-chat-salary") || "",
          seniority:
            button.getAttribute("data-sffc-apply-chat-seniority") || "",
          sector: button.getAttribute("data-sffc-apply-chat-sector") || "",
          description:
            button.getAttribute("data-sffc-apply-chat-description") || "",
          matchReason:
            button.getAttribute("data-sffc-apply-chat-match-reason") || "",
