    function looksEducationalEmailDomain(domain) {
      var clean = normalizeEmailDomain(domain);
      var universityWords = [
        "university",
        "universite",
        "universita",
        "universidad",
        "universidade",
        "universiteit",
        "universitat",
        "universitaet",
        "college",
        "school",
      ];
      if (getKnownUniversityDomains().indexOf(clean) !== -1) {
        return true;
      }
      if (
        /\.ac\.[a-z]{2}$/.test(clean) ||
        /\.edu$/.test(clean) ||
        /\.edu\.[a-z]{2}$/.test(clean)
      ) {
        return true;
      }
      return universityWords.some(function (word) {
        return clean.indexOf(word) !== -1;
      });
    }

    function classifyEmailCandidate(email) {
      var clean = normalizeEmailCandidate(email);
      var domain = clean.indexOf("@") !== -1 ? clean.split("@")[1] : "";
      var local = clean.indexOf("@") !== -1 ? clean.split("@")[0] : "";
      var disposableDomains = [
        "mailinator.com",
        "guerrillamail.com",
        "10minutemail.com",
        "temp-mail.org",
      ];
      var genericPrefixes = [
        "info",
        "hello",
        "contact",
        "support",
        "admin",
        "sales",
        "careers",
        "jobs",
        "recruitment",
        "recruiting",
        "hr",
        "people",
        "team",
        "office",
        "admissions",
      ];
      var category = "unknown";
      var confidence = 0;
      if (!looksLikeEmail(clean)) {
        return {
          email: clean,
          validSyntax: false,
          domain: domain,
          category: category,
          confidence: 0,
        };
      }
      if (disposableDomains.indexOf(domain) !== -1) {
        category = "temporary/disposable";
        confidence = 1;
      } else if (getCommonMailboxDomains().indexOf(domain) !== -1) {
        category = "personal";
        confidence = 1;
      } else if (looksEducationalEmailDomain(domain)) {
        category = "education";
        confidence = 0.9;
      } else {
        category = "business";
        confidence = 0.75;
      }
      return {
        email: clean,
        validSyntax: true,
        domain: domain,
        category: category,
        subtype:
          genericPrefixes.indexOf(local) !== -1
            ? "generic_mailbox"
            : category === "business"
            ? "custom_domain"
            : "individual",
        disposable: category === "temporary/disposable",
        confidence: confidence,
      };
    }

    function extractEmailCandidate(text) {
      var raw = String(text || "");
      raw = raw
        .replace(/\s+(?:at|\[at\]|\(at\)|@)\s+/gi, "@")
        .replace(/\s+(?:dot|\[dot\]|\(dot\)|\.)\s+/gi, ".")
        .replace(/\s*@\s*/g, "@")
        .replace(/\s*\.\s*/g, ".");
      var match = raw.match(
        /([A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,63})/i
      );
      var email = match && match[1] ? normalizeEmailCandidate(match[1]) : "";
      return looksLikeEmail(email) ? email : "";
    }

    function extractDomainCandidate(text) {
      var clean = cleanMessageText(text || "").toLowerCase();
      var match = clean.match(/\b([a-z0-9-]+(?:\.[a-z0-9-]+)+)\b/);
      return match ? match[1] : "";
    }

    function suggestMailboxDomain(domain) {
      var value = String(domain || "")
        .toLowerCase()
        .trim();
      var domains = getCommonMailboxDomains();
      var directMap = {
        "gnail.com": "gmail.com",
        "gmail.con": "gmail.com",
        "gmail.co": "gmail.com",
        "gmail.comm": "gmail.com",
        "googlemail.con": "googlemail.com",
        "hotmail.con": "hotmail.com",
        "hotmail.co": "hotmail.com",
        "hotnail.com": "hotmail.com",
        "outlook.con": "outlook.com",
        "outlook.co": "outlook.com",
        "outlok.com": "outlook.com",
        "outllok.com": "outlook.com",
        "live.con": "live.com",
        "yahoo.con": "yahoo.com",
        "yahoo.co": "yahoo.com",
        "yahoo.comm": "yahoo.com",
        "icloud.con": "icloud.com",
        "protonmail.con": "protonmail.com",
        "gmal.com": "gmail.com",
        "gmail.cm": "gmail.com",
        "gmail.om": "gmail.com",
      };
      var best = "";
      var bestDistance = 99;
      var i;

      if (!value) {
        return "";
      }
      if (domains.indexOf(value) !== -1) {
        return value;
      }
      if (directMap[value]) {
        return directMap[value];
      }

      domains.forEach(function (candidate) {
        var distance = levenshteinDistance(value, candidate);
        if (distance < bestDistance) {
          bestDistance = distance;
          best = candidate;
        }
      });

      if (best && bestDistance <= 2) {
        return best;
      }
      return value;
    }

    function analysePreferredEmail(text, fallbackLocalPart) {
      var rawEmail = extractEmailCandidate(text);
      var domainOnly = "";
      var localPart = "";
      var domainPart = "";
      var suggestedDomain = "";
      var confirmedEmail = "";
      if (!rawEmail && fallbackLocalPart) {
        domainOnly = extractDomainCandidate(text);
        if (domainOnly) {
          rawEmail = String(fallbackLocalPart) + "@" + domainOnly;
        }
      }
      rawEmail = normalizeEmailCandidate(rawEmail);
      if (
        !rawEmail ||
        !looksLikeEmail(rawEmail) ||
        rawEmail.indexOf("@") === -1
      ) {
        return null;
      }
      localPart = rawEmail.split("@")[0] || "";
      domainPart = rawEmail.split("@").slice(1).join("@");
      suggestedDomain = suggestMailboxDomain(domainPart);
      confirmedEmail = (localPart + "@" + suggestedDomain).toLowerCase();
      return {
        raw: rawEmail.toLowerCase(),
        confirmed: confirmedEmail,
        suggestion:
          confirmedEmail !== rawEmail.toLowerCase() ? confirmedEmail : "",
        localPart: localPart.toLowerCase(),
      };
    }

    function isReasonableFullName(text) {
      var clean = extractReasonableFullName(text || "");
      return (
        /^[A-Za-zÀ-ÿ'’.-]+(?:\s+[A-Za-zÀ-ÿ'’.-]+){1,5}$/.test(clean) &&
        !/@/.test(clean)
      );
    }

    function extractReasonableFullName(text) {
      var clean = cleanMessageText(text || "")
        .replace(/\bmy\s+(?=full name is|name is)\b/gi, " ")
        .replace(
          /\b(?:my name is|name is|full name is|full name:|use the name|use name|use|i am|i'm|im|it's|its|this is)\b/gi,
          " "
        )
        .replace(
          /\b(?:for this application|for the application|please|thanks|thank you)\b/gi,
          " "
        )
        .replace(/[^A-Za-zÀ-ÿ'’.\-\s]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      var words = clean.split(/\s+/).filter(Boolean);
      if (words.length > 6) {
        words = words.slice(0, 6);
      }
      clean = words.join(" ");
      return /^[A-Za-zÀ-ÿ'’.-]+(?:\s+[A-Za-zÀ-ÿ'’.-]+){1,5}$/.test(clean)
        ? clean
        : "";
    }

    function getApplyOnboardingCvContactSuggestion() {
      var rawText = String(capturedCvText || "");
      var text = cleanMessageText(rawText);
      var sections = text ? parseCvSectionsFromText(rawText) : [];
      var headerModel = text
        ? buildCvHeaderModel(rawText, sections, { allowRoleFallback: false })
        : null;
      var name = extractReasonableFullName(
        (headerModel && headerModel.name) || ""
      );
      var headerEmail =
        headerModel && headerModel.email
          ? normalizeEmailCandidate(headerModel.email)
          : "";
      var email = looksLikeEmail(headerEmail)
        ? headerEmail
        : findCvEmail(rawText);
      var emailInfo = email ? classifyEmailCandidate(email) : null;
      if (!name) {
        name = extractReasonableFullName(
          currentUserFullName || getConfig().currentUserFullName || ""
        );
      }
      return {
        name: name,
        email: emailInfo && emailInfo.validSyntax ? emailInfo.email : "",
        emailInfo: emailInfo,
      };
    }

    function hydrateApplyOnboardingDetailsFromCv() {
      var suggestion = getApplyOnboardingCvContactSuggestion();
      if (!cleanMessageText(applyOnboardingFullName || "") && suggestion.name) {
        applyOnboardingFullName = suggestion.name;
      }
      if (
        !cleanMessageText(applyOnboardingPreferredEmail || "") &&
        suggestion.email
      ) {
        applyOnboardingPreferredEmail = suggestion.email;
        applyOnboardingEmailSuggestion = "";
      }
      return suggestion;
    }

    function buildPrefilledApplySignupUrl() {
      var state = ensureApplyIntroState();
      var url;
      try {
        url = new URL(signupUrl, window.location.origin);
      } catch (err) {
        return signupUrl;
      }
      url.searchParams.set(
        "account_type",
        applySelectedPricingOption || "platform"
      );
      if (applyOnboardingFullName) {
        url.searchParams.set("full_name", applyOnboardingFullName);
      }
      if (applyOnboardingPreferredEmail) {
        url.searchParams.set("email", applyOnboardingPreferredEmail);
      }
      url.searchParams.set("service", "apply_for_me");
      url.searchParams.set("source", "apply_chat");
      if (roleTitle) {
        url.searchParams.set("role", roleTitle);
      }
      if (applyNeedsCoverLetter) {
        url.searchParams.set("cover_letter", applyNeedsCoverLetter);
      }
      if (applySelectedPricingOption) {
        url.searchParams.set("signup_path", applySelectedPricingOption);
      }
      if (state.supportMode) {
        url.searchParams.set("support_mode", state.supportMode);
      }
      if (state.applicationsPerWeek) {
        url.searchParams.set(
          "applications_per_week",
          state.applicationsPerWeek
        );
      }
      if (state.introsPerWeek) {
        url.searchParams.set("intros_per_week", state.introsPerWeek);
      }
      if (state.priority) {
        url.searchParams.set("priority_preference", state.priority);
      }
      if (state.lanePreference) {
        url.searchParams.set("lane_preference", state.lanePreference);
      }
      if (state.desiredRole) {
        url.searchParams.set("target_roles", state.desiredRole);
      }
      if (state.preferredSectors) {
        url.searchParams.set("target_sectors", state.preferredSectors);
      }
      if (state.preferredMarket) {
        url.searchParams.set("preferred_market", state.preferredMarket);
      }
      if (state.originalBrief) {
        url.searchParams.set("search_query", state.originalBrief);
      }
      return url.toString();
    }

