      function fetchApplicationWorkspaceSchema() {
        var config = getConfig();
        var formData = new FormData();
        formData.append("action", "sffc_crm_apply_chat_get_auto_submit_schema");
        formData.append(
          "nonce",
          config.autoSubmitSchemaNonce ||
            config.autoApplyContactNonce ||
            config.nonce ||
            ""
        );
        formData.append("post_id", postId || "");
        formData.append("jobs_post_id", jobsPostId || "");
        return window
          .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
            method: "POST",
            credentials: "same-origin",
            body: formData,
          })
          .then(parseAjaxJson)
          .then(function (payload) {
            if (!payload || !payload.success || !payload.data) {
              throw new Error(
                (payload && payload.data && payload.data.message) ||
                  "I could not load the employer application form."
              );
            }
            return payload.data;
          });
      }

