    function askJobSearchDeliveryFrequency() {
      var frequencyPrompt = getJobSearchFrequencyPrompt();
      var frequencyIntro =
        monetizationState.emailConfirmed && !hasPremiumMemberChatAccess()
          ? buildJobSearchContinuationUpgradeMessage("email_confirmed")
          : "";
      var frequencyPlaceholder = isArabicChat()
        ? "يومي، أسبوعي، أو فوراً"
        : "Daily, weekly, or as soon as a match comes across";
      var frequencyClarify = getJobSearchDeliveryFrequencyClarifyLine();
      if (
        getNormalizedPremiumDeliveryFrequency(jobSearchDeliveryFrequency || "")
      ) {
        if (hasPremiumMemberChatAccess()) {
          beginJobSearchContinuityConversation("membership_complete");
          return;
        }
        askJobSearchAccountQuestion();
        return;
      }
      botSequenceForCurrentTurn(
        [
          frequencyIntro
            ? {
                html: frequencyIntro,
                delay: humanComposeDelay(
                  cleanMessageText(frequencyIntro),
                  1100,
                  2000
                ),
              }
            : null,
          {
            html: frequencyPrompt,
            delay: humanComposeDelay(frequencyPrompt, 1000, 1800),
            pause: frequencyIntro
              ? humanReadDelay(cleanMessageText(frequencyIntro), 260)
              : 0,
          },
        ].filter(Boolean),
        function () {
          setPromptState(
            "job_search_delivery_frequency",
            {
              other: function (value) {
                var detected = detectJobSearchDeliveryFrequency(value);
                if (!detected) {
                  showPromptRecoveryMessage(
                    "job_search_delivery_frequency",
                    frequencyClarify,
                    frequencyPlaceholder,
                    value
                  );
                  return;
                }
                clearPromptState();
                echoPromptChoice(value);
                jobSearchDeliveryFrequency = detected;
                queueApplyChatMemoryPersist();
                if (hasPremiumMemberChatAccess()) {
                  window.setTimeout(function () {
                    beginJobSearchContinuityConversation("membership_complete");
                  }, randomBetween(220, 420));
                  return;
                }
                window.setTimeout(
                  askJobSearchAccountQuestion,
                  randomBetween(220, 420)
                );
              },
            },
            frequencyPlaceholder
          );
          focusComposer(frequencyPlaceholder);
        }
      );
    }

