                          if (isLikelyClarificationShorthand(replyValue)) {
                            showPromptRecoveryMessage(
                              "job_search_other_roles_text",
                              getJobSearchPromptClarifier("other_roles"),
                              isArabicChat()
                                ? "اذكري لي الأدوار الأخرى"
                                : "Tell me the other roles",
                              replyValue
                            );
                            return;
                          }
                          var replySignals =
                            extractJobSearchPreferenceSignals(replyValue);
