    function analyzeCv(cvText) {
      var isProfileReview = activePath === "review_profile";
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: isProfileReview
          ? "Reading your profile against the role"
          : "Reading your CV against the role",
        note: isProfileReview
          ? "I am scanning the CV for the strongest evidence, unclear proof, and profile changes to make before applying."
          : "I am scanning the CV for the strongest evidence, the role-specific gaps, and anything that should be verified before I make changes.",
        cvStatus: "Review in progress",
        coverStatus:
          activePath === "apply_for_me"
            ? "Waiting for Career Assessment"
            : "Not in scope yet",
      });
      fetchCvAnalysis(cvText)
        .then(function (analysis) {
          pendingAnalysis = analysis || {};
          analysisReady = true;
          window.setTimeout(
            function () {
              showAnalysis(pendingAnalysis);
            },
            isReviewOnlyLauncher && isProfileReview
              ? 250
              : Math.max(
                  humanReadDelay(cvText, 900),
                  reviewMinimumUntil - Date.now()
                )
          );
        })
        .catch(function (error) {
          botMessage(
            escapeHtml(
              error.message ||
                "I could not read that CV. Try uploading a PDF or DOCX with selectable text."
            )
          );
          uploadButton.hidden = false;
        });
    }

