    function openChat() {
      var launchContext = pendingLaunchContext;
      var shouldOpenFilePicker = pendingLaunchOpenFilePicker;
      primeAudio();
      portalChatRoot();
      if (isMobileWorkspaceView()) {
        suppressAutoScrollUntil = Date.now() + 500;
      }
      desk.hidden = false;
      desk.setAttribute("aria-hidden", "false");
      root.classList.add("is-chat-open");
      document.documentElement.classList.add("sffc-crm-apply-chat-lock");
      document.body.classList.add("sffc-crm-apply-chat-lock");
      bootApplyChatSession().then(function () {
        startApplyChatReplyPolling();
        startApplyChatHeartbeat();
      });
      if (resetChatOnNextOpen) {
        resetChat();
        resetChatOnNextOpen = false;
      } else {
        renderWorkspace();
        if (!isMobileWorkspaceView()) {
          focusComposer(getLocalizedCurrentPromptPlaceholder());
        } else {
          input.disabled = false;
          input.placeholder = getLocalizedCurrentPromptPlaceholder();
        }
      }
      if (isMobileWorkspaceView()) {
        window.requestAnimationFrame(function () {
          if (messages) {
            messages.scrollTop = 0;
          }
          window.setTimeout(function () {
            if (messages) {
              messages.scrollTop = 0;
            }
            suppressAutoScrollUntil = 0;
          }, 160);
        });
      } else {
        suppressAutoScrollUntil = 0;
      }
      pendingLaunchContext = launchContext;
      pendingLaunchOpenFilePicker = shouldOpenFilePicker;
    }

    function closeChat(forceClose) {
      if (!forceClose) {
        showEndChatPrompt();
        return;
      }
      clearQueuedChatUiWork();
      hidePremiumMemberOnboarding();
      desk.hidden = true;
      desk.setAttribute("aria-hidden", "true");
      root.classList.remove("is-chat-open");
      document.documentElement.classList.remove("sffc-crm-apply-chat-lock");
      document.body.classList.remove("sffc-crm-apply-chat-lock");
      hideEndChatPrompt();
      closeChatCvPreviewModal();
      closeApplicationQueueRoleModal();
      closeDeskMenu();
      closeDeskSearch();
      stopApplyChatReplyPolling();
      stopApplyChatHeartbeat();
      restoreChatRoot();
    }

    function portalChatRoot() {
      if (!homeLauncherForm || isRootPortaled || !document.body) {
        return;
      }
      portalOriginalParent = portalOriginalParent || root.parentNode;
      portalOriginalNextSibling = portalOriginalNextSibling || root.nextSibling;
      if (root.parentNode !== document.body) {
        document.body.appendChild(root);
      }
      isRootPortaled = true;
    }

    function restoreChatRoot() {
      if (!isRootPortaled || !portalOriginalParent) {
        return;
      }
      if (
        portalOriginalNextSibling &&
        portalOriginalNextSibling.parentNode === portalOriginalParent
      ) {
        portalOriginalParent.insertBefore(root, portalOriginalNextSibling);
      } else {
        portalOriginalParent.appendChild(root);
      }
      isRootPortaled = false;
    }

    function dismissChatPreservingState() {
      resetChatOnNextOpen = false;
      closeChat(true);
    }

    function endChatAndReset() {
      resetChatOnNextOpen = true;
      closeChat(true);
    }

