    root
      .querySelectorAll("[data-sffc-apply-chat-open]")
      .forEach(function (button) {
        button.addEventListener("click", openChat);
      });

    root.addEventListener("sffc:apply-chat-open", function () {
      openChat();
    });

    root.addEventListener("sffc:apply-chat-launch-search", function (event) {
      var detail = (event && event.detail) || {};
      var role = cleanMessageText(detail.role || "");
      var seniority = cleanMessageText(detail.seniority || "");
      var location = cleanMessageText(detail.location || "");
      var sector = cleanMessageText(
        detail.specialisation || detail.specialization || detail.sector || ""
      );
      if (/^all\b/i.test(seniority)) {
        seniority = "";
      }
      var roleTarget = [seniority, role]
        .filter(Boolean)
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
      var query = cleanMessageText(detail.query || "");

      if (!query) {
        query = [roleTarget, sector].filter(Boolean).join(" ");
        if (location) {
          query += (query ? " jobs in " : "Jobs in ") + location;
        }
      }

      pendingLaunchContext = {
        entryRoute: "landing_filter_search",
        query: query || "finance jobs",
        roleTarget: roleTarget || role,
        location: location,
        sector: sector,
        seniority: seniority,
        filters: {
          role: role,
          seniority: seniority,
          location: location,
          specialisation: sector,
        },
      };
      pendingLaunchOpenFilePicker = false;
      resetChatOnNextOpen = true;
      openChat();
    });

    root.addEventListener("sffc:apply-chat-close", function () {
      dismissChatPreservingState();
    });

    if (reviewMode === "profile") {
      pendingLaunchContext = { profileReviewStart: true };
      resetChatOnNextOpen = true;
      window.setTimeout(openChat, 120);
    }

    if (reviewMode === "recruiter_outreach") {
      pendingLaunchContext = { recruiterOutreachStart: true };
      resetChatOnNextOpen = true;
      if (!isRecruiterOutreachMini) {
        window.setTimeout(openChat, 120);
      }
    }

    root
      .querySelectorAll("[data-sffc-apply-chat-close]")
      .forEach(function (button) {
        button.addEventListener("click", function (event) {
          event.preventDefault();
          dismissChatPreservingState();
        });
      });

    if (deskSearchToggle) {
      deskSearchToggle.addEventListener("click", function () {
        if (deskSearch && !deskSearch.hidden) {
          closeDeskSearch();
          focusComposer(getLocalizedCurrentPromptPlaceholder());
          return;
        }
        openDeskSearch();
      });
    }

    if (deskSearchInput) {
      deskSearchInput.addEventListener("input", function () {
        runDeskSearch(deskSearchInput.value);
      });

      deskSearchInput.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
          event.preventDefault();
          if (searchMatchNodes.length) {
            focusDeskSearchMatch(activeSearchMatchIndex + 1);
          }
          return;
        }
        if (event.key === "Escape") {
          event.preventDefault();
          closeDeskSearch();
          focusComposer(getLocalizedCurrentPromptPlaceholder());
        }
      });
    }

    if (deskMenuToggle) {
      deskMenuToggle.addEventListener("click", function (event) {
        event.preventDefault();
        closeDeskSearch();
        closeDeskLanguageMenu();
        if (!deskMenu) {
          return;
        }
        deskMenu.hidden = !deskMenu.hidden;
        deskMenuToggle.setAttribute(
          "aria-expanded",
          deskMenu.hidden ? "false" : "true"
        );
      });
    }

    if (deskLanguageToggle) {
      deskLanguageToggle.addEventListener("click", function (event) {
        event.preventDefault();
        closeDeskSearch();
        closeDeskMenu();
        if (!deskLanguageMenu) {
          return;
        }
        deskLanguageMenu.hidden = !deskLanguageMenu.hidden;
        deskLanguageToggle.setAttribute(
          "aria-expanded",
          deskLanguageMenu.hidden ? "false" : "true"
        );
      });
    }

    if (deskLanguageMenu) {
      deskLanguageMenu
        .querySelectorAll("[data-sffc-apply-chat-language-option]")
        .forEach(function (button) {
          button.addEventListener("click", function (event) {
            var selectedLanguage =
              button.getAttribute("data-sffc-apply-chat-language-option") ||
              "en";
            event.preventDefault();
            setChatLanguage(selectedLanguage);
            closeDeskLanguageMenu();
            focusComposer(getLocalizedCurrentPromptPlaceholder());
          });
        });
      updateDeskLanguageControl();
    }

