    if (homeLauncherForm) {
      homeLauncherForm.addEventListener("submit", function (event) {
        var query;
        event.preventDefault();
        query = cleanMessageText(
          homeLauncherQuery ? homeLauncherQuery.value : ""
        );
        if (!query) {
          if (homeLauncherQuery) {
            homeLauncherQuery.focus();
          }
          return;
        }
        pendingLaunchContext = buildActiveLauncherContext(query);
        openChat();
      });
    }

    if (homeLauncherQuery) {
      homeLauncherQuery.addEventListener("input", function () {
        syncHomeLauncherTypingState();
        renderHomeLauncherSuggestions(homeLauncherQuery.value);
      });

      homeLauncherQuery.addEventListener("focus", function () {
        syncHomeLauncherTypingState();
        if (cleanMessageText(homeLauncherQuery.value || "")) {
          renderHomeLauncherSuggestions(homeLauncherQuery.value);
        }
      });

      homeLauncherQuery.addEventListener("blur", function () {
        syncHomeLauncherTypingState();
      });

      homeLauncherQuery.addEventListener("keydown", function (event) {
        if (!homeLauncherSuggestionItems.length) {
          return;
        }
        if (event.key === "ArrowDown") {
          event.preventDefault();
          homeLauncherSuggestionIndex = Math.min(
            homeLauncherSuggestionIndex + 1,
            homeLauncherSuggestionItems.length - 1
          );
          updateHomeLauncherSuggestionHighlight();
          return;
        }
        if (event.key === "ArrowUp") {
          event.preventDefault();
          homeLauncherSuggestionIndex = Math.max(
            homeLauncherSuggestionIndex - 1,
            0
          );
          updateHomeLauncherSuggestionHighlight();
          return;
        }
        if (
          event.key === "Enter" &&
          homeLauncherSuggestionIndex >= 0 &&
          homeLauncherSuggestionItems[homeLauncherSuggestionIndex]
        ) {
          event.preventDefault();
          applyHomeLauncherSuggestion(
            homeLauncherSuggestionItems[homeLauncherSuggestionIndex],
            { launch: true }
          );
          return;
        }
        if (event.key === "Escape") {
          closeHomeLauncherSuggestions();
        }
      });
      startHomeLauncherTyping();
    }

