    function setApplyResultsPreviewReady(
      preview,
      screenshotUrl,
      finalUrl,
      pageTitle
    ) {
      if (!preview || !screenshotUrl) {
        return;
      }
      preview.classList.remove("is-loading", "is-error");
      preview.hidden = false;
      preview.setAttribute("data-sffc-preview-state", "ready");
      preview.innerHTML =
        '<a class="sffc-crm-apply-results__review-image-link" href="' +
        escapeHtml(
          finalUrl ||
            preview.getAttribute("data-sffc-apply-results-preview-url") ||
            ""
        ) +
        '" target="_blank" rel="noopener noreferrer">' +
        '<img src="' +
        escapeHtml(screenshotUrl) +
        '" alt="' +
        escapeHtml(pageTitle || "Employer page preview") +
        '">' +
        "</a>";
    }

    function fetchApplyResultsPreviewTaskStatus(taskUuid) {
      var config = getConfig();
      var formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_application_task_status");
      formData.append(
        "nonce",
        config.applicationTaskNonce ||
          config.autoSubmitSchemaNonce ||
          config.nonce ||
          ""
      );
      formData.append("task_uuid", cleanMessageText(taskUuid || ""));
      formData.append("session_token", ensureApplyChatSessionToken());
      return window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          if (!payload || !payload.success) {
            throw new Error(
              (payload && payload.data && payload.data.message) ||
                "I could not check this employer preview."
            );
          }
          return payload.data || {};
        });
    }

    function pollApplyResultsApplicationPreview(preview, taskUuid, attempt) {
      var currentAttempt = Number(attempt || 0);
      if (
        !preview ||
        preview.getAttribute("data-sffc-preview-state") !== "loading"
      ) {
        return;
      }
      if (!taskUuid || currentAttempt > 45) {
        preview.removeAttribute("data-sffc-preview-state");
        setApplyResultsPreviewError(
          preview,
          "The employer page preview took too long. Open the form in a new tab to review it."
        );
        return;
      }
      window.setTimeout(
        function () {
          fetchApplyResultsPreviewTaskStatus(taskUuid)
            .then(function (data) {
              var status = cleanMessageText((data && data.status) || "");
              var screenshotUrl = cleanMessageText(
                (data && data.screenshot_url) || ""
              );
              var resultPayload =
                data && data.result_payload ? data.result_payload : {};
              var finalUrl = cleanMessageText(
                (data && data.final_url) ||
                  (resultPayload && resultPayload.final_url) ||
                  preview.getAttribute("data-sffc-apply-results-preview-url") ||
                  ""
              );
              var pageTitle = cleanMessageText(
                (resultPayload && resultPayload.page_title) ||
                  preview.getAttribute(
                    "data-sffc-apply-results-preview-title"
                  ) ||
                  "Employer page preview"
              );
              if (screenshotUrl) {
                setApplyResultsPreviewReady(
                  preview,
                  screenshotUrl,
                  finalUrl,
                  pageTitle
                );
                return;
              }
              if (status === "queued" || status === "processing") {
                preview.innerHTML = renderApplyResultsPreviewLoader(
                  isArabicChat()
                    ? "جار تجهيز معاينة صفحة جهة العمل..."
                    : "Preparing employer page preview..."
                );
                pollApplyResultsApplicationPreview(
                  preview,
                  taskUuid,
                  currentAttempt + 1
                );
                return;
              }
              preview.removeAttribute("data-sffc-preview-state");
              setApplyResultsPreviewError(
                preview,
                (data && data.last_error) ||
                  "I could not generate a screenshot preview for this employer page."
              );
            })
            .catch(function (error) {
              preview.removeAttribute("data-sffc-preview-state");
              setApplyResultsPreviewError(
                preview,
                (error && error.message) ||
                  "I could not generate a screenshot preview for this employer page."
              );
            });
        },
        currentAttempt === 0 ? 900 : 2000
      );
    }

    function requestApplyResultsApplicationPreview(preview) {
      var config = getConfig();
      var previewUrl = cleanMessageText(
        preview
          ? preview.getAttribute("data-sffc-apply-results-preview-url") || ""
          : ""
      );
      var provider = cleanMessageText(
        preview
          ? preview.getAttribute("data-sffc-apply-results-preview-provider") ||
              ""
          : ""
      );
      var taskUuid = cleanMessageText(
        preview ? preview.getAttribute("data-sffc-preview-task-uuid") || "" : ""
      );
      var formData;
      if (
        !preview ||
        preview.getAttribute("data-sffc-preview-state") === "loading" ||
        preview.getAttribute("data-sffc-preview-state") === "ready"
      ) {
        return;
      }
      if (taskUuid) {
        preview.hidden = false;
        preview.classList.add("is-loading");
        preview.classList.remove("is-error");
        preview.setAttribute("data-sffc-preview-state", "loading");
        pollApplyResultsApplicationPreview(preview, taskUuid, 0);
        return;
      }
      if (!previewUrl || !/^https?:\/\//i.test(previewUrl)) {
        setApplyResultsPreviewError(
          preview,
          "Open this employer form in a new tab to review it."
        );
        return;
      }
      if (!config.ajaxUrl || !config.applicationPreviewQueueNonce) {
        setApplyResultsPreviewError(
          preview,
          "The employer page screenshot preview is not configured yet."
        );
        return;
      }
      preview.hidden = false;
      preview.classList.add("is-loading");
      preview.classList.remove("is-error");
      preview.setAttribute("data-sffc-preview-state", "loading");
      preview.innerHTML = renderApplyResultsPreviewLoader(
          isArabicChat()
            ? "جار تجهيز معاينة صفحة جهة العمل..."
            : "Preparing employer page preview..."
      );
      formData = new FormData();
      formData.append(
        "action",
        "sffc_crm_apply_chat_queue_application_preview"
      );
      formData.append("nonce", config.applicationPreviewQueueNonce || "");
      formData.append("application_url", previewUrl);
      formData.append("provider", provider);
      formData.append("session_token", ensureApplyChatSessionToken());
      formData.append(
        "role_title",
        preview.getAttribute("data-sffc-apply-results-preview-title") || ""
      );
      formData.append(
        "company_name",
        preview.getAttribute("data-sffc-apply-results-preview-company") || ""
      );
      formData.append(
        "role_url",
        preview.getAttribute("data-sffc-apply-results-preview-role-url") ||
          previewUrl
      );
      formData.append(
        "jobs_post_id",
        preview.getAttribute("data-sffc-apply-results-preview-jobs-post-id") ||
          ""
      );
      formData.append(
        "crm_post_id",
        preview.getAttribute("data-sffc-apply-results-preview-crm-post-id") ||
          ""
      );
      formData.append("page_url", window.location.href || "");
      window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          var data = payload && payload.data ? payload.data : {};
          var queuedTaskUuid = cleanMessageText(data.task_uuid || "");
          if (!queuedTaskUuid) {
            throw new Error(
              "The preview worker queue did not return a task ID."
            );
          }
          preview.setAttribute("data-sffc-preview-task-uuid", queuedTaskUuid);
          pollApplyResultsApplicationPreview(preview, queuedTaskUuid, 0);
        })
        .catch(function (error) {
          preview.removeAttribute("data-sffc-preview-state");
          setApplyResultsPreviewError(
            preview,
            (error && error.message) ||
              "I could not generate a screenshot preview for this employer page."
          );
        });
    }

    function setApplyResultsRemoteBrowserError(remoteBrowser, message) {
      var viewport = remoteBrowser
        ? remoteBrowser.querySelector("[data-sffc-remote-browser-viewport]")
        : null;
      var status = remoteBrowser
        ? remoteBrowser.querySelector("[data-sffc-remote-browser-status]")
        : null;
      if (!remoteBrowser || !viewport) {
        return;
      }
      remoteBrowser.classList.remove("is-loading", "is-ready");
      remoteBrowser.classList.add("is-error");
      remoteBrowser.setAttribute("data-sffc-remote-browser-state", "error");
      viewport.innerHTML =
        '<div class="sffc-crm-apply-results__remote-browser-error">' +
        escapeHtml(
          message ||
            uiText(
              "I could not start the secure browser. I’ll show the preview fallback instead.",
              "تعذر تشغيل المتصفح الآمن. سأعرض المعاينة الاحتياطية بدلاً من ذلك."
            )
        ) +
        "</div>";
      if (status) {
        status.textContent = uiText(
          "Preview fallback is available below.",
          "المعاينة الاحتياطية متاحة بالأسفل."
        );
      }
    }

    function getApplyResultsRemoteBrowserControlCopy(control) {
      var cleanControl = cleanMessageText(control || "user_control");
      if (cleanControl === "emily_control") {
        return uiText(
          "Emily is driving this step. You can take control any time. Final submission still needs explicit confirmation.",
          "إميلي تتحكم في هذه الخطوة. يمكنك استعادة التحكم في أي وقت. الإرسال النهائي يحتاج تأكيداً صريحاً."
        );
      }
      if (cleanControl === "waiting_for_user") {
        return uiText(
          "Emily needs you here: complete the verification, login, CAPTCHA, or employer-specific answer before we continue.",
          "إميلي تحتاجك هنا: أكمل التحقق أو تسجيل الدخول أو الكابتشا أو الإجابة الخاصة بصاحب العمل قبل المتابعة."
        );
      }
      if (cleanControl === "read_only") {
        return uiText(
          "Read-only while Emily checks the page. Take control if you need to type or choose an answer.",
          "وضع القراءة فقط أثناء فحص إميلي للصفحة. استعد التحكم إذا احتجت للكتابة أو اختيار إجابة."
        );
      }
      return uiText(
        "You are in control. Emily will not submit anything without explicit confirmation.",
        "أنت المتحكم. لن ترسل إميلي أي شيء بدون تأكيد صريح."
      );
    }

    function setApplyResultsRemoteBrowserControlState(remoteBrowser, control) {
      var cleanControl = cleanMessageText(control || "user_control");
      var status = remoteBrowser
        ? remoteBrowser.querySelector("[data-sffc-remote-browser-status]")
        : null;
      var controls = remoteBrowser
        ? remoteBrowser.querySelectorAll("[data-sffc-remote-browser-control]")
        : [];
      if (!remoteBrowser) {
        return;
      }
      remoteBrowser.setAttribute(
        "data-sffc-remote-browser-control",
        cleanControl
      );
      Array.prototype.forEach.call(controls, function (button) {
        var buttonControl = cleanMessageText(
          button.getAttribute("data-sffc-remote-browser-control") || ""
        );
        var isActive = buttonControl === cleanControl;
        button.classList.toggle("is-active", isActive);
        button.setAttribute("aria-pressed", isActive ? "true" : "false");
      });
      if (status) {
        status.textContent = getApplyResultsRemoteBrowserControlCopy(cleanControl);
      }
    }

    function setApplyResultsRemoteBrowserReady(remoteBrowser, session) {
      var viewport = remoteBrowser
        ? remoteBrowser.querySelector("[data-sffc-remote-browser-viewport]")
        : null;
      var status = remoteBrowser
        ? remoteBrowser.querySelector("[data-sffc-remote-browser-status]")
        : null;
      var streamUrl = cleanMessageText(session && session.streamUrl);
      if (!remoteBrowser || !viewport || !streamUrl) {
        return;
      }
      remoteBrowser.classList.remove("is-loading", "is-error");
      remoteBrowser.classList.add("is-ready");
      remoteBrowser.setAttribute("data-sffc-remote-browser-state", "ready");
      remoteBrowser.setAttribute(
        "data-sffc-remote-browser-session-id",
        cleanMessageText(session.sessionId || "")
      );
      setApplyResultsRemoteBrowserControlState(
        remoteBrowser,
        cleanMessageText(session.control || "user_control")
      );
      viewport.innerHTML =
        '<iframe class="sffc-crm-apply-results__remote-browser-frame" title="' +
        escapeHtml(
          uiText("Secure employer browser", "متصفح جهة العمل الآمن")
        ) +
        '" src="' +
        escapeHtml(streamUrl) +
        '" loading="eager" allow="clipboard-read; clipboard-write"></iframe>';
      if (status) {
        status.textContent = getApplyResultsRemoteBrowserControlCopy(
          cleanMessageText(session.control || "user_control")
        );
      }
    }

    function requestApplyResultsRemoteBrowser(remoteBrowser) {
      var config = getConfig();
      var url = cleanMessageText(
        remoteBrowser
          ? remoteBrowser.getAttribute("data-sffc-remote-browser-url") || ""
          : ""
      );
      var provider = cleanMessageText(
        remoteBrowser
          ? remoteBrowser.getAttribute("data-sffc-remote-browser-provider") ||
              ""
          : ""
      );
      var formData;
      if (
        !remoteBrowser ||
        remoteBrowser.getAttribute("data-sffc-remote-browser-state") ===
          "loading" ||
        remoteBrowser.getAttribute("data-sffc-remote-browser-state") ===
          "ready"
      ) {
        return;
      }
      if (!config.remoteBrowserEnabled || !config.remoteBrowserNonce) {
        setApplyResultsRemoteBrowserError(
          remoteBrowser,
          uiText(
            "The secure browser is not configured yet.",
            "لم يتم إعداد المتصفح الآمن بعد."
          )
        );
        return;
      }
      if (!url || !/^https?:\/\//i.test(url)) {
        setApplyResultsRemoteBrowserError(
          remoteBrowser,
          uiText(
            "I need a valid employer page before I can open the secure browser.",
            "أحتاج إلى صفحة جهة عمل صالحة قبل فتح المتصفح الآمن."
          )
        );
        return;
      }
      remoteBrowser.hidden = false;
      remoteBrowser.classList.add("is-loading");
      remoteBrowser.classList.remove("is-error", "is-ready");
      remoteBrowser.setAttribute("data-sffc-remote-browser-state", "loading");
      formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_remote_browser_create");
      formData.append("nonce", config.remoteBrowserNonce || "");
      formData.append("application_url", url);
      formData.append("provider", provider);
      formData.append("session_token", ensureApplyChatSessionToken());
      formData.append(
        "role_title",
        remoteBrowser.getAttribute("data-sffc-remote-browser-title") || ""
      );
      formData.append(
        "company_name",
        remoteBrowser.getAttribute("data-sffc-remote-browser-company") || ""
      );
      formData.append(
        "role_url",
        remoteBrowser.getAttribute("data-sffc-remote-browser-role-url") || url
      );
      formData.append(
        "jobs_post_id",
        remoteBrowser.getAttribute("data-sffc-remote-browser-jobs-post-id") ||
          ""
      );
      formData.append(
        "crm_post_id",
        remoteBrowser.getAttribute("data-sffc-remote-browser-crm-post-id") ||
          ""
      );
      formData.append("page_url", window.location.href || "");
      window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          var data = payload && payload.data ? payload.data : {};
          if (!payload || !payload.success || !data.session) {
            throw new Error(
              (data && data.message) ||
                uiText(
                  "The secure browser did not return a session.",
                  "لم يرجع المتصفح الآمن جلسة."
                )
            );
          }
          setApplyResultsRemoteBrowserReady(remoteBrowser, data.session);
        })
        .catch(function (error) {
          var panel = remoteBrowser.closest(
            "[data-sffc-apply-results-review-panel]"
          );
          var preview = panel
            ? panel.querySelector("[data-sffc-apply-results-preview-url]")
            : null;
          setApplyResultsRemoteBrowserError(
            remoteBrowser,
            (error && error.message) ||
              uiText(
                "I could not start the secure browser.",
                "تعذر تشغيل المتصفح الآمن."
              )
          );
          if (preview) {
            preview.hidden = false;
            requestApplyResultsApplicationPreview(preview);
          }
        });
    }

    function closeApplyResultsRemoteBrowser(remoteBrowser) {
      var config = getConfig();
      var sessionId = cleanMessageText(
        remoteBrowser
          ? remoteBrowser.getAttribute(
              "data-sffc-remote-browser-session-id"
            ) || ""
          : ""
      );
      var formData;
      if (!remoteBrowser) {
        return;
      }
      remoteBrowser.hidden = true;
      if (!sessionId || !config.remoteBrowserNonce || !config.ajaxUrl) {
        return;
      }
      formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_remote_browser_close");
      formData.append("nonce", config.remoteBrowserNonce || "");
      formData.append("session_id", sessionId);
      formData.append("session_token", ensureApplyChatSessionToken());
      window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .catch(function () {});
    }

    function requestApplyResultsRemoteBrowserControl(remoteBrowser, control) {
      var config = getConfig();
      var sessionId = cleanMessageText(
        remoteBrowser
          ? remoteBrowser.getAttribute(
              "data-sffc-remote-browser-session-id"
            ) || ""
          : ""
      );
      var cleanControl = cleanMessageText(control || "");
      var formData;
      if (!remoteBrowser || !sessionId || !cleanControl) {
        return;
      }
      if (!config.remoteBrowserNonce || !config.ajaxUrl) {
        setApplyResultsRemoteBrowserError(
          remoteBrowser,
          uiText(
            "The secure browser controls are not configured yet.",
            "لم يتم إعداد عناصر التحكم في المتصفح الآمن بعد."
          )
        );
        return;
      }
      remoteBrowser.classList.add("is-updating-control");
      formData = new FormData();
      formData.append("action", "sffc_crm_apply_chat_remote_browser_control");
      formData.append("nonce", config.remoteBrowserNonce || "");
      formData.append("session_id", sessionId);
      formData.append("session_token", ensureApplyChatSessionToken());
      formData.append("control", cleanControl);
      window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          var data = payload && payload.data ? payload.data : {};
          if (!payload || !payload.success || !data.session) {
            throw new Error(
              (data && data.message) ||
                uiText(
                  "I could not update browser control.",
                  "تعذر تحديث التحكم في المتصفح."
                )
            );
          }
          setApplyResultsRemoteBrowserControlState(
            remoteBrowser,
            cleanMessageText(data.session.control || cleanControl)
          );
        })
        .catch(function (error) {
          var status = remoteBrowser.querySelector(
            "[data-sffc-remote-browser-status]"
          );
          if (status) {
            status.textContent =
              (error && error.message) ||
              uiText(
                "I could not update browser control.",
                "تعذر تحديث التحكم في المتصفح."
              );
          }
        })
        .finally(function () {
          remoteBrowser.classList.remove("is-updating-control");
        });
    }

    function showApplyResultsIframePreviewFallback(panel, preview, frame) {
      var frameWrap = frame
        ? frame.closest(".sffc-crm-apply-results__review-frame-wrap")
        : null;
      var remoteBrowser = panel
        ? panel.querySelector("[data-sffc-apply-results-remote-browser]")
        : null;
      if (!preview) {
        return;
      }
      if (panel) {
        panel.setAttribute(
          "data-sffc-apply-results-review-current-mode",
          remoteBrowser ? "remote_browser" : "static_preview"
        );
      }
      if (frameWrap) {
        frameWrap.hidden = true;
      }
      if (remoteBrowser) {
        remoteBrowser.hidden = false;
        requestApplyResultsRemoteBrowser(remoteBrowser);
        return;
      }
      preview.hidden = false;
      requestApplyResultsApplicationPreview(preview);
    }

    function markApplyResultsReviewFrameState(panel, frame, state, reason) {
      var cleanState = cleanMessageText(state || "");
      var cleanReason = cleanMessageText(reason || "");
      if (frame && cleanState) {
        frame.setAttribute("data-sffc-review-frame-state", cleanState);
      }
      if (panel && cleanState) {
        panel.setAttribute("data-sffc-apply-results-iframe-state", cleanState);
      }
      if (panel && cleanReason) {
        panel.setAttribute("data-sffc-apply-results-iframe-reason", cleanReason);
      }
    }

    function shouldProbeApplyResultsIframe(panel) {
      var mode = cleanMessageText(
        panel ? panel.getAttribute("data-sffc-apply-results-review-mode") : ""
      );
      return !mode || mode === "iframe_embed";
    }

    function startApplyResultsIframeProbe(panel, frame, preview, timeoutMs) {
      if (!frame || frame.getAttribute("src")) {
        return;
      }
      if (!frame.getAttribute("data-sffc-review-frame-listeners")) {
        frame.setAttribute("data-sffc-review-frame-listeners", "1");
        frame.addEventListener(
          "load",
          function () {
            markApplyResultsReviewFrameState(
              panel,
              frame,
              "loaded",
              "iframe_load_event"
            );
          },
          { once: true }
        );
        frame.addEventListener(
          "error",
          function () {
            markApplyResultsReviewFrameState(
              panel,
              frame,
              "blocked",
              "iframe_error_event"
            );
            showApplyResultsIframePreviewFallback(panel, preview, frame);
          },
          { once: true }
        );
      }
      markApplyResultsReviewFrameState(
        panel,
        frame,
        "loading",
        "iframe_probe_started"
      );
      frame.setAttribute("src", frame.getAttribute("data-src") || "");
      if (preview) {
        window.setTimeout(function () {
          if (
            !frame ||
            frame.getAttribute("data-sffc-review-frame-state") === "loaded" ||
            !panel ||
            panel.hidden
          ) {
            return;
          }
          markApplyResultsReviewFrameState(
            panel,
            frame,
            "timeout",
            "iframe_probe_timeout"
          );
          showApplyResultsIframePreviewFallback(panel, preview, frame);
        }, timeoutMs || 4500);
      }
    }

    function hydrateApplyResultsReviewPanel(panel) {
      var frame = panel
        ? panel.querySelector("[data-sffc-apply-results-review-frame]")
        : null;
      var preview = panel
        ? panel.querySelector("[data-sffc-apply-results-preview-url]")
        : null;
      var remoteBrowser = panel
        ? panel.querySelector("[data-sffc-apply-results-remote-browser]")
        : null;
      if (frame && !frame.getAttribute("src") && shouldProbeApplyResultsIframe(panel)) {
        startApplyResultsIframeProbe(panel, frame, preview, 4500);
      }
      if (remoteBrowser && !remoteBrowser.hidden) {
        requestApplyResultsRemoteBrowser(remoteBrowser);
      }
      if (preview && !preview.hidden) {
        requestApplyResultsApplicationPreview(preview);
      }
    }

    root.addEventListener(
      "click",
      function (event) {
        var queueMutationButton = event.target.closest(
          "[data-sffc-apply-chat-queue-add], [data-sffc-apply-chat-queue-remove]"
        );
        if (!queueMutationButton || !root.contains(queueMutationButton)) {
          return;
        }
        event.preventDefault();
        event.stopPropagation();
        if (
          queueMutationButton.hasAttribute("data-sffc-apply-chat-queue-add")
        ) {
          var addQueueKey =
            queueMutationButton.getAttribute(
              "data-sffc-apply-chat-queue-add"
            ) || "";
          var addQueueItem =
            findJobsWorkspaceItemByKey(addQueueKey) ||
            getApplyResultsItemFromSelectionElement(queueMutationButton);
          logEmilyJobOutcomeEvent("job_save", addQueueItem || {}, null, {
            resultKey: cleanMessageText(addQueueKey),
            source: "queue_mutation",
            outcome: "saved",
          });
          addCommercialApplyQueueItemByKey(
            addQueueKey
          );
          return;
        }
        var removeQueueKey =
          queueMutationButton.getAttribute(
            "data-sffc-apply-chat-queue-remove"
          ) || "";
        var removeQueueItem =
          findJobsWorkspaceItemByKey(removeQueueKey) ||
          getApplyResultsItemFromSelectionElement(queueMutationButton);
        logEmilyJobOutcomeEvent("job_dismiss", removeQueueItem || {}, null, {
          resultKey: cleanMessageText(removeQueueKey),
          source: "queue_mutation",
          outcome: "removed",
        });
        if (
          !removeCommercialApplyQueueItemByKey(
            removeQueueKey
          )
        ) {
          removeCommercialApplyQueueItemByIndex(
            queueMutationButton.getAttribute("data-sffc-apply-chat-queue-index")
          );
        }
      },
      true
    );

    function syncApplyResultsSearchSurface(surface) {
      var card =
        surface && surface.closest
          ? surface.closest(".sffc-crm-apply-results--job-search")
          : surface;
      var searchInput = card
        ? card.querySelector("[data-sffc-apply-results-search]")
        : null;
      var activeFilterButton = card
        ? card.querySelector("[data-sffc-apply-results-filter].is-active")
        : null;
      var countNode = card
        ? card.querySelector("[data-sffc-apply-results-count]")
        : null;
      var statCountNode = card
        ? card.querySelector("[data-sffc-apply-results-stat-count]")
        : null;
      var query = cleanMessageText(
        (searchInput && searchInput.value) || ""
      ).toLowerCase();
      var filter = activeFilterButton
        ? activeFilterButton.getAttribute("data-sffc-apply-results-filter") ||
          "all"
        : "all";
      var visibleCount = 0;
      if (!card) {
        return;
      }
      card
        .querySelectorAll("[data-sffc-apply-results-item]")
        .forEach(function (item) {
          var searchText = cleanMessageText(
            item.getAttribute("data-sffc-apply-results-search-text") ||
              item.textContent ||
              ""
          ).toLowerCase();
          var matchTone =
            item.getAttribute("data-sffc-apply-results-match") || "";
          var posted =
            item.getAttribute("data-sffc-apply-results-posted") || "";
          var matchesSearch = applyResultsSearchTextMatches(searchText, query);
          var matchesFilter =
            filter === "all" ||
            matchTone === filter ||
            (filter === "recent" && !!posted);
          var visible = matchesSearch && matchesFilter;
          item.hidden = !visible;
          if (visible) {
            visibleCount += 1;
          }
        });
      if (countNode) {
        countNode.textContent =
          String(visibleCount) +
          (visibleCount === 1 ? " job" : " jobs") +
          getApplyResultsPersonalizationLabel();
      }
      if (statCountNode) {
        statCountNode.textContent = String(visibleCount);
      }
    }

